\title{Combining social relations and interaction data in Recommender System with Graph Convolution Collaborative Filtering}

\author{\uppercase{Tin T. Tran} \orcidlink{0000-0003-4252-6898}\authorrefmark{1},
\uppercase{Vaclav Snasel} \orcidlink{0000-0002-9600-8319}\authorrefmark{1},
