\begin{equation}
I_1(t)=I_3(t)=U(t)=0,\qquad
I_2(t)= \frac{t}{R_{n_A}}.\nonumber
%I_3(t)&=0,\nonumber\\
%U(t)&=0.\nonumber\\
\end{equation}
Since $G(t)=(I_1(t)+I_2(t)+I_3(t))/C$, we get $e^{\pm G(t)} = e^{\frac{\pm t}{CR_{n_A}}}$ and $\int_{0}^{t} e^{G(t)} U(t) =0$. With $V_0^{\uparrow} = V_{out}^{T^{\uparrow}_{-}}(0)$ as our initial value, \cref{Eq1} 
