\end {cases}
\end{align}
\begin{align}
& = \vdd \cdot e^{\frac{i_k}{C}} \bigl(e^{\frac{t}{2RC}} - \gamma_k  \bigr)  \nonumber
\end{align}
\normalsize
for Case $k \in \{1,2,3,4\}$, where
\small
\begin{flalign} 
\label{eq:gam1}
 \gamma_1 &= \frac{4R^2C}{\alpha_1+ \alpha_2} e^{\frac{\alpha_1+ \alpha_2}{4R^2C}} - \frac{4R^2C}{\alpha_2} &&\nonumber \\
& - \bigl(\frac{2R(\Delta- \epsilon) - 4R^2C}{\alpha_2} - \frac{4R(\Delta - \epsilon) - 8R^2C}{\alpha_1+ 2 \alpha_2} \bigr) e^{\frac{\Delta - \epsilon}{2RC}} &&\nonumber \\
&- \bigl(\frac{4R(\Delta+ \epsilon) - 8R^2C}{\alpha_1 + 2\alpha_2} - \frac{2R(\Delta + \epsilon) - 4R^2C}{\alpha_1+ \alpha_2} \bigr) e^{\frac{\Delta + \epsilon}{2RC}},&&
\end{flalign}
\begin{flalign}
\label{eq:gam2}
\gamma_2 &= \frac{4R^2C}{\alpha_1+ \alpha_2} e^{\frac{\alpha_1+ \alpha_2}{4R^2C}} - \bigl(1 - \frac{4R(\Delta - \epsilon) - 8R^2C}{\alpha_1+ 2 \alpha_2} \bigr) e^{\frac{\Delta - \epsilon}{2RC}} &&\nonumber \\
