e^{\frac{i_2}{C}} \bigl (\frac{\int_{0}^{\frac{\alpha_2}{2R}} s \cdot e^{\frac{s}{2RC}} ds}{\alpha_2}  + \frac{ \int_{\frac{\alpha_2}{2R}}^{\Delta- \epsilon} e^{\frac{s}{2RC}} ds}{2R} +  \frac{2( \int_{\Delta- \epsilon}^{\Delta+ \epsilon} s \cdot e^{\frac{s}{2RC}}ds)}{\alpha_1+ 2 \alpha_2}  \\\quad + \frac{\int_{\Delta+ \epsilon}^{\frac{\alpha_1+ \alpha_2}{2R}} s \cdot e^{\frac{s}{2RC}} ds}{\alpha_1 + \alpha_2} + \frac{\int_{\frac{\alpha_1+ \alpha_2}{2R}}^{t} e^{\frac{s}{2RC}} ds}{2R} \bigr ) &    \ \text{\small Case 2} \\ 
e^{\frac{i_3}{C}} \bigl (\frac{\int_{0}^{\frac{\alpha_2}{2R}} s \cdot e^{\frac{s}{2RC}} ds}{\alpha_2}  + \frac{ \int_{\frac{\alpha_2}{2R}}^{\Delta+ \epsilon} e^{\frac{s}{2RC}} ds}{2R} +  \frac{ \int_{\Delta+ \epsilon}^{\frac{\alpha_1+ \alpha_2}{2R}} s \cdot e^{\frac{s}{2RC}}ds}{\alpha_1+ \alpha_2} \\\quad + \frac{\int_{\frac{\alpha_1+ \alpha_2}{2R}}^{t} e^{\frac{s}{2RC}} ds}{2R} \bigr ) &   \  \text{\small Case 3} \\ 
e^{\frac{i_4}{C}} \bigl (\frac{\int_{0}^{\frac{\alpha_2}{2R}} s \cdot e^{\frac{s}{2RC}} ds}{\alpha_2}  + \frac{\int_{\frac{\alpha_2}{2R}}^{t} e^{\frac{s}{2RC}} ds}{2R} \bigr ) &   \ \text{\small Case 4} \nonumber
\end {cases}
\end{align}
\begin{align}
& = \vdd \cdot e^{\frac{i_k}{C}} \bigl(e^{\frac{t}{2RC}} - \gamma_k  \bigr)  \nonumber
\end{align}
for Case $k \in \{1,2,3,4\}$, where
{\small
\begin{flalign} 
\label{eq:gam1}
 \gamma_1 &= \frac{4R^2C}{\alpha_1+ \alpha_2} e^{\frac{\alpha_1+ \alpha_2}{4R^2C}} - \frac{4R^2C}{\alpha_2} &&\nonumber \\
& - \bigl(\frac{2R(\Delta- \epsilon) - 4R^2C}{\alpha_2} - \frac{4R(\Delta - \epsilon) - 8R^2C}{\alpha_1+ 2 \alpha_2} \bigr) e^{\frac{\Delta - \epsilon}{2RC}} &&\nonumber \\
&- \bigl(\frac{4R(\Delta+ \epsilon) - 8R^2C}{\alpha_1 + 2\alpha_2} - \frac{2R(\Delta + \epsilon) - 4R^2C}{\alpha_1+ \alpha_2} \bigr) e^{\frac{\Delta + \epsilon}{2RC}},&&
\end{flalign}
\begin{flalign}
\label{eq:gam2}
\gamma_2 &= \frac{4R^2C}{\alpha_1+ \alpha_2} e^{\frac{\alpha_1+ \alpha_2}{4R^2C}} - \bigl(1 - \frac{4R(\Delta - \epsilon) - 8R^2C}{\alpha_1+ 2 \alpha_2} \bigr) e^{\frac{\Delta - \epsilon}{2RC}} &&\nonumber \\
&- \bigl(\frac{4R(\Delta+ \epsilon) - 8R^2C}{\alpha_1 + 2\alpha_2} - \frac{2R(\Delta + \epsilon) - 4R^2C}{\alpha_1+ \alpha_2} \bigr) e^{\frac{\Delta + \epsilon}{2RC}} &&\nonumber \\
&+ \frac{4R^2C}{\alpha_2} \bigl(e^{\frac{\alpha_2}{4R^2C}} -1 \bigr),&&
\end{flalign}
\begin{flalign}
\label{eq:gam3}
\gamma_3 &= \frac{4R^2C}{\alpha_1+ \alpha_2} e^{\frac{\alpha_1+ \alpha_2}{4R^2C}} - \bigl(1 - \frac{2R(\Delta + \epsilon) - 4R^2C}{\alpha_1+ \alpha_2} \bigr) e^{\frac{\Delta + \epsilon}{2RC}} &&\nonumber \\
&+ \frac{4R^2C}{\alpha_2} \bigl(e^{\frac{\alpha_2}{4R^2C}} -1 \bigr),
\end{flalign}
\begin{flalign}
\label{eq:gam4}
\gamma_4 &= \frac{4R^2C}{\alpha_2} \bigl(e^{\frac{\alpha_2}{4R^2C}}-1 \bigr).&&
\end{flalign}
}
Combining the above solutions for \cref{crucial_I1} and \cref{crucial_expint}
according to \cref{Eq1}
provides an accurate expression for the output trajectory $V_{out}^{T^{\downarrow \downarrow}_{+}}(t)$:

\begin{align}
V_{out}^{T^{\downarrow \downarrow}_{+}}(t) \approx 
V_{out}^{T_{-}^{\downarrow}}(\Delta) e^{\frac{-(2i_{k}R+t)}{2RC}}+ \vdd (1- \gamma_k e^{-\frac{t}{2RC}})  \label{eq:bothFall}
\end{align}
for Case $k\in\{1,2,3,4\}$, where $V_{out}^{T^{\downarrow}_{-}}(\Delta) = V_{out}^{T_{-}^{\downarrow}}(0) e^{\frac{-\Delta}{CR_{n_B}}}$,
$i_1, \ldots, i_4$, $\gamma_1, \ldots, \gamma_4$, are  defined in \cref{eq:FirstFall}, \cref{eq:i1}, ..., \cref{eq:gam4}, respectively. In addition, our symmetry immediately provides us with a trajectory
corresponding to the case of negative $\Delta$:

\begin{equation}
V_{out}^{T^{\downarrow \downarrow}_{-}}(t) \approx 
V_{out}^{T_{+}^{\downarrow}}(\Delta) e^{\frac{-(2i'_{k}R+t)}{2RC}}+ \vdd (1- \gamma'_k e^{-\frac{t}{2RC}})  \nonumber,
\end{equation}
for Case $k\in\{1,2,3,4\}$, where $V_{out}^{T_{+}^{\downarrow}}(\Delta)=V_{out}^{T_{+}^{\downarrow}}(0) e^{-\frac{|\Delta|}{CR_{n_A}}}$ and $i'_1, \ldots, i'_4$, $\gamma'_1, \ldots, \gamma'_4$ are obtained by substituting $\alpha_1$ by $\alpha_2$ and $\Delta$ by $|\Delta|$ in \cref{eq:i1}, ..., \cref{eq:gam4}, respectively.
}
\subsection{Single Input Switching}
Whereas the main focus of our model is the proper modeling of MIS effects, it of course also
needs to handle the ``simple'' single input switching case. This is
done exactly as in the IDM \cite{FNNS19:TCAD}, by continuously switching between the
trajectories of the modes $(0,0)$ and $(1,0)$ (for input A) resp.\ $(0,0)$ and $(0,1)$ 
(for input B).
\ifthenelse{\boolean{conference}}
{
Fortunately, by adjusting  $\Delta$ to be the time difference between the current and the previous transition of the \emph{same} input, we could adapt the above trajectory formulas for the MIS cases to also obtain the ones for the SIS cases. For switching from $(1,0)$ and $(0,0)$, 
for example, it suffices to replace the initial value $V_{out}^{T_{-}^{\downarrow}}(\Delta)$ in $V_{out}^{T_{+}^{\downarrow \downarrow}}(t)$ by the initial value $V_{out}^{T^{\uparrow}_{-}}(\Delta)$, which gives the output voltage at the time the previous switch from $(0,0)$ to $(1,0)$.
}
