\subsection{Fine-grained modality awareness Fusion}
Consistent with previous mainstream MMKGC works \cite{cao2022otkge}\cite{zhang2024native}\cite{zhang2024mygo}\cite{li2023imf}, this paper also considers three types of modality information in MMKGC: visual, textual, and structural modalities.

\textbf{Visual Tokenizer}{:} In order to capture fine-grained interaction information at the token level, this paper follows the setting in previous work \cite{zhang2024mygo}. We use the visual pre-trained model BEIT-V2 \cite{peng2022beit} to convert the image corresponding to each entity $e$ into a set of discrete visual tags through a visual tagger, each of which corresponds to an image patch. Thus, the visual tag $\mathbf{Tokens}_{visual}(e)$ of each entity $e$ is obtained:
\begin{equation}
        \mathbf{Tokens}_{visual}(e)=\text{V-Encoder(e)}= \left\{v_{1}, v_{2}, \cdots, v_{n}\right\}
\end{equation}
where $n$ represents the number of visual modality tokens. $\text{V-Encoder(e)}$ represents the visual encoder \cite{peng2022beit}.

\textbf{Textual Tokenizer}: Similar to the process of Visual Tokenizer, we use the pre-trained language model Bert \cite{devlin2018bert} to convert the text description paragraph corresponding to each entity $e$ into a set of discrete text tags through the text tagger, where each text tag corresponds to the smallest unit of a text. Thus, we obtain the text tag $\mathbf{T}_{textual}(e)$ of each entity $e$:
\begin{equation}
        \mathbf{Tokens}_{textual}(e)=\text{T-Encoder(e)}= \left\{t_{1}, t_{2}, \cdots, t_{m}\right\}
\end{equation}
Where $m$ represents the number of text modality tokens and $\text{T}$-Encoder(e) represents the text encoder \cite{devlin2018bert}.

\textbf{Visual and Textual Encoder}: After obtaining the fine-grained information tokens of visual and textual, TSAM is different from MyGo \cite{zhang2024mygo} which directly concatenates the tokens of the two modalities. TSAM aims to directly interact and perceive the fine-grained information between modalities from a more fine-grained perspective. First, we define two linear projection layers $g_{v}\left(\right)$ and $g_{t}\left(\right)$ to project the visual and textual tokens into the same space:

\begin{small}
    \begin{equation}
    \mathbf{Tokens}^{'}_{visual}(e)=\{{v}^{'}_{1},...,{v}^{'}_{n}\}=\{g_{v}\left(v_{1}\right)+b^{v}_{1} ,...,g_{v}\left(v_{n}\right)+b^{v}_{n} \}
    \end{equation}
\end{small}
\begin{small}
    \begin{equation}
    \mathbf{Tokens}^{'}_{txtual}(e)=\{{t}^{'}_{1},...,{t}^{'}_{n}\}=\{g_{t}\left(t_{1}\right)+b^{t}_{1} ,...,g_{t}\left(t_{n}\right)+b^{t}_{n} \}
    \end{equation}
\end{small}%
where $\{{t}^{'}_{1},...,{t}^{'}_{n}\}$ represent the tokens that have been transformed into the unified spatial dimension through linear projection, $b^v$ and $b^t$ represent bias vectors, so as to better integrate the two modalities through training the linear projection layer. After obtaining the token sequences of the two modalities after linear layer projection, TSAM uses the pre-trained language model based on transformer\cite{vaswani2017attention} to perform encoder processing on the sequences respectively:

\begin{equation}
    \mathrm{e}_{vis}=\operatorname{Pooling}\left(g_{e}\left([\mathrm{ENT}],  v_{1}^{'} , \cdots, v_{n}^{'}\right)\right)
\end{equation}
\begin{equation}
    \mathrm{e}_{txt}=\operatorname{Pooling}\left(g_{e}\left([\mathrm{ENT}],  t_{1}^{'} , \cdots, t_{n}^{'}\right)\right)
\end{equation}
where $g_{e}$ represents the encoder layer based on the Transformer \cite{vaswani2017attention} pre-trained language model, Pooling is the pooling operation, and [ENT] is similar to [CLS] in Bert\cite{devlin2018bert}, which is used to obtain the final hidden representation of the token. $\mathrm{e}_{vis}$ $\mathrm{e}_{txt}$ represent the visual and text embeddings of entity $e$ respectively.


\textbf{Structural Encoder: } Typically, the semantic information of structural modality is learned through triples through the knowledge graph embedding (KGE) model. These embeddings are learned during training by optimizing scoring functions that capture the semantic relationships in the knowledge graph. KGE uses a scoring function to evaluate the authenticity of the triple $(h, r, t)$. 
In KGE models (e.g., TransE \cite{bordes2013translating}, TuckER \cite{balavzevic2019tucker}, RotatE \cite{sun2019rotate}), the embeddings for entities $\mathbf{h}, \mathbf{t} \in \mathbb{R}^d$ and relations $\mathbf{r} \in \mathbb{R}^d$ are initialized as trainable vectors. These embeddings form the basis for the structural modality.
During training, these embeddings are optimized by minimizing a loss function (e.g., margin-based loss) that ensures plausible triples $(h, r, t)$ receive higher scores than implausible ones.
The scoring function is not only used to evaluate the interaction between entities and relations but also plays an important role in learning structural information. We adopt the TuckER \cite{balavzevic2019tucker}, TransE \cite{bordes2013translating} and RotatE \cite{sun2019rotate} models to construct a structured encoder to achieve more accurate knowledge representation.

For TuckER \cite{balavzevic2019tucker}, its core idea is to use Tucker decomposition to represent the score of the triple as a product of a tensor. Specifically, TuckER defines the scoring function of the triple $(h, r, t)$ in the knowledge graph as:
\begin{equation}
\operatorname{Score}(h, r, t)=\sum_{i, j, k} \mathbf{W}_{i j k} \cdot \mathbf{h}_i \cdot \mathbf{r}_j \cdot \mathbf{t}_k
\end{equation}
where $\mathbf{W}_{ijk}$ is a learnable three-dimensional tensor weight, which represents the interaction weight of the relation $r$ on the head entity $h$ and the tail entity $t$, $\mathbf{h}_i$, $\mathbf{r}_j$ and $\mathbf{t}_k$ are the embedding vectors of the head entity, relation and tail entity respectively. 

For TransE\cite{bordes2013translating}, the core idea is to capture the relation between entities through vector addition. The model assumes that each relation can be regarded as a "translation" operation, that is, given the head entity $h$ and the relation $r$, the tail entity $t$ can be obtained by "translating" the head entity in the direction of the relation. Specifically, the basic formula of TransE is:
\begin{equation}
\operatorname{Score}(h, r, t)=\|\mathbf{h}+\mathbf{r}-\mathbf{t}\|
\end{equation}

For RotatE \cite{sun2019rotate}, its core idea is to model relations as rotations in a complex vector space. The method represents the relationship between entities by rotating the head entity vector in the complex plane. Specifically, RotatE defines the scoring function of the triple $(h, r, t)$ as:
\begin{equation}
\operatorname{Score}(h, r, t) = |\mathbf{h} \circ \mathbf{r} - \mathbf{t}|
\end{equation}
where $\mathbf{h}, \mathbf{r}, \mathbf{t} \in \mathbb{C}^d$ are complex-valued embeddings of the head entity, relation, and tail entity, respectively. The operator $\circ$ denotes the Hadamard (element-wise) product, which performs a rotation operation on $\mathbf{h}$ in complex space. The score measures the distance between the rotated head entity $\mathbf{h} \circ \mathbf{r}$ and the tail entity $\mathbf{t}$, enforcing geometric consistency in the embedding space.


These scoring functions guide the learning of structural embeddings through backpropagation, ensuring that semantically valid triples are assigned higher scores. Through the above three KGE models, we have the embedding representation of the structural modality of entity $e$: $e_{str}$ and the embedding representation of the relation $r$.


\textbf{Modality Awareness Fusion}: In our model, we introduce a Modality Awareness Fusion mechanism to effectively integrate the embedding representations of an entity 
$e$ across three distinct modalities: structural, visual, and textual. This fusion process is designed to leverage the complementary information provided by each modality, thereby enhancing the overall representation of the entity. After obtaining the embedding representations $e_{str}$, $\mathrm{e}_{vis}$ and $\mathrm{e}_{txt}$, and for the entity $e$ in the structural, visual, and textual modalities, respectively, we construct an attention vector to dynamically weigh the importance of each modality in the final fused representation. The attention mechanism is crucial as it allows the model to focus on the most informative aspects of each modality, thereby improving the quality of the fused representation.The fused entity representation $e_{f}$ is computed as follows:

After obtaining the embedding representations of entity $e$ in three modalities, we construct an attention vector to enhance modality fusion: 

\begin{equation}
e_{f}=\operatorname{stack}\left(\alpha_s \boldsymbol{e}_{str}, \alpha_v \boldsymbol{e}_{vis}, \alpha_t \boldsymbol{e}_{txt} \right)
\end{equation}
\begin{equation}
    \left(\alpha_s, \alpha_v, \alpha_t\right)=\operatorname{Softmax}\left(\boldsymbol{\alpha}^T e_{vis}, \boldsymbol{\alpha}^T e_{txt}, \boldsymbol{\alpha}^T \boldsymbol{e}_{str}\right)
\end{equation}    
where $\boldsymbol{\alpha}$ is the attention vector and  $e_{f}$ represents the fused entity representation. The attention weights 
$\alpha_s, \alpha_v, \alpha_t$ reflect the relative importance of the structural, visual, and textual modalities, respectively, in the context of the entity $e$. These weights are normalized using the softmax function to ensure that they sum to one, providing a probabilistic interpretation of the modality contributions. This fine-grained interaction allows the model to perceive subtle inter-modal relationships, which are crucial for accurately representing the entity in a multi-modal context.

Finally, we learn the entity representation $e_{f}$ with very fine-grained interaction and inter-modal perception. through this modality-aware fusion process, our model is able to achieve a high level of granularity in capturing the nuances of each modality while also integrating them in a coherent and meaningful way. This approach ensures that the final representation is both rich and contextually relevant, enabling superior performance in downstream tasks that require multi-modal understanding.


\subsection{Structure-aware Contrastive learning}
Although modality fusion can be achieved through linear transformations and attention mechanisms, a semantic gap invariably exists between different modalities. Contrastive learning \cite{chen2020simple}\cite{he2020mocov1}\cite{radford2021learning}\cite{gao2021simcse}\cite{liang2023knowledge} has garnered significant attention across various fields, as it enhances the representation of similar samples by bringing them closer together while pushing dissimilar samples apart. This paper aims to align the visual and textual modality representations with the structural modality through contrastive learning, thereby mitigating noise potentially introduced by irrelevant images and texts, and ultimately improving the model's predictive performance. Specifically, to achieve this effect, the SaCL method performs contrastive learning twice, centering on the structured modality.

In the contrastive learning of structural modality-visual modality, the embedding set $ S = \{s_{1}, \dots, s_{k}\}$ of the entity structural modality $E_{str}$ and the embedding set $ V = \{v_{1}, \dots, v_{k}\}$ of the entity visual modality $E_{vis}$ are positive samples of each other. And randomly select K other samples in the same mini-batch as negative sample pairs of $E_{str}$ and $E_{vis}$, and express them as:
\begin{equation}
    V_{\boldsymbol{i}}^{-}=\left\{V_{i 1}^{-}, V_{i 2}^{-}, \ldots, V_{i K}^{-}\right\} , S_{\boldsymbol{i}}^{-}=\left\{S_{i 1}^{-}, S_{i 2}^{-}, \ldots, S_{i K}^{-}\right\}
\end{equation}

After that, the negative log-likelihood function is used to train the maximum similarity between positive sample pairs and the minimum similarity between negative sample pairs. The formula is as follows:
\begin{small}
    \begin{equation}
        \mathcal{L}_{S_V}=-\frac{1}{B} \sum_{i=1}^B \log \frac{\exp \left(s\left(S_i, V_i\right) / \tau\right)}{\exp \left(s\left(S_i, V_i\right) / \tau\right)+\sum_{j=1}^K \exp \left(s\left(S_i, V_{i j}^{-}\right) / \tau\right)}
    \end{equation}
    \begin{equation}
        \mathcal{L}_{V_S}=-\frac{1}{B} \sum_{i=1}^B \log \frac{\exp \left(s\left(V_i, S_i\right) / \tau\right)}{\exp \left(s\left(V_i, S_i\right) / \tau\right)+\sum_{j=1}^K \exp \left(s\left(V_i, S_{i j}^{-}\right) / \tau\right)}
    \end{equation}
\end{small}
\begin{equation}
        \mathcal{L}_{SV}=\mathcal{L}_{S_V} +\mathcal{L}_{V_S}
\end{equation}
where $B$ represents the total batch size, $s(\cdot)$ represents the calculation of the cosine similarity of two tensors, and $\tau $ is the temperature parameter. $\mathcal{L}_{SV}$ represents the contrast loss of the structure-visual modality so that the visual modality and the textual modality can be better aligned and reflect the more realistic graph structure pattern in MMKG.

In the contrastive learning of structural modality and text modality, the embedding set $ T = \{t_{1}, \dots, t_{k}\}$ of entity text modality $E_{txt}$ and the embedding set $ S = \{s_{1}, \dots, s_{k}\}$ of $E_{str}$ are positive samples of each other. And K other samples in the same mini-batch are randomly selected as negative sample pairs of $E_{str}$ and $E_{txt}$ and are expressed as:
\begin{equation}
     S_{\boldsymbol{i}}^{-}=\left\{S_{i 1}^{-}, S_{i 2}^{-}, \ldots, S_{i K}^{-}\right\} , T_{\boldsymbol{i}}^{-}=\left\{t_{i 1}^{-}, t_{i 2}^{-}, \ldots, t_{i K}^{-}\right\} 
\end{equation}

Similar to the structural modality-visual modality operation, the contrast loss of structural modality-textual modality can be defined as:
\begin{small}
    \begin{equation}
        \mathcal{L}_{S_T}=-\frac{1}{B} \sum_{i=1}^B \log \frac{\exp \left(s\left(S_i, T_i\right) / \tau\right)}{\exp \left(s\left(S_i, T_i\right) / \tau\right)+\sum_{j=1}^K \exp \left(s\left(S_i, T_{i j}^{-}\right) / \tau\right)}
\end{equation}
\begin{equation}
        \mathcal{L}_{T_S}=-\frac{1}{B} \sum_{i=1}^B \log \frac{\exp \left(s\left(T_i, S_i\right) / \tau\right)}{\exp \left(s\left(T_i, S_i\right) / \tau\right)+\sum_{j=1}^K \exp \left(s\left(T_i, S_{i j}^{-}\right) / \tau\right)}
\end{equation}
\end{small}
\begin{equation}
    \mathcal{L}_{ST}=\mathcal{L}_{S_T} +\mathcal{L}_{T_S}
\end{equation}
where $\mathcal{L}_{ST}$ represents the contrastive loss of structural modality-text modality so that the text modality and structural modality can be better aligned and reflect a more realistic graph structure pattern in MMKG.
\subsection{Model Training Process}
After having the fused representation of the entity $\boldsymbol{e_f}$ and the relation embedding representation $r$ obtained using KGE, we use the Transformer-based decoder to obtain the prediction result of the tail entity in the triple:
\begin{equation}
    \boldsymbol{t}^{p}=g_{d}([CLS] , \boldsymbol{h_f} , \mathbf{r})
\end{equation}
where $g_{d}()$ represents the decoder layer with a Transformer-based pre-trained language model \cite{devlin2018bert}\cite{liu2019roberta}\cite{he2020deberta}, $\boldsymbol{h_f}$ represents the modality fusion representation of the head entity. $[CLS]$ indicates that the final representation of the token is used as the overall representation of the input sequence and is predicted and classified through a fully connected layer. $\boldsymbol{t}^{p}$ represents the predicted tail entity given $\boldsymbol{h_f}$ and $\boldsymbol{r}$.

We choose the cross entropy loss function as the core loss function for model prediction, which is defined as follows:
\begin{equation}
\begin{split}
\mathcal{L}_{p} = \sum_{(h, r, t) \in \mathcal{T}} -\frac{1}{|\mathcal{E}|} \sum_{n=1}^{|\mathcal{E}|} \left( y \cdot \log \left(\Theta\left(h, r, t_n\right)\right) + \right. \\
\left. \left(1-y\right) \cdot \log \left(1-\Theta\left(h, r, t_n\right)\right) \right)
\end{split}
\end{equation}
\begin{equation}
    \Theta (h, r, t)=\operatorname{sigmoid}(Score(h, r, t))
\end{equation}
Where $\mathcal{E}$ is the entire set of candidate prediction entities, $y \in\{0,1\}$ is the label of the triple $\left(h, r, t_n\right)$. The total loss of the model is:
\begin{equation}
    \mathcal{L}= \mathcal{L}_{p} + \mathcal{L}_{ST} + \mathcal{L}_{SV}
\end{equation}
where $\mathcal{L}_{p}$ represents the cross entropy loss function for prediction. $\mathcal{L}_{ST}$ and $\mathcal{L}_{SV}$ represent the contrastive learning loss functions for modality alignment, respectively.
The training process of the model is shown in Algorithm 1.
% -------------------------------------------
\begin{algorithm}
\caption{TSAM Model for multi-modal Knowledge Graph Completion }
\begin{flushleft}
 % 从这里开始标红
\begin{algorithmic}[1]
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\Require Knowledge Graph $\mathcal{G} = (\mathcal{E}, \mathcal{R}, \mathcal{T}, \mathcal{M})$ with multi-modal data $\mathbf{V}$, $\mathbf{T}$, $\mathbf{S}$
\Ensure Optimized embeddings for each modality

\State \textbf{Initialization:} Pre-trained tokenizers, scoring function, attention parameters

\State \textbf{Fine-grained Modality-aware Fusion (FgMAF):}
\For{each entity $e \in \mathcal{E}$}
    \State $\text{Tokens}_{\text{visual}} = \text{V-Encoder}(e)$
    \State $\text{Tokens}_{\text{textual}} = \text{T-Encoder}(e)$
    \State Project tokens $\text{Tokens}_{\text{visual}}$ and $\text{Tokens}_{\text{textual}}$ to unified space 
    \State Use Transformer layers and KGE model to represent multi-modal $\boldsymbol{e}_{vis}$, $\boldsymbol{e}_{txt}$ $\boldsymbol{e}_{str}$ respectively
\EndFor

\State {Modality Fusion:}
\For{each entity $e \in \mathcal{E}$}
    \State Compute $e_{f}$ by combining $\boldsymbol{e}_{str}$, $\boldsymbol{e}_{vis}$, $\boldsymbol{e}_{txt}$, and $\text{Encoded}_{\text{text}}$ with attention mechanism
\EndFor

\State \textbf{Structure-aware Contrastive Learning (SaCL):}
\State Generate positive and negative samples for contrastive learning
\State Compute contrastive losses $\mathcal{L}_{SV}$ for (structural, visual) and $\mathcal{L}_{ST}$ for (structural, textual) pairs

\State Total contrastive loss = $\mathcal{L}_{ST}$ + $\mathcal{L}_{SV}$

\State \textbf{Training:}
\For{each $(h, r, t) \in \mathcal{T}$}
    \State Predict the tail entity $t_{\text{pred}} = \text{Decoder}(h_{\text{fused}}, r)$ and calculate the score function and cross-entropy loss $\mathcal{L}_{ST}$
\EndFor
\State $\text{Total Loss} = \text{prediction loss} + \text{Total}_{\text{contrastive loss}}$
\State \textbf{Repeat:}Training and optimized is repeated to get the best-predicted value
\State \textbf{Until:}Converges
\end{algorithmic}

\end{flushleft}
\end{algorithm}


