\subsection{Merger initialization}

\begin{algorithm}[H]
\SetAlgoLined

\KwIn{Rank of content $R(\text{content})$, Rank of style $R(\text{style})$ acorss layers}
\KwOut{Initialized content merger vector, Initialized style merger vector}

% Initialize a random vector V
$V \gets \text{rand}(64, 1)$\;
$V' \gets \frac{V}{\|V\|}$ \tcp*{Normalize V}

\uIf{$R(\text{content}) > R(\text{style})$}{
    $\text{content\_merger\_init} \gets V' \cdot 1(V' > 0.25)$\;
    $\text{style\_merger\_init} \gets V' \cdot 1(V' > 0.75)$\;
}
\uElseIf{$R(\text{content}) < R(\text{style})$}{
    $\text{content\_merger\_init} \gets V' \cdot 1(V' > 0.75)$\;
    $\text{style\_merger\_init} \gets V' \cdot 1(V' > 0.25)$\;
}
\Else{
    $\text{content\_merger\_init} \gets \mathbf{1}_{64 \times 1}$\;
    $\text{style\_merger\_init} \gets \mathbf{1}_{64 \times 1}$\;
}

\caption{Content and Style Merger Initialization Algorithm}
\end{algorithm}

\subsection{Layer priors}

\begin{algorithm}[H]
\SetAlgoLined

\KwIn{Resolution of SDXL UNet, $R(\text{content})$, $R(\text{style})$}
\KwOut{Loss function $L$ for merging layers}

\uIf{Resolution(SDXL UNet) $<$ 32 \tcp*[h]{Low resolution}}{
    \uIf{$\text{Rank}(\text{content}) > \text{Rank}(\text{style})$}{
        Minimize $R(m_s) - R(m_c)$ \tcp*[h]{Minimize the difference between style and content rank}\;
        $L \gets \left( \|m_s\|_* - \|m_c\|_* \right) + |m_c|_1$\;
    }
}
\Else(\tcp*[h]{Resolution(SDXL UNet) $=$ 32}){
    \uIf{$\text{Rank}(\text{style}) > \text{Rank}(\text{content})$}{
        Minimize $R(m_c) - R(m_s)$ \tcp*[h]{Minimize the difference between content and style rank}\;
        $L \gets \left( \|m_c\|_* - \|m_s\|_* \right) + |m_s|_1$\;
    }
}

\caption{Rank-constrained Layer-prior Merging}
\end{algorithm}




