\frac{1}{2}\left[ \|e_{n+1}^{h}-\widetilde{e}_{n+1}^{h}\|^{2}+k\nu \|\nabla
(e_{n+1}^{h}-\widetilde{e}_{n+1}^{h})\|^{2}\right] + \\
+\frac{k\chi }{2}\left[ \|I_{H}e^{n+1}\|^{2}+\|I_{H}e^{n}\|^{2}\right] -k%
\frac{1}{\nu }\|\nabla u^{n+1}\|_{\infty }^{2}\|e^{n}\|^{2}\leq k(\rho
^{n+1},\widetilde{e}^{n+1}).
\end{gather*}%
Note that 
\begin{gather*}
\|e^{n}\|^{2}=\|I_{H}e^{n}\|^{2}+\|(I-I_{H})e^{n}\|^{2}\leq
\|I_{H}e^{n}\|^{2}+\left( C_{1}H\|\nabla e^{n}\|\right) ^{2},thus \\
\frac{1}{2}k\chi \|I_{H}e^{n}\|^{2}\geq \frac{1}{2}k\chi \|e^{n}\|^{2}-\frac{%
1}{2}k\chi \left( C_{1}H\right) ^{2}\|\nabla e^{n}\|^{2},
\end{gather*}%
so that we have 
\begin{gather*}
\frac{1}{2}\left[ \|e^{n+1}\|^{2}+\frac{1}{2}k\chi \|I_{H}e^{n+1}\|^{2}%
\right] -\frac{1}{2}\left[ \|e^{n}\|^{2}+\frac{1}{2}k\chi \|I_{H}e^{n}\|^{2}%
\right] \\
\frac{1}{2}\left[ \|\widetilde{e}^{n+1}-e^{n}\|^{2}\right] +\frac{k\nu }{2}%
\|\nabla e_{n+1}\|^{2}+k\frac{\nu }{4}\|\nabla \widetilde{e}^{n+1}\|^{2} \\
\frac{1}{2}\left[ \|e_{n+1}^{h}-\widetilde{e}_{n+1}^{h}\|^{2}+k\nu \|\nabla
(e_{n+1}^{h}-\widetilde{e}_{n+1}^{h})\|^{2}\right] + \\
+\frac{k\chi }{2}\|I_{H}e^{n+1}\|^{2}+\frac{1}{2}k\chi \|e^{n}\|^{2}-\frac{1%
}{2}k\chi \left( CH\right) ^{2}\|\nabla e^{n}\|^{2} \\
-k\frac{1}{\nu }\|\nabla u^{n+1}\|_{\infty }^{2}\|e^{n}\|^{2}\leq k(\rho
^{n+1},\widetilde{e}^{n+1}).
\end{gather*}%
Regrouping gives
\begin{gather*}
\frac{1}{2}\left[ \|e^{n+1}\|^{2}+\frac{1}{2}k\chi \|I_{H}e^{n+1}\|^{2}%
\right] -\frac{1}{2}\left[ \|e^{n}\|^{2}+\frac{1}{2}k\chi \|I_{H}e^{n}\|^{2}%
\right] \\
\frac{1}{2}\left[ \|\widetilde{e}^{n+1}-e^{n}\|^{2}\right] +\frac{k\nu }{2}%
\|\nabla e_{n+1}\|^{2}+k\frac{\nu }{4}\|\nabla \widetilde{e}^{n+1}\|^{2} \\
\frac{1}{2}\left[ \|e_{n+1}^{h}-\widetilde{e}_{n+1}^{h}\|^{2}+k\nu \|\nabla
(e_{n+1}^{h}-\widetilde{e}_{n+1}^{h})\|^{2}\right] + \\
+\frac{k\chi }{2}\|I_{H}e^{n+1}\|^{2}+k\left[ \frac{\chi }{2}-\frac{1}{\nu }%
\|\nabla u^{n+1}\|_{\infty }^{2}\right] \|e^{n}\|^{2} \\
-\frac{1}{2}k\chi \left( C_{1}H\right) ^{2}\|\nabla e^{n}\|^{2}\leq k(\rho
^{n+1},\widetilde{e}^{n+1}).
\end{gather*}%
There is one remaining negative term: $-\frac{1}{2}k\chi \left(
C_{1}H\right) ^{2}\|\nabla e^{n}\|^{2}$ . We proceed as above. Write 
\begin{equation*}
\frac{k\nu }{2}\|\nabla e_{n+1}\|^{2}=\frac{k\nu }{4}\|\nabla e_{n+1}\|^{2}+%
\frac{k\nu }{4}\|\nabla e_{n}\|^{2}+\frac{k\nu }{4}\|\nabla e_{n+1}\|^{2}-%
\frac{k\nu }{4}\|\nabla e_{n}\|^{2}.
\end{equation*}%
Use this and regroup. This gives 
\begin{gather*}
\frac{1}{2}\left[ \|e^{n+1}\|^{2}+\frac{1}{2}k\chi \|I_{H}e^{n+1}\|^{2}+%
\frac{k\nu }{4}\|\nabla e_{n+1}\|^{2}\right] \\
-\frac{1}{2}\left[ \|e^{n}\|^{2}+\frac{1}{2}k\chi \|I_{H}e^{n}\|^{2}+\frac{%
k\nu }{4}\|\nabla e_{n}\|^{2}\right] \\
\frac{1}{2}\left[ \|\widetilde{e}^{n+1}-e^{n}\|^{2}\right] +\frac{k}{4}\left[
\nu \|\nabla e_{n+1}\|^{2}+\nu \|\nabla \widetilde{e}^{n+1}\|^{2}\right] + \\
\frac{1}{2}\left[ \|e_{n+1}^{h}-\widetilde{e}_{n+1}^{h}\|^{2}+k\nu \|\nabla
(e_{n+1}^{h}-\widetilde{e}_{n+1}^{h})\|^{2}\right] \\
+\frac{k\chi }{2}\|I_{H}e^{n+1}\|^{2}+k\left[ \frac{\chi }{2}-\frac{1}{\nu }%
\|\nabla u^{n+1}\|_{\infty }^{2}\right] \|e^{n}\|^{2} \\
+\frac{k}{2}\left( \frac{\nu }{2}-\chi \left( CH\right) ^{2}\right) \|\nabla
e^{n}\|^{2}\leq k(\rho ^{n+1},\widetilde{e}^{n+1}).
\end{gather*}%
The proof is then completed with standard arguments in the numerical analysis of the NSE. This yields a uniform in time error estimate (and thus an infinite predictability horizon).

\section{Computational Explorations}
In this section, we present numerical experiments to validate the performance of the 2-step nudging method. Section~\ref{rates_of_conv} verifies the theoretical temporal convergence rates using a test case with a known exact solution. In Section~\ref{test:offset_cyl}, we explore a more complex 2d flow scenario and evaluate the effectiveness of the 2-step nudging by comparing it with standard nudging and a baseline simulation without data assimilation.

\subsection{Convergence rates in time}\label{rates_of_conv}
We verify the theoretical temporal convergence of the backward Euler time discretization of the 2-step nudging using an exact solution from~\cite{CFLS25} on the domain \( \Omega = (0,1) \times (0,1) \). The exact velocity and pressure are given by
\[
u(x,y,t) = \exp(t)(\cos y, \sin x)^\top, \quad p(x,y,t) = (x - y)(1 + t).
\]
Note that $\nabla \times (u\cdot \nabla u)=0$ so, like most exact NSE solutions, this will be a solution of the Stokes problem with modified pressure. These are inserted in the NSE to calculate the corresponding body force $f(x,t)$ with viscosity $\nu=1$. To isolate temporal errors, we use a fine mesh with $43266$ degrees of freedom (dof), minimizing spatial error effects. The final time is $T=2$. Here we choose $I_H$ as the $L^2$ projection. We use a Scott-Vogelius finite element pair with a barycenter refined mesh. We choose the time-step sizes $k = 1/4, 1/8, 1/16, 1/32$, and $1/64$. The $L^2$ velocity errors at $T=2$ for the 2-step nudging and standard nudging are presented in Table \ref{tab:error-main}. We observed a first-order convergence rate for both methods. 
