\section{Proof of class-conditional entropy upper bound}
\label{appA}

\begin{lemma}[Entropy Upper Bound for Class-Conditional Gaussian]\label{lem:class_cond_entropy}
Let $Z_{\mathrm{dec}} \in \mathbb{R}^D$ be the decision-level representation, and suppose that for each class $c \in \{1,\dots,K\}$, the conditional distribution satisfies
\[
Z_{\mathrm{dec}} \mid Y=c \sim \mathcal{N}(\mu_c, \Sigma_c),
\]
where $\Sigma_c$ is the class-specific covariance matrix with spectral decomposition. Let $R_c^2 = \mathrm{tr}(\Sigma_c)$ denote the class-wise mean-squared radius. Then the conditional entropy satisfies:
\[
h(Z_{\mathrm{dec}} \mid Y=c) \;\le\; \frac{D}{2} \ln\left(2\pi e \cdot \frac{R_c^2}{D}\right).
\]
\end{lemma}

\begin{proof}
By the differential entropy formula for multivariate Gaussians,
\[
h(Z_{\mathrm{dec}} \mid Y=c) = \frac{1}{2} \ln\left[(2\pi e)^D \det \Sigma_c\right].
\]

Let $\lambda_1, \dots, \lambda_D > 0$ be the eigenvalues of $\Sigma_c$. Then
\[
\det \Sigma_c = \prod_{i=1}^D \lambda_i, \quad \mathrm{tr}(\Sigma_c) = \sum_{i=1}^D \lambda_i = R_c^2.
\]

Applying the arithmetic–geometric mean (AM–GM) inequality to the eigenvalues yields:
\[
\prod_{i=1}^D \lambda_i \le \left( \frac{1}{D} \sum_{i=1}^D \lambda_i \right)^D = \left( \frac{R_c^2}{D} \right)^D.
\]

Substituting this into the entropy expression gives:
\[
\begin{aligned}
h(Z_{\mathrm{dec}} \mid Y=c)
&= \frac{1}{2} \ln \left[(2\pi e)^D \det \Sigma_c \right] \\
&\le \frac{1}{2} \ln \left[ (2\pi e)^D \cdot \left( \frac{R_c^2}{D} \right)^D \right] \\
&= \frac{D}{2} \ln \left( 2\pi e \cdot \frac{R_c^2}{D} \right),
\end{aligned}
\]
\end{proof}

\section{Batch-level contraction carries over to individual samples.}
\label{appB}
During training, the network processes a mini-batch
\(Z=(z^{(1)},\dots,\\z^{(B)})\) of \(B\) i.i.d.\ samples, where each
continuous vector \(z^{(i)}\in\mathbb{R}^{d}\) (feature space) is mapped to
\(z^{(i)}_{\!\mathrm{dec}}\in\mathbb{R}^{D}\) (decision space, \(d\!\ge\!D\)).
Independence implies
\[
  h(Z_{\mathrm{feat}})=\sum_{i=1}^{B} h\!\bigl(z^{(i)}_{\mathrm{feat}}\bigr),\qquad
  h(Z_{\mathrm{dec}} )=\sum_{i=1}^{B} h\!\bigl(z^{(i)}_{\mathrm{dec}}\bigr).
\]
Hence the proven batch-level inequality
\(h(Z_{\mathrm{feat}})>h(Z_{\mathrm{dec}})\)
already guarantees
\(h\!\bigl(z^{(i)}_{\mathrm{feat}}\bigr)>h\!\bigl(z^{(i)}_{\mathrm{dec}}\bigr)\)  
for every sample \(i\).

After uniform quantisation with step \(\Delta\),
Cover–Thomas \cite{cover2006elements} yields
\[
\begin{aligned}
  H\!\bigl(z^{(i)}_{\mathrm{feat},\Delta}\bigr)
    &= h\!\bigl(z^{(i)}_{\mathrm{feat}}\bigr) + d\ln\!\tfrac1\Delta + o(1), \\
  H\!\bigl(z^{(i)}_{\mathrm{dec},\Delta}\bigr)
    &= h\!\bigl(z^{(i)}_{\mathrm{dec}}\bigr ) + D\ln\!\tfrac1\Delta + o(1).
\end{aligned}
\]

Subtracting the two lines gives the per-sample Shannon-entropy gap

\[
  H\!\bigl(z^{(i)}_{\mathrm{feat},\Delta}\bigr)
  -H\!\bigl(z^{(i)}_{\mathrm{dec},\Delta}\bigr)
  =\bigl[h\!\bigl(z^{(i)}_{\mathrm{feat}}\bigr)
         -h\!\bigl(z^{(i)}_{\mathrm{dec}}\bigr)\bigr]
   + (d-D)\ln\!\tfrac1\Delta + o(1).
\]

Because \(d\ge D\) and \(\ln(1/\Delta)>0\), the extra term
\((d-D)\ln(1/\Delta)\) is non-negative.  Thus the discrete entropy drop is
at least as large as the differential-entropy drop, ensuring that the
information contraction observed on the batch persists—indeed is slightly
amplified—at the level of each individual finite-precision feature vector.



\section{$R_c^{2}$ under one–hot vectors}
\label{appC}

Consider a training sample \(i\) whose ground-truth class is \(c\).
Let
\[
z_i\in\mathbb{R}^{d}, \qquad
\mu_c = \frac{1}{N_c}\sum_{i\in c} z_i, \qquad
R_c^{2} = \frac{1}{N_c}\sum_{i\in c}\|z_i-\mu_c\|^{2}.
\]

After one gradient step with learning rate \(\gamma\),
\[
z_i^{+}=z_i-\gamma\,\tilde g_i,
\qquad
\mu_c^{+} = \mu_c - \gamma\,\tilde g_c,
\qquad
\tilde g_c = \frac{1}{N_c}\sum_{i\in c}\tilde g_i
\]

With logits \(o_i\) and Jacobian \(J_i=\partial o_i/\partial z_i\), the
one-hot gradient is
\[
\tilde g_i = J_i^{\!\top}(p_i - y_i)
           = (p_{ic}-1)\,J_i^{\!\top}e_c
           + \sum_{k\ne c} p_{ik}\,J_i^{\!\top}e_k. \tag{C.1}
\]

We first write the updated radius in full:
\[
\begin{aligned}
R_c^{2+}
&:= \frac{1}{N_c}\sum_{i\in c}\bigl\|z_i^{+}-\mu_c^{+}\bigr\|^{2}.
\end{aligned}
\]

Substituting the SGD updates \(z_i^{+}=z_i-\gamma\tilde g_i\) and
\(\mu_c^{+}=\mu_c-\gamma\tilde g_c\),
\[
\begin{aligned}
R_c^{2+}
&= \frac{1}{N_c}\sum_{i\in c}
   \bigl\| \,z_i-\gamma\tilde g_i - \mu_c + \gamma\tilde g_c \bigr\|^{2} \\[4pt]
&= \frac{1}{N_c}\sum_{i\in c}
   \bigl\| (z_i-\mu_c) - \gamma(\tilde g_i-\tilde g_c) \bigr\|^{2}. 
\end{aligned}
\]

For any vectors \(a,b\) and scalar \(\gamma\),
\(\|a-\gamma b\|^{2} = \|a\|^{2} - 2\gamma\,a^{\top}b + \gamma^{2}\|b\|^{2}\).
Applying this identity with \(a=z_i-\mu_c\) and \(b=\tilde g_i-\tilde g_c\),
\[
\begin{aligned}
R_c^{2+}
&= \frac{1}{N_c}\sum_{i\in c}
   \Bigl(\|z_i-\mu_c\|^{2}
         - 2\gamma\,(z_i-\mu_c)^{\!\top}(\tilde g_i-\tilde g_c)
         + \gamma^{2}\,\|\tilde g_i-\tilde g_c\|^{2}\Bigr) \\
&= R_c^{2}
   - \frac{2\gamma}{N_c}\sum_{i\in c}(z_i-\mu_c)^{\!\top}(\tilde g_i-\tilde g_c)
   + \frac{\gamma^{2}}{N_c}\sum_{i\in c}\|\tilde g_i-\tilde g_c\|^{2}.
\end{aligned}
\]

Using \(\sum_{i\in c}(z_i-\mu_c)=0\), the increment can be written as a
chain of equalities that shows each algebraic simplification explicitly:
\[
\begin{aligned}
\Delta R_c^{2}
&:= R_c^{2+}-R_c^{2} \\[2pt]
&= -\frac{2\gamma}{N_c}\!
     \sum_{i\in c}(z_i-\mu_c)^{\!\top}\bigl(\tilde g_i-\tilde g_c\bigr)
   +\frac{\gamma^{2}}{N_c}\!
     \sum_{i\in c}\|\tilde g_i-\tilde g_c\|^{2} \\[6pt]
&= -\frac{2\gamma}{N_c}\!
     \Bigl[\sum_{i\in c}(z_i-\mu_c)^{\!\top}\tilde g_i
           -\Bigl(\sum_{i\in c}(z_i-\mu_c)\Bigr)^{\!\top}\tilde g_c\Bigr]
   +O(\gamma^{2}) \\[6pt]
&= -\frac{2\gamma}{N_c}\sum_{i\in c}(z_i-\mu_c)^{\!\top}\tilde g_i
   +O(\gamma^{2}).
\end{aligned}
\]

Therefore,
\[
\Delta R_c^{2} := -\frac{2\gamma}{N_c}
     \sum_{i\in c}(z_i-\mu_c)^{\!\top}\tilde g_i.
\tag{C.2}
\]
Since we are interested only in the first-order effect and \(\gamma\) is sufficiently small, the \(O(\gamma^{2})\) term has been discarded.

Define
\[
T_{\mathrm{corr},i}:=(z_i-\mu_c)^{\!\top}J_i^{\!\top}e_c,
\qquad
T_{k,i}:=(z_i-\mu_c)^{\!\top}J_i^{\!\top}e_k \;(k\ne c).
\]

Substituting (C.1) into (C.2) yields
\[
\Delta R_c^{2}\bigl(\text{one-hot}\bigr)
= -\frac{2\gamma}{N_c}
  \sum_{i\in c}\Bigl[(p_{ic}-1)\,T_{\!\mathrm{corr},i}
                     + \sum_{k\ne c} p_{ik}\,T_{k,i}\Bigr]
.
\]

\section{Gradient norm lower bound under label smoothing}
\label{appD}

\paragraph{Step 1: SVD inequality.}
Let \(J_\ell\) be the Jacobian of the cloud-side subnetwork at layer~\(\ell\).
Write its SVD \(J_\ell = U\Sigma V^{\!\top}\) with
\(\Sigma=\mathrm{diag}(\sigma_1,\dots,\sigma_r)\) and
\(\sigma_{\min}(J_\ell)=\sigma_r>0\).
For any vector \(x\in\mathbb{R}^{K}\),
\begin{equation}
\|J_\ell^{\!\top}x\|_2
   =\|\Sigma U^{\!\top}x\|_2
   \;\ge\;\sigma_{\min}(J_\ell)\,\|x\|_2 .
\tag{D.1}
\end{equation}

\paragraph{Step 2: squared norms of the logit-level gradients.}
For a sample whose true class is \(c\) we define  
\[
\delta_i = p_i-y_i, \qquad
\tilde\delta_i = p_i-y'_i ,
\]
corresponding to one-hot and label-smoothed targets, respectively.
Expanding every coordinate gives
\begin{equation}
\|\delta_i\|_2^{2}
   =(p_{ic}-1)^{2}+\sum_{k\neq c}p_{ik}^{2},
\qquad
\|\tilde\delta_i\|_2^{2}
   =(p_{ic}-1+\alpha)^{2}
   +\sum_{k\neq c}\Bigl(p_{ik}-\tfrac{\alpha}{K}\Bigr)^{2}.
\tag{D.2}
\end{equation}

At convergence \(p_{ic}\to1\) and \(p_{ik}\to0\;(k\neq c)\); substituting
these limits into (D.2) yields
\begin{equation}
\|\delta_i\|_2^{2}\longrightarrow 0,
\qquad
\|\tilde\delta_i\|_2^{2}
    \longrightarrow
    \alpha^{2}+(K-1)\!\bigl(\tfrac{\alpha}{K}\bigr)^{\!2}
    =:c_\alpha^{2}>0 .
\tag{D.3}
\end{equation}

\paragraph{Step 3: lower bounds on feature-gradient norms.}
The feature-layer gradients are
\(g_{\ell,i}=J_\ell^{\!\top}\delta_i\) (one-hot)
and \(\tilde g_{\ell,i}=J_\ell^{\!\top}\tilde\delta_i\) (LS).
Applying (D.1) to each error vector,
\[
\|g_{\ell,i}\|_2
   \;\ge\; \sigma_{\min}(J_\ell)\,\|\delta_i\|_2, 
\qquad
\|\tilde g_{\ell,i}\|_2
   \;\ge\; \sigma_{\min}(J_\ell)\,\|\tilde\delta_i\|_2 .
\]

Combining with the limits in (D.3) we obtain
\[
\|g_{\ell,i}\|_2^{\text{OH}}\!\longrightarrow 0,
\qquad
\|\tilde g_{\ell,i}\|_2^{\text{LS}}
  \;\ge\;\sigma_{\min}(J_\ell)\,c_\alpha\;>\;0 .
\]

Thus, whereas one-hot cross-entropy drives the feature-layer gradients to
vanish at convergence, label smoothing preserves a strictly positive lower
bound proportional to \(\sigma_{\min}(J_\ell)c_\alpha\).




