\section{Weakly Supervised Speech Representation Learning}
\subsection{Attention Encoder Decoder (AED)}

As for AED models, Whisper architecture is shown in Figure \ref{fig:whisper_architecture}, and Deepgram architecture is shown in Figure \ref{fig:deepgram_architecture}.


\subsubsection{Whisper Architecture}
\subsubsection{Deepgram Nova-2 Architecture}
\begin{figure*}[h]
    \centering
    \includegraphics[width=1.0\linewidth]{figures/whisper_architecture.png}
    \caption{\textbf{OpenAI's Whisper architecture}. Whisper is a Transformer-based AED architecture, using MFCC features as input.}
    \label{fig:whisper_architecture}
\end{figure*}

\begin{figure*}[h]
    \centering
    \includegraphics[width=1.0\linewidth]{figures/deepgram_architecture.PNG}
    \caption{\textbf{Deepgram's Nova-2 architecture}. To our best understanding of Deepgram's documentation, Deepgram's Nova-2 is a Transformer-based AED architecture, using raw waveform as input instead of MFCC like Whisper. Feature extraction from raw waveform is probably  conducted by a learnable feature encoder, e.g. a block of CNNs like wav2vec 2.0. Between encoder-decoder space, (unknown) acoustic embeddings are probably added as cross-attention.}
    \label{fig:deepgram_architecture}
\end{figure*}

An ASR model is used to transcribe speech into text by mapping an audio signal $x^{T}_{1} := x_{1}, x_{2}, ..., x_{T}$ of length $T$ to the most likely word sequence $w^{N}_{1}$ of length $N$. The word sequence probability is described as:

\begin{equation}
\label{eq:word_sequence_general}
p(w_{1}^{N}|x_{1}^{T}) = \prod_{n=1}^{N} p(w_n|w_{1}^{n-1},x_{1}^{T}).    
\end{equation}

In the ASR encoder-decoder architecture, given $D$ as the feature dimension size, the input audio signal matrix could be described as $x^{T}_{1} \in \mathbb{R}^{T \times D_{input}}$. When simplified, downsampling before or inside the encoder - conducted by a fixed factor, such as striding in a Convolutional Neural Network (CNN) - is removed. Thus, the encoder output sequence is as follows:

\begin{equation}
%$$
h_{1}^{T} = Encoder(x_{1}^{T}) \in \mathbb{R}^{T \times D_{encoder}}. 
%$$
\end{equation}

Using a stack of Transformer (\scalebox{1.44}{$\tau$}) blocks \cite{vaswani2017attention}, the encoder output sequence is described as function composition:
\begin{equation}
%$$
h_{1}^{T} = {\scalebox{1.44}{$\tau$}}_{0} \circ ... \circ {\scalebox{1.44}{$\tau$}}_{N_{EncLayers}}(x_{1}^{T}).
%$$
\end{equation}

In the decoder, the probability for each single word is defined as:

\begin{equation}
\begin{split}
p(w_n|w_{1}^{n-1},x_{1}^{T}) &= p(w_n|w_{1}^{n-1},h_{1}^{T}(x_{1}^{T}))\\
&= p(w_n|w_{1}^{n-1},h_{1}^{T}). 
\end{split}   
\end{equation}

Based on Equation \ref{eq:word_sequence_general}, the word sequence probability given the output of encoder is described as:
\begin{equation}
%$$
p(w_{1}^{N}|x_{1}^{T}) = \prod_{n=1}^{N} p(w_n|w_{1}^{n-1},h_{1}^{T}).    
%$$
\end{equation}

Then, decoder hidden state is formulated as:
\begin{equation}
%$$
g_n = \mathcal{F}(g_{n-1},w_{n-1}, c_n) \in \mathbb{R}^{D_{g}},
%$$
\end{equation}
where $\mathcal{F}$ is neural network; $D_{g}$ is hidden state dimension; and $c_n$ is context vector, e.g. weighted sum of encoder outputs via attention mechanism.

The attention mechanism in the decoder is described via 3 components: context vector $c_n$, attention weights $\alpha_{n,t}$, and attention energy $e_{n,t}$:

\begin{equation}
\begin{split}
c_n &= \sum_{t=1}^{T} \alpha_{n,t} {h}_{t} \in \mathbb{R}^{D_{encoder}},\\
\alpha_{n,t} &= \frac{\exp(e_{n,t})}{\sum_{t'=1}^{T}\exp(e_{n,t'})} \\
&= Softmax_{T}(\exp(e_{n,t})) \in \mathbb{R},\\
e_{n,t} &= Align(g_{n-1}, h_t) \in \mathbb{R} \\
&= W_{2} \cdot \tanh(W_{1} \cdot [g_{n-1}, h_t]),
\end{split}
\end{equation}
where $n$ is decoder step; $t$ is encoder frame; $\alpha \in \mathbb{R}^{T \times N}$ is attention weight matrix; $\alpha_n \in \mathbb{R}^{T}$ is normalized probability distribution over $t$; $Softmax_{T}$ is Softmax function over spatial dimension $T$, not feature dimension; $W_{1} \in \mathbb{R}^{(D_{g}+D_{encoder}) \times D_{key}}$; $W_{2} \in \mathbb{R}^{D_{key}}$.

In the decoding, the output probability distribution over vocabulary is defined as:
\begin{equation}
\begin{split}
&p(w_{n} = *|w_{1}^{n-1}, h_{1}^{T})\\
&= Softmax(MLP(w_{n-1}, g_n, c_n)) \in \mathbb{R}^{N}, 
\end{split}
\end{equation}
where $MLP$ is Multi-layer Perceptron.

To train an AED model,  sequence-level frame-wise cross-entropy loss is employed:
\begin{equation}
\begin{split}
\mathscr{L}_{AED} &= - \sum_{(x_{1}^{T}, w_{1}^{N})} \log p(w_{1}^{N}|x_{1}^{T})\\
&= - \sum_{(x_{1}^{T}, w_{1}^{N})} \sum_{n=1}^{N} \log p(w_n|w_{1}^{n-1},x_{1}^{T}).
\end{split}
\end{equation}

During beam search, the auxilary quantity for each unknown partial string (tree of partial hypotheses) $w_{1}^{n}$ is defined as:
\begin{equation}
\begin{split}
Q(n; w_{1}^{n}) :&= \prod_{n'=1}^{n} p(w_{n'}|w_{0}^{n'-1},x_{1}^{T})\\
&= p(w_{n}|w_{0}^{n-1},x_{1}^{T}) \cdot Q(n-1, w_{1}^{n-1}).
\end{split}
\end{equation}

After discarding the less likely hypotheses in the beam search, the word sequence probability is calculated by the best hypothesis:
\begin{equation}
%$$
p(w_{1}^{N}|x_{1}^{T}) = Q(N; w_{1}^{N}).    
%$$
\end{equation}

