\section{Proof}
\label{app:proof}

\textbf{Property 1.}
$\mathcal{L}^{nav}_b$ \textit{is bounded as follows:}
\begin{equation}
    \begin{split}
    \mathcal{L}^{nav}_b \leq \left|\left(\nabla_{\theta_{b-1}}\mathcal{L}^{pkt}(\theta_{b-1})\right)^{T}\right| \cdot\left|\delta \theta_{b-1}\right|+\left|\delta \theta_{b-1}\right|^T \cdot|J^{T}J| \cdot\left|\delta \theta_{b-1}\right|,
    \label{eq:app_l_nav_bound}
    \end{split}
\end{equation}
where $J$ is the Jacobian matrix~\cite{wilamowski2010improved}.
The proof is as follows:
\begin{proof}
Given the following equations,
\begin{equation}
    \begin{split}
        \mathcal{L}^{nav}_b=\left|\sum_{u=1}^{N}\sum_{t=1}^{T_{u}}\mathcal{L}_{u,t}^{pkt}(\theta_{b})-\sum_{u=1}^{N}\sum_{t=1}^{T_{u}}\mathcal{L}_{u,t}^{pkt}(\theta_{b-1})\right|,\;\delta\theta_{b-1}=\theta_{b}-\theta_{b-1},
    \end{split}
\end{equation}
and let $\mathcal{L}^{pkt}(\theta_{b})$ and $\mathcal{L}^{pkt}(\theta_{b-1})$ denote $\sum_{u=1}^{N}\sum_{t=1}^{T_{u}}\mathcal{L}_{u,t}^{pkt}(\theta_{b})$ and $\sum_{u=1}^{N}\sum_{t=1}^{T_{u}}\mathcal{L}_{u,t}^{pkt}(\theta_{b-1})$ respectively, we take the Taylor expansion of $\mathcal{L}^{pkt}(\theta_{b-1})$ at point $\theta_{b-1}$, which is an infinite sum of terms that are expressed in the form of loss function’s derivatives at a single point:
\begin{equation}
    \begin{split}
        \mathcal{L}^{pkt}(\theta_{b-1}+\delta\theta_{b-1})&=\mathcal{L}^{pkt}(\theta_{b-1})+\left(\nabla_{\theta_{b-1}}\mathcal{L}^{pkt}(\theta_{b-1})\right)^{T}\cdot \delta \theta_{b-1} \\
& +\frac{1}{2}\left(\delta \theta_{b-1}\right)^T \cdot H \cdot \delta \theta_{b-1}+O\left(\left\|\delta \theta_{b-1}\right\|^3\right),
    \end{split}
    \label{eq:app_original_l}
\end{equation}
where $H$ denotes Hessian matrix:
\begin{equation}
    \begin{split}
        H=\nabla_{\theta_{b-1}}\mathcal{L}^{pkt}(\theta_{b-1}).
    \end{split}
\end{equation}
% Then obtaining the prediction performance of our model on the $(b-1)$-th training batch corresponds to minimize the following objective function:
Then $\mathcal{L}^{nav}_b$ can be derived as:
\begin{equation}
    \begin{split}
        \mathcal{L}^{nav}_b&=\left|\mathcal{L}^{pkt}(\theta_{b})-\mathcal{L}^{pkt}(\theta_{b-1})\right| \\
        &=\left|\mathcal{L}^{pkt}(\theta_{b-1}+\delta\theta_{b-1})-\mathcal{L}^{pkt}(\theta_{b-1})\right|\\
        &\approx\left|\left(\nabla_{\theta_{b-1}}\mathcal{L}^{pkt}(\theta_{b-1})\right)^{T}\cdot \delta \theta_{b-1}+\frac{1}{2}\left(\delta \theta_{b-1}\right)^T \cdot H \cdot \delta \theta_{b-1}\right|.
        \label{eq:app_performance}
    \end{split}
\end{equation}
It is evident that Eq.(\ref{eq:app_performance}) significantly reduces the computational demands on each training datum compared to Eq.(\ref{eq:app_original_l}), thereby accelerating the calculation of the total loss. However, the storage requirements associated with Hessian matrices remain substantial~\cite{zhou2021image}. Therefore, drawing inspiration from the Gauss-Newton method~\cite{wilamowski2010improved}, we approximate $H$ as $2\cdot J^{T}J$ for the Hessian matrix, where $J$ represents the Jacobian matrix. Consequently, we arrive at the final formulation of $\mathcal{L}^{nav}_b$ as follows:
\begin{equation}
    \begin{split}
        \mathcal{L}^{nav}_b&\approx\left|\left(\nabla_{\theta_{b-1}}\mathcal{L}^{pkt}(\theta_{b-1})\right)^{T}\cdot \delta \theta_{b-1}+\left(\delta \theta_{b-1}\right)^T \cdot J^{T}J \cdot \delta \theta_{b-1}\right|\\
        &\leq \left|\left(\nabla_{\theta_{b-1}}\mathcal{L}^{pkt}(\theta_{b-1})\right)^{T}\right| \cdot\left|\delta \theta_{b-1}\right|+\left|\delta \theta_{b-1}\right|^T \cdot|J^{T}J| \cdot\left|\delta \theta_{b-1}\right|\\
        \label{eq:app_final_l_nav}
    \end{split}
\end{equation}
where $|\cdot|$ in the Eq.~(\ref{eq:app_final_l_nav}) denotes element-wise absolute value in our implementation. The proof is completed.
