\vspace{-0.5cm}
\begin{algorithm}
\caption{The training and test of PKT backbone models}\label{train_test_algo}
\begin{algorithmic}[1]
\REQUIRE Training dataset $D_{train}$, test dataset $D_{test}$, learning rate $\alpha$, number of epochs $N$
\ENSURE Trained PKT backbone model $M$
\STATE Initialize model parameters $W$ randomly
\STATE \textbf{Training started}
\FOR{$epoch=1$ \TO $N$}
    \FORALL{$l_u \in D_{train}$}
        \STATE // $l_u$ denotes a programming sequence of learner $u$ and its length is $T_u$
        \FOR{$t=1$ \TO $T_u-1$}
            \STATE Compute programming performance at the next step $\hat{r}_{u,t+1} = M(l_{u,1:t}; W)$
            \STATE // $l_{u,1:t}$ is programming records of $u$ from step $1$ to $t$
            \STATE Compute cross-entropy loss $\mathcal{L}_{u,t}^{pkt} = BCE\left(r_{u,t+1},\hat{r}_{u,t+1}\right)$
            \STATE Update parameters $W = W - \alpha \nabla \mathcal{L}_{u,t}^{pkt}$
        \ENDFOR
    \ENDFOR
\ENDFOR
\STATE \textbf{Training completed}
\STATE \textbf{}
\STATE \textbf{Testing started}
\FORALL{$l_u \in D_{test}$}
    \FOR{$t=1$ \TO $T_u-1$}
        \STATE Compute programming performance at the next step $\hat{r}_{u,t+1} = M(l_u; W)$
        \STATE Compute performance metric using $r_{u,t+1}$ and $\hat{r}_{u,t+1}$
    \ENDFOR
\ENDFOR
\STATE \textbf{Testing completed}
% \RETURN Trained PKT backbone model $M$
\end{algorithmic}
\end{algorithm}


