\begin{algorithm}[h]
\caption{The Algorithm of Coda (Part 1)}
\label{algo:coda-pkt}
\begin{algorithmic}[1]
\STATE \textbf{Input:} $N$ learners' programming sequences $\{l_1, l_2, \cdots, l_N\}$, the optimized backbone PKT model $\mathcal{M}_{PKT}$, correct solution feature set $\{\mathcal{S}_{q_j}\}_{j=1}^{M}$ of $M$ questions, training set $\mathcal{D}_{train}$, test set $\mathcal{D}_{test}$.
\STATE \textbf{Parameters ($\theta$):} $\mathbf{W}$, $\mathbf{W}_a$, $\mathbf{W}_c$, $\mathbf{W}_A$, $\mathbf{W}_B$.

\STATE \textbf{Function} \texttt{CodeGraphConstruction}($l_u$):
\STATE \quad // \textit{Construct code graph based on code semantic similarity.}
\STATE \quad // $l_{u}=\{(q_{u,1}, c_{u,1}, x_{u,1}, r_{u,1}), \dots, (q_{u,T_u}, c_{u,T_u}, x_{u,T_u}, r_{u,T_u})\}$
\STATE \quad \textbf{For each} pair of codes $<x_{u,i}, x_{u,j}>$ in $l_u$:
\STATE \quad \quad Calculate indicator matrix $M_{u,<i,j>}$.
\STATE \quad \textbf{End for}
\STATE \quad Generate binary adjacency matrix $A_{u}$ via $\text{Rank}_{\epsilon}$.
\STATE \quad \textit{// Note that $A_{u}$ may not guarantee a connected graph, and it may contain $n$ subgraphs.}
\STATE \quad \textbf{Return} code graph set: $\{G_{u,i}\}_{i=1}^{n}$, isolated code set: $\mathcal{I}_{u}$.

\STATE \textbf{Function} \texttt{UnwantedSignalsIdentification}($\mathcal{I}_{u}$, $\{\mathcal{S}_{q_j}\}_{j=1}^{M}$, $\{G_{u,i}\}_{i=1}^{n}$):
\STATE \quad // \textit{Identify unwanted submissions from isolated nodes.}
\STATE \quad Initialize an unwanted set $\mathcal{I}_{u}^{*} \leftarrow \emptyset$
\STATE \quad \textbf{For each} isolated node $i \in \mathcal{I}_{u}$:
\STATE \quad \quad Obtain question ID $q_{u,i}$ corresponding to code $i$
\STATE \quad \quad \textbf{For each} ${x}_{u,j'}$ in $\mathcal{S}_{q_{u,i}}$:
\STATE \quad \quad \quad $s_{i,j'} \leftarrow {\rm sim}(\mathbf{W} \odot \vec{x}_{u,i}, \mathbf{W} \odot \vec{x}_{u,j'})$.
\STATE \quad \quad \textbf{End for}
\STATE \quad \quad $S_{i} \leftarrow \{s_{i,j'}; j' \in \mathcal{S}_{q_{u,i}}\}$
\STATE \quad \quad \textbf{If} mean($S_i$) $<$ median($S_i$):
\STATE \quad \quad \quad Mark node $i$ as unwanted and $\mathcal{I}_{u}^{*} \cup \{i\}$.
\STATE \quad \quad \textbf{Else}:
\STATE \quad \quad \quad Link code node $i$ with $\{G_{u,i}\}_{i=1}^{n}$.
\STATE \quad \textbf{End for}
\STATE \quad \textbf{Return} unwanted set: $\mathcal{I}_{u}^{*}$, updated code graphs: $\{G_{u,i}\}_{i=1}^{n}$.

\STATE \textbf{Function} \texttt{ClusterAwareWeakSignalFusion}($\{G_{u,i}\}_{i=1}^{n}$, $\{\vec{x}_{u,i}\}_{i=1}^{T_u}$, $C_k$, $L$):
\STATE \quad // \textit{Apply} $L$-\textit{layer cluster-aware GCN to update node features.}
\STATE \quad $\{\vec{x'}_{u,i}\}_{i=1}^{T_u} \leftarrow \mathbf{GCN}(\{\vec{x}_{u,i}\}_{i=1}^{T_u}, \{G_{u,i}\}_{i=1}^{n}, \mathbf{W}, \mathbf{W_{a}}, \mathbf{W_{c}})$
\STATE \quad $C_k$ clusters $\leftarrow \text{KMeans}(\{\vec{x'}_{u,i}\}, C_k)$.
\STATE \quad Mark core submissions and weak signals for each cluster.
\STATE \quad \textbf{Return} a core submission and its related weak signal set for each cluster $cl$: $\{(C_{u,cl}, \mathcal{W}_{u,cl})\}_{cl=1}^{C_k}$.
\end{algorithmic}
\end{algorithm}

