\section{Algorithms}
\label{app:algo}
% \subsection{The Training and Test of PKT}
% \label{app:train_test_algo}
Algorithm~\ref{train_test_algo} shows the pseudo-code of training and testing a PKT backbone model.
% \subsection{The Algorithm of Coda}
Algorithms~\ref{algo:coda-pkt} and \ref{algo:coda-pkt2} show the workflow of Coda.

\begin{algorithm}
\caption{The Algorithm of Coda (Part 2)}
\label{algo:coda-pkt2}
\begin{algorithmic}[1]
\STATE \textbf{BEGIN MAIN FUNCTION:}
\STATE \textbf{Initialize:} learning rate $lr$, $epoch \leftarrow 0$, $BatchSize$, $TotalEpoch$, the number of clusters $C_k$, the number of GCN layers $L$.
\STATE // \textit{Training process:}
\STATE \textbf{repeat}
\STATE \quad \textbf{For} $b$ from $1$ to $|\mathcal{D}_{train}| / BatchSize$:
\STATE \quad \quad Initialize prediction loss $\mathcal{L}^{p} \leftarrow 0$
\STATE \quad \quad \textbf{For each} $u \in \mathcal{D}_{train_b}$:
\STATE \quad \quad \quad $\{G_{u,i}\}_{i=1}^{n}$, $\mathcal{I}_{u} \leftarrow$ \texttt{CodeGraphConstruction}($l_u$).
\STATE \quad \quad \quad $\mathcal{I}_{u}^{*}$, $\{G_{u,i}\}_{i=1}^{n} \leftarrow$ \texttt{UnwantedSignalsIdentification}($\mathcal{I}_{u}$, $\{\mathcal{S}_{q_j}\}_{j=1}^{M}$, $\{G_{u,i}\}_{i=1}^{n}$).
\STATE \quad \quad \quad $\{(C_{u,cl}, \mathcal{W}_{u,cl})\}_{cl=1}^{C_k} \leftarrow$ \texttt{ClusterAwareWeakSignalFusion}($\{G_{u,i}\}_{i=1}^{n}$, $\{\vec{x}_{u,i}\}_{i=1}^{T_u}$, $C_k$, $L$).

\STATE \quad \quad \quad // \textit{Tuning Adaptor for PKT}
\STATE \quad \quad \quad \textbf{For} $t$ from 1 to $T_u-1$:
\STATE \quad \quad \quad \quad Construct prompt $\vec{p}_u,t$ via $\mathcal{I}_{u}$, $\{(C_{u,cl}, \mathcal{W}_{u,cl})\}_{cl=1}^{C_k}$.
\STATE \quad \quad \quad \quad // \textit{Calculate correction signal.}
\STATE \quad \quad \quad \quad $\vec{h'}_{t_{u,a}} \leftarrow (\mathbf{W}_{A}^{T} \cdot \mathbf{W}_{B}) \odot \vec{p}_{u,t}$.
\STATE \quad \quad \quad \quad // \textit{Update knowledge state $\vec{h}_{u,t}$ learned by the PKT backbone $\mathcal{M}_{PKT}$.}
\STATE \quad \quad \quad \quad $\vec{h'}_{u,t} \leftarrow \vec{h}_{u,t} + \vec{h'}_{u,t_{a}}$.
\STATE \quad \quad \quad \quad // \textit{Compute programming performance at the step $t+1$ via programming records of $u$ from step $1$ to $t$.}
\STATE \quad \quad \quad \quad $\hat{r}_{u,t+1} = \mathcal{M}_{PKT}(l_{u,1:t}; \vec{h'}_{u,t})$
\STATE \quad \quad \quad \quad Compute loss $\mathcal{L}_{p} = \mathcal{L}_{u,t}^{pkt} + \mathcal{L}_{u,t}^{adaptor}$.
\STATE \quad \quad \quad \textbf{End for}
\STATE \quad \quad \textbf{End for}
\STATE \quad \quad Calculate $\theta_{b} \leftarrow \theta_{b-1} - lr \cdot \nabla_{\theta} \mathcal{L}^{p}$, without gradient backpropagating.

\STATE \quad \quad Calculate $\mathcal{L}^{nav}_b$ via $\theta_{b}$, $\theta_{b-1}$.
\STATE \quad \quad $\mathcal{L}^{Coda} \leftarrow \mathcal{L}_{p} + \mathcal{L}^{nav}_b$
\STATE \quad \quad Update parameters $\theta_{b} \leftarrow \theta_{b-1} - lr \cdot  \nabla_{\theta} \mathcal{L}^{nav}_b$, with gradient backpropagating.
\STATE \quad \textbf{End for}
\STATE \textbf{until} $epoch$ \textbf{equals} $TotalEpoch$


\STATE // \textit{Test process:}

\STATE \textbf{For each} $u \in \mathcal{D}_{test}$:
\STATE \quad \textbf{For} $t$ from 1 to $T_u-1$:
\STATE \quad \quad $\{G_{u,i}\}_{i=1}^{n}$, $\mathcal{I}_{u} \leftarrow$ \texttt{CodeGraphConstruction}($l_{u,1:t}$).
\STATE \quad \quad $\mathcal{I}_{u}^{*}$, $\{G_{u,i}\}_{i=1}^{n} \leftarrow$ \texttt{UnwantedSignalsIdentification}($\mathcal{I}_{u}$, $\{\mathcal{S}_{q_j}\}_{j=1}^{M}$, $\{G_{u,i}\}_{i=1}^{n}$).
\STATE \quad \quad $\{(C_{u,cl}, \mathcal{W}_{u,cl})\}_{cl=1}^{C_k} \leftarrow$ \texttt{ClusterAwareWeakSignalFusion}($\{G_{u,i}\}_{i=1}^{n}$, $\{\vec{x}_{u,i}\}_{i=1}^{T_u}$, $C_k$, $L$).
\STATE \quad \quad Construct prompt $\vec{p}_u,t$ via $\mathcal{I}_{u}$, $\{(C_{u,cl}, \mathcal{W}_{u,cl})\}_{cl=1}^{C_k}$.
\STATE \quad \quad $\vec{h'}_{t_{u,a}} \leftarrow (\mathbf{W}_{A}^{T} \cdot \mathbf{W}_{B}) \odot \vec{p}_{u,t}$.
\STATE \quad \quad $\vec{h'}_{u,t} \leftarrow \vec{h}_{u,t} + \vec{h'}_{u,t_{a}}$.
\STATE \quad \quad $\hat{r}_{u,t+1} = \mathcal{M}_{PKT}(l_{u,1:t}; \vec{h'}_{u,t})$
\STATE \quad \quad Compute performance metric using $r_{u,t+1}$ and $\hat{r}_{u,t+1}$.
\STATE \quad \textbf{End for}
\STATE \textbf{End for}
\end{algorithmic}
\end{algorithm}


