\section{Preliminaries}
\label{sec:preliminaries}
We recall coalgebraic semantics for transition systems, which has been widely used in the literature (e.g.~\cite{HinoKH016,UrabeHH17,Kori0RK24,WatanabeJRH25}). Given a coalgebra $c\colon X\rightarrow FX$ of an endofunctor $F$ modelling a system, 
the semantics of $c$ is given by a least fixed point of a specific \emph{predicate transformer} of $c$ that is induced by a \emph{modality}. 

Throughout the paper, we consider coalgebras $c\colon X\rightarrow FX$ on the category of sets ($\sets$), thus $F$ is an endofunctor on the category of sets. A \emph{semantic structure} for $F$ is given by a pair $(\mathbf{\Omega}, \tau)$ such that (i) $\mathbf{\Omega}$ is an $\omega$-complete partially ordered set $(\Omega, \preceq)$ with the least element $\bot$; 
and (ii) $\tau$ is a function $\tau\colon F\Omega\rightarrow \Omega$. We call $\mathbf{\Omega}$ and $\tau$ \emph{semantic domain} and \emph{modality} (for $F$), respectively. 

\begin{definition}[predicate transformer]
    Given a coalgebra $c\colon X\rightarrow FX$ and a semantic structure $(\mathbf{\Omega}, \tau)$ for $F$, the \emph{predicate transformer} $\Phi_{c}$ of $c$ is a function $\Phi_c\colon \Omega^X \rightarrow \Omega^X$ given by $\Phi_c(u) \defeq \tau \circ F(u)\circ c$ for each $u\in \Omega^X$. 
    Additionally, we assume that $\Phi_{c}$ is $\omega$-continuous with respect to the pointwise order in $\Omega^X$. 
\end{definition}

By the Kleene-fixed point theorem, the predicate transformer $\Phi_c$ has the least fixed point $\mu \Phi_c = \bigvee_{n\in \nat} \Phi^n(\bot)$. 
\begin{definition}[semantics]
    Given a coalgebra $c$ and a semantic structure $(\mathbf{\Omega}, \tau)$, 
    the \emph{semantics} is the least fixed point $\mu \Phi_c \in \Omega^X$ of the predicate transformer $\Phi_c$. 
\end{definition}


We recall the coalgebraic semantics of (labelled) Markov chains (MCs) and \emph{deterministic finite automaton (DFA)}.   
\begin{example}[semantics of MC] \label{eg:mc}
    We define a \emph{(labelled) MC} as a coalgebra $c\colon X\rightarrow\mcfunc{X}$. 
    The semantic structure $(\mathbf{\Omega}, \tau)$ is given by (i) $\mathbf{\Omega} \defeq (\traceMC, \preceq)$, where $\preceq$ is the pointwise order; and (ii) $\tau \colon \mcfunc{\traceMC} \rightarrow \traceMC$ is given by 
    \begin{align*}
        \tau(\sigma, a)(w) \defeq \begin{cases*}
            \sigma(\checkmark) &if  $w = a$,\\
            \sum_{\mu \in \subdistcount(A^+)}\sigma(\mu) \cdot \mu(w') &if   $w = a\cdot w'$ for some $w' \in A^+$,\\
            0 &otherwise.
        \end{cases*}
    \end{align*}
    The least fixed point of the predicate transformer $\Phi_c$ gives 
    the reachability probability $\mu \Phi_c(x)(w)\in [0, 1]$ from each state $x\in X$ to the target $\checkmark$ with the trace $w\in A^{+}$. 
\end{example}

\begin{example}[semantics of DFA]
    We define a DFA\footnote{Following~\cite{WatanabeJRH25}, the acceptance condition is given by the output, as in Mealy machines.} as a coalgebra $d\colon Y\rightarrow \dfafunc{Y}$. 
    The semantic structure $(\mathbf{\Omega}, \tau)$ is given by (i) 
    $\mathbf{\Omega} \defeq(\traceDFA, \subseteq)$, where $\subseteq$ is the inclusion order; and (ii) $\tau \colon \dfafunc{\traceDFA} \rightarrow \traceDFA$ is given by 
    \begin{align*}
        \tau(\delta)\defeq \big\{a\in A \mid \pi_2 \big(\delta(a)\big) = \top\big\} \cup \big\{a\cdot w\in A^{+} \mid w \in \pi_1 \big(\delta(a)\big) \big\}.
    \end{align*}
    % \begin{align*}
    %     \tau(\sigma)(w) \defeq \begin{cases*}
    %         \sigma(\checkmark) &\text{ if } $w = a$,\\
    %         \sum_{\mu \in \sigma }\sigma(\mu) \cdot \mu(w') &\text{ if }  $w = a\cdot w'$.\\
    %     \end{cases*}
    % \end{align*}
    The least fixed point of the predicate transformer $\Phi_d$ yields
    the recognized language with excluding the empty string, as $\mu \Phi_d(y)\in \traceDFA$ 
    for each state $y\in Y$. 
\end{example}



\section{Coalgebraic Product Construction}
\label{sec:coprodconst}
We introduce the coalgebraic product construction~\cite{WatanabeJRH25}, which is the foundation for our study of product constructions.
% Given two coalgebras $c\colon X\rightarrow F_S X$ and $d\colon X\rightarrow F_R X$, 
% a \emph{coalgebraic product} of $c$ and $d$ is induced by a \emph{distributive law} $\lambda_{X, Y}\colon F_SX \times F_RY \rightarrow F_{S\otimes R} (X\times Y) $ with an endofunctor $F_{S\otimes R}$.
The coalgebraic product construction employs 
a natural transformation $\lambda$ called a \emph{distributive law}
to merge behaviours of two coalgebras.
% a \emph{distributive law} $\lambda_{X, Y}\colon F_SX \times F_RY \rightarrow F_{S\otimes R} (X\times Y) $ with an endofunctor $F_{S\otimes R}$.
% an endofunctor $F_{S\otimes R}$, representing the product type,

\begin{definition}[distributive law, coalgebraic product]
    Let $F_S$, $F_R$, and $F_{S\otimes R}$ be endofunctors.
    A \emph{distributive law} $\lambda$ from $F_S$ and $F_R$ to $F_{S\otimes R}$ is a natural transformation 
    $\lambda\colon \times \circ F_S \times F_R \Rightarrow F_{S\otimes R}\circ \times$. 
    Given two coalgebras $c\colon X\rightarrow F_S X$ and $d\colon Y\rightarrow F_R Y$,
     the \emph{coalgebraic product} $c\otimes_{\lambda} d$ induced by the distributive law $\lambda$ is defined as the coalgebra: 
     \begin{displaymath}
     c\otimes_{\lambda} d\colon X\times Y\rightarrow F_{S\otimes R} (X\times Y),  \quad c\otimes_{\lambda} d \defeq \lambda_{X, Y}\circ (c\times d). 
     \end{displaymath}
\end{definition}

\begin{example}[product of MC and DFA]
    \label{ex:prodMCDFA}
    Define a distributive law $\lambda$ from $\mcfunc{(\_)}$ and $\dfafunc{(\_)}$ to $\mcfuncproduct{(\_)}$ by
    \begin{align*}
        \lambda_{X, Y}(z)(x, y)&\defeq \begin{cases}
            \sigma(x) &\text{ if } y = \pi_1 \big(\delta(a)\big),\\
            0 &\text{ otherwise,}
        \end{cases} 
         &\lambda_{X, Y}(z)(\checkmark) \defeq \begin{cases}
            \sigma(\checkmark) &\text{ if } \top = \pi_2 \big(\delta(a)\big),\\
            0 &\text{ otherwise,}
        \end{cases}
    \end{align*}
    where $z = (\sigma, a, \delta)\in \mcfunc{X}\times\dfafunc{Y}$.
    Then the coalgebraic product $c \otimes_\lambda d$ of an MC $c\colon X\rightarrow\mcfuncproduct{X}$ and a DFA $d\colon Y\rightarrow \dfafunc{Y}$ is the standard product of the MC and the DFA, e.g.~\cite{baierKatoen, WatanabeJRH25}.
\end{example}

It is worth emphasizing that the coalgebraic product $c\otimes_{\lambda} d$ is itself a coalgebra.
This allows its semantics to be defined in the same manner as for its components, using a semantic structure $(\mathbf{\Omega}_{S\otimes R}, \tau_{S\otimes R})$.
\begin{example}[semantics of the product]
  \label{ex:semanticsProduct}
  Consider~\cref{ex:prodMCDFA}.
  % The distributive law $\lambda_{X, Y}$ given in~\cref{ex:prodMCDFA} defines the product of MCs and DFAs.
  We define the semantic structure $(\mathbf{\Omega}_{S\otimes  R}, \tau_{S\otimes R})$ as follows: (i) 
  $\mathbf{\Omega}_{S\otimes R} \defeq ([0, 1], \leq)$, where $\leq$ is the standard order; and (ii) $\tau_{S\otimes R}\colon \mcdfafunc{[0, 1]} \rightarrow [0, 1]$ is given by $\tau_{S\otimes R}(\sigma) \defeq \sigma(\checkmark) + \sum_{r\in [0, 1]}r \cdot \sigma(r)$. 
  Under this semantic structure, the semantics $\mu \Phi_{c \otimes_\lambda d}$ of the product gives, for each $(x, y)$, the reachability probability from $(x, y)$ to the target state $\checkmark$. 
\end{example}

We then move on to the \emph{correctness} of coalgebraic products.
This notion is defined with respect to an \emph{inference map} $q\colon \Omega_S\times \Omega_R \rightarrow \Omega_{S\otimes R}$, where $\Omega_S$ and $\Omega_R$ are the underlying sets of semantic domains $\mathbf{\Omega_S}$ and $\mathbf{\Omega_R}$  of $c$ and $d$, respectively.  

\begin{definition}[inference map, correctness]
    Let $c\colon X\rightarrow F_S X$ and $d\colon Y\rightarrow F_R Y$ be coalgebras, $\lambda$ be a distributive law $\lambda_{X, Y}\colon (F_S X) \times (F_R Y)\rightarrow F_{S\otimes R} (X\times Y)$, and $(\mathbf{\Omega}_S, \tau_S)$,  $(\mathbf{\Omega}_R, \tau_R)$, and  $(\mathbf{\Omega}_{S\otimes R}, \tau_{S\otimes R})$ be semantic structures for $F_S, F_R$ and $F_{S\otimes R}$, respectively. 
    An \emph{inference map} is a function $q\colon \Omega_S\times\Omega_R \rightarrow \Omega_{S\otimes R} $ such that 
    \begin{enumerate}
      \item  $q(\bot, \bot) = \bot$; and
      \item $\bigvee_{l\in \nat} q(u_l,  v_l) = q\big(\bigvee_{m\in \nat}u_m,  \bigvee_{n\in \nat}v_n \big)$ for each $\omega$-chains $(u_m)_{m\in \nat}$ and $(v_n)_{n\in \nat}$.    
    \end{enumerate}
    The coalgebraic product $c\otimes_{\lambda} d$ is said to be \emph{correct w.r.t.~$q$} if 
        $q \circ (\mu \Phi_c \times \mu \Phi_d) = \mu \Phi_{c\otimes_{\lambda} d}$ holds. 
\end{definition}

\begin{example}
    \label{ex:correctnessMCDFA}
    Consider~\cref{ex:prodMCDFA,ex:semanticsProduct}.
    % The distributive law $\lambda_{X, Y}$ given in~\cref{ex:prodMCDFA} defines the product of MCs and DFAs.
    The coalgebraic product $c \otimes_\lambda d$ is correct w.r.t.~the inference map $q\colon\traceMC\times \traceDFA\rightarrow [0, 1]$ defined by $q(\sigma, L) \defeq \sum_{w\in L}\sigma(w)$.
    This means that the semantics of the products---the reachability probabilities---coincides with the probability that traces of MCs are accepted by DFAs.  
\end{example}

A simple \emph{correctness criterion} that ensures the correctness of the coalgebraic product is proposed in~\cite{WatanabeJRH25}. 
This criterion is indeed general enough to capture a wide range of known product constructions in the literature~\cite{baierKatoen,AndovaHK03,BaierDDKK14,BaierAFK18}, including the one illustrated in~\cref{ex:correctnessMCDFA}.  
\begin{proposition}[correctness criterion~\cite{WatanabeJRH25}]
    \label{prop:correctCriterion}
    Assume the following data: 
    \begin{itemize}
        \item a distributive law $\lambda$ from $F_S$ and $F_R$ to $F_{S\otimes R}$, 
        \item semantic structures $(\mathbf{\Omega}_S, \tau_S)$,  $(\mathbf{\Omega}_R, \tau_R)$, and  $(\mathbf{\Omega}_{S\otimes R}, \tau_{S\otimes R})$ for $F_S$, $F_R$, and $F_{S\otimes R}$, respectively,
        \item an inference map $q\colon \Omega_S \times \Omega_R \to \Omega_{S \otimes R}$.
    \end{itemize}
    Then for any coalgebras $c\colon X\rightarrow F_SX$ and  $d\colon Y\rightarrow F_RY$,
    the coalgebraic product $c\otimes_{\lambda} d$ is correct w.r.t.~$q$ if the following equation holds: 
      $q\circ (\tau_S\times \tau_R) = \tau_{S\otimes R}\circ F_{S\otimes R}(q)\circ \lambda_{\Omega_S, \Omega_R}$. \qed
    % \begin{equation}
    %     \label{eq:coherence_evaluation}
    %     \begin{tikzcd}
    %             F_S(\Omega_S)\times F_R(\Omega_R)\arrow[rr,"\tau_S\times \tau_R"] \arrow[d,"\lambda_{\Omega_S, \Omega_R}"]
    %             & 
    %             &\Omega_S\times \Omega_R \arrow[d,"q"]\\
    % F_{S\otimes R}(\Omega_S\times\Omega_R) \arrow[r,"F_{S\otimes R}(q)"]
    %             & F_{S\otimes R}(\Omega_{S\otimes R}) \arrow[r, "\tau_{S\otimes R}"]
    %             & \Omega_{S\otimes R}
    %     \end{tikzcd}
    %   \end{equation}
\end{proposition}
The correctness criterion requires that a semantic structure $(\mathbf{\Omega}_{S\otimes R}, \tau_{S\otimes R})$ for products be explicitly specified.
This requirement arises from the practical need for efficient computation of the semantics of products.
Model checking problems should ideally be solvable by mature techniques.
For instance, the semantics described in~\cref{ex:correctnessMCDFA} can be efficiently computed by solving linear equation systems, or applying value iterations (see~\cite{baierKatoen}). 


\section{Natural Transformations for Coalgebraic Product Construction}
\label{sec:naturaltrans}
As demonstrated in~\cref{prop:correctCriterion}, 
coalgebraic product construction requires a distributive law $\lambda$, semantic structures $(\Omega_{i}, \tau_i)$ for $i \in \{S, R, S \otimes R\}$, and an inference map $q$.
Before exploring these structures in concrete settings,
we begin by studying natural transformations between endofunctors on $\sets$ that arise from commutative monoids (see Def.~\ref{def:func_cmon}).
The results established in this section enable us to prove a no-go theorem and uniqueness of distributive laws for coalgebraic products in later sections.
% distributive laws in view of commutative monoids.
%  in general
% enough to cover all distributive laws in our examples.

\newcommand{\CMon}{\mathbf{CMon}}
We write $\CMon$ for the category of commutative monoids.
For a commutative monoid $A$,
the binary operator is denoted by $+_A$ and  the unit element by $0_A$;
when the context is clear, 
we omit these subscripts for simplicity.
For $n \in \mathbb{N}$ and $a \in A$, we define $n \cdot a$ as the sum of $n$ copies of $a$, with $0 \cdot a = 0$.
\begin{definition} \label{def:func_cmon}
  % Let $(A, \lor, \bot)$ be a commutative monoid.
  We define a \emph{functor} $F_{(\_)}\colon \CMon \to [\sets, \sets]$ as follows. 
  For each $A \in \CMon$, the \emph{functor} $F_A$ is defined by 
  \begin{align*}
    &F_A(X) \coloneqq \{h\colon X \to A \mid \supp(h) \text{ is finite} \}, 
    &&F_A(g)(f) \coloneqq \sum_{x \in g^{-1}(\_)} f(x), 
  \end{align*}
  for each $X \in \sets$, $g\colon X \to Y$, and $f\in F_A(X)$,   where $\supp(h) = \{x \in X \mid h(x) \neq 0\}$.
  For each $i\colon A \to B$ in $\CMon$, the \emph{natural transformation} $F_i$ is defined by $(F_i)_X(f) \coloneqq i \circ f$ for each $X\in \sets$ and $f\in F_A(X)$. 
\end{definition}

\begin{example} \label{eg:cmon_functor}
  \begin{enumerate}
    \item 
    % Consider the commutative monoid $(\mathbb{N}, +, 0)$. 
    The functor $F_{(\mathbb{N}, +, 0)}$ is the multiset functor $\mfunc$.
    \item 
