\begin{lemma} \label{lem:monoid_lambda}
  Let $A$ and $B$ be commutative monoids,
  and let $\lambda\colon F_A \Rightarrow F_B$ be a natural transformation.
  Then, 
  for each $f \in F_A(X)$ and $x, x' \in X$, the following statements hold.
  % if $\lambda_X(f)(y)$ is an idempotent then $\lambda_X(f)(y) = 0$.
  \begin{enumerate}
    % \item $\lambda_X(f)(y)$ is an idempotent element for each $y \in X$.
    % \item \label{item:bot_zero} $f(x) = \bot$ implies $\lambda_X f(x) = 0$. 
    % \item \label{item:lambda_sum} $\sum_{x \in X}\lambda_X(f)(x) = \lambda_1(\Delta_{\sum_{x \in X}f(x)})(*)$
    \item \label{item:f_equal} $f(x) = f(x')$ implies $\lambda_X(f)(x) = \lambda_X(f)(x')$.
    \item \label{item:idempotent} 
    For each $n \in \mathbb{N}$,
    $n \cdot f(x) = f(x)$ implies $n \cdot \lambda_X(f)(x) = \lambda_X(f)(x)$.
  \end{enumerate}
  % Moreover,
  % for any subfunctors $F$ of $F_A$ and $G$ of $F_B$ and $\lambda\colon F \Rightarrow G$,
  % statements (\ref{item:f_equal}), and (\ref{item:idempotent} with $n\leq 1$) for $f \in F(X)$ and $x, x' \in X$ continue to hold.
\end{lemma}
\begin{proofs}
  \eqref{item:f_equal} 
  This is easy to prove by taking a function $g\colon X\rightarrow X$ that swaps $x$ and $x'$ and by the naturality of $\lambda$. 

  \eqref{item:idempotent}
  The cases $n = 0$ and $n=1$ are easy to prove. 
  We sketch the proof for the case $n \geq 2$. 
  Let $\kappa_2$ be the second coprojection of a binary coproduct. 
  We define $f'\in F_A(X+(\setn{2n-2}))$ as $[f, \Delta_{f(x)}]$ 
  and show that 
  \begin{align*}
    \lambda_X(f)(x) &= (2n-1)\cdot \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)),\text{ and }\\
     \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)) &= n\cdot \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)).
  \end{align*}
  Then, we can see that $\lambda_X(f)(x) = \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n))$
  because 
  \begin{align*}
    \lambda_X(f)(x) &= (2n-1)\cdot \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n))\\
    &= n\cdot \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)) + (n-1)\cdot \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)) \\
    &= \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)) + (n-1)\cdot \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)) \\
    &= \lambda_{X + (\setn{2n-2})}(f')(\kappa_2(n)).
  \end{align*}
This concludes that $\lambda_X(f)(x) = n\cdot \lambda_X(f)(x)$. 
  See~\cref{subsec:proof_lem_monoid_lambda} for the full proof. 
\end{proofs}

The second statement places a restriction on the possible values of $\lambda_X(f)(x)$ when $n \cdot f(x) = f(x)$.
In particular, setting $n=0$ 
