% the natural transformation $\lambda\colon F_A \Rightarrow F_B$ respects identity elements of commutative monoids.

% We further show that $\lambda$ also respects monoid operations
The following result tells how 
$\lambda$ respects the $n$-th times operation.
To formalize this,
we introduce a preorder on a commutative monoid $A$ defined by
% Any commutative monoid $A$ is a partial order $(A, \leq)$ defined by 
$a \leq a'$ if and only if there exists $a'' \in A$ such that $a + a'' = a'$.
% This ordering helps us to analyze how natural transformations interact with algebraic structures within monoids.
\begin{lemma} \label{lem:lambda_m_n}
  Let $A$ and $B$ be commutative monoids,
  and $\lambda\colon F_A \Rightarrow F_B$ be a natural transformation.
  For each $f \in F_A(X)$, $x \in X$, $a \in A$, $n, m \in \mathbb{N}$, 
  and
  $\triangleright_1, \triangleright_2 \in \{=, \geq\}$,
  we assume that 
  \begin{center}
  $f(x) \triangleright_1 n \cdot a$,\quad and\quad  $\sum_{x' \in X \setminus \{x\}}f(x') \triangleright_2 m \cdot a$.
  \end{center}
  Then there are $a_1, a_2 \in A$ such that $f(x) = n \cdot a + a_1$ and $\sum_{x' \in X \setminus \{x\}}f(x') = m \cdot a + a_2$ by definition of $\triangleright_1$ and $\triangleright_2$.
  For these $a_1$ and $a_2$, the following relations hold:
  \begin{center}
  $\lambda_X(f)(x) \triangleright_1 n \cdot \lambda_{\setn{n+m+2}}(f')(1)$, \quad $\sum_{x' \in X \setminus \{x\}} \lambda_X(f)(x') \triangleright_2 m \cdot \lambda_{\setn{n+m+2}}(f')(1)$,
  \end{center}
  where $f'\in F_A(\setn{n+m+2})$ is defined by $f'(n+m+1) \defeq a_1$, $f'(n+m+2) \defeq a_2$, and $f'(i) \defeq a$ for each $i \in \setn{n+m}$. 
  % \begin{align*}
  %   f'(i) = 
  %   \begin{cases}
  %     a &\text{if }i \in \setn{n+m}, \\
  %     a_1 &\text{if }i = n+m+1, \\
  %     a_2 &\text{if }i = n+m+2.
  %   \end{cases}
  % \end{align*}
  % For subfunctors $F$ of $F_A$ and $G$ of $F_B$ and $\lambda\colon F \Rightarrow G$, this statement for $f \in F(X)$ also holds if $f' \in F(\setn{n+m+2})$.
\end{lemma}
\begin{proof}
  Define $g_1\colon \setn{n+m+2} \to \setn{2}$ by $g_1(i) = 1$ if $i \in \setn{n} \cup \{n+m+1\}$ and $2$ otherwise,
  and $g_2\colon X \to \setn{2}$ by $g_2(x') = 1$ if $x' = x$ and $2$ otherwise.
  Then the following equalities hold.
  \begin{align*}
    \lambda_X(f)(x)
    &= \lambda_\setn{2}(F_A(g_2)(f))(1) &&\text{by naturality for }g_2, \\
    &= \lambda_\setn{2}(F_A(g_1)(f'))(1) &&\text{since }F_A(g_2)(f) = F_A(g_1)(f'), \\
    &= n \cdot \lambda_{\setn{n+m+2}}(f')(1) + \lambda_{\setn{n+m+2}}(f')(n+m+1) &&\text{by naturality for }g_1.
  \end{align*}
  If $\triangleright_1$ is equal to $=$, then $\lambda_X(f)(x) = n \cdot \lambda_{\setn{n+m+2}}(f')(1)$ since
  $\lambda_{\setn{n+m+2}}(f')(n+m+1) = 0$, which follows from \cref{lem:monoid_lambda}.\ref{item:idempotent} with $n=0$.
  If $\triangleright_1$ is equal to $\geq$, then $\lambda_X(f)(x) \geq n \cdot \lambda_{\setn{n+m+2}}(f')(1)$ clearly holds.
  One can also prove $\sum_{x' \in X \setminus \{x\}} \lambda_X(f)(x') \triangleright_2 m \cdot \lambda_{\setn{n+m+2}}(f')(1)$ by considering $\lambda_\setn{2}(F_A(g_2)(f))(2)$ instead of $\lambda_\setn{2}(F_A(g_2)(f))(1)$.
\end{proof}



\subsection{For Natural Transformations from $F_A$ Where $A$ is Singly Generated} \label{sec:nt_single}

Let us focus on a commutative monoid $A$ generated by a single element $a \in A$.
In this setting, 
each $a' \in A$ can be written by the form $l \cdot a$ for some $l \in \mathbb{N}$.
We define $N\colon A \to \mathbb{N}$ that assigns to each $a' \in A$ the least natural number $l$ such that $l \cdot a = a'$.
% , for each element $a'$, of 

For a singly generated commutative monoid $A$,
\cref{lem:lambda_m_n} provides an insight into 
the explicit form of $\lambda$. 
Informally, given a natural transformation $\lambda\colon F_A \Rightarrow F_B$ and $f\in F_A(X)$, the value $\lambda_X(f)(x)$ can be expressed  as 
$\lambda_X(f)(x) = N(f(x))\cdot O(f)$ for any $x\in X$, 
where $O\colon F_A(X) \to B$ is a certain function. 
% Furthermore, the function $O$ can be explicitly determined by a mapping $b\in B^{\mathbb{N}_{\geq 1}}$,
Moreover, the function $O$ depends only on the sum of values of $f$.
% assigns the same value to all functions with the same sum of values.
This follows from the fact that
the naturality of $\lambda$ imposes conditions only on functions whose total sums are equal
because for any $g\in X\rightarrow Y$,
$F_A(g)$ preserves the sum of function values, i.e.~$\sum_{x \in X} f(x) = \sum_{y \in Y}(F_A(g)(f))(y)$.

For a function $b\colon X \to B$ and a pair $(i, v)$ where $i \not \in X$ and $v \in B$,
we often write $\extendb{(i, v)}\colon X \cup \{i\}\rightarrow B$ for 
the extension of $b$ obtained by defining $b(i) \coloneqq v$.
% It allows us to characterise natural transformations from $F_A$ to $F_B$. 

%   Using this notation, \cref{lem:lambda_m_n} with $n\coloneqq N(f(x))$ and $m \coloneqq \Sigma_{x' \in X \setminus \{x\}}N(f(x'))$ yields the following:
%   $\lambda_X(f)(x) = N(f(x)) \cdot \lambda_{\setn{\Sigma_{x \in X}N(f(x))+2}}(f')(1)$
%   where $f'$ is defined by $f'(i) = a$ if $i \in \setn{\Sigma_{x \in X}N(f(x))}$, and $0$ otherwise ($a_1 = a_2 = 0$).
%   In particular, for several specific cases, the possible values of 
% $\lambda_{\setn{\sigma_{x \in X}N(f(x))+2}}(f')(1)$ can be explicitly determined,
% and it allows us to describe natural transformations from $F_A$ to $F_B$ in a precise manner.

\begin{theorem} \label{thm:monoid_lambda}
  Let $A$ be a commutative monoid 
  generated by a single element $a \in A$,
  and let $B$ be a commutative monoid.
 In the following two cases, the set $\Nat{F_A}{F_B}$ of natural transformations 
 can be explicitly characterized:
  % We write $a^l$ for $$
  % and $\lambda\colon F_A \Rightarrow F_B$ be a natural transformation.
  \begin{enumerate}
    \item \label{item:case_n} Case 1: for each $n, m \in \mathbb{N}$, $n \neq m$ implies $n \cdot a \neq m \cdot a$.

    There exists an isomorphism 
    $\lambda^{(\_)}\colon B^{\mathbb{N}_{\geq 1}} \to \Nat{F_A}{F_B}$
    given by
  \begin{displaymath}
    \lambda^b_X(f)(x) \coloneqq
    N(f(x)) \cdot \extendb{(0, 0)}\big(\sum_{x \in X}N(f(x))\big).
  \end{displaymath}

    \item \label{item:case_cycle} Case 2: 
    $a \neq 0$ and there is $n \in \mathbb{N}_{> 1}$ such that $n \cdot a = a$.

    Let $n$ be the least natural number such that $n > 1$ and $n \cdot a = a$.
   There exists an isomorphism $\lambda^{(\_)}\colon \{c \in B \mid n \cdot c = c\}^{\{0, \cdots, n-2\}} \to \Nat{F_A}{F_B}$ given by
    % For each $b\colon \{1, \cdots, n-1\} \to \{c \in B \mid c^n = c\}$,
    % we have a natural transformation
    % $\lambda^b\colon F_A \Rightarrow F_B$ defined by 
  \begin{displaymath}
    \lambda^b_X(f)(x) \coloneqq
    N(f(x)) \cdot b\Big(\big[\sum_{x \in X}N(f(x))\big]\Big),
    % \begin{cases}
    %   0 &\text{if }\forall x \in X.~f(x) = 1, \\
    %   N(f(x)) \cdot b([\sum_{x \in X}N(f(x))-1]+1) &\text{otherwise},
    % \end{cases}
  \end{displaymath}
  where $[l]$ is the remainder of $l$ modulo $n-1$.
  % , and we extend $b$ by $b(0) \defeq 0$.
  \end{enumerate}
\end{theorem}
% In both cases, the component of a natural transformation $F_A \Rightarrow F_B$ can be written by using the sum of $N(f(x))$ copies of an element in $B$.
% The element is determined by the value $\sum_{x \in X}f(x)$.
% It comes from the fact that
% $F_A$ does not change the sum of values of functions, that is, $\sum_{x \in X} f(x) = \sum_{y \in Y}(F_A(g)(f))(y)$.


% Before going through the proof sketch,
%  ...
\begin{proofs}
  1) For each $n\in \mathbb{N}_{\geq 1}$, we use the function $f'_n \in F_A(\setn{n+2})$ given by $f'_n(i) = a$ for each $i \in \setn{n}$ and $f'_n(n+1) = f'_n(n+2) = 0$.
  We define the inverse $(\lambda^{(\_)})^{-1}\colon \Nat{F_A}{F_B}\rightarrow B^{\mathbb{N}_{\geq 1}}$ as follows: 
  Given a natural transformation $\lambda$, the inverse $b^{\lambda}\colon \mathbb{N}_{\geq 1} \to B$ is given by $b(n) = \lambda_{\setn{n+2}}(f'_n)(1)$ for each $n \in \mathbb{N}_{\geq 1}$. 
  We can show that the mapping $b^{(\_)}$ is indeed the inverse by~\cref{lem:lambda_m_n}. 

  2) 
  The construction of the inverse is more involved. 
  We use the same function $f'_n$ for each $n\in \mathbb{N}_{\geq 1}$. 
  We define the inverse $(\lambda^{(\_)})^{-1}\colon \Nat{F_A}{F_B}\rightarrow  \{c \in B \mid n \cdot c = c\}$ as follows:
  Given a natural transformation $\lambda$, the inverse $b^{\lambda}\colon \{0, \cdots, n-2\} \to \{c \in B \mid n \cdot c = c\}$ is given by $b^\lambda(m) \defeq d^\lambda([m-1]+1)$, 
  where the function $d^\lambda\colon \mathbb{N}_{\geq 1} \to \{c \in B \mid n \cdot c = c\}$ is defined by $d^{\lambda}(m) \defeq \lambda_{\setn{m+2}}(f'_m)(1)$. 
  We can show that this mapping is the inverse by~\cref{lem:monoid_lambda}.\ref{item:idempotent} and~\cref{lem:lambda_m_n}. 

  See~\cref{appendix:proof_monoid_lambda} for the full proof. 
\end{proofs}


Let us instantiate this theorem with concrete examples.
\begin{example}[$\mfunc \Rightarrow F_B$] \label{eg:mfunc_natural_trans}
Consider the multiset functor $\mfunc = F_{(\mathbb{N}, +, 0)}$ (see \cref{eg:cmon_functor}).
The monoid $(\mathbb{N}, +, 0)$ is generated by $1$,
and
this falls under Case 1 of \cref{thm:monoid_lambda}.
Applying the theorem, we derive the following results:
  \begin{enumerate}
    \item
    There exists an isomorphism
    $\lambda\colon \bools^{\mathbb{N}_{\geq 1}} \to \Nat{\mfunc}{\powfunc}$ defined by \\ 
      $\lambda_X^b(f)\coloneqq 
      \{x \in X \mid f(x) > 0 \text{ and } \extendb{(0, \bot)}(\sum_{x \in X} f(x))\}$.
    \item
    There exists an isomorphism
    $\lambda\colon \nnegreal^{\mathbb{N}_{\geq 1}} \to \Nat{\mfunc}{\erealfunc}$ defined by \\
      $\lambda_X^b(f)(x) \coloneqq 
      f(x) \cdot \extendb{(0, 0)}(\sum_{x \in X} f(x))$.
    \item
    There exists an isomorphism
    $\lambda\colon \nnegreal^{\mathbb{N}_{\geq 1}} \to \Nat{\mfunc}{\erealfunctimes}$ defined by \\
      $\lambda_X^b(f)(x) \coloneqq 
      \big(\extendb{(0, 1)}\big(\sum_{x \in X} f(x)\big)\big)^{f(x)}$.
  \end{enumerate}
\end{example}

\begin{example}[$\powfunc \Rightarrow F_B$] \label{eg:powfunc_natural_trans}
Consider the finite powerset functor $\powfunc = F_{(\bools, \lor, \bot)}$ (see \cref{eg:cmon_functor}).
This falls under Case 2 of \cref{thm:monoid_lambda}
since
the commutative monoid $(\bools, \lor, \bot)$ is generated by $\top$
and $\top$ is idempotent.
By the theorem, natural transformations are constrained by the idempotent property of $\top$, and
the isomorphism takes the form:
$\lambda^{(\_)}\colon \{c \in B \mid c^2 = c\} \to \Nat{\powfunc}{F_B}$.
From this, we derive the following results:
  \begin{enumerate}
    \item There exists a unique natural transformation $\lambda\colon \powfunc \Rightarrow \erealfunc$
    (respectively, $\lambda\colon \powfunc \Rightarrow \mfunc$),
    which is
    given by $\lambda_X(S)(x) = 0$.
    \item There exists only two natural transformations $\lambda\colon \powfunc \Rightarrow \erealfunctimes$. 
    One is given by $\lambda_X(S)(x) \defeq 1$; and the other is by $\lambda_X(S)(x) \defeq 0$ if $x \in S$, and $1$ otherwise.
  \qed
  \end{enumerate}
\end{example}

The following lemma allows us to extend our results 
about natural transformations between $F_A$ and $F_B$ to their respective subfunctors.
See~\cref{ap:proof_subfunctor} for its proof.
\begin{lemma} \label{lem:subfunctor}
  Let $F$ and $G$ be subfunctors of $F_A$ and $F_B$, respectively,
  meaning that there exist $\iota_A\colon F \Rightarrow F_A$ and $\iota_B\colon G \Rightarrow F_B$ given by inclusions.
  Assume that for all $g\colon X \to Y$ in $\sets$ and $f \in F_A(X)$,
  $F_A(g)(f) \in F(Y)$ implies $f \in F(X)$.
  Then for any 
  natural transformation $\lambda\colon F \Rightarrow G$,
  there exists a natural transformation 
  $\lambda' \colon F_A \Rightarrow F_B$
  such that
  $\iota_B \circ \lambda = \lambda' \circ \iota_A$.
  \qed
\end{lemma}

\begin{proposition} \label{prop:subfunc_pm}
  \begin{enumerate}
    \item \label{item:pd} No natural transformation $\powfunc \Rightarrow \mathcal{D}$ exists.
    \item There exists a unique natural transformation $\lambda\colon \powfunc \Rightarrow \subdist$, given by $\lambda_X(S)(x) = 0$.
    \item No natural transformation $\mfunc \Rightarrow \mathcal{D}$ exists.
    \item
    There is an isomorphism $\lambda^{(\_)}\colon [0, 1]^{\mathbb{N}_{\geq 1}} \to \Nat{\mfunc}{\subdist}$ defined by
    \begin{displaymath}
      \lambda^b_X(f)(x) = 
      \begin{cases}
        \frac{f(x)}{\sum_{x \in X}f(x)} \cdot b\big(\sum_{x \in X}f(x)\big) &\text{if }\sum_{x \in X}f(x) > 0, \\
        0 &\text{if }\sum_{x \in X}f(x) = 0.
      \end{cases}
    \end{displaymath}
  \end{enumerate}
\end{proposition}
We provide a proof of statement~\ref{item:pd} below.
