We now present our first main result, a no-go theorem for coalgebraic product MCs for MCs and NFAs.
The proof relies on the characterisation of natural transformations from $\powfunc$ to $\erealfunc$ presented in \cref{sec:nt_single}.
The characterisation imposes strict constraints on possible forms of distributive laws,
and we demonstrate that no such distributive law satisfies the correctness criterion.
\begin{theorem}[no-go theorem under correcness criterion]
    \label{thm:no-go-mc-nfa}
    Consider semantic structures defined in \cref{eg:mc}, \cref{def:nfas}, and \cref{def:sem_product}.
    There is no distributive law $\lambda$ from $\subdist(\_) \times A$ and $\nfafunc{(\_)}$ to $\mcnfafunc{(\_)}$
    % \colon \mcfunc{X}\times \nfafunc{Y}\rightarrow\mcnfafunc{X\times Y}$
    such that for each MC $c$ and NFA $d$,
    the coalgebraic product $c\otimes_{\lambda} d$ satisfies the correctness criterion with the inference map $q\colon \traceMC\times \traceNFA \rightarrow \exreal$ defined by 
    \begin{align*}
    q(\sigma, L) \defeq \sum_{w\in L} \sigma(w), &&\text{for each $\sigma \in \traceMC$ and $L \in \traceNFA$.} 
    \end{align*}
\end{theorem}
\begin{proof}
  Suppose that there exists a distributive law $\lambda$ from $\subdist(\_) \times A$ and $\nfafunc{(\_)}$ to $\mcnfafunc{(\_)}$
  satisfying the correctness criterion.
  Since there is a natural isomorphism $\mcnfafunc{(\_)} \Rightarrow \erealfunc(\_) \times \nonnegreal$,
  there is a bijective correspondence between
  $\lambda$ and a pair of natural transformations:
  \begin{itemize}
    \item $\{\lambda'_{X, Y}\colon \subdist(X) \times A \times \nfafunc{Y} \to \nnegreal \}_{X, Y}$, and
    % $\lambda'\colon \times \circ \left((\subdist(\_) \times A)\times (\nfafunc{(\_)}) \right)\Rightarrow \exreal$,
    \item $\{\lambda''_{X, Y}\colon \subdist(X) \times A \times \nfafunc{Y} \to \erealfunc(X \times Y)\}_{X, Y}$.
    % $\lambda''\colon \times \circ \left((\subdist(\_) \times A)\times (\nfafunc{(\_)}) \right)\Rightarrow \erealfunc(\_) \circ \times$.
  \end{itemize}
  We now analyze the properties of $\lambda'$ and $\lambda''$.
  \begin{itemize}
    \item By the naturality of $\lambda'$, 
    for each $(\sigma, a) \in \subdist(X) \times A$ and $\delta \in \nfafunc{Y}$, we have:
    \begin{equation} \label{eq:lambda'_nogo}
      \lambda'_{X, Y}(\sigma, a, \delta) = \lambda'_{\setn{1}\, , \setn{1}}\left(\Delta_{r}, \, a, \, \powfunc(!_Y + \{\checkmark\})^A(\delta) \right),
      % (a' \mapsto \{\kappa_1(1) \mid y \in Y, y \in \delta(a') \} \cup \{\kappa_2(\checkmark) \mid \checkmark \in \delta(a')\})\right).
    \end{equation}
    where $r \coloneqq \sum_{x \in X}\sigma(x)$.
    \item For each $(\sigma, a) \in \subdist(X) \times A$,
    % For each $S \in \powfunc(Y)$,
    define a natural transformation $\rho\colon \powfunc \Rightarrow \erealfunc$
    by $\{\rho_{Y} \coloneqq \erealfunc(\pi_2) \circ \lambda''_{X, Y} \circ \langle \sigma,\, a, \,\Delta_{\powfunc(\kappa_1)(\_)} \rangle\}_Y$.
    By~\cref{eg:powfunc_natural_trans}, it is the constant natural transformation to $0$.
    Thus
    it follows that 
    $\lambda''_{X, Y}(\sigma, a, \Delta_{L})(x, y) = 0$ 
    for each $L \in \powfunc(X)$,
    $x \in X$, and $y \in Y$
    since $\rho_{Y}(L)(y) = \sum_{x \in X}\lambda''_{X, Y}(\sigma, a, \Delta_{L})(x, y) = 0$.
  \end{itemize}

  By the correctness criterion, for each $(\sigma, a) \in \subdist(\mathbf{\Omega}_S) \times A$ and $\delta \in \nfafunc{\mathbf{\Omega}_R}$,
  \begin{align}
    \begin{split} \label{eq:nfa_correct}
    &\Big(1-\sum_{\mu \in \mathbf{\Omega}_S}\sigma(\mu)\Big) \cdot \delta(a)(\checkmark) + \sum_{w \in A^+} \Big(\sum_{\mu \in \mathbf{\Omega}_S} \sigma(\mu) \cdot \mu(w)\Big) \cdot \Big(\bigvee_{L \in \delta(a)}L(w)\Big) \\
    &= \lambda'_{\mathbf{\Omega}_S, \mathbf{\Omega}_R}(\sigma, a, \delta) + \sum_{\mu \in \mathbf{\Omega}_S, L \in \delta(a)}  \sum_{w \in A^+} \mu(w) \cdot L(w) \cdot \lambda''_{\mathbf{\Omega}_S, \mathbf{\Omega}_R}(\sigma, a, \delta)(\mu, L).
    \end{split}
  \end{align}
For simplicity, we write $\delta(a)$ and $L$ for their characteristic functions in the equation above.

  For each $r \in [0, 1]$, $a \in A$, and $\delta \in \nfafunc{\setn{1}}$,
  define $\sigma_1 \in \subdist(\mathbf{\Omega}_S)$ and $\delta_1 \in \nfafunc{\mathbf{\Omega}_R}$ by 
  \begin{align*}
    \sigma_1(x) \coloneqq 
    \begin{cases}
      r &\text{if }x = \Delta_0 \\
      0 &\text{otherwise}
    \end{cases}, \quad
% \{a\}
    \delta_1 \coloneqq \powfunc(\Delta_{\emptyset}+\{\checkmark\})^A(\delta).
      %  \{\kappa_1(\{a\}) \mid \kappa_1(1) \in \delta(a')\} \cup \{\kappa_2(\checkmark) \mid \kappa_2(\checkmark) \in \delta(a')\}.
  \end{align*}
  Then \eqref{eq:nfa_correct} for $(\sigma_1, a)$ and $\delta_1$ 
  gives that
  $(1-r) \cdot \delta(a)(\checkmark) = \lambda'_{\mathbf{\Omega}_S, \mathbf{\Omega}_R}(\sigma_1, a, \delta_1) = \lambda'_{\setn{1}, \setn{1}}(\Delta_r, a, \delta)$.
  Therefore, 
    for each $(\sigma, a) \in \subdist(X) \times A$ and $\delta \in \nfafunc{Y}$,  \eqref{eq:lambda'_nogo} induces
    \begin{displaymath}
      \lambda'_{X, Y}(\sigma, a, \delta) 
      % = \lambda'_{\setn{1}\, , \setn{1}}\left(\Delta_{\sum_{x \in X}\sigma(x)}, \, a, \, \powfunc(!_Y + \{\checkmark\})^A(\delta) \right)
      = \big(1-\sum_{x \in X}\sigma(x)\big) \cdot \delta(a)(\checkmark).
      % (a' \mapsto \{\kappa_1(1) \mid y \in Y, y \in \delta(a') \} \cup \{\kappa_2(\checkmark) \mid \checkmark \in \delta(a')\})\right).
    \end{displaymath}

  Let $r \in (0, 1]$, $w \in A^+$, and $a \in A$.
  Consider $\mu \in \mathbf{\Omega}_S$ defined by $\mu(w) = 1$ and $\mu(w') = 0$ for each $w' \in A^+ \setminus \{w\}$.
  Define $\sigma_2 \in \subdist(\mathbf{\Omega}_S)$ and $\delta_2 \in \nfafunc{\mathbf{\Omega}_R}$ by 
  \begin{align*}
    \sigma_2(x) \coloneqq 
    \begin{cases}
      r &\text{if }x = \mu \\
      0 &\text{otherwise}
    \end{cases}, \quad
    \delta_2 \coloneqq 
    \Delta_{\{w\}}.
  \end{align*}
  Then \eqref{eq:nfa_correct} for $(\sigma_2, a)$ and $\delta_2$ gives that
  \begin{align*}
    r &= \sum_{w \in A^+} \Big(\sum_{\mu \in \mathbf{\Omega}_S} \sigma_2(\mu) \cdot \mu(w)\Big) \cdot \Big(\bigvee_{L \in \delta_2(a)}L(w)\Big) \\
    &= \sum_{\mu \in \mathbf{\Omega}_S, L \in \delta_2(a)}  \sum_{w \in A^+} \mu(w) \cdot L(w) \cdot \lambda''_{\mathbf{\Omega}_S, \mathbf{\Omega}_R}(\sigma_2, a, \delta_2)(\mu, L) = 0.
  \end{align*}
   This leads a contradiction, proving that no such distributive law $\lambda$ can exist.
\end{proof}
Note that this immediately implies the no-go theorem for 
distributive laws 
from $\subdist(\_) \times A$ and $\nfafunc{(\_)}$ to $\mcfuncproduct{(\_)}$
as well.
