\section{Markov Chains and Multiset Finite Automata}
\label{sec:mcmfas}

In this section, we present a coalgebraic product construction of MCs and \emph{multiset finite automata (MFAs)}, and show the coalgebraic product construction is correct w.r.t.~the inference map that takes the expectation of the number of accepting paths. 
This immediately shows the correctness of the existing product construction of MCs and unambiguous finite automata~\cite{BenediktLW14,BaierK00023} as a special case. 
We further study the coalgebraic product of MCs and MFAs itself, and present some useful properties that can be benefitical for verification.

\subsection{Coalgebraic Product of MCs and MFAs}

\begin{definition}[semantic structure of MFAs]
    \label{def:mfas}
    An \emph{MFA} is a coalgebra $d\colon Y\rightarrow \mfafunc{Y}$, where the underlying set $Y$ is finite.
    The \emph{semantic structure $(\mathbf{\Omega}_{R}, \tau_R)$ of MFAs} is defined by (i) $\mathbf{\Omega}_{R} \defeq (\traceMFA, \preceq)$, where $\preceq$ is the pointwise order; 
    and (ii) $\tau_R\colon \mfafunc{\traceMFA}\rightarrow \traceMFA$ is given by
    \begin{align*}
        \tau_R(\delta)(w) \defeq \begin{cases}
            \delta(a)(\checkmark) &\text{ if } w = a,\\
            \sum_{\mu \in \traceMFA}\delta(a)(\mu)\cdot \mu(w')&\text{ if } w = a\cdot w',\\
            0 &\text{ otherwise.}
        \end{cases}
    \end{align*}
\end{definition}
The semantics of MFAs is the number of accepting paths for each word. 
MFAs are indeed a weighted automaton with the standard commutative ring on $\nat$. 

\begin{definition} \label{def:dist_mfa}
    The \emph{distributive law} $\lambda_{X, Y}\colon \mcfunc{X}\times \mfafunc{Y}\rightarrow\mcmfafunc{X\times Y}$ is given by 
    \begin{align*}
        \lambda_{X, Y}(\sigma, a, \delta)(x, y) 
           &\defeq \delta(a)(y) \cdot \sigma(x), && \lambda_{X, Y}(\sigma, a, \delta)(\checkmark) 
           \defeq \delta(a)(\checkmark) \cdot \sigma(\checkmark).
    \end{align*}
\end{definition}
Importantly, the coalgebraic product $c\otimes_{\lambda} d\colon X\times Y\rightarrow \mcmfafunc{X\times Y}$ is not substochastic, that is, the sum $\sum_{(x', y')} (c\otimes_{\lambda} d)(x, y)(x', y') + (c\otimes_{\lambda} d)(x, y)(\checkmark)$ may be strictly greater than $1$, for some $(x, y)\in X\times Y$. 
% Nevertheless, the coalgebraic product $c\otimes_{\lambda} d$ behaves like an ``MC-like'' transition system, as we will see later.  


We now establish the correctness of the coalgebraic product for MCs and MFAs w.r.t.~the model checking problem that computes the expectation of the number of accepting paths.
% formally define the model checking problem for MCs and MFAs, and state 
\begin{proposition}[correcness]
    \label{prop:correctmcmfas}
    Consider semantic structures defined in \cref{eg:mc}, \cref{def:sem_product}, and \cref{def:mfas}.
    Then
    the coalgebraic product $c\otimes_{\lambda} d$ is correct
    w.r.t.~$q\colon \traceMC\times \traceMFA \rightarrow \exreal$ defined by 
    \begin{align*}
    q(\sigma, \mu) \defeq \sum_{w\in A^{+}} \mu(w) \cdot \sigma(w),
    &&\text{ for each $\sigma \in \traceMC$ and $\mu \in \traceMFA$.}
    \qed
    \end{align*}
\end{proposition}
