% \end{proofs}
As a direct consequence, the product of an MC $c$ and an unambiguous finite automaton $d$~\cite{BenediktLW14,BaierK00023} is correct w.r.t.~the inference map that computes the probability of paths that are accepting. 
In fact, $(\mu \Phi_d)(w) = 1$ iff $l$ is an accepting word, and $(\mu \Phi_d)(w) = 0$ otherwise, because $d$ is unambiguous,
implying that the model checking $q \circ (\mu \Phi_c \times \mu \Phi_d)$ precisely gives the probability of paths that are accepting. 

We remark that the distributive law $\lambda$ is the unique one in the following sense:
\newcommand{\ev}{\mathrm{ev}}
\begin{proposition}[uniqueness under correctness criterion] \label{prop:lambda_uniqueness}
  The distributive law $\lambda$
  defined in~\cref{def:dist_mfa}
    is the unique one 
    % from $\subdist(\_) \times A$ and $\mfafunc{(\_)}$ to $\mcmfafunc{(\_)}$
    satisfying the following properties.
    \begin{enumerate}
      \item There is a distributive law $\rho$
      % $\rho\colon \times \circ (\subdist \times \mfunc((\_)+1)) \Rightarrow \mcmfafunc{(\_)} \circ \times$
      % $\rho_{X, Y}\colon \subdist(X) \times \mfunc(Y+1) \to \mcmfafunc{X \times Y}$
    from $\subdist$ and $\mfunc((\_)+1)$ to $\mcmfafunc{(\_)}$
    s.t.~$\lambda = \rho \circ (\id_{\subdist(\_)} \times \ev_{A, \mfunc((\_)+1)})$,
      where $\ev_{A, (\_)}\colon A \times \id^A \Rightarrow \id$ is given by evaluation maps.
      \item
    % For each MC $c$ and MFA $d$,
