 \begin{lemma} \label{lem:mlc}
  % Consider the setting of case~\ref{item:case_cycle} in~\cref{thm:monoid_lambda}.
  Let $C$ be a commutative monoid, $n \in \mathbb{N}_{> 1}$, and $c \in C$ be an element such that 
  % the least natural number such that $n > 1$ and 
  $n \cdot c = c$.
  We write $[l]$ for the remainder of $l$ modulo $n-1$.
  Then the following statements hold.
  \begin{enumerate}
    \item \label{item:mlc} For each $m, l \in \mathbb{N}$, $[m] = [l]$ implies $m \cdot c = l \cdot c$.
    \item If $n$ is the least natural number such that $n > 1$ and $n \cdot c = c$, for each $m, l \in \mathbb{N}$, $m \cdot c = l \cdot c$ implies $[m] = [l]$.
  \end{enumerate}
 \end{lemma}
 \begin{proof}
Assume $m \leq l$ without loss of generality.
 1) 
 Since $[m] = [l]$, there exists $k \in \mathbb{N}$ such that $l = m+(n-1) \cdot k$.
 We show $m \cdot c = l \cdot c$ by induction on $k$.
 If $k \leq m$, 
  $l \cdot c = (m-k+n\cdot k)\cdot c = (m-k) \cdot c + (n \cdot k) \cdot c = (m-k) \cdot c + k \cdot c = m \cdot c$.
  Otherwise, 
  $l \cdot c = (m+(n-1) k) \cdot c = (m+(n-1)(k-m) + (n-1) m)\cdot c = (m + (n-1) m)\cdot c = m \cdot c$ by induction hypothesis.

  2) By~\cref{lem:mlc}.\ref{item:mlc}, it follows that $m \cdot c = [m] \cdot c$ and $l \cdot c = [l] \cdot c$.
  Thus we have $[m] \cdot c = [l] \cdot c$.
  Then it follows that $(n+[m]-[l]) \cdot c = (n+[l]-[l]) \cdot c = n \cdot c = c$.
  Since $n$ is the least natural number such that $n > 1$ and $n \cdot c = c$,
  we obtain $[m] = [l]$.
 \end{proof}

