    &= \sum_{x \in g^{-1}(y)} N(f(x)) \cdot b\big([\sum_{x \in X}N(f(x))]\big)  \\
    &= \left(\sum_{x \in g^{-1}(y)} N(f(x))\right) \cdot b\Big(\big[\sum_{x \in X}N(f(x))\big]\Big), \\
  % If $\forall y \in Y.~\prod_{x \in g^{-1}(y)} f(x) = 1$,
  % then $\forall y \in Y.~\forall x \in g^{-1}(y).~f(x)=1$.
  % Thus, $\sum_{x \in g^{-1}(y)} N(f(x)) = 0$.
  % It gives that $\lambda^b_Y(F_A(g)(f))(y) = 0 = F_B(g)(\lambda^b_X(f))(y)$.
  % If $\exists y \in Y.~\prod_{x \in g^{-1}(y)} f(x) \neq 1$,
    \lambda^b_Y(F_A(g)(f))(y)
    &= N(\sum_{x \in g^{-1}(y)} f(x)) \cdot b\Big(\big[\sum_{y \in Y}N(\sum_{x \in g^{-1}(y)} f(x))\big]\Big).
  \end{align*}
  By~\cref{lem:mlc},
  \begin{displaymath}
  [N(\sum_{x \in g^{-1}(y)} f(x))] = [\sum_{x \in g^{-1}(y)} N(f(x))] \text{ and } 
  \big[\sum_{x \in X}N(f(x))\big] = \big[\sum_{y \in Y}N(\sum_{x \in g^{-1}(y)} f(x))\big],
  \end{displaymath}
  and thus we also obtain 
  $F_B(g)(\lambda^b_X(f))(y) = \lambda^b_Y(F_A(g)(f))(y)$.


  Let us define the inverse of $\lambda^{(\_)}$.
%  We then show that the mapping is surjective. 
 For $\lambda\colon F_A \Rightarrow F_B$,
  define $d^\lambda\colon \mathbb{N}_{\geq 1} \to \{c \in B \mid n \cdot c = c\}$ 
  and $b^\lambda\colon \{0, \cdots, n-2\} \to \{c \in B \mid n \cdot c = c\}$ 
  by 
  \begin{displaymath}
    d^\lambda(m) \coloneqq \lambda_{\setn{m+2}}(f'_m)(1),
    \quad
    b^\lambda(m) \coloneqq d^\lambda([m-1]+1),
  \end{displaymath}
  where $f'_m(i) = a$ for each $i \in \setn{m}$ and $f'_m(m+1) = f'(m+2) = 0$.
  By~\cref{lem:monoid_lambda}.\ref{item:idempotent},
  we have
  $n \cdot \lambda_{\setn{m+2}}(f'_m)(1) = \lambda_{\setn{m+2}}(f'_m)(1)$, which ensures $d^\lambda(m), b^\lambda(m) \in \{c \in B \mid n \cdot c = c\}$.

  We show that $\lambda^{(\_)}$ is a left inverse of $b^{(\_)}$, that is, $\lambda^{(\_)} \circ b^{(\_)} = \id$.
  Let $\lambda\colon F_A \Rightarrow F_B$ be any natural transformation.
  For each $m \in \mathbb{N}_{\geq 1}$,
   by \cref{lem:lambda_m_n} for $(f'_{m+n-1}, 1, a, 1, m-1, =, =)$, it follows that
  \begin{equation} \label{eq:bm}
    d^\lambda(m) = d^\lambda(m+n-1).
  \end{equation}
  Therefore, 
  \cref{lem:lambda_m_n} for $(f, x, a, N(f(x)), \sum_{x' \in X \setminus \{x\}}N(f(x')), =, =)$  implies that
  for each $f \in F_A(X)$ and $x \in X$,
  \begin{align*}
  \lambda_X(f)(x) 
  &= N\big(f(x)\big) \cdot d^\lambda\big(\sum_x N(f(x))\big)  \\
  &= N\big(f(x)\big) \cdot b^\lambda\big([\sum_x N(f(x))]\big) 
  = \lambda^{(b^\lambda)}_X(f)(x).
  \end{align*}
  The second equality holds because 
  $d^\lambda(\sum_x N(f(x))) = d^\lambda([\sum_x N(f(x))-1]+1) = b^\lambda\big([\sum_x N(f(x))]\big)$ by \eqref{eq:bm} if $\sum_{x \in X}N(f(x)) > 0$,
  and $N(f(x)) = 0$ if $\sum_{x \in X}N(f(x)) = 0$.

  We show that $\lambda^{(\_)}$ is a right inverse of $b^{(\_)}$, that is, $b^{(\_)}\circ \lambda^{(\_)} = \id$.
  Let $b\colon \{0, \cdots, n-2\} \to \{c \in B \mid n \cdot c = c\}$ be any function.
  Then for each $i \in \{0, \cdots, n-2\}$, 
  $b(i) = 1 \cdot b([i+n-1]) = \lambda^b_{\setn{i+n+1}}(f'_{i+n-1})(1) = d^{(\lambda^b)}(i+n-1) = b^{(\lambda^b)}(i)$.
  The last equality holds since 
  if $i=0$ then $d^{(\lambda^b)}(n-1) = b^{(\lambda^b)}(0)$,
  and if $i>0$ then
  $d^{(\lambda^b)}(i+n-1) = d^{(\lambda^b)}(i) = b^{(\lambda^b)}(i)$ by definition of $b^\lambda$ and \eqref{eq:bm}.
\end{proof}

