\subsection{Proof of~\cref{prop:correctmcmfas}}
\label{subsec:proofcorrect}
We prove that the product $c\otimes_{\lambda} d$ and the inference map $q$ satisfy the correctness criterion (\cref{prop:correctCriterion}). 
This is immediate by the following equations: 
\begin{align*}
  &(q\circ \tau_S\times \tau_R)(\nu, a, \delta) =  \sum_{w} \tau_S(\nu, a)(w)\cdot \tau_R(\delta)(w)\\
  &= \nu(\checkmark) \cdot \delta(a)(\checkmark) + \sum_{w} \big(\sum_{\sigma} \nu(\sigma)\cdot \sigma(w)\big)\cdot \big(\sum_{f} \delta(a)(f)\cdot f(w)\big),\\
  &(\tau_{S\otimes R}\circ F_{S\otimes R}(q)\circ \lambda_{\Omega_S, \Omega_R})(\nu, a, \delta) = \nu(\checkmark)\cdot \delta(a)(\checkmark) + \sum_{r} r\cdot \big((F_{S\otimes R}(q)\circ \lambda_{\Omega_S, \Omega_R})(\nu, a, \delta) \big)(r)\\
  &= \nu(\checkmark)\cdot \delta(a)(\checkmark) + \sum_{(\sigma, f)} q(\sigma, f)\cdot \big(\lambda_{\Omega_S, \Omega_R})(\nu, a, \delta) \big)(\sigma, f)\\
  &= \nu(\checkmark)\cdot \delta(a)(\checkmark) + \sum_{(\sigma, f)} q(\sigma, f)\cdot \nu(\sigma)\cdot \delta(a)(f)\\
  &= \nu(\checkmark)\cdot \delta(a)(\checkmark) + \sum_{(\sigma, f)} \big( \sum_{w}f(w)\cdot \sigma(w)\big) \cdot \nu(\sigma)\cdot \delta(a)(f)\\
  &= \nu(\checkmark)\cdot \delta(a)(\checkmark)+ \sum_{w} \big(\sum_{\sigma} \nu(\sigma)\cdot \sigma(w)\big)\cdot \big(\sum_{f} \delta(a)(f)\cdot f(w)\big). \qed
\end{align*}

