  $(1-r) \cdot n_2 = \rho'_{\mathbf{\Omega}_S, \mathbf{\Omega}_R}(\sigma_1, \delta_1(a)) = \rho'_{\setn{1}, \setn{1}}(\Delta_r, (1 \mapsto n_1, \checkmark \mapsto n_2))$.
  Therefore, $\rho'_{X, Y}(\sigma, \delta) = (1-\sum_{\mu \in \mathbf{\Omega}_S}\sigma(\mu)) \cdot \delta(\checkmark)$ for each $\sigma \in \subdist(X)$ and $\delta \in \mfunc(Y+1)$.

  For each $r \in (0, 1]$, $a \in A$, and $n_1, n_2 \in \mathbb{N}$ $(n_2 \geq 1)$,
  consider a word $w \in A^+$ and $\mu \in \mathbf{\Omega}_S$ defined by $\mu(w) = 1$ and $\mu(w') = 0$ for each $w' \in A^+ \setminus \{w\}$, and
  % Let $r \in (0, 1]$, $w \in A^+$, and $a \in A$.
  % consider $\mu \in \Omega_c$ defined by $\mu(w) = 1$ and $\mu(w') = 0$ for each $w \in A^+ \setminus \{w'\}$.
  define 
  $\sigma_2 \in \subdist(\mathbf{\Omega}_S)$ and
  $\delta_2 \in \mfafunc{\mathbf{\Omega}_R}$ by 
  \begin{align*}
    \sigma_2(x) \coloneqq 
    \begin{cases}
      r &\text{if }x = \mu, \\
      0 &\text{otherwise,}
    \end{cases} 
    &&\delta_2(a')(i) \coloneqq 
    \begin{cases}
      n_1 &\text{if }a' = a \text{ and }i = \checkmark,  \\
      n_2 &\text{if }a'=a \text{ and }i=\delta', \\
      0 &\text{otherwise,}
    \end{cases}
  \end{align*}
  where $\delta' \in \mathbf{\Omega}_R$ is defined by $\delta'(w) = 1$ and $\delta'(w') = 0$ for each $w' \in A^+ \setminus \{w\}$.
  Then \eqref{eq:nfa_correct} for $(\sigma_2, a)$ and $\delta_2$ gives that
    $r \cdot n_2 
    = n_2 \cdot b_{\Delta_r, n_1}(n_2)$.
    Hence, $b_{\Delta_r, n_1}(n_2) = r$, and consequently,
      $\rho''_{X, Y}(\sigma, \delta)(x, y) = 
        \sigma(x) \cdot \delta(y)$  for each $\sigma \in \subdist(X)$ and $\delta \in \mfunc(Y+1)$.

  The distributive law $\lambda$ given by the pair $(\rho', \rho'')$ is the one defined in \cref{def:dist_mfa}. This establishes the existence and uniqueness of $\lambda$.
\end{proof}




\subsection{Proof of~\cref{prop:finiteSufficient}}
\label{subsec:proofNtermination}
\begin{proof}
We prove that the semantics $\mu \Phi_{c\otimes_{\lambda} d}(x_0, y_0)\in \exreal$ is finite if the MFA $d$ is polynomially ambiguous. 
Since the product is correct w.r.t.~the query $q$, it suffices to show that the following inference is finite: 
\begin{align*}
    &\sum_{w\in A^{+}} \mu\Phi_{c}(x_0)(w) \cdot \mu\Phi_{d}(y_0)(w) < \infty.
\end{align*}
Since the MFA $d$ is polynomially ambiguous, there is a constant $C$ and $n\in \nat$ such that 
\begin{align*}
    \mu\Phi_{d}(y_0)(w) \leq C\cdot |w|^{n}.
\end{align*}
Therefore, it suffices to prove that 
\begin{align*}
    &\sum_{w\in A^{+}} \mu\Phi_{c}(x_0)(w) \cdot |w|^{n} < \infty.
\end{align*}
In fact, this means that the $n$-th termination moment (e.g.~\cite{WinklerK23}) on finite MCs is finite. 
We conclude the proof by showing that the $n$-th termination moment on finite MCs is indeed finite.

Without loss of generality, we assume that $c$ is almost surely reachable to $\checkmark$ from any $x$.
If not, we can create a finite MC that is almost surely reachable to $\checkmark$ from any state, whose $n$-th termination moment is greater than that of the original MC $c$. 

For any $m\in \nat$, $x\in X$, and $z\in X+\{\checkmark\}$, we write $\mathbb{P}^m_{x, z}$ for the probability to reach from $x$ to $z$ in exactly $m$ steps. 
Then, there is $M\in \nat$ such that $\sum_{z\in Z}\mathbb{P}^M_{x, z} \leq 1/2$ for any $x$ because $c$ is almost surely reachable to $\checkmark$. 
Now, for any $k \in \nat$, we can further see that 
\begin{align*}
    \mathbb{P}^{M+k}_{x, \checkmark} = \sum_{x'\in X}  \mathbb{P}^{k}_{x, x'} \cdot \mathbb{P}^{M}_{x', \checkmark} \leq \sum_{x'\in X} \mathbb{P}^{k}_{x, x'}\cdot 1/2.
\end{align*}
By the induction on $l\in \nat$, we can show that $\mathbb{P}^{M\cdot l}_{x, \checkmark} \leq (1/2)^{l} $ for any $l\in \nat$ and $x\in X$.
In fact, assume that $\mathbb{P}^{M\cdot l}_{x, \checkmark} \leq (1/2)^{l} $ for a given $l\in \nat$ and any $x\in X$. 
Then we can easily see that 
\begin{align*}
    \mathbb{P}^{M\cdot (l+1)}_{x, \checkmark} =  \sum_{x'\in X}  \mathbb{P}^{M}_{x, x'} \cdot \mathbb{P}^{M\cdot l}_{x', \checkmark} \leq 1/2 \cdot (1/2)^{l} =  (1/2)^{l+1}.
\end{align*}
Finally, we prove the finiteness of the $n$-th termination moment on finite MCs as follows: 
\begin{align*}
    \sum_{w\in A^{+}} \mu\Phi_{c}(x_0)(w) \cdot |w|^{n} &= \sum_{m\in \nat} |m|^{n} \cdot  \mathbb{P}^m_{x_0, \checkmark} = \sum^{\infty}_{l = 0} \sum^{M-1}_{ k = 0} |M\cdot l + k|^{n}\cdot \mathbb{P}^{M\cdot l + k}_{x_0, \checkmark}\\
&= \sum^{\infty}_{l = 0} \sum^{M-1}_{ k = 0} |M\cdot l + k|^{n}\cdot \sum_{x'\in X}\mathbb{P}^{k}_{x_0, x'}\cdot  \mathbb{P}^{M\cdot l }_{x', \checkmark}\\
&\leq \sum^{\infty}_{l = 0} \sum^{M-1}_{ k = 0}  |M\cdot l + k|^{n}\cdot (1/2)^{l} < \infty.
\end{align*} 
\end{proof}


