\subsection{Proof of~\cref{prop:proofPolAmb}}
\label{subsec:proofPolAmb}
\begin{proof}
Given a trim MFA $d\colon Y\rightarrow \mfafunc{Y}$ with the initial state $y_0$, we construct an NFA $d'\colon Y'\rightarrow \powfunc(Y' + \{\checkmark\})^{A+\{\epsilon\}}$ with the same initial state $y_0$  and the empty string $\epsilon$ as follows. 
The set $Y'$ of states is given by $Y' \defeq Y + \{ (y, a, i, z)\in Y\times  A\times  \nat\times  (Y+\{\checkmark\}) \mid 1\leq  i \leq d(y)(a)(z) \}$.
The coalgebra $d'$ is defined as follows: 
\begin{align*}
  d'(y)(a) &\defeq \{ (y, a, i, z) \mid 1\leq i \leq d(y)(a)(z)\}, & d'(y)(\epsilon) \defeq \emptyset,\\
  d'(y, a, i, z)(\epsilon) &\defeq \{z\}, &d'(y, a, i, z)(a') \defeq \emptyset.
\end{align*}
By construction, the number of accepting runs of $d$ and $d'$ are the same. 
By~\cite{AllauzenMR11}, we can check the polynomial ambiguity of $d'$ in polynomial-time with respect to the size $|d'|$ of NFAs. 
Note that the size $|Y'|$ is bounded by $|Y| + |Y|\times A\times W\times (|Y|+\{\checkmark\})$, where $W$ is the maximum weight that appears in the weighted transitions of $d$. 
We can thus conclude that the polynomial ambiguity of $d$ is decidable in polynomial-time if we fix $W$.  
\end{proof}

\subsection{Proof of~\cref{prop:uniqueSolution}}
\label{proofOfUniqueSolution}
We follow the proof for the MC and unambiguous B\"{u}chi automaton~\cite{BaierK00023} with minor changes for MCs and MFAs. 

We first remark that $\mu \Phi_{c\otimes_{\lambda} d}(x, y)$ is finite for any $(x, y)\in Z$. Otherwise, we can easily see that $\mu \Phi_{c\otimes_{\lambda} d}(x_0, y_0)$ diverges because $(x, y)$ is reachable from $(x_0, y_0)$, contradicting to the assumption. 

Given a finite set $S$, we simply write a matrix $M\in  \nnegreal^{|S|\times |S|}$ by $M\in  \nnegreal^{S\times S}$ whose entries are indexed by the pairs of elements in $S$ (with a suitable total order in $S$ if it is required). 
For any $T\subseteq S$, we write $M_T\in  \nnegreal^{T\times T}$ for the submatrix whose entries are indexed by the pairs of elements in $T$.
We call a matrix $M$ \emph{strongly connected} (or \emph{strongly connected component}) if the underlying directed graph of $M$ is strongly connected (or \emph{strongly connected component}). 

For the proof, we use the matrix $B\in \nnegreal^{Z\times Z}$ that is defined as follows: 
\begin{align*}
    B_{(x, y), z} &\defeq (c\otimes_{\lambda} d)(x, y)(z), &&
    B_{\checkmark, z} \defeq   \begin{cases}
        1 &\text{ if } z = \checkmark,\\
        0        &\text{otherwise.}
    \end{cases} 
\end{align*}
for any $(x, y)\in Z\cap (X\times Y)$ and $z\in Z$. 
Let $W \subseteq Z$ be the set $W\defeq \{(x, y)\in Z\cap (X\times Y) \mid (x, y) \text{ is reachable to $\checkmark$} \} \cup \{\checkmark\}$. 

\begin{proposition}
  \label{prop:finitebound}
    There is a constant $C > 0$ such that $(B_{W, W})^{n}_{w_1, w_2} < C$ for any $n\in \nat$ and $w_1, w_2\in W$. 
\end{proposition}
\begin{proof}
    Assume that there are no such bound. 
    Then, for any $C > 0$, there is $n\in \nat$ such that $(B_{W, W})^{n}_{w_1, w_2} \geq C$ for some $w_1, w_2$. 
    Since the set $W$ is finite, we can further say that there are $w_1, w_2\in W$ such that for any $C > 0$, there is $n\in \nat$ such that $(B_{W, W})^{n}_{w_1, w_2} \geq C$.
    Note that $w_1$ cannot be $\checkmark$. 
    By definition, $(B_{W, W})^{n}_{w_1, w_2}$ is the expected number of runs from $w_1$ to $w_2$ in exactly $n$-steps (through $W$). 
    Since any $w\in W$ is reachable to $\checkmark$, the expected number of runs from $w_1$ to $\checkmark$ in exactly $n+1$-steps is at least $C\cdot (c\otimes_{\lambda}d)(w_2)(\checkmark) > 0$.
    Such $n\in \nat$ that satisfy $(B_{W, W})^{n}_{w_1, w_2} \geq C$ exist infinitely many: This is because we can make $C$ arbitrary large for the fixed $w_1$ and $w_2$. 
    Therefore, we can conclude that $\mu_{c\otimes_{\lambda} d}(w_1) \geq \sum^{\infty}_{k=0} C\cdot (c\otimes_{\lambda}d)(w_2)(\checkmark) = \infty$, contradicting to the finiteness of  $\mu_{c\otimes_{\lambda} d}(w_1)$. 
\end{proof}


Second, we recall spectral theory for non-negative matrices: We refer to~\cite{BermanP94,BaierK00023} as references. 

\begin{definition}[spectral radius]
    Given $M\in \nnegreal^{S\times S}$, the \emph{spectral radius}  $\rho(M)$ is the maximum absolute value of eigenvalues, that is, 
    $\rho(M) \defeq \max_{1\leq i\leq m} |\lambda_i|$, where $\lambda_1,\dots, \lambda_m$ are the eigenvalues of $M$. 
\end{definition}



\begin{proposition}[\!\!\cite{BermanP94}]
  \label{prop:nonnegmatrix}
    Given $M\in \nnegreal^{S\times S}$,  the following all statements hold: 
    \begin{itemize}
        \item The spectral radius $\rho(M)$ is an eigenvalue of $M$, and there is a nonnegative eigenvector $\vec{x}$ of $\rho(M)$. 
              We call such an eigenvector $\vec{x}$ \emph{dominant}.
        \item If $T\subseteq S$, then $\rho(M_{T, T})\leq \rho(M)$.
    \end{itemize}
\end{proposition}

\begin{proposition}[\!\!\cite{BermanP94}]
  Let $M\in \nnegreal^{S\times S}$ be a strongly connected matrix. The following statement holds: 
  \begin{itemize}
      \item If $\vec{x} \geq 0$ and $M\vec{x}\leq \rho(M)\vec{x}$ then $M\vec{x} = \rho(M)\vec{x}$. 
  \end{itemize}
  \end{proposition}

\begin{lemma}
  \label{lem:sizeSpectral}
  The inequality
      $\rho(B_{W, W}) \leq 1$ holds. Moreover, if $S\subseteq W$ is an SCC and $\rho(B_{S, S}) = 1$, then $S = \{\checkmark\}$.  
\end{lemma}
\begin{proof}
  By~\cref{prop:finitebound}, there is a constant $C$ such that $(B_{W, W})^{n}_{x, y} < C$  for any $n, x, y$. 
  Let $\vec{x}$ be a dominant eigenvector of $B_{W, W}$, that is, $B_{W, W}\vec{x} = \rho(B_{W, W})\vec{x}$. Then, for any $n$,  $\rho(B_{W, W})^{n}\vec{x} \leq (C\cdot |W|\cdot \|\vec{x}\|_{\infty})\vec{1}$. This means that $\rho(B_{W, W}) \leq 1$ because $\vec{x}$ is non-negative by~\cref{prop:nonnegmatrix}.   

  Suppose that $S \subseteq W$ such that $B_{S, S}$ is strongly connected component and $\rho(B_{S, S}) = 1$ (such SCCs are called \emph{recurrent SCC}~\cite{BaierK00023}). 
  We write $\widehat{\mu \Phi_{c\otimes_{\lambda} d}}\colon W\rightarrow \nonnegreal$ for the vector whose entries $\widehat{\mu \Phi_{c\otimes_{\lambda} d}}(z)$  are $ \mu \Phi_{c\otimes_{\lambda} d}(x, y)$ if $z = (x, y)\in X\times Y$ and $1$ if  $z = \checkmark$. 
  By definition, we know that $\widehat{\mu \Phi_{c\otimes_{\lambda} d}} = B_{W, W}(\widehat{\mu \Phi_{c\otimes_{\lambda} d}})$, and therefore $ B_{S, S}(\widehat{\mu \Phi_{c\otimes_{\lambda} d}}_S)\leq \widehat{\mu \Phi_{c\otimes_{\lambda} d}}_S $. 
  Since $B_{S, S}$ is strongly connected and $\rho(B_{S, S}) = 1$, we can see that $ B_{S, S}(\widehat{\mu \Phi_{c\otimes_{\lambda} d}}_S)= \widehat{\mu \Phi_{c\otimes_{\lambda} d}}_S $.
  It means that $ B_{S, S}(\widehat{\mu \Phi_{c\otimes_{\lambda} d}}_S)= B_{S, W}(\widehat{\mu \Phi_{c\otimes_{\lambda} d}}) $, and for any $i\in S$ and $j \in W\backslash S$, $B_{i, j} = 0$ because $(\mu \Phi_{c\otimes_{\lambda} d})(j) > 0$. 
  Therefore, we cannot leave from $S$ once we enter $S$. Since the target state $\checkmark$ is reachable from any state in $W$, $S$ must be the singleton $\{\checkmark\}$. 
\end{proof}

Finally, we prove~\cref{prop:uniqueSolution}, that is, the uniqueness of the solution of the equation system. 
Equivalently, we prove the uniquenss of the solution $\vec{x}\in W$ of the following equation system: 
\begin{align*}
  \vec{x} &= B_{W, W}\vec{x}, \quad x_{\checkmark} = 1.
\end{align*}
We prove this by the induction over the DAG of SCCs of (the underlying directed graph of) $B_{W, W}$. 
Let $\vec{y}$ be a solution for the equation system. 
For the base case (the SCC $\{\checkmark\}$), the equation $y_{\checkmark} = 1$ holds by the definition. 
Let $D$ be an SCC. We write $\mathbf{D}_r$ for the set of SCCs that can reach from $D$, but can not reach to $D$. 
By the induction hypothesis, we know that $\vec{y}_E =  \vec{x}_E$ for any $E\in \mathbf{D}_r$. 
Since $\vec{x} = B_{W, W}\vec{x}$ and  $\vec{y} = B_{W, W}\vec{y}$, we have 
\begin{align*}
  \vec{x}_D - \vec{y}_D = B_{D, W}(\vec{x} - \vec{y}) = B_{D, D}(\vec{x}_D - \vec{y}_D) + \sum_{E\in \mathbf{D}_r} B_{D, E}(\vec{x}_E - \vec{y}_E) = B_{D, D}(\vec{x}_D - \vec{y}_D).
\end{align*}
Since $D$ is not recurrent and $\rho(D) < 1$ by~\cref{lem:sizeSpectral,prop:nonnegmatrix}, 
this implies that $\vec{x}_D = \vec{y}_D$. \qed



