	]
	\def\s{0.35}
	\def\h{1}
	\def\n{12}
	\def\a{3}

	% subdivided path, a\i are original vertices, b\i subdivisions
	\pgfmathtruncatemacro\p{\n * \a}
	\foreach \i in {1,...,\p}{
