\title{Stream-Omni: Simultaneous Multimodal Interactions with Large Language-Vision-Speech Model}



\author{
Shaolei Zhang\textsuperscript{\rm 1,3},\quad Shoutao Guo\textsuperscript{\rm 1,3},\quad Qingkai Fang\textsuperscript{\rm 1,3},\quad Yan Zhou\textsuperscript{\rm 1,3},\quad Yang Feng\textsuperscript{\rm 1,2,3}\thanks{Corresponding author: Yang Feng.} \\
