\section{Tighter Guarantees for Submodular Instances} \label{app:objective_reductions_submodular}
In this section we show versions of  \Cref{lem:reduction_to_mrl} and \Cref{lem:reduction_from_mrl} with improved constants for the case where $f$ is submodular. More specifically, we prove the following two lemmas:
\begin{lemma} 
[Constant-Factor Reduction from $\MAX\varphi(B)$ to $\maxlightreward(B)$, submodular $f$]
\label{lem:reduction_to_mrl_submodular}
    Fix an instance $\instance$ with submodular $f$, a budget $B\in (0,1]$, and a \goodobj  \
    objective $\varphi$.
    For any given team $S \subseteq \agents$ that is a $\gamma$-approximation to $\maxlightreward(B)$, let $S'$ be the result of applying \Cref{lem:submodular_payment_scaling} to $S$ with $M=3$. Then, it holds that one of $\{\{i\}\}_{i\in \agents} \cup \{S\}$ is a $(6\gamma+1)$-approximation to $\MAX\varphi(B)$.
\end{lemma}

\begin{lemma}
[Constant-Factor Reduction from $\maxlightreward(B)$ to $\MAX\varphi(B')$, submodular $f$]
 \label{lem:reduction_from_mrl_submodular}
    Let $I=\instance$  be an
    instance such that $f$ is submodular, let $\varphi$ be a \goodobj\  objective, and let $B, B'\in(0,1]$.
    Consider the instance $I'=\langle \lightagents, f\mid_\lightagents, \frac{c\cdot B'}{B}\mid_\lightagents\rangle$, i.e., $I'$ is the same as $I$ except with only the light agents, and all costs have been scaled by $\frac{B'}{B}$. 

    If $S$ is a $\gamma$-approximation to $\MAX\varphi(B')$ in $I'$, then one of $\{\{i\}\}_{i\in \agents} \cup \{S\}$ is a $6\gamma$-approximation to $\maxlightreward(B)$ in $I$.
\end{lemma}

We first prove a version of \Cref{lemma:goodobj_upper_bound} for the case of submodular $f$ with a better constant:
\begin{lemma} [Key Property of \goodobj\ Objectives with Submodular $f$]\label{lemma:goodobj_upper_bound_submodular}
 Fix an instance $\instance$ with submodular $f$, a budget $B\in (0,1]$, and a \goodobj\ objective $\varphi$. It holds that
\[
\MAX\varphi(B) \le \maxlightreward(B)+\max_{i\in \agents} \varphi(\{i\}).
\]
\end{lemma}
\begin{proof}
    Let $S^\star$ be an optimal solution to $\MAX\varphi(B)$, i.e., $\varphi(S^\star) = \MAX\varphi(B)$ and $p(S^\star) \le B$.
    Note that, by \Cref{obs:1_heavy}, $S^\star$ contains at most $1$ heavy agent. If it contains no heavy agents, we have 
    $\varphi(S^\star) \le f(S^\star) \le \maxlightreward(B)$, as needed.
    Otherwise, let $S^\star \setminus \lightagents= \{i^\star\}$ and we get 

    \begin{align*}
    \varphi(S^\star)
    &\le
    \varphi(S^\star \cap \lightagents) + \varphi(\{i^\star\}) && (\text{property $1$ of \goodobj\ objectives}) \\
    &\le
    f(S^\star \cap \lightagents) + \max_{i \in A} \varphi(\{i\}) && (\varphi \le f).  \\
    &\le \maxlightreward(B)+\max_{i\in \agents} \varphi(\{i\}) && (P(S^\star\cap L) \le P(S^\star)\le B),
    \end{align*}
    where the last inequality is because when $f$ is submodular the payment function $p$ is monotone.
\end{proof}

\begin{proof} [Proof of \Cref{lem:reduction_to_mrl_submodular}]
    We start by showing that 
    \[
    6\gamma \cdot \varphi(S') \ge \maxlightreward(B).
    \]
    This holds, because by the guarantees of \Cref{lem:submodular_payment_scaling} we have 
    \[f(S')\ge \frac{1}{M-1} f(S^\star) \ge \frac{1}{2\gamma} \maxlightreward(B),
    \]
    Moreover, we have either $|S'| = 1$ or $p(S') \leq (2/3) \cdot p(S)$. Observe that $S'$ is budget-feasible since, if $|S'|\ne 1$ then $p(S')\le \frac{2}{3}p(S)\le \frac{2}{3}B\le B$, and if $|S'|=1$ then from sub-additivity of $f$,
    \[
    p(\{i\})=\frac{c_i}{f(\{i\})}\le \frac{c_i}{f(S)-f(S\setminus\{i\})}=\frac{c_i}{f_S(i)}\le \sum_{j\in S}\frac{c_j}{f_S(j)}=p(S)\le B.
    \]

    We will now show that $p(S') \leq 2/3$. If $|S'| = 1$, then since $S' \subseteq \lightagents$, it follows that $p(S') \leq 1/2$.
    If $p(S') \leq (2/3) \cdot p(S)$, then by the budget feasibility of $S$, we get $p(S') \leq (2/3) \cdot p(S) \leq (2/3) \cdot B \le 2/3$. 
 Now,
    \[
    \varphi(S') \ge g(S') = (1-p(S'))f(S') \ge \left(1-\frac{2}{3}\right)\frac{1}{2} f(S) = \frac{1}{6\gamma}\maxlightreward(B).
    \]
    Thus, by \Cref{lemma:goodobj_upper_bound_submodular} we have
    \begin{align*}
    \MAX\varphi(B)&\le \maxlightreward(B)+\max_{i\in \agents} \varphi(\{i\}) \le 6\gamma \cdot \varphi(S')+\max_{i\in \agents} \varphi(\{i\}),
    \end{align*}
    as needed.
\end{proof}

\begin{proof} [Proof of \Cref{lem:reduction_from_mrl_submodular}]
Let $S^\star$ be a solution to $\maxlightreward(B)$, i.e., $S\subseteq \lightagents$ and satisfies both $f(S^\star) = \maxlightreward(B)$ and $p(S^\star) \le B$. 
Apply \Cref{lem:submodular_payment_scaling} to $S^\star$ with $M=3$, and get a set $T$ such that $f(T) \ge \frac{1}{M-1} f(S^\star)=\frac{1}{2}f(S^\star)$ and either $|T|=1$ or $p(T) \le \frac{2}{3} p(S) \le \frac{2}{3}B$. Observe that, in either case, $p(T)\le p(S^\star)\le B$.

Note that if $|T|=1$, then $T$ itself is a $2$-approximation to $\maxlightreward(B)$, and therefore also a $6\gamma$ approximation, concluding the proof. 

Otherwise, let $p'$, $\varphi'$, and $g'$ denote the total payment, objective $\varphi$, and the principal's profit (respectively) in the scaled instance $I'$. Note that $p'(T) =\frac{B'}{B}p(T) \le \frac{2}{3}B' \le \frac{2}{3}$, and therefore $T$ is budget-feasible in $I'$ with respect to $B'$, and also
\[
\begin{split}
f(S) &\ge \varphi'(S) \ge \frac{1}{\gamma} \varphi'(T) \ge \frac{1}{\gamma} g'(T) =\frac{1}{\gamma} (1-p'(T))f(T) \\
&\ge \frac{1}{\gamma}\left(1-\frac{2}{3}\right)\frac{1}{2}f(S^\star) \ge \frac{1}{6\gamma} \maxlightreward(B).
\end{split}
\]
Additionally, $S$ is budget-feasible in the original instance $I$, since $p(S) = \frac{B}{B'}\cdot p'(S) \le \frac{B}{B'} \cdot B'=B$, concluding the proof.
\end{proof}


\section{FPTAS for Additive Instances}
\label{app:additive_fptas}

In this section we consider the multi-agent 
budgeted setting when $f$ is additive. Notably, in this case any additive objective (and in particular the expected reward and social welfare) is equivalent to a \textsc{Knapsack} problem, implying that exact solutions are NP-hard to compute and the existence of FPTAS.
\begin{remark}\label{remark:additive_f_sw_reward_fptas}
    For the case of additive $f$, let $\varphi$ be an additive objective (i.e., for any instance $\instance$ it holds that $\varphi_{\instance}$ is additive) and let $B\in (0,1]$. The problem $\MAX\varphi(B)$ is equivalent to the knapsack problem with items $\agents$, capacity $B$, weights $\frac{c_i}{f(\{i\})}$ for all $i\in \agents$, and values $\varphi(\{i\})$.
\end{remark}
\cite{duetting2022multi} show that in a multi-agent setting with 
an additive reward function $f$, the optimal contract problem is NP-hard. This hardness carries over trivially to the corresponding budgeted setting. Additionally, \cite{duetting2022multi} demonstrate that this problem admits an FPTAS. The following proposition establishes that the algorithms used to achieve this result can be adapted to provide an FPTAS for budgeted settings as well.


\newcommand{\tf}{\tilde{f}}

\begin{proposition}\label{prop:FPTAS}
    In a multi-agent setting with additive reward function $f$, the optimal budgeted contract problem admits an FPTAS.    
\end{proposition}

Let $S^*$ be the set that maximizes the principal's utility under budget constraints., with $b = \max_{i \in S^*} f_i$. We may assume we know $b$, as we can run the algorithm with the $n$ different possible values. 

For any $\eps >0$, let $\delta = \frac{\eps}{n}$.
We define a rounded reward function as follows: $\tf(\{i\}) = \floor{\frac{f(\{i\})}{\delta b}}\cdot \delta b$ and $\tf(S) = \sum_{i \in S} \tf(\{i\})$. 
Observe that all values of $\tf$ are multiples of $\delta b$.




Let $T: \{0,\dots,\ceil{\frac{n}{\delta}}\} \to 2^{[n]}$ be the function that for every $k \in \{0,\dots,\ceil{\frac{n}{\delta}}\}$ returns the set $T(k)$ that minimizes $\sum_{i \in S} \frac{c_i}{f(\{i\})}$ subject to $\tf(S) \ge k\delta b$.


It was shown in \cite{duetting2022multi} that the table which represent the function $T$ can be computed in poly-time in $n$ and $\frac{1}{\eps}$.





\begin{proof}[Proof of \cref{prop:FPTAS}]







    Our algorithm returns the set of agents $T^*$ that maximizes the principal's profit among all sets computed in the table $T$ which are budget-feasible. Namely, $T^* := T(k^*)$, is the budget-feasible set, i.e. $\sum_{i \in T(k^*)} \frac{c_i}{f(\{i\})} \le B$, which maximizes $\left( 1 -  \sum_{i \in S} \frac{c_i}{f(\{i\})} \right) k \delta b$ for any $k$ as above.

    We will show that $g(T^*) \ge (1-\eps) g(S^*)$:
    \begin{eqnarray*}
        g(T^*)
        =
        \left( 1 -  \sum_{i \in T^*} \frac{c_i}{f(\{i\})} \right)f(T^*) 
        \ge
        \left( 1 -  \sum_{i \in T^*} \frac{c_i}{f(\{i\})} \right) k^* \delta b
    \end{eqnarray*}

    Denote $\tf(S^*) = \hat{k} \delta b$. 
    Since $S^*$ is budget-feasible and $f(S^*) \ge \tf(S^*) = \hat{k} \delta b$, we get, by definition of $T$, that $T(\hat{k})$ is also budget feasible. By optimality of $T^*$ we have
    $$
    \left( 1 -  \sum_{i \in T^*} \frac{c_i}{f(\{i\})} \right) k^* \delta b
    \ge
    \left( 1 -  \sum_{i \in T(\hat{k})} \frac{c_i}{f(\{i\})} \right)\hat{k}\delta b
    \ge
    \left( 1 -  \sum_{i \in S^*} \frac{c_i}{f(\{i\})} \right)\tf(S^*)
    $$
    where the last inequality is by definition of the function $T$.

    Finally, observe that
    $$
    \tf(S^*) = \sum_{i \in S^*} \tf(\{i\}) 
    \ge \sum_{i \in S^*} (f(\{i\}) - \delta b)
    \ge f(S^*) - n\delta b
    = f(S^*) - \eps \cdot \max_{i \in S^*} f(\{i\})
    \ge (1-\eps)f(S^*)
    $$
    and we have
    $g(T^*) \ge (1-\eps) g(S^*)$.
\end{proof}


\section{Missing Proofs from Section 5} \label{sec:price_of_f_proofs}

\subsection{Proof of Theorem 5.2}
















In the following lemma, we upper bound  the price of frugality for any BEST objective under XOS $f$.

\begin{lemma}[Upper Bound on Price of Frugality for BEST Objectives]\label{lem:upperxosfdlkdsfj}
     For any $0 < b < B \leq 1$ and any \goodobj\ objective $\varphi$, it holds that:
\begin{align*}
    \gapphixos(b,B) = O(\min(B/b, n))
\end{align*}
\end{lemma}

\begin{proof}
From \Cref{lemma:goodobj_upper_bound} we know that
\[
\frac{\MAX\varphi(B)}{\MAX\varphi(b)}\le \frac{2 \cdot \maxlightreward(B) +\max_{i\in \agents} \varphi(\{i\})}{\MAX\varphi(b)}.
\]
First, we note that by the assumption that any single agent is incentivizable under $b$, it holds that $\MAX\varphi(b)\ge \max_{i\in \agents}\varphi(\{i\})$. Therefore, for asymptotic bounds we are interested in the ratio
\[
\frac{2\cdot \maxlightreward(B)}{\MAX\varphi(b)}.
\]
Note that because $f$ is subadditive we have 
\[
\begin{split}
2\maxlightreward(B) &\le n\cdot \max_{i\in \lightagents} f(\{i\}) \le n\cdot 2\max_{i\in \lightagents} (1-p(\{i\}) \cdot f(\{i\}) \le 2n\cdot \max_{i\in \lightagents} g(\{i\}) \\
&\le \max_{i\in \lightagents} \varphi(\{i\}) \le 2n\cdot \MAX\varphi(b).
\end{split}
\]

Now, let $S\subseteq \lightagents$ be a solution to $\maxlightreward(B)$, and define $M = \lceil 8B/b \rceil$. We show that $\MAX\varphi(b) \geq (1/(4M-4)) \cdot \maxlightreward(B)$. Since $b < B$ implies $8B/b > 8$, we have $M \geq 3$.  
Thus, applying \Cref{lem:scale_xos}, there exists a subset $T \subseteq S$ such that $\varphi(T) \geq (1/(2M-2)) \cdot \varphi(S)$ and either $p(T) \leq (4/M) \cdot p(S)$ or $|T| = 1$.  
If $|T| = 1$, then $p(T) \leq b$ by assumption, and because $S\subseteq\lightagents$ we also have $p(T)\le \frac{1}{2}$. Otherwise, since $M = \lceil 8B/b \rceil$, it follows that $p(T) \leq (4/M) \cdot p(S) \leq (b/2B) \cdot B = \frac{1}{2}b$. Thus, $p(T) \leq \frac{1}{2}b$. In particular, $T$ is budget-feasible with respect to $b$ and $p(T)\le \frac{1}{2}$, so
\[
\varphi(T) \ge g(T) =(1-p(T)) \cdot f(T) \ge \frac{1}{2} \frac{1}{(2M-2)}f(S)=\frac{1}{(4M-4)}\maxlightreward(B).
\]

This concludes the proof since $1/(4M-4) = 1/(4\lceil 8B/b \rceil -4) \geq 1/(4(8B/b + 1) - 4) = (1/32) \cdot (b/B)$.
\end{proof}


We also give an asymptotically tight lower bound.

\begin{restatable}[Lower Bound on Price of Frugality for BEST Objectives]
    {lemma}{pofsandwiched} \label{lem:pof_sandwiched}
 For any $0 < b < B \leq 1$ and any \goodobj\ objective $\varphi$, it holds that:
\begin{align*}
 \gapphixos(b,B) = \Omega(\min(B/b,n)).
\end{align*}
\end{restatable}
\begin{proof}
    If $B \leq 2b$, then $\min(B/b, n) = \Omega(1)$, so it suffices to observe that $\gapphixos(b, B) \geq 1$. For $B > 2b$, we have:  
    \begin{align*}
        \MAX\varphi(B) \geq \maxrevenue(B) \geq (1-B/2) \cdot \maxreward(B/2) \geq (1/2) \cdot \maxreward(B/2)
    \end{align*}
   and $\MAX\varphi(b) \leq \maxreward(b)$.  
Therefore:
\begin{align*}
    \gapphixos(b, B) \geq \gaprewardxos(b, B/2) = \Omega(\min(B/(2b), n)).
\end{align*}  
The result follows.  
\end{proof}

We are finally ready to prove \Cref{thm:price_asymptotic}.

\asymptoticfrugality*
\begin{proof}
This follows directly from \Cref{lem:upperxosfdlkdsfj,lem:pof_sandwiched}.
\end{proof}
















