\begin{lemma}\label{lem:pof_rev_upper}
For any $0 < b < B \leq 1$ and $0 < \varepsilon < B -b $,
    there exists an 
    instance $\instance$ with additive $f$ and $p(\{i\}) \leq b$ for all $i \in \agents$ such that:
    \begin{align*}
    \gaprevenue(b,B) \geq (1-\varepsilon/2) \cdot (2-b) \xrightarrow{\varepsilon \to 0} 2-b.
    \end{align*}
\end{lemma}
\begin{proof}
The instance used in the following proof is depicted in \Cref{fig:rev_impo}.

    Consider an instance with two agents, where the reward $f$ is additive with $f(\{1\}) = 1/2$ and $f(\{2\}) = 1/2 - b/2$, and the agents' costs are $c_1 = b/2$ and $c_2 = \varepsilon \cdot (1/2 - b/2)^2$. It holds that $p(\{1\}) = c_1 / f_{\{1\}}(1) = b$ and $p(\{2\}) = c_2 / f_{\{2\}}(2) = \varepsilon \cdot (1/2 - b/2)$. Given $\varepsilon < B - b$ and $b < 1$, we obtain $p(\{1,2\}) =c_1 / f_{\{1,2\}}(1) + c_2 / f_{\{1,2\}}(2) = b + \varepsilon \cdot (1/2 - b/2) < B$, implying:
    \begin{align*}
        \maxrevenue(B) &\geq (1-p(\{1,2\})) \cdot f(\{1,2\}) \\
        &= (1-b-\varepsilon \cdot (1/2 - b/2)) \cdot (1-b/2) \\
        &= (1/2 - b/2 - (\varepsilon/2) \cdot (1/2 - b/2)) \cdot (2-b) \\ 
        &= (1-\varepsilon/2) \cdot (1/2 - b/2) \cdot (2-b).
    \end{align*} 

    Since $p(\{1,2\}) = b + \varepsilon \cdot (1/2 - b/2) > b$,  we can bound $\maxrevenue(b)$ as follows. 
    Note that $(1-p(\{1\})) \cdot f(\{1\}) = (1-b) \cdot (1/2) = 1/2 - b/2$ and that $(1-p(\{2\})) \cdot f(\{2\}) = (1-\varepsilon \cdot (1/2-b/2)) \cdot (1/2-b/2) < 1/2-b/2$. 
    Thus, $\maxrevenue(b) \leq 1/2 - b/2$, and
    we obtain:
    \begin{align*}
        \frac{\maxrevenue(B)}{\maxrevenue(b)} \geq \frac{(1-\varepsilon/2) \cdot (1/2-b/2) \cdot (2-b)}{1/2-b/2}  = (1-\varepsilon/2) \cdot (2-b),
    \end{align*}
    which concludes the proof.
\end{proof}

We next give our second lower bound on the price of frugality for profit.


\begin{lemma}\label{lem:pof_rev_upper_2}
For any $0 < b < B \leq 1$, any integer $1 \leq k < \min(2B/b, n+1)$,  and $0 < \varepsilon < 2B/k - b$, there exists an 
instance $\instance$ with additive $f$ and $p(\{i\}) \leq b$ for all $i \in \agents$ such that:
    \begin{align*}
    \gaprevenue(b,B) \geq \frac{(2-k \cdot (b + \varepsilon)) \cdot k}{2-b-\varepsilon} \xrightarrow{\varepsilon \to 0} \frac{(2-k \cdot b) \cdot k}{2-b}.
    \end{align*}
Moreover, for any $b$ and $B$, the expression above is minimized at $k = \min(\lfloor 1 / b + 1/2 \rfloor, \lceil 2B/b \rceil - 1, n)$.
\end{lemma}
\begin{proof}
The instance used in the following proof is depicted in \Cref{fig:rev_impo_2}. 

    Consider an instance with $k$ agents, where the reward $f$ is additive with $f(\{i\}) = 1/k$ for all $i \in \agents$ and the costs are $c_i = (1/k) \cdot (b/2 + \varepsilon/2)$ for all $i \in \agents$. It holds that $p(\{i\}) = c_i / f_{\{i\}}(i) = b/2 + \varepsilon/2$. Since $\varepsilon < 2B/k - b$, we get $p(A) = \sum_{i=1}^k c_i / f_{\{i\}}(i) = k \cdot (b/2 + \varepsilon/2) < k \cdot (b/2 + B/k - b/2) = B$. Thus, the optimal profit satisfies $\maxrevenue(B) \geq (1-p(A)) \cdot f(A) = (1 - k \cdot (b/2 + \varepsilon/2)) \cdot 1$.  

Since $p(T) = |T| \cdot (b/2 + \varepsilon/2)$, only singletons are budget-feasible. Therefore, we have $\maxrevenue(b) \leq (1 - p(\{1\})) \cdot f(\{1\}) = (1 - b/2 - \varepsilon/2) \cdot (1/k)$. This gives the desired  lower bound on the price of frugality.

For the second part of the statement, note that minimizing $(2-b)/((2-k \cdot b) \cdot k)$ is equivalent to maximizing the quadratic function $(2-k \cdot b) \cdot k = (1/b) \cdot (2/b - k) \cdot k$, which attains its maximum at $k = 1/b$. However, $k = 1/b$ may not be an integer and it may violate $k < \min(2B/b, n+1)$. 

If $\lfloor 1/b + 1/2 \rfloor < \min(2B/b, n+1)$, then the quadratic function is maximized at $k = \lfloor 1/b + 1/2 \rfloor$, as this is the closest integer to $1/b$. Otherwise, if $\lfloor 1/b + 1/2 \rfloor \geq  \min(2B/b, n+1)$, the integer closest to $1/b$ among all permissible values of $k$ is precisely $k = \min(\lceil 2B/b \rceil - 1, n)$.  
\end{proof}

We are now ready to prove \Cref{thm:revenuepofff}.

\begin{proof}[Proof of \Cref{thm:revenuepofff}]
The upper bound for the price of frugality for profit follows from \Cref{lem:revenue_upper}, while the lower bound follows from \Cref{lem:pof_rev_upper,lem:pof_rev_upper_2}.
\end{proof}
