\section{Alternate Optimization of Original Problem}
\vspace{1.0em}


In this section, we first approximate the original optimization problem by introducing an auxiliary variable to turn it, and then combine it with the quadratic transformation theorem to reconstruct the original problem into an easy-to-handle equivalent optimization form, and further solve the optimization problem by using the AO method.


\subsection{Equivalent Transformation of Original Problem \eqref{mosd2}}

To deal with the nonconvexity of the original WSR maximization problem \eqref{mosd2}, we adopt the Lagrangian dyadic transformation method to transform problem \eqref{mosd2} into an equivalent optimization problem by introducing auxiliary variables \cite{043}. In particular, with the help of the introduced auxiliary variable, the rate $\log_2(1+\mathrm{SINR}_m)$ in the objective function of problem \eqref{mosd2} can be expressed as the optimization problem in \textbf{Theorem 1}.
\begin{theorem}
With the $\text{SINR}_m$ of user $m$, the rate $\log_2(1+\mathrm{SINR}_m)$ can  be formulated as
\begin{align}\label{sldo2}
\log_2(1 + \text{SINR}_m) &= \max_{\gamma_m \geq 0} \left[ \log_2(1 + \gamma_m) - \frac{\gamma_m}{\ln 2} \right. \nonumber\\
&\quad + \left. \frac{(1 + \gamma_m) \text{SINR}_m}{\ln 2 (1 + \text{SINR}_m)} \right].
\end{align}
\end{theorem}

\begin{proof}
We first define an auxiliary function as
\begin{equation}
f(\gamma_m) = \log_2(1 + \gamma_m) - \frac{\gamma_m}{\ln 2} + \frac{(1 + \gamma_m) \text{SINR}_m}{\ln 2(1 + \text{SINR}_m)}.
\end{equation}

Then the derivative of $f(\gamma_m)$ with respect to the variable $\gamma_m$ is given by
\begin{equation}
\frac{\partial f}{\partial \gamma_m} = \frac{1}{\ln 2} \cdot \frac{1}{1 + \gamma_m} - \frac{1}{\ln 2} + \frac{\text{SINR}_m}{\ln 2 (1 + \text{SINR}_m)}.
\end{equation}
Let the derivative be zero, we have
\begin{equation}\label{lspd}
\frac{1}{1 + \gamma_m} - 1 + \frac{\text{SINR}_m}{1 + \text{SINR}_m} = 0.
\end{equation}
By further simplifying \eqref{lspd}, results in
\begin{equation}
\frac{1}{1 + \gamma_m} = 1 - \frac{\text{SINR}_m}{1 + \text{SINR}_m} = \frac{1}{1 + \text{SINR}_m}.
\end{equation}
Furthermore, the second-order derivative of $f(\gamma_m)$ with respect to the variable $\gamma_m$ is $\frac{\partial^2 f}{\partial \gamma_m^2}=-\frac{1}{(1 + \gamma_m)^2}<0$. Thus, the optimal solution of problem \eqref{sldo2} can be expressed as
\begin{equation}\label{sldow21}
\gamma_m^* = \text{SINR}_m.
\end{equation}
Substituting the optimal value $\gamma_m^*$ into $f(\gamma_m)$, we have
\begin{align}
f(\text{SINR}_m) &= \log_2(1 + \text{SINR}_m) - \frac{\text{SINR}_m}{\ln 2} \nonumber\\
&\quad + \frac{(1 + \text{SINR}_m) \text{SINR}_m}{\ln 2 (1 + \text{SINR}_m)} \nonumber\\
&= \log_2(1 + \text{SINR}_m) - \frac{\text{SINR}_m}{\ln 2} + \frac{\text{SINR}_m}{\ln 2} \nonumber\\
&= \log_2(1 + \text{SINR}_m).
\end{align}
\end{proof}
\begin{remark}
By using the theorem, the data rate $\log_2(1+\mathrm{SINR}_m)$ which is the objective function in problem \eqref{mosd2} can be equivalently expressed as optimization problem \eqref{sldo2} by introducing variable $\gamma_m$. Especially, $\log_2(1+\mathrm{SINR}_m)$ can be obtained at the optimal $\gamma_m^{*}=\mathrm{SINR}_m$.
\end{remark}

However, the fractional term $\frac{\text{SINR}_m}{1 + \text{SINR}_m}$ in \eqref{sldo2} is still difficult to optimize directly. By introducing another auxiliary variable, fractional term $\frac{\text{SINR}_m}{1 + \text{SINR}_m}$ can be further recast with quadratic transformation \cite{044} shown in following theorem.
\begin{theorem}
For any $\text{SINR}_m \geq 0$, the fractional term $\frac{\text{SINR}_m}{1 + \text{SINR}_m}$ in \eqref{sldo2} can be formulated as
\begin{equation}
\begin{aligned}
\frac{\text{SINR}_m}{1 + \text{SINR}_m} &= \max_{y_m \geq 0} \left[ 2 y_m \sqrt{G_m} - y_m^2 (G_m + I_m + \sigma^2) \right].
\end{aligned}
\end{equation}
\end{theorem}

\begin{proof}
Let $G_m = |\mathbf{h}_m^H \mathbf{p}_m|^2$ and $I_m = \sum_{n \ne m} |\mathbf{h}_m^H \mathbf{p}_n|^2$, then fractional term $\frac{\text{SINR}_m}{1 + \text{SINR}_m}$ can be expressed as
\begin{equation}
\frac{\text{SINR}_m}{1 + \text{SINR}_m} = \frac{G_m}{G_m + I_m + \sigma^2}.
\end{equation}
According to the quadratic transformation \cite{044}, we define a function $f(y_m)$ as
\begin{equation}
f(y_m) = 2 y_m \sqrt{G_m} - y_m^2 (G_m + I_m + \sigma^2).
\end{equation}
The derivative of $f(y_m)$ can be obtained by
\begin{equation}
f'(y_m) = 2 \sqrt{G_m} - 2 y_m (G_m + I_m + \sigma^2).
\end{equation}
Let the derivative be zero, i.e.,
\begin{equation}
2 \sqrt{G_m} - 2 y_m (G_m + I_m + \sigma^2) = 0,
\end{equation}
then, we have
\begin{equation}\label{tr43}
y_m^* = \frac{\sqrt{G_m}}{G_m + I_m + \sigma^2}.
\end{equation}
Since $G_m > 0$ and $G_m+I_m + \sigma^2 > 0$, thus the condition $y_m > 0$ is satisfied. To verify that $y_m^*$ is the maximum point, the second-order derivative is calculated by

\begin{equation}
f''(y_m) = \frac{d}{d y_m} \left( 2 \sqrt{G_m} - 2 y_m (G_m + I_m + \sigma^2) \right),
\end{equation}
and
\begin{equation}
f''(y_m) = -2 (G_m + I_m + \sigma^2) < 0.
\end{equation}
By substituting $y_m^*$ into $g(y_m)$, we have
\begin{align}
g(y_m^*) &= 2 \left( \frac{\sqrt{G_m}}{G_m + I_m + \sigma^2} \right) \sqrt{G_m} \nonumber\\
&\quad - \left( \frac{\sqrt{G_m}}{G_m + I_m + \sigma^2} \right)^2 (G_m + I_m + \sigma^2)\nonumber\\
&= 2 \cdot \frac{G_m}{G_m + I_m + \sigma^2} - \frac{G_m}{G_m + I_m + \sigma^2} \nonumber\\
          &= \frac{G_m}{G_m + I_m + \sigma^2} \nonumber\\
          &= \frac{\text{SINR}_m}{1 + \text{SINR}_m}.
\end{align}
\end{proof}
Based on Theorem 1 and Theorem 2, the original problem \eqref{mosd2} is converted to
\begin{subequations}\label{mosd5}
\begin{align}
& \max_{\mathbf{d}, \mathbf{p}_m, \gamma_m, y_m} \sum_{m=1}^{M} w_m \left[ \log_2(1 + \gamma_m) - \frac{\gamma_m}{\ln 2} + \frac{1 + \gamma_m}{\ln 2} \right. \nonumber\\
&\quad\quad\quad \left( 2 y_m \sqrt{G_m} - y_m^2 (G_m + I_m + \sigma^2) \right), \label{sldp21} \\
&\mathrm{s.t.} \quad \sum_{m=1}^{M} \|\mathbf{p}_m\|^2 \leq P_{\text{total}}, \label{sldo14} \\
&\quad\quad \quad d_k \in D, \quad \forall k = 1, 2, \dots, K, \label{sld14} \\
& \quad\quad\quad \text{SINR}_m \geq \gamma_m^{\min}, \quad \forall m = 1, 2, \dots, M, \label{stre14}\\
&\quad\quad\quad\gamma_m \geq 0, \quad y_m \geq 0, \quad \forall m = 1, 2, \dots, M. \label{stre15}
\end{align}
\end{subequations}

\textbf{Theorem 1} and \textbf{Theorem 2} provide an equivalence transformation of the original optimization problem \eqref{mosd2} by introducing variables $\gamma_m$ and $y_m$. Note that the objective function \eqref{sldp21} can be easier handled compared to the objective function \eqref{sldo61}. However, problem \eqref{mosd5} is still difficult to deal with because of the constraints on variables $d_k$ and $\mathbf{p}_m$.

\subsection{Alternate Optimization of Problem \eqref{mosd5}}

It is important to point out that problem \eqref{mosd5} is still nonconvex due to the coupling of variables $\mathbf{p}_m$, $\mathbf{d}$, $\gamma_m$, and $y_m$. Thus, we solve problem \eqref{mosd5} alternately, including the auxiliary variables update and subproblems update.
\subsubsection{Auxiliary variables update}
The auxiliary variables $\gamma_m$ and $y_m$ can be obtained by \eqref{sldow21} and \eqref{tr43} with given $G_m$ and $I_m$. Thus, the auxiliary variables update are given by
\begin{equation}\label{mosd520}
\gamma_m^{(t+1)} = \frac{G_m^{(t)}}{I_m^{(t)} + \sigma^2},
\end{equation}
and
\begin{equation}\label{mosd521}
y_m^{(t+1)} = \frac{\sqrt{G^{(t)}_m}}{G^{(t)}_m + I^{(t)}_m + \sigma^2},
\end{equation}
where $G^{(t)}_m$ and $I^{(t)}_m$ denote the $t$-th iteration of $G_m$ and $I_m$.

\subsubsection{{Beamforming Coefficient $\mathbf{p}_m$} update}
For given $y_m^{(t)}$, $\mathbf{d}^{(t)}$ and $\gamma_m^{(t)}$, the subproblem of problem \eqref{mosd5} on variable $\mathbf{p}_m$ can be formulated as
\begin{subequations}\label{sldp32}
\begin{align}
& \max_{\mathbf{p}_m} \sum_{m=1}^{M} \frac{w_m (1 + \gamma_m^{(t)})}{\ln 2} \bigg[ 2y_m^{(t)} \sqrt{G_m} - \left(y_m^{(t)}\right)^2 \nonumber\\
&\quad\left(G_m + I_m + \sigma^2\right) \bigg],\label{obj2}\\
& \mathrm{s.t.} \sum_{m=1}^{M} \|\mathbf{p}_m\|^2 \leq P_{\text{total}}, \label{sldo611} \\
& \quad\mathrm{SINR}_m = \frac{G_m}{\sigma^2 + I_m} \geq \gamma_m^{\min}, \quad \forall m = 1, 2, \dots, M. \label{stre712}
\end{align}
\end{subequations}

Since $G_m$ and $I_m$ are nonconvex functions with respect to variable $\mathbf{p}_m$, the objective function and the $\mathrm{SINR}_m$ constraint in subproblem \eqref{sldp32} are nonconvex. To solve this problem, we perform a first-order Taylor expansion of $G_m$ at $\mathbf{p}_m^{(t)}$, i.e.,
\begin{equation}\label{mosd522}
\sqrt{G_m} \approx \sqrt{G_m^{(t)}} + \frac{1}{2\sqrt{G_m^{(t)}}} \text{Re} \left( \mathbf{h}_m^H ( \mathbf{p}_m - \mathbf{p}_m^{(t)} ) \right).
\end{equation}
Similarly, the linearization$ ofI_m$ can be approximated as
\begin{equation}\label{mosd523}
I_m \approx I_m^{(t)} + 2\!\sum_{n \neq m} \text{Re} \left( \left( \mathbf{p}_n^{(t)} \right)^H \!\mathbf{h}_m \mathbf{h}_m^H \left( \mathbf{p}_n - \mathbf{p}_n^{(t)} \right) \right).
\end{equation}
Then the objective function \eqref{obj2} can be approximated by
\begin{align}
&\tilde{f}_p(\mathbf{p}_m ) \triangleq \sum_{m=1}^{M} w_m \frac{1 + \gamma_m^{(t)}}{\ln 2} \Bigg[ 2y_m^{(t)} \bigg( \sqrt{G_m^{(t)}} + \frac{1}{2\sqrt{G_m^{(t)}}}\nonumber\\ &\cdot\text{Re} \left( h_m^H (\mathbf{p}_m - \mathbf{p}_m^{(t)}) \right) \bigg)- \left( y_m^{(t)} \right)^2 \left( G_m^{(t)} + I_m^{(t)} \right)\nonumber \\
&+ 2 \sum_{n \neq m} \text{Re} \left( \left( \mathbf{p}_n^{(t)} \right)^H h_m h_m^H \left( \mathbf{p}_n - \mathbf{p}_n^{(t)} \right) \right) + \sigma^2 \Bigg].
\end{align}
The $\mathrm{SINR}_m$ constraint \eqref{stre712} can be approximated by
\begin{equation}
\begin{aligned}\label{sinre2}
G_m - \gamma_{\min}^{m} \Big( & I_m^{(t)} + 2 \sum_{n \neq m} \text{Re} \left( \left( \mathbf{p}_n^{(t)} \right)^H \mathbf{h}_m \mathbf{h}_m^H \left( \mathbf{p}_n - \mathbf{p}_n^{(t)} \right) \right) \\
& \quad \quad + \sigma^2 \Big) \geq 0.
\end{aligned}
\end{equation}
Therefore, the subproblem \eqref{sldp32} can be approximated by
\begin{subequations}\label{lotr}
\begin{align}
& \max_{\mathbf{p}_m} \tilde{f}_p(\mathbf{p}_m )\\
&\mathrm{s.t.} \quad\eqref{sldo611}, \eqref{sinre2}.
\end{align}
\end{subequations}

Note that problem \eqref{lotr} is a convex optimization problem, which can be easily solved by CVX. To facilitate the joint optimization of problem \eqref{mosd5} in the next section, a neural network will be designed to solve subproblem \eqref{lotr}. Specially, we obtain the following subproblem by ignoring constraint \eqref{sldo611}, i.e.,
\begin{subequations}\label{lotr22}
\begin{align}
& \max_{\mathbf{p}_m} \tilde{f}_p(\mathbf{p}_m )\\
&\mathrm{s.t.}~~~ \eqref{sinre2}.
\end{align}
\end{subequations}
Utilizing the quadratic penalty function method, constrained problem \eqref{lotr22} is transformed into an unconstrained problem, i.e.,
\begin{equation}\label{oier5}
\max_{\mathbf{p_m} }\tilde{f}_p^{\text{new}}(\mathbf{p}_m ) = \tilde{f}_p(\mathbf{p}_m ) - \mu \sum_{m=1}^{M} V_m^2(\mathbf{p}_m ),
\end{equation}
where $\mu>0$ is the penalty factor, and
\begin{equation}
V_m = \max \left( 0, \gamma_m^{\min} I_m^{\text{approx}} - G_m \right)
\end{equation}
with
\begin{equation}
I_m^{\text{app}} = I_m^{(t)} + 2 \sum_{n \neq m} \text{Re} \left( \left( \mathbf{p}_n^{(t)} \right)^H \mathbf{h}_m \mathbf{h}_m^H \left( \mathbf{p}_n - \mathbf{p}_n^{(t)} \right) \right) + \sigma^2.
\end{equation}

It is important to point out that the objective function $\tilde{f}_p^{\text{new}}(\{ \mathbf{p}_m \})$ is differentiable and its gradient is given by
\begin{equation}
\nabla_{\mathbf{p_m}} \tilde{f}_p^{\text{new}} = \nabla_{\mathbf{p_m}} \tilde{f}_p - 2\mu \sum_{m=1}^{M} V_m \cdot \nabla_{\mathbf{p_m}} V_m.
\end{equation}
Then the solution of \eqref{oier5} is obtained by
\begin{equation}\label{etl32}
\mathbf{p}_m^{(t+1)} = \mathbf{p}_m^{(t)} + \eta \nabla_{\mathbf{p_m}} \tilde{f}_p^{\text{new}},
\end{equation}
where $\eta$ is the learning rate. To satisfy the constraint \eqref{sldo611} in \eqref{lotr}, the updated $\mathbf{p_m}^{(t+1)}$ in \eqref{etl32} is then normalized by
\begin{equation}\label{rtle3}
\mathbf {p}_m^{(t+1)} = \frac{\sqrt{P_{\text{total}}}}{\sqrt{\sum_{m=1}^{M} \left| \mathbf {p}_m^{(t+1)} \right|^2}} \, \mathbf {p}_m^{(t+1)}.
\end{equation}

\subsubsection{{Antenna Position $\mathbf{d}$ update}} With fixing $y_m^{(t)}$, $\mathbf{p}_m^{(t+1)}$ and $\gamma_m^{(t)}$, the subproblem of problem \eqref{mosd5} on variable $\mathbf{d}$ can be formulated as

\begin{subequations}\label{lotr5}
\begin{align}
& \max_{\{\mathbf{d}\}} {f}(\mathbf{d}) \triangleq\sum_{m=1}^{M} \frac{w_m (1 + \gamma_m^{(t)})}{\ln 2} \bigg[ 2y_m^{(t)} \sqrt{G_m} - \left(y_m^{(t)}\right)^2 \nonumber\\
&\quad\quad\left(G_m + I_m + \sigma^2\right) \bigg],\\
&\mathrm{s.t.} \quad d_k \in D, \quad \forall k = 1, 2, \dots, K. \label{lert3}
\end{align}
\end{subequations}

To maximize $f(\mathbf{d})$, the gradient descent method is considered and the gradient of the objective function is given by
\begin{equation}\label{tre45}
\nabla_{\mathbf{d}} f(\mathbf{d}) = \left[ \frac{\partial f}{\partial d_1}, \frac{\partial f}{\partial d_2}, \dots, \frac{\partial f}{\partial d_K} \right]^T.
\end{equation}

Note that the derivation of $f(\mathbf{d})$ needs to be combined with the chain rule, and the analytical expression cannot be obtained. With the calculation of the gradient $\nabla_{\mathbf{d}} f(\mathbf{d})$, the update of $\mathbf{d}$ is given by
\begin{equation}
{\mathbf{d}}^{(t+1)} =  {\mathbf{d}}^{(t)} + \alpha \nabla_{\mathbf{d}} f \left( {\mathbf{d}}^{(t)} \right),
\end{equation}
where $\alpha$ is the step size. To ensure that $\mathbf{d}$ satisfies the constraint \eqref{lert3}, the updated $\mathbf{d}^{(t+1)}$ needs to be projected to the feasible set $D$, i.e.,
\begin{equation}\label{rty56}
{\mathbf{d}}^{(t+1)} = \text{proj}_D \left( {\mathbf{d}}^{(t)} + \alpha \nabla_{\mathbf{d}} f \left( {\mathbf{d}}^{(t)} \right) \right).
\end{equation}
\begin{remark}
The calculation and projection of the gradient in \eqref{tre45} are difficult to achieve in the traditional gradient descent algorithm. Thus, we can expand the gradient descent algorithm into a deep neural network and implement it based on Pytorch.
\end{remark}
\begin{remark}
The solution of problem \eqref{mosd5} by alternating updates of auxiliary variables update and the solutions of subproblems is only a feasible solution, which is affected by the initial value update.
\end{remark}

\section{Joint Optimization Based on Gradient Meta-Learning}
\vspace{1.0em}

In this section, we propose a gradient meta-learning joint optimization (GML-JO) algorithm to solve problem \eqref{mosd5} including auxiliary variables update, beam assignment vector update and pinching-antenna position vector update. In particular, beam assignment vector update and pinching-antenna position vector update are extended into two networks, namely, the beamforming network (BN) and the antenna position network (AN), which optimize the beamforming vector and the antenna positions, respectively. Moreover, the proposed GML-JO algorithm contains a three-layer loop structure, where the inner loop quickly updates the solutions of subproblems \eqref{lotr} and \eqref{lotr5}; the middle loop accumulates the loss function; and the outer loop dynamically adjusts the meta-parameters by the Adam algorithm, realizing the transition from the local fast response to the global robust convergence.

