  \label{fig:example2125}
\end{figure*}
As shown in Fig. \ref{fig:example2125}, we introduce a gradient-input unfolding network to solve subproblem \eqref{lotr} with respect to the parameter $\mathbf{p_m}$, where the input is the gradient of the objective function \eqref{oier5}. To satisfy the input of neural network, the complex gradient is first transformed into a real vector, i.e.,
\begin{equation}
\mathbf{g_p} = \left[ \text{Re} \left(\nabla_{\mathbf{p_m}} \tilde{f}_p^{\text{new}} \right)^T, \text{Im} \left( \nabla_{\mathbf{p_m}} \tilde{f}_p^{\text{new}}\right)^T \right]^T \in \mathbb{R}^{2KM}.
\end{equation}

Then three linear hidden layers are designed to learning the gradient change in \eqref{etl32}, i.e.,
\begin{equation}
h_1 = \text{ELU}(W_1 \mathbf{g_p} + b_1),
\end{equation}
and
\begin{equation}
h_2 = \text{ELU}(W_2 h_1 + b_2).
\end{equation}
The output of the network is given by
\begin{equation}
\Delta \mathbf{p_m} = \tanh(W_3 h_2 + b_3) \in [-1, 1]^{2KM},
\end{equation}
where $\mathrm{tanh}(\cdot)$ is the activation function.
Thus $\mathbf{p_m}$ updated in \eqref{etl32} is further expressed as

\begin{equation}
\mathbf {p}_m^{(i+1,j)} = \mathbf {p}_m^{(i,j)} + \Delta \mathbf {p}_m^{(i,j)}.
\end{equation}

Finally, updated $\mathbf{p_m}^{(i+1,j)}$ is then normalized by
\eqref{rtle3} to satisfy the constraint \eqref{sldo611}.


\subsection{ Antenna Position Optimization Network}


We introduce a gradient-input unfolding network with respect to $\mathbf{d}$. Especially, the last updated position gradient is the input of the network.

Then a three-layer  network is designed, i.e.,
\begin{equation}
\mathbf{h}_1 = \text{ELU}(\mathbf{W}_1 \nabla_{\mathbf{d}} f(\mathbf{d}) + \mathbf{b}_1),
\end{equation}
\begin{equation}
\mathbf{h}_2 = \text{ELU}(\mathbf{W}_2 \mathbf{h}_1 + \mathbf{b}_2),
\end{equation}
and the output is obtained by
\begin{equation}
\Delta \mathbf{d} = \tanh(\mathbf{W}_3 \mathbf{h}_2 + \mathbf{b}_3) \in [-1, 1]^K.
\end{equation}
Then, $\mathbf{d}$ updated in \eqref{rty56} is further expressed as
\begin{equation}
\mathbf{d}^{(i+1,j)} = \mathbf{d}^{(i,j)} + \Delta \mathbf{d}^{(i,j)}.
\end{equation}
According to \eqref{rty56}, the updated $\mathbf{d}^{(i+1,j)}$ is projected into $\mathbf{D}$, given by
\begin{equation}
\mathbf{d}^{(i+1,j)} = \text{proj}_D \left( \mathbf{d}^{(i+1,j)} \right),
\end{equation}
where $\text{Proj}_\mathbf{D}(\cdot)$ is defined as

\begin{equation}
\text{Proj}_\mathbf{D}(x) =
\begin{cases}
x_{\text{min}} & \text{if } x < x_{\text{min}}, \\
x_{\text{max}} & \text{if } x > x_{\text{max}}, \\
x & \text{otherwise}.
\end{cases}
\end{equation}

