\begin{algorithm}[tp]
\caption{Proposed GML-JO Algorithm}
\begin{algorithmic}[1]
\Procedure{GML-JO}{$\mathbf{P}, \mathbf{d}$}
    \State Randomly initialize $\theta_P, \theta_d, \mathbf{P}^{(0,1)}, \mathbf{d}^{(0,1)}$,$\gamma_m, y_m$
    \State $\mathbf{P}^* \gets \mathbf{P}^{(0,1)}$
    \State $\mathbf{d}^* \gets \mathbf{d}^{(0,1)}$
    \State Initialize the maximum WSR $\text{MAX} \gets 0$

    \For{$k \gets 1$ \textbf{to} $N_k$}
        \State $\overline{\mathcal{L}} \gets 0$
        \For{$j \gets 1$ \textbf{to} $N_j$}
            \State $\mathbf{P}^{(0,j)} \gets \mathbf{P}^{(0,1)}$
            \State $\mathbf{d}^{(0,j)} \gets \mathbf{d}^{(0,1)}$
                        \State Update $\gamma_m^{(j)}, y_m^{(j)}$
            \For{$i \gets 1$ \textbf{to} $N_i$}
                \State $\Delta \mathbf{P}^{(i-1,j)} \gets \text{BN}_{\theta_P}(\mathbf{g_p})$
                \State $\mathbf{P}^{(i,j)} \gets \mathbf{P}^{(i-1,j)} + \lambda \cdot \Delta \mathbf{P}^{(i-1,j)}$
                \State $\mathbf{P}^{(i,j)} \gets \text{normalize\_P}(\mathbf{P}^{(i,j)}, P_{\text{total}})$
            \State \hspace{-2\algorithmicindent}
            \EndFor \textbf{end for}
            \State $\mathbf{P}^* \gets \mathbf{P}^{(N_i,j)}$
            \For{$i \gets 1$ \textbf{to} $N_i$}
                \State $\Delta \mathbf{d}^{(i-1,j)} \gets \text{AN}_{\theta_d}(\nabla_{\mathbf{d}} f)$
                \State $\mathbf{d}^{(i,j)} \gets \mathbf{d}^{(i-1,j)} + \lambda \cdot \Delta \mathbf{d}^{(i-1,j)}$
                \State $\mathbf{d}^{(i,j)} \gets \text{Proj}_D(\mathbf{d}^{(i,j)})$
            \State \hspace{-2\algorithmicindent}
            \EndFor\textbf{end for}
            \State $\mathbf{d}^* \gets \mathbf{d}^{(N_i,j)}$
            \State $\mathcal{L}^j \gets -\text{WSR}(\mathbf{P}^*, \mathbf{d}^*)$
            \If{$-\mathcal{L}^j > \text{MAX}$}
                \State $\text{MAX} \gets -\mathcal{L}^j$
                \State $\mathbf{P}_{\text{opt}} \gets \mathbf{P}^*$
                \State $\mathbf{d}_{\text{opt}} \gets \mathbf{d}^*$
            \State \hspace{-2\algorithmicindent}
            \EndIf\textbf{end if}
            \State $\overline{\mathcal{L}} \gets \overline{\mathcal{L}} + \mathcal{L}^j$
        \State \hspace{-\algorithmicindent}
        \EndFor   \textbf{end for}
        \State $\overline{\mathcal{L}} \gets \frac{1}{N_j} \overline{\mathcal{L}}$
        \State $\theta_P \gets \text{Adam}(\theta_P, \nabla \overline{\mathcal{L}})$
        \State $\theta_d \gets \text{Adam}(\theta_d, \nabla \overline{\mathcal{L}})$
    \State \textbf{end for}
    \EndFor
    \State \Return $\mathbf{P}_{\text{opt}}, \mathbf{d}_{\text{opt}}$
    \State \textbf{end procedure}
\EndProcedure
\end{algorithmic}
\end{algorithm}



