\section*{\textbf{Appendix A}}
\begin{center}
\textbf{ET-CA Baseline Algorithm}
\end{center}



Based on the Lagrange duality and quadratic transformations, we introduce auxiliary variables \( \gamma_m \) and \( y_m \) to decouple variables, transforming the original non-convex WSR problem \eqref{mosd2} into an equivalent form \eqref{mosd5}, and decompose it into two subproblems. The auxiliary variables update are given by \eqref{mosd520} and \eqref{mosd521}, and the beamforming coefficient and antenna position updates of ET-CA are given as follows:

\subsubsection{Beamforming Coefficient $\mathbf{p}_m$ Update}
For given $y_m^{(t)}$, $\mathbf{d}^{(t)}$, and $\gamma_m^{(t)}$, the sub-problem of problem \eqref{mosd5} on variable $\mathbf{p}_m$ can be formulated as \eqref{sldp32}. Since $G_m$ and $I_m$ are nonconvex functions with respect to variable $\mathbf{p}_m$, the objective function and the $\mathrm{SINR}_m$ constraint in subproblem \eqref{sldp32} are nonconvex. To solve this problem, we perform a first-order Taylor expansion of $G_m$ and $I_m$ at $\mathbf{p}_m^{(t)}$ by \eqref{mosd522} and \eqref{mosd523}.

Then, the subproblem \eqref{sldp32} can be approximated by
\begin{subequations}\label{lotr1}
\begin{align}
& \max_{\mathbf{p}_m} \tilde{f}_p(\mathbf{p}_m ) \\
&\text{s.t.} \quad \eqref{sldo611}, \eqref{sinre2}.
\end{align}
\end{subequations}

Using the quadratic penalty function method, problem \eqref{lotr1} only with constraint \eqref{sinre2} is transformed into an unconstrained problem, i.e.,

\begin{equation}\label{oier5}
\max_{\mathbf{p}_m } \tilde{f}_p^{\text{new}}(\mathbf{p}_m ) = \tilde{f}_p(\mathbf{p}_m ) - \mu \sum_{m=1}^{M} V_m^2(\mathbf{p}_m ).
\end{equation}
To handle power constraint \eqref{sldo611}, we introduce an obstacle function, defined as
\begin{equation}\label{lorte}
\varphi(\mathbf{p}_m) = - \log \left( P_{\text{total}} - \sum_{m=1}^{M} \| \mathbf{p}_m \|^2 \right).
\end{equation}

By considering the constraint \eqref{sldo611}, the objective function of unconstrained problem \eqref{oier5} is further expressed as
\begin{equation}
Z(\mathbf{p}_m) = \tilde{f}_{p}^{\text{new}}(\mathbf{p}_m) + \frac{1}{t} \varphi(\mathbf{p}_m),
\end{equation}
where $t > 0$ is the obstacle parameter.

The interior point method maximises $Z(\{\mathbf{p}_m\})$ using gradient ascent method, where the gradient  calculation is given by
\begin{equation}\label{lopt32}
\nabla_{\mathbf{p}_m} Z = \nabla_{\mathbf{p}_m} \tilde{f}_p^{\text{new}} + \frac{1}{t} \nabla_{\mathbf{p}_m} \varphi(\mathbf{p}_m).
\end{equation}
From \eqref{oier5} and \eqref{lorte}, we have
\begin{equation}\label{rty6}
\nabla_{\mathbf{p}_m} \tilde{f}_p^{\text{new}} = \nabla_{\mathbf{p}_m} \tilde{f}_p - 2\mu \sum_{m=1}^{M} V_m \nabla_{\mathbf{p}_m} V_m,
\end{equation}
and
\begin{equation}\label{port7}
\nabla_{\mathbf{p}_m} \varphi(\mathbf{p}_m) = \frac{2 \mathbf{p}_m}{P_{\text{total}} - \sum_{m=1}^{M} \| \mathbf{p}_m \|^2}.
\end{equation}

Submitting \eqref{rty6} and \eqref{port7} into \eqref{lopt32}, the update of $\{\mathbf{p}_m\}$ is expressed as
\begin{equation}
\mathbf{p}_m^{(k+1)} = \mathbf{p}_m^{(k)} + \alpha \nabla_{\mathbf{p}_m} Z.
\end{equation}

\subsubsection{Antenna Position $\mathbf{d}$ Update}
With fixing $y_m^{(t)}$, $\mathbf{p}_m^{(t+1)}$, and $\gamma_m^{(t)}$, the subproblem of problem \eqref{mosd5} on variable $\mathbf{d}$ can be formulated as \eqref{lotr5}.

With the calculation of the gradient $\nabla_{\mathbf{d}} f(\mathbf{d})$, the update of $\mathbf{d}$ is given by

\begin{equation}
\mathbf{d}^{(t+1)} = \mathbf{d}^{(t)} + \alpha \nabla_{\mathbf{d}} f \left( \mathbf{d}^{(t)} \right),
\end{equation}
where $\alpha$ is the step size. To ensure that $\mathbf{d}$ satisfies the constraint \eqref{lert3}, the updated $\mathbf{d}^{(t+1)}$ needs to be projected to the feasible set $D$, i.e.,

\begin{equation}\label{rty56}
\mathbf{d}^{(t+1)} = \text{proj}_D \left( \mathbf{d}^{(t)} + \alpha \nabla_{\mathbf{d}} f \left( \mathbf{d}^{(t)} \right) \right).
\end{equation}






