\section{Preliminaries}\label{sec:pre}
\subsection*{Linear algebraic groups}
Let $n > p$ be positive integers and let $\mathbb{F} = \mathbb{R}$,  $\mathbb{C}$ or $\mathbb{H}$.  We denote by $\GL_n(\mathbb{F})$ the group of $n\times n$ invertible matrices over $\mathbb{F}$.  Classical subgroups of $\GL_n(\mathbb{F})$ are 
\begin{align*}
\O_n(\mathbb{R}) &\coloneqq \lbrace 
X \in \GL_n(\mathbb{R}): X^\tp X = I_n
\rbrace, \\
\SO_n(\mathbb{R}) &\coloneqq \lbrace 
X \in \O_n(\mathbb{R}):\det(X) = 1
\rbrace, \\
\U_n &\coloneqq \lbrace 
X \in \GL_n(\mathbb{C}): X^\ast X = I_n
\rbrace, \\
\SU_n &\coloneqq \lbrace 
X \in \U_n: \det(X) = 1
\rbrace,  \\
\Sp_{2n}(\mathbb{R}) &\coloneqq \left\lbrace 
X \in \GL_{2n}(\mathbb{R}): X \begin{bsmallmatrix}
0 & I_n \\
- I_n & 0 
\end{bsmallmatrix} X^\tp = \begin{bsmallmatrix}
0 & I_n \\
- I_n & 0 
\end{bsmallmatrix}
\right\rbrace.
\end{align*} 
Our discussions in the sequel will also involve indefinite orthogonal groups and their inhomogeneous version.  Let $I_{p,n-p} \coloneqq \diag(
I_p, -I_{n-p})$.  We define:  
\begin{align*} 
\O_{p,n-p}(\mathbb{R}) &\coloneqq \lbrace 
X \in \GL_n(\mathbb{R}): X^\tp I_{p,n-p} X = I_{p,n-p}
\rbrace, \\
\SO^+_{p,n-p}(\mathbb{R}) &\coloneqq \text{the identity component of $\O_{p,n-p}(\mathbb{R})$}, \\
\SE_{n}(\mathbb{R}) & \coloneqq
 \mathbb{R}^n \ltimes  \O_n(\mathbb{R}) = 
\left\lbrace
\begin{bsmallmatrix}
Q & u \\
0 & 1
\end{bsmallmatrix} \in \GL_{n+1}(\mathbb{R}): Q\in \O_{n}(\mathbb{R}),  u \in \mathbb{R}^n
\right\rbrace,  \\
\ISO^+_{p,n-p}(\mathbb{R}) &\coloneqq \mathbb{R}^{n} \ltimes \SO^+_{p,n-p}(\mathbb{R}) = 
\left\lbrace
\begin{bsmallmatrix}
Q & u \\
0 & 1
\end{bsmallmatrix} \in \GL_{n+1}(\mathbb{R}): Q\in \SO^+_{p,n-p}(\mathbb{R}),  u \in \mathbb{R}^{n}
\right\rbrace.
\end{align*}
