\subsection*{Topology and Geometry}
Let  $X, Y$ be topological spaces and let $p: Y \to X$,  $\gamma: \mathbb{S}^1 \to X$ be continuous maps.  A \emph{lift} of $\gamma$ is a continuous map $\beta:\mathbb{S}^1 \to Y$ such that $p \circ \beta = \gamma$. 
\begin{lemma}\cite[Lemma~55.3]{Munkres00}\label{lem:null homotopic}
Let $X$ be a topological space.  A continuous map $\gamma: \mathbb{S}^1 \to X$ is homotopic to a constant map if and only if $[\gamma] = 0 \in \pi_1(X)$.
\end{lemma}
Topological lifting criteria like \cite[Proposition~1.33]{Hatcher02} indicates that the existence of a lift of $\gamma$ is controlled by $[\gamma] \in \pi_1 (X)$.  However,  if $\gamma$ is a rational curve,  then there is no guarantee that the lift of $\gamma$,  if it exists,  is also a rational curve.  We will need the following lifting criterion for algebraic curves,  which is a consequence of \cite[Satz~3.3]{Harder67},  see also \cite{BF19, BS68, Steinberg65}.
\begin{proposition}\label{prop:rational triviality}
Let $k$ be a field (not necessarily algebraically closed) and let $C$ be a smooth affine curve over $k$.  If $G$ is a semisimple and simply connected algebraic group,  then every generically trivial principal $G$-bundle on $C$ is trivial. 
\end{proposition}



What follows is a topological criterion for the existence of a regular approximation of a continuous map between real algebraic varieties.
\begin{theorem}\cite[Theorem~1.1]{BK22}\label{thm:approx by regular maps}
Let $X$ be a real algebraic variety and let $Y$ be a homogeneous space for some linear algebraic group.  A continuous map $f: X\to Y$ can be approximated by regular maps in the compact-open topology if and only if $f$ is homotopic to a regular map.
\end{theorem}

\section{Rational curves on real algebraic varieties}\label{sec:rat}
We begin with the definition of rational curves on a real algebraic variety.
\begin{definition}[rational curve]\label{def: curve}
Let $X$ be a real quasi-affine variety. A \emph{rational curve} on $X$ is a morphism $\gamma: \mathbb{P}_{\mathbb{R}}^1 \to X$. We denote by $\Rat(X)$ the set of rational curves on $X$. Given $x_0\in X$, we also denote 
\[
\Rat(X,x_0) \coloneqq \lbrace
\gamma \in \Rat(X): \gamma \left( [0 : 1 ] \right) = x_0
\rbrace.
\]
\end{definition}
Since we have an identification $\mathbb{P}_{\mathbb{R}}^1 \simeq \mathbb{R}^1 \sqcup \{ \infty\}$,  rational curves can be characterized alternatively. 
\begin{lemma}\label{lem:equiv_def}
Let $X \subseteq \mathbb{R}^N$ be a real quasi-affine variety. The following are equivalent:
\begin{enumerate}[(i)]
\item\label{lem:equiv_def:item1} $\gamma$ is a rational curve on $X$.
\item\label{lem:equiv_def:item3}  $\gamma(t)$ is an everywhere defined $X$-valued rational function on $\mathbb{R}\sqcup \{\pm \infty\}$ such that $\gamma(+ \infty) = \gamma(-\infty) \in X$.
\item\label{lem:equiv_def:item4}
$\gamma(t) = (p_1(t)/q(t),\dots, p_N(t)/q(t)): \mathbb{R} \to X \subseteq \mathbb{R}^N$ and $\gamma(+ \infty) = \gamma(-\infty) \in X$ where $p_1,\dots, p_N,q$ are univariate real polynomials such that $q$ has no real root and $\gcd(p_1,\dots, p_N,q) = 1$.
\end{enumerate}
\end{lemma}
\begin{remark}
It is worth remarking that over an arbitrary field $k$, a rational curve on a quasi-projective variety $X$ is defined \cite[Chapter~II]{Kollar96} as a morphism from $\mathbb{P}_{k}^1$ to $X$. For $k = \mathbb{C}$, there is no non-constant rational curve on a quasi-affine variety. However, non-constant rational curves may exist on real quasi-affine varieties.  It is also noticeable that every real projective variety is isomorphic to a real affine variety \cite[Proposition~2.4.1]{AK92}.  This fact indicates that over $\mathbb{R}$, it is sufficient to consider rational curves on quasi-affine varieties.
\end{remark}
\begin{definition}[degree]
Let $\gamma (t) = (p_1(t)/q(t), \dots, p_N(t)/q(t) )$ be a rational curve on $X$ with $\gcd(p_1,\dots, p_N,q) = 1$.  The \emph{degree} of $\gamma$ is $\deg(\gamma) \coloneqq \deg (q)$. The set of rational curves of degree $d$ on $X$ is denoted by $\Rat_d(X)$. Moreover, if $x_0 \in X$ is a fixed point, we denote
\[
\Rat_d(X,x_0) \coloneqq \lbrace
\gamma \in \Rat_d(X): \gamma(\infty) = x_0 \rbrace.
\]
\end{definition}
\begin{remark}
Since $q$ has no real root, $\deg(\gamma)$ must be an even non-negative integer. 
\end{remark}

\begin{lemma}\label{lem:induced action}
Let $X$ be a real quasi-affine variety and let $G$ be a real algebraic group acting on $X$. For any $x_0 \in X$ and $g\in G$, the map 
\[
L_g: \Rat(X,x_0) \to \Rat (X,g x_0),\quad \gamma \mapsto  g \gamma
\]
is bijective. In particular, if $G$ acts on $X$ transitively, then there is a bijection between $\Rat (X)$ and $\Rat (X,x_0) \times X$.
\end{lemma}

Let $G \subseteq \GL_n(\mathbb{R})$ be a real linear algebraic group. According to Lemma~\ref{lem:induced action}, we have $\Rat (G) = \Rat (G,I_n) \times G$ where $I_n \in G$ is the identity matrix. By Lemma~\ref{lem:equiv_def}, a curve $\gamma \in \Rat (G,I_n)$ admits a unique parametrization: 
\[
\gamma(t) = (P_{ij}(t)/q(t))_{i,j=1}^n,
\]
where $q\in \mathbb{R}[t]$ and $P_{ij} \in \mathbb{R}[t]$ satisfy
\begin{itemize}
\item $\gamma(t_0) \in G$ for any $t_0\in \mathbb{R}$.
\item $\gcd(q,P_{11},\dots, P_{nn}) = 1$.
\item $q,P_{11},\dots, P_{nn}$ are monic.
\item $\deg(q)  = \deg(P_{ii}) > \deg(P_{ij})$ for $1\le i \ne j \le n$.
\item $q$ has no real roots.
\end{itemize}

\begin{lemma}
If $\gamma(t)$ is a  rational curve on $G$, then it is also a rational curve on the connected component $G_0$ of $G$.
\end{lemma}
Let $\mathbb{F}$ be $\mathbb{R},\mathbb{C}$ or $\mathbb{H}$ and let $\sigma: \mathbb{F}^{n\times n} \to \mathbb{F}^{n\times n}$ be an \emph{$\mathbb{R}$-involution} on $\mathbb{F}^{n\times n} $, i.e., $\sigma$ is an $\mathbb{R}$-linear map satisfying
\[
\sigma(I_n) = I_n,\quad \sigma(\sigma(A)) = A,\quad
\sigma(AB) = \sigma(B) \sigma(A),\quad A,B\in \mathbb{F}^{n\times n}.
\]
For each $X\in \mathbb{F}^{n\times n}$, we denote $X^\sigma \coloneqq \sigma(X)$. A typical example of an involution is the transpose (resp. conjugate transpose) of matrices in $\mathbb{R}^{n\times n}$ (resp. $\mathbb{C}^{n\times n}$ or $\mathbb{H}^{n\times n}$). Given an involution $\sigma$ on $\mathbb{F}^{n\times n}$ and $B\in \GL_n(\mathbb{F})$, we define 
\[
G_B(\mathbb{F}) \coloneqq \lbrace 
X \in \mathbb{F}^{n\times n}: X B X^{\sigma} = B
\rbrace.
\]
By definition, $G_B(\mathbb{F})$ is a real algebraic subgroup of $\GL_n(\mathbb{F})$, whose Lie algebra is 
\begin{equation}
\mathfrak{g}_B(\mathbb{F}) \coloneqq \lbrace 
Y\in \mathbb{F}^{n\times n}: B Y^\sigma + Y B   = 0
\rbrace.
\end{equation}
Familiar examples of $G_B(\mathbb{F})$ include:  
\begin{enumerate}[(a)]
\item $\mathbb{F} = \mathbb{R}$ (resp. $\mathbb{F} = \mathbb{C}$), $B = I_{p,n-p} \coloneqq \diag (I_p, -I_{n-p})$, $\sigma = \text{transpose}$: $G_B(\mathbb{F})$ is the indefinite orthogonal $\O_{p,n-p}(\mathbb{R})$ (resp. $\O_{p,n-p}(\mathbb{C}) \simeq \O_n(\mathbb{C})$) of type $(p,n-p)$. In particular, if $p = n$, then $G_B(\mathbb{F})$ is the orthogonal group $\O_n(\mathbb{R})$ (resp. $\O_{n}(\mathbb{C})$).
\item $\mathbb{F} = \mathbb{R}$ (resp. $\mathbb{F} = \mathbb{C}$), $B = \begin{bsmallmatrix}
0 & I_n \\
-I_n & 0
\end{bsmallmatrix}$, $\sigma = \text{transpose}$: $G_B(\mathbb{F}) $ is the symplectic group $\Sp_{2n}(\mathbb{R})$ (resp. $\Sp_{2n}(\mathbb{C})$).
\item $\mathbb{F} = \mathbb{C}, B = I_{p,n-p}$, $\sigma = \text{conjugate transpose}$: $G_B(\mathbb{F})$ is the indefinite unitary group $\U_{n,n-p}$ of type $(p,n-p)$.
\item $\mathbb{F} = \mathbb{H}, B = I_{p,n-p}$, $\sigma = \text{conjugate transpose}$: $G_B(\mathbb{F})$ is the quaternionic indefinite symplectic group $\Sp_{p,n-p}(\mathbb{H})$ of type $(p,n-p)$. 
\end{enumerate}
The lemma that follows is a well-known fact.  Nonetheless,  we provide a proof due to the lack of appropriate reference. 
\begin{lemma}\label{lem:involution}
Let $\sigma$ be an $\mathbb{R}$-involution on $\mathbb{F}^{n\times n}$. Then there exists $C\in \GL_n(\mathbb{F})$ such that for all $A\in \mathbb{F}^{n\times n}$ we have $A^\sigma = C A^\xi C^{-1}$ where 
\[
A^\xi = 
\begin{cases}
A^\tp,&~\text{if}~\mathbb{F} = \mathbb{R} \\
A^\tp~\text{or}~A^\ast,&~\text{if}~\mathbb{F} = \mathbb{C} \\
A^\ast,&~\text{if}~\mathbb{F} = \mathbb{H}
\end{cases}.
\]
\end{lemma}
\begin{proof}
We denote by $\Aut_{\mathbb{R}}(\mathbb{F}^{n\times n})$ the automorphism group of $\mathbb{F}^{n\times n}$ as an $\mathbb{R}$-algebra. We consider the map $\varphi: \mathbb{F}^{n\times n} \to \mathbb{F}^{n\times n}$ defined by $\varphi(A) = (A^\sigma)^\xi$. Since bot $\sigma$ and $\xi$ are $\mathbb{R}$-involutions, $\varphi$ lies in $\Aut_{\mathbb{R}}(\mathbb{F}^{n\times n})$. Let $Z(\mathbb{F}^{n\times n})$ be the center of $\mathbb{F}^{n\times n}$. It is straightforward to verify that 
\[
Z(\mathbb{F}^{n\times n}) = \begin{cases}
\mathbb{R} I_n,&~\text{if}~\mathbb{F} = \mathbb{R}~\text{or}~\mathbb{F} \\
\mathbb{C} I_n,&~\text{if}~\mathbb{F} = \mathbb{C}\\
\end{cases}.
\]

If $\mathbb{F} = \mathbb{R}$ or $\mathbb{H}$, $\mathbb{F}^{n\times n}$ is a simple central algebra, thus by Skolem-Noetherm theorem \cite{Kersten90} each element in $\Aut_{\mathbb{R}}(\mathbb{F}^{n\times n})$ is an inner automorphism. Hence $A^\sigma$ can be written in the desired form for some $C\in \GL_n(\mathbb{F})$.

For $\mathbb{F} = \mathbb{C}$, we observe that $\varphi(A) \varphi(B) = \varphi(AB) = \varphi(BA) = \varphi(B) \varphi(A)$ if $A,B$ commute. Therefore, $\varphi$ preserves $Z(\mathbb{C}^{n\times n})$. Let $\psi_0: \mathbb{C} \to \mathbb{C}$ be the restriction of $\varphi$ onto $Z(\mathbb{C}^{n\times n}) \simeq \mathbb{C}$ and let $\psi: \mathbb{C}^{n\times n} \to \mathbb{C}^{n\times n}$ be the map component-wise induced by $\psi_0$. Clearly, $\psi$ is an automorphism of $\mathbb{C}^{n\times n}$ as an $\mathbb{R}$-algebra. By construction, the map $\varphi\circ \psi^{-1}$ is an automorphism of $\mathbb{C}^{n\times n}$ as a $\mathbb{C}$-algebra. Skolem-Noetherm theorem implies that $\varphi\circ \psi^{-1}$ is an inner automorphism on $\mathbb{C}^{n\times n}$ as a $\mathbb{C}$-algebra. Lastly, since $\psi_0$ is an automorphism of $\mathbb{C}$ as an $\mathbb{R}$-algebra, $\psi_0$ is either the identity map or the complex conjugation and this completes the proof.
\end{proof}
According to Lemma~\ref{lem:involution},  it is sufficient to assume that $\sigma$ is either the transpose or the conjugate transpose.  We conclude this section by an observation that is essential to our discussion in Section~\ref{sec:dec}.
\begin{proposition}[Inverse]\label{prop:inverse}
If $\gamma \in \Rat_{2d}(G_B(\mathbb{F}),I_n)$, then $\gamma(t)^{-1} \in \Rat_{2d}(G_B(\mathbb{F}),I_n)$ and it has the same poles as $\gamma(t)$.
\end{proposition}
\begin{proof}
Since $\gamma(t)$ is a curve on $G_B(\mathbb{F})$, we have $\gamma(t) B \gamma(t)^\sigma = B$. Thus $\gamma(t)^{-1} = B \gamma(t)^\sigma B^{-1}$, which is a  rational curve on $G_B(\mathbb{F})$ of degree $2d$ whose poles are the same as those of $\gamma(t)$.
\end{proof}
\begin{remark}
For a general real linear algebraic group $G \subseteq \GL_n(\mathbb{R})$, it may happen that $\deg (\gamma^{-1}) \ne \deg(\gamma)$ if $\gamma \in \Rat(G,I_n)$. For instance, we consider $G = \GL_2(\mathbb{R})$ and 
\[
\gamma(t) = \begin{bsmallmatrix}
1 & \frac{t}{t^2 + 1} \\
\frac{t}{t^2 + 1}  & 1
\end{bsmallmatrix}.
\]
Clearly, $\gamma(t)$ is a  rational curve on $\GL_2(\mathbb{R})$ since $\det(\gamma(t)) = (t^4 + t^2 + 1)/(t^2 + 1)^2$. However, a direct calculation implies 
\[
\gamma(t)^{-1} = \frac{(t^2 + 1)^2}{t^4 + t^2 + 1} \begin{bsmallmatrix}
1 & -\frac{t}{t^2 + 1} \\
-\frac{t}{t^2 + 1}  & 1
\end{bsmallmatrix} =  \begin{bsmallmatrix}
\frac{(t^2 + 1)^2}{t^4 + t^2 + 1} & -\frac{(t^2 + 1)t}{t^4 + t^2 + 1} \\[3pt]
-\frac{(t^2 + 1)t}{t^4 + t^2 + 1}   & \frac{(t^2 + 1)^2}{t^4 + t^2 + 1}
\end{bsmallmatrix}
\]
and $\deg(\gamma^{-1}) = 4 > 2 = \deg(\gamma)$. Moreover,  poles of $\gamma(t)^{-1}$ are different from those of $\gamma(t)$.
\end{remark}
