\section{Quadratic  rational curves on \texorpdfstring{$G_B(\mathbb{F})$}{GB}}\label{sec:quad}
Let $\alpha$ be a quadratic  rational curve on $G_B(\mathbb{F})$.  If poles of $\alpha$ are $x \pm y \ci$ where $(x,y) \in \mathbb{R} \times (\mathbb{R}\setminus \{0\})$, then clearly $ \widetilde{\alpha}(t) \coloneqq \alpha \left( x + y t \right)$ is a quadratic  rational curve on $G_B(\mathbb{F})$ with poles $\pm \ci$, where $\ci$ is the complex unit with $\ci^2=-1$. Therefore, there is no loss of generality to assume that poles of $\alpha$  are $\pm \ci$. We write 
\[
\alpha (t) = \frac{ I_n t^2 + A_1 t + A_0}{t^2 + 1}
\]
for some $A_1, A_0\in \mathbb{F}^{n\times n}$.  Since $\alpha \in \Rat_2(G_B(\mathbb{F}), I_n)$,  we may derive 
\begin{align}
B A_1^{\sigma} + A_1 B &= 0, \label{eq:quadratic1} \\ 
B A_0^{\sigma}  + A_0 B   &= (2I_n + A_1^2) B, \label{eq:quadratic2} \\
A_1 B A_0^{\sigma}   &= A_0   A_1 B , \label{eq:quadratic3} \\
A_0 B A_0^{\sigma} &= B. \label{eq:quadratic4}
\end{align}
by comparing coefficients in the equation $(I_n t^2 + A_1 t + A_0) B (I_n t^2 + A_1 t + A_0)^{\sigma} = (t^2 + 1)^2 B$.
\begin{remark}
We notice that \eqref{eq:quadratic1} and \eqref{eq:quadratic4} are equivalent to the condition $(A_0,A_1) \in G_B(\mathbb{F}) \times \mathfrak{g}_B(\mathbb{F})$.
\end{remark}

The lemma that follows characterizes the invariance of a solution of \eqref{eq:quadratic1}-\eqref{eq:quadratic4} with respect to the action of $\GL_n(\mathbb{F}) \times Z(\mathbb{F})^{\times}$ and $G_B(\mathbb{F})$, respectively.
\begin{lemma}\label{lem:invariance}
For any $(R,c) \in \GL_n(\mathbb{F}) \times Z(\mathbb{F})^{\times}$, a triple $(A_0,A_1,B)\in \mathbb{F}^{n\times n} \times \mathbb{F}^{n\times n} \times \GL_n(\mathbb{F})$ satisfies \eqref{eq:quadratic1}-\eqref{eq:quadratic4} if and only if $(R A_0 R^{-1}, R A_1 R^{-1}, c R B R^\sigma)$ satisfies \eqref{eq:quadratic1}-\eqref{eq:quadratic4}. In particular, given $B\in \GL_n(\mathbb{F})$ and $P\in G_B(\mathbb{F})$, a pair $(A_0,A_1)\in \mathbb{F}^{n\times n} \times \mathbb{F}^{n\times n}$ satisfies \eqref{eq:quadratic1}-\eqref{eq:quadratic4} if and only if $(P A_0 P^{-1}, P A_1 P^{-1})$ satisfies \eqref{eq:quadratic1}-\eqref{eq:quadratic4}.
\end{lemma}
\begin{proof}
It can be verified by a straightforward calculation.
\end{proof}
\subsection{Structure theorem for quadratic  rational curves}
We recall that each pair $(B,X)\in \mathbb{F}^{n\times n}$ satisfying $B^\sigma = \pm B$ and $X\in \mathfrak{g}_B(\mathbb{F})$ has a block diagonal normal form under the action of $\GL_n(\mathbb{F})$. We record this fact in Lemma~\ref{lem:indecomposable} for ease of reference.
