\begin{lemma}\label{lem:block}
Let $(A_0,A_1,B) \in \mathbb{F}^{n\times n} \times \mathbb{F}^{n\times n} \times \GL_n(\mathbb{F})$ be a solution of \eqref{eq:quadratic1}--\eqref{eq:quadratic4}. Assume further that $A_1 = \diag(X_1,\dots, X_s)$ and $B = \diag(B_1,\dots, B_s)$ where $\varepsilon = \pm 1$, $B_j^\sigma = \varepsilon B_j \in \GL_{m_j}(\mathbb{F})$ and $X_j\in \mathfrak{g}_{B_j}(\mathbb{F}) \subseteq \mathbb{F}^{m_j \times m_j}$ for each $1 \le j \le s$. If we partition $A_0 \in G_B(\mathbb{F})$ accordingly as $A_0 = (Y_{ij})_{i,j=1}^s$, then for each $1 \le i,j \le s$ we have
\begin{align}
X_i Y_{ij}  + Y_{ij} X_j   &= \delta_{ij} (2X_i + X_i^3).  \label{lem:block:eq1}\\
Y_{ji} &= \left( \delta_{ij}B_i^{-1} (2I_{m_i} + X_i^2) B_i - B_i^{-1} Y_{ij} B_j \right)^\sigma , \label{lem:block:eq2}
\end{align}
Here $\delta_{ij}$ is the Kronecker delta. In particular, if $i \ne j$ and $0 \not\in \rho(X_i) + \rho(X_j)$, then $Y_{ij} = Y_{ji} = 0$, where $\rho(X)$ is the spectrum of a matrix $X\in \mathbb{F}^{m\times n}$.
\end{lemma}
\begin{proof}
By equations \eqref{eq:quadratic2} and \eqref{eq:quadratic3}, we have 
\begin{align*}
B_i Y_{ji}^\sigma   &= \delta_{ij} (2 I_{m_i} + X_i^2) B_{i} - Y_{ij} B_j, \\
X_{i} B_i Y_{ji}^\sigma &= Y_{ij} X_j B_j,
\end{align*}
from which \eqref{lem:block:eq1} and \eqref{lem:block:eq2} can be obtained easily. We observe that \eqref{lem:block:eq1} is a Sylvester equation, whose solution is unique if and only if $\rho(X_i) \cap (-\rho(X_j)) = \emptyset$. Thus for $ i \ne j$ and $\rho(X_i) \cap (-\rho(X_j)) = \emptyset$, $Y_{ij} = 0$ is the unique solution of the homogeneous Sylvester equation \eqref{lem:block:eq1}.
\end{proof}

\begin{lemma}\label{lem:lower triangular}
We have the following:
\begin{enumerate}[(a)]
\item\label{lem:lower triangular:item1} For any $\lambda\in \mathbb{C}$, a solution of $J_m(\lambda) Y + Y J_n(-\lambda) = 0$ in $\mathbb{C}^{m\times n}$ is lower triangular alternating Toeplitz. Similarly, if $Y$ is a solution of $J_m(\lambda) Y + Y J_n(-\lambda)^\tp = 0$ (resp. $J_m(\lambda)^\tp Y + Y J_n(-\lambda) = 0$ and $J_m(\lambda)^\tp Y + Y J_n(-\lambda)^\tp = 0$), then $YH_n$ (resp. $H_m Y$ and  $H_m Y H_n$) is lower triangular alternating Toeplitz.
\item\label{lem:lower triangular:item1'} For any $\lambda\in \mathbb{C}$, a solution of $J_m(\lambda) Y - Y J_n(\lambda) = 0$ in $\mathbb{C}^{m\times n}$ is lower triangular Toeplitz. Similarly, if $Y$ is a solution of $J_m(\lambda) Y - Y J_n(\lambda)^\tp = 0$ (resp. $J_m(\lambda)^\tp Y - Y J_n(\lambda) = 0$ and $J_m(\lambda)^\tp Y - Y J_n(\lambda)^\tp = 0$), then $YH_n$ (resp. $H_m Y$ and  $H_m Y H_n$) is lower triangular Toeplitz.
\item\label{lem:lower triangular:item2} For any $\lambda\in \mathbb{C}$, a solution of $J_m(\lambda) Y + Y J_m(\lambda) = 2J_m(\lambda)  + J_m(\lambda)^3$ in $\mathbb{C}^{m\times m}$ has the form $Y = I_m + J_m(\lambda)^2/2 + T$ where $T$ is a lower triangular alternating Toeplitz matrix. Similarly, if $Y$ is a solution of $J_m(\lambda)^\tp Y + Y J_m(\lambda)^\tp = 2J_m(\lambda)^\tp  + (J_m(\lambda)^\tp)^3$ in $\mathbb{C}^{m\times m}$ then $Y  = I_m + (J_m(\lambda)^\tp)^2/2 + T$ for some $T$ such that $H_m T H_m$ is a lower triangular alternating Toeplitz matrix. In particular, if $\lambda \ne 0$ then $T = 0$.
\item\label{lem:lower triangular:item3} For any $b \ge 0$, a solution of 
\[
J_m\left( \begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix} \right) Y + Y J_n \left(\begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix}\right) = 0
\] 
in $\mathbb{F}^{2m\times 2n}$ is block lower triangular alternating Toeplitz, where each block has size $2\times 2$. If $b > 0$ then $2 \times 2$ blocks are of the form $\begin{bsmallmatrix}
x & y \\
y & -x
\end{bsmallmatrix} \in \mathbb{F}^{2\times 2}$.

\item\label{lem:lower triangular:item4} For any $b \ge 0$, a solution of 
\[
J_m\left( \begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix} \right) Y + Y J_m \left(\begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix}\right) = 2 J_m \left(\begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix}\right)  + J_m \left(\begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix}\right) ^3
\] 
in $\mathbb{F}^{2m\times 2m}$ can be written as $I_{2m} + \frac{1}{2} J_m\left( \begin{bsmallmatrix}
0 & b \\
-b & 0
\end{bsmallmatrix}\right)^2 + T$ for some block lower triangular alternating Toeplitz matrix $T$, where each block has size $2\times 2$. If $b > 0$ then $2 \times 2$ blocks are of the form $\begin{bsmallmatrix}
x & y \\
y & -x
\end{bsmallmatrix}\in \mathbb{F}^{2\times 2}$.

\item\label{lem:lower triangular:item5} For any $a, b \ge 0$, $Y (I_2\otimes H_n)$ is block lower triangular Toeplitz, where each block is of the form $\begin{bsmallmatrix}
x & y \\
y & -x
\end{bsmallmatrix} \in \mathbb{C}^{2\times 2}$. Here $Y$ is a solution of 
\[
J_m\left( \begin{bsmallmatrix}
a & b \\
-b & a
\end{bsmallmatrix} \right) Y - Y J_n \left(\begin{bsmallmatrix}
a & b \\
-b & a
\end{bsmallmatrix}\right)^\tp = 0
\] 
in $\mathbb{C}^{2m\times 2n}$. Similarly, If $Y$ is a solution of 
\[
J_m^\tp \left( \begin{bsmallmatrix}
a & b \\
-b & a
\end{bsmallmatrix} \right) Y - Y J_n \left(\begin{bsmallmatrix}
a & b \\
-b & a
\end{bsmallmatrix}\right) = 0,
\] 
then $(I_2 \otimes H_m) Y$ is block lower triangular Toeplitz, where each block is of the form $\begin{bsmallmatrix}
x & y \\
y & -x
\end{bsmallmatrix} \mathbb{C}^{2\times 2}.
$
\item\label{lem:lower triangular:item6} For any $\lambda \in \mathbb{C}$ with $\operatorname{Re}(\lambda) > 0$ and $\operatorname{Im}(\lambda) \ge 0$, $Y (I_2\otimes H_n)$ is block lower triangular Toeplitz, where each block has size $2\times 2$ and $Y$ is a solution of 
\[
J_m\left( \begin{bsmallmatrix}
\lambda & 0 \\
0 & \lambda^\ast
\end{bsmallmatrix} \right) Y - Y J_n \left(\begin{bsmallmatrix}
\lambda & 0 \\
0 & \lambda^\ast
\end{bsmallmatrix}\right)^\ast  = 0
\] 
in $\mathbb{H}^{2m\times 2n}$. Similarly, if $Y$ is a solution of 
\[
J_m\left( \begin{bsmallmatrix}
\lambda & 0 \\
0 & \lambda^\ast
\end{bsmallmatrix} \right)^\ast Y - Y J_n \left(\begin{bsmallmatrix}
\lambda & 0 \\
0 & \lambda^\ast
\end{bsmallmatrix}\right)  = 0,
\] 
then $(I_2 \otimes H_m) Y$ is block lower triangular Toeplitz, where each block has size $2\times 2$.  Moreover, if $\lambda \in \mathbb{C}\setminus \mathbb{R}$ then $2\times 2$ blocks are of the form $\begin{bsmallmatrix}
x\qj & y \\
z & w\qj
\end{bsmallmatrix} \in \mathbb{H}^{2\times 2}, x, y, z, w\in \mathbb{C}
$.\footnote{Here $\qi,\qj,\qk \in \mathbb{H}$ are the units in the standard expression $a + b \qi + c \qj + d \qk \in \mathbb{H}$ of a quaternion number.  The reader should distinguish the complex unit $\ci \in \mathbb{C}$ from the quaternion unit $\qi \in \mathbb{H}$.} 
\end{enumerate}
\end{lemma}
\begin{proof}
We defer the proof to Appendix~\ref{append:proof of lem:lower triangular}.
\end{proof} 
\begin{example}
As an illustration of Lemma~\ref{lem:lower triangular},  we consider $m = 2, n =3$ and $\lambda = 0$ so that
 $J_m(\lambda) Y + Y J_n(-\lambda) = 0$ becomes
\[
\begin{bsmallmatrix}
0 & 0 & 0 \\
y_{11}  & y_{12} & y_{13}
\end{bsmallmatrix} +
\begin{bsmallmatrix}
y_{12}  & y_{13} & 0 \\
y_{22}  & y_{23} & 0 \\
\end{bsmallmatrix} = 0,
\]
where $Y = (y_{ij})_{i,j=1}^{2,3}$. Clearly we have $y_{12} = y_{13} = y_{23} = 0$ and $y_{11} + y_{22} = 0$ from which we obtain $Y = \begin{bsmallmatrix}
y_{11} & 0 & 0 \\
y_{21} & -y_{11} & 0
\end{bsmallmatrix}$ is a lower triangular alternating Toeplitz matrix.
\end{example}
