\end{bsmallmatrix}, \quad 
\ch{_{$\fp$} S}(x_1,\dots, x_p) \coloneqq 
\begin{bsmallmatrix}
x_p & 0 & \cdots & 0\\
x_{p-1} & -x_p & \cdots & 0 \\
\vdots & \vdots & \ddots & 0 \\
x_1 & -x_{2} & \cdots & (-1)^{p-1} x_p
\end{bsmallmatrix}, \\  
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
T_{\fp}(x_1,\dots, x_p) &\coloneqq 
\begin{bsmallmatrix}
0 & \cdots & 0 & x_p\\
0 & \cdots & x_p & x_{p-1} \\
\vdots & \udots & \vdots & \vdots \\
x_p & \cdots & x_{2} & x_1
\end{bsmallmatrix}, \quad 
S_{\fp}(x_1,\dots, x_p) \coloneqq 
\begin{bsmallmatrix}
0 & \cdots & 0 & x_p\\
0 & \cdots & -x_p & x_{p-1} \\
\vdots & \udots & \vdots & \vdots \\
(-1)^{p-1} x_p & \cdots & -x_{2} & x_1
\end{bsmallmatrix},\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\ch{^{$\fp$} T}(x_1,\dots, x_p) &\coloneqq 
\begin{bsmallmatrix}
x_1 & x_{2} & \cdots &  x_p \\
\vdots & \vdots & \udots & 0 \\
x_{p-1} & x_p & \cdots & 0 \\
x_p & 0 & \cdots & 0
\end{bsmallmatrix},\quad 
\ch{^{$\fp$} S}(x_1,\dots, x_p) \coloneqq 
\begin{bsmallmatrix}
x_1 & -x_{2} & \cdots &  (-1)^{p-1}x_p\\
\vdots & \vdots  & \udots & 0 \\
x_{p-1} & -x_p & \cdots & 0 \\
x_p & 0 & \cdots & 0
\end{bsmallmatrix},  \\ 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
T^{\fp}(x_1,\dots, x_p) &\coloneqq 
\begin{bsmallmatrix}
x_p & \cdots & x_{2} & x_1\\
\vdots & \udots & \vdots & \vdots \\
0 & \cdots & x_p & x_{p-1} \\
0 & \cdots & 0 & x_p
\end{bsmallmatrix},\quad 
S^{\fp}(x_1,\dots, x_p) \coloneqq 
\begin{bsmallmatrix}
(-1)^{p-1} x_p & \cdots & -x_{2} & x_1\\
\vdots & \udots & \vdots & \vdots \\
0 & \cdots & -x_p & x_{p-1} \\
0 & \cdots & 0 & x_p
\end{bsmallmatrix}.
\end{align*}




