\begin{proof}
The characterization of $Y_{ij}$'s in Tables~\ref{Tab:CandidatesYij} and \ref{Tab:CandidatesYijcon'd} is obtained by solving equations \eqref{lem:block:eq1} and \eqref{lem:block:eq2}, which relies on Lemma~\ref{lem:lower triangular}. We need to split the discussion with respect to the seven cases in Table~\ref{Tab:indecomposable}. This leads to a lengthy calculation and we omit the proof here for clarity. A detailed proof can be found in Appendix~\ref{append:proof lem:Yij}.
\end{proof}

\begin{theorem}[Structure theorem]\label{thm:structure}
Assume $B\in \GL_n(\mathbb{F})$  satisfies $B^\sigma = \varepsilon B$ where $\varepsilon = \pm 1$. Let $\alpha: \mathbb{R} \to G_B(\mathbb{F})$ be a quadratic  rational curve on $G_B(\mathbb{F})$ with poles at $\pm \ci$.  There exists $R\in \GL_n(\mathbb{F})$ such that
\[
\alpha(t) =R\left( \frac{t^2  I_{n} + t \diag(X_1,\dots, X_s) + (Y_{pq})_{p,q=1}^s}{t^2 + 1} \right)R^{-1}, \quad B  = R \diag(B_1,\dots, B_s) R^{\sigma},
\]
where 
\begin{enumerate}[(i)]
\item $(X_p,B_p)\in \mathbb{F}^{m_p\times m_p}\times \GL_{m_p}(\mathbb{F})$ is as in Table~\ref{Tab:indecomposable}.
\item If $0\not\in \rho(X_p) + \rho(X_q)$ then $Y_{pq} = 0$.
\item If $0 \in \rho(X_p) + \rho(X_q)$ then $Y_{pq}$ is as in Tables~\ref{Tab:CandidatesYij} and \ref{Tab:CandidatesYijcon'd}. 
\item Moreover, $\{ Y_{pq}: 1 \le p, q \le s \}$ satisfies the equation
\begin{equation}\label{thm:structure:eq1}
\sum_{r=1}^s Y_{ur} B_r Y_{vr}^\sigma =\delta_{u,v} B_u,\quad 1 \le u \le v \le s.
\end{equation}
\end{enumerate}
In particular, if $\alpha'(0)$ has distinct eigenvalues, then $Y_{pq} = 0$ if $1 \le p \ne q \le s$ and $Y_{pp}\in G_{B_p}(\mathbb{F})$, i.e.,
\begin{equation*}
Y_{pp} B_p Y_{pp}^\sigma = B_p,\quad 1 \le p \le s.
\end{equation*}
\end{theorem}
\begin{proof}
This is a direct consequence of equation~\eqref{eq:quadratic4}, Lemmas~\ref{lem:invariance}, \ref{lem:indecomposable} and \ref{lem:Yij}. 
\end{proof}
