\subsection{Quadratic  rational curves on unitary groups}
We notice that $G_B(\mathbb{F}) = \U_n$ (resp. $\mathfrak{g}_B(\mathbb{F}) = \mathfrak{u}_n$) for $(B,\mathbb{F},\sigma) = (I_n,\mathbb{C},\text{conjugate transpose})$. The lemma that follows is a basic fact.
\begin{lemma}[Normal form of skew Hermitian matrices]\label{lem:normal form skew Hermitian}
For each $A_1 \in \mathfrak{u}_n$, there exist $U\in \U_n$, positive integers $m_1,\dots, m_r$ and real numbers $\lambda_1 > \cdots > \lambda_r > 0$ such that 
\[
A_1 = \ci U \diag \left(
\lambda_1 I_{m_1}, -\lambda_1 I_{m_1}, \dots,  \lambda_r I_{m_r}, -\lambda_r I_{m_r}, 0,\dots, 0
\right) U^\ast.
\]
\end{lemma}
%\begin{proof}
%Since $A_1$ is skew Hermitian, its eigenvalues are pure imaginary. Moreover, it is diagonalizable by a unitary matrix. The desired normal form of $A_1$ can be easily obtained by further conjugating a permutation matrix.
%\end{proof}
\begin{theorem}[Classification of quadratic  rational curves on $\U_n$]\label{thm:classification U_n}
If $\alpha$ is a quadratic  rational curve on $\U_n$ with poles at $\pm \ci$, then there exist $Q \in \U_n$, $2 \ge a_1 > \cdots > a_r > 0$ such that $\alpha(t) = Q \left( t^2  I_{n} + t A_1+ A_0 \right)/(t^2 + 1) Q^\ast$, where 
\begin{align*}
A_1 &= \ci \diag \left(
a_1 I_{m_1}, -a_1 I_{m_1}, \dots,  a_r I_{m_r}, -a_r I_{m_r}, 0,\dots, 0
\right), \\
A_0 &= \diag \left(
\begin{bsmallmatrix}
(1 -a_1^2/2) I_{m_1} & b_1 I_{m_1} \\
-b_1 I_{m_1} & (1 -a_1^2/2) I_{m_1}
\end{bsmallmatrix}, \dots,  
\begin{bsmallmatrix}
(1 -a_r^2/2) I_{m_r} & b_r I_{m_r} \\
-b_r I_{m_r}  & (1 -a_r^2/2) I_{m_r} 
\end{bsmallmatrix}, 
I_{n - 2 \sum_{j=1}^r m_r}
\right), \\
b_p &= a_p \sqrt{1-a_p^2/4},\quad 1 \le p \le r.
\end{align*}
In particular, every quadratic  rational curve $\alpha$ on $\U_n$ with poles at $\pm \ci$ can be written as $\alpha = Q \prod_{j=1}^r \beta_j Q^\ast$ where $Q\in \U_n$ and  
\[
\beta_j = \diag\left(
I_{2j-2},
\begin{bsmallmatrix}
\frac{t^2 + \ci f_j t + (1-f_j^2/2)}{t^2 + 1} & \frac{f_j \sqrt{1-f_j^2/4}}{t^2 + 1}  \\[2pt]
-\frac{f_j \sqrt{1-f_j^2/4}}{t^2 + 1} & \frac{t^2 - \ci f_j t + (1-f_j^2/2)}{t^2 + 1}
\end{bsmallmatrix} ,
I_{n - 2j}
\right),\quad f_j\in (0,2], \quad 1 \le j \le r.
\]
\end{theorem}
\begin{proof}
We write 
\[
\alpha(t) =R\left( \frac{t^2  I_{n} + t \diag(X_1,\dots, X_s) + (Y_{pq})_{p,q=1}^s}{t^2 + 1} \right)R^{-1}, \quad I_n  = R \diag(c_1 B_1,\dots, c_s B_s) R^{\ast},
\]
where $R$, $(X_1,\dots, X_s)$ and $(Y_{pq})_{p,q=1}^s$ are those given in Theorem~\ref{thm:structure}. Since eigenvalues of $A_1 \in \mathfrak{u}_n$ are pure imaginary, each $(X_p,B_p)$ must has the form $(J_m(x\ci) , \kappa \ci^{m-1} F_m)$ by Lemma~\ref{lem:Yij}. We also notice that $\diag(B_1,\dots, B_s) = R^{-1} (R^{-1})^\ast$ is positive definite. This implies that each $B_p = 1$. Consequently, we obtain $s =n$, $R\in \U_n$, $X_p = x_p \ci \in  \mathbb{R} \ci$ and $B_p = \kappa_p = 1, 1 \le p \le n$. 
%Without loss of generality, we may assume $\kappa_1 = \cdots = \kappa_n = 1$.

According to Table~\ref{Tab:CandidatesYij}~No.~3, we have 
\[
Y_{pp} = \begin{cases}
1 + \ci y_p,&~\text{if}~x_p  = 0 \\
1 - x_p^2/2,&~\text{if}~x_p  \ne 0 \\
\end{cases}, \quad
-\overline{Y}_{qp} = Y_{pq} = 
\begin{cases}
y_{pq},&~\text{if}~x_p = -x_q \\
0,&~\text{if}~x_p \ne -x_q \\
\end{cases},
\] 
where $y_p\in \mathbb{R}, y_{pq} \in \mathbb{C}$, $1\le p \le q \le n$. Lemma~\ref{lem:normal form skew Hermitian} ensures the existence of a permutation matrix $P$ such that 
\[
P \diag(x_1 \ci ,\dots, x_n \ci ) P^\tp = 
\ci \diag \left(
a_1 I_{m_1}, -a_1 I_{m_1}, \dots,  a_r I_{m_r}, -a_r I_{m_r}, 0,\dots, 0
\right).
\]
Obviously, we have $\{x_1,\dots, x_n
\} = \{a_1,\dots, a_r\}$. It is straightforward to verify that 
\[
P (Y_{pq})_{p,q=1}^n P^\tp = 
\diag \left(
\begin{bsmallmatrix}
(1 -a_1^2/2) I_{m_1} & Z_1 \\
-Z_1^\ast & (1 -a_1^2/2) I_{m_1}
\end{bsmallmatrix}, \dots,  
\begin{bsmallmatrix}
(1 -a_r^2/2) I_{m_r} & Z_r \\
-Z_r^\ast & (1 -a_r^2/2) I_{m_r} 
\end{bsmallmatrix}, 
I_{n - 2\sum_{j=1}^r m_r} + \ci D
\right),
\]
where $D$ is a real diagonal matrix. Now \eqref{thm:structure:eq1} implies $D =0$ and $Z_p Z_p^\ast = a_p^2(1-a_p^2/4) I_{m_p}, 1\le p \le r$. In particular, we must have $a_p \in (0,2]$ since $Z_p Z_p^\ast$ is positive semidefinite. We observe that $Z_p =a_p \sqrt{1-a_p^2/4} Q_p$ for some $Q_p \in \U_{m_p}$. Thus we have  
\[
\begin{bsmallmatrix}
(1- a_p^2/2) I_{m_p} & Z_p \\
-Z_p^\ast & (1- a_p^2/2) I_{m_p}
\end{bsmallmatrix} =
\begin{bsmallmatrix}
Q_p & 0 \\
0 & I_{m_p}
\end{bsmallmatrix}
 \begin{bsmallmatrix}
(1- a_p^2/2) I_{m_p} & a_p \sqrt{1-a_p^2/4} I_{m_p} \\
-a_p \sqrt{1-a_p^2/4} I_{m_p} & (1- a_p^2/2) I_{m_p}
\end{bsmallmatrix}
\begin{bsmallmatrix}
Q_p & 0 \\
0 & I_{m_p}
\end{bsmallmatrix}^\ast
\] 
and this completes the proof.
\end{proof}
\begin{corollary}[Classification of quadratic  rational curves on $\SU_n$]\label{cor:classification SU_n}
A quadratic   rational curve on $\U_n$ is also a quadratic   rational curve on $\SU_n$.
\end{corollary}
\begin{proof}
Let $\alpha$ be a quadratic  rational curve on $\U_n$. We prove that $\det(\alpha) = 1$. Without loss of generality,  we assume that poles of $\alpha$ are $\pm \ci$. By Theorem~\ref{thm:classification U_n}, it suffices to prove 
\[
\det \left( 
\begin{bsmallmatrix}
(t^2 + \ci a t+ (1-a^2/2) ) I_m & a \sqrt{1-a^2/4} I_m \\
-a \sqrt{1-a^2/4} I_m & (t^2 - \ci a t + (1-a^2/2) ) I_m
\end{bsmallmatrix}
\right) = (t^2 + 1)^{2m},\quad a\in [0,2].
\] 
\end{proof}

