\section{Decomposition of rational curves on linear algebraic groups}\label{sec:dec}
This section is devoted to the decomposition of rational curves on $G_B(\mathbb{F})$ and $\ISO_{p,n-p}^+(\mathbb{R})$.  We first deal with $G_B(\mathbb{F})$ as $\SO_{p,n-p}^+(\mathbb{R})$ is a special case of $G_B(\mathbb{F})$,  and the proof for $\ISO_{p,n-p}^+(\mathbb{R})$ relies on the decomposition theorem for $\SO_{p,n-p}^+(\mathbb{R})$.
\subsection{Decomposition of rational curves on \texorpdfstring{$G_B(\mathbb{F})$}{GB}}\label{subsec:KempeGB}
\begin{lemma}\label{lem:relation}
Let $\gamma(t) = P(t)/q(t)$ be a  rational curve  on $G_B(\mathbb{F})$ and let $\zeta \in \mathbb{C}\setminus \mathbb{R}$ be a root of $q(t)$ with multiplicity $s\ge 1$. Then we have  
\[
\sum_{j=0}^{l} P^{(j)}(\zeta) B P^{(l - j)}(\zeta)^\sigma = 0,\quad l = 0,\dots, 2s-1.
\]
\end{lemma}
\begin{proof}
By definition, $P(t)$ and $q(t)$ satisfy the relation:
\begin{equation}\label{lem:relation:eq1}
P(t) B P(t)^\sigma  = q(t)^2 B.
\end{equation}
Since $\zeta$ is a root of $q(t)$ with multiplicity $s$, 
the desired relations for $P^{(j)}(\zeta)$'s are obtained immediately by differentiating \eqref{lem:relation:eq1} at $\zeta$. 
\end{proof}
