\begin{lemma}[Degree reduction for $G_B(\mathbb{R})$]\label{lem:existenceR}
For any $\gamma(t) = P(t)/q(t)\in \Rat_d(G_B(\mathbb{R}),  I_n)$ with a pole $\zeta \in \mathbb{C}\setminus \mathbb{R}$ of multiplicity $s$, there exists an $\alpha(t)\in \Rat_{2s}(G_B(\mathbb{R},I_n)$ with only poles at $\zeta$ and $\overline{\zeta}$ such that $\alpha(t) \gamma(t) \in \Rat_{d- 2s}(G_B(\mathbb{R},I_n) $.
\end{lemma}
\begin{proof}
By a linear change of coordinate, we may assume that $\zeta = \ci$. We write $A(t) = c  I_n t^{2s} +\sum_{j=0}^{2s - 1} A_j t^j$ where $c\in \mathbb{R}, A_{2s - 1},\dots, A_0\in \mathbb{R}^{n\times n}$ are coefficients to be determined. Then we have 
\[
A^{(m)}( \ci ) =\frac{(2s)!}{(2s - m)!} c  I_n \ci^{2s-m}  + \sum_{j=m}^{2s - 1} \frac{j!}{(j - m)!} A_j \ci^{j-m},\quad 0 \le m \le 2s-1.
\]
We consider the homogeneous system of linear equations:
\begin{equation}\label{lem:existence:eq1}
(AP)^{(l)}( \ci ) = \sum_{j = 0}^l A^{(l-j)}( \ci ) P_{j} = 0,\quad l = 0,\dots, 2s-1
\end{equation}
where $P_j = P^{(j)}( \ci ), 0 \le j \le 2s-1$. 

If \eqref{lem:existence:eq1} has a solution of the form $(1,A_{2s-1},\dots, A_0)\in \mathbb{R}\times (\mathbb{R}^{n\times n})^{2s}$, then $\alpha(t) \coloneqq A(t)/( t^2 + 1)^s$ is a desired  rational curve of degree $2s$. Indeed, by \eqref{lem:existence:eq1} we clearly have $(t - \ci )^{2s} | A(t) P(t)$. Since both $A(t)$ and $P(t)$ are real, we further have  $(t^2 + 1)^{2s} | A(t) P(t)$. We notice that 
\[
(t^2 + 1)^{4s} | A(t) P(t) B  (A(t) P(t))^\sigma  = q(t)^2 A(t) B A(t)^\sigma.
\]
Therefore, $(t^2 + 1)^{2s} | A(t) B A(t)^\sigma$ since $ \ci $ is a root of $q(t)$ of multiplicity $s$. Since $A(t) = I_n t^{2s} + \sum_{j=0}^{2s - 1} A_j t^j$, we have $A(t) B A(t)^\sigma  = B t^{4s} + O(t^{4s-1}) \ne 0$. This implies $A(t) B A(t)^\sigma = (t^2 + 1)^{2s}B$ and $\alpha(t)$ is a  rational curve of degree $2s$ on $G_B(\mathbb{R})$.

Thus, it is left to prove that \eqref{lem:existence:eq1} has a solution $(c,A_{2s-1},\dots,A_0)\in \mathbb{R}\times (\mathbb{R}^{n\times n})^s$ such that $c \ne 0$. To this end, we obverse that 
\begin{equation}\label{lem:existence:eq11}
A^{(m)}( \ci ) =
\begin{bmatrix}
cI_n & A_{2s-1} & \cdots & A_m & A_{m-1} & \cdots & A_0
\end{bmatrix}
\begin{bmatrix}
\frac{(2s)! \ci^{2s-m}}{(2s - m)!} I_n \\ 
\frac{(2s-1)! \ci^{2s-1-m} }{(2s - 1 - m)!} I_n \\ 
\vdots \\
\frac{(m)! \ci^0}{0!} I_n \\
0 \\ 
\vdots \\
0 
\end{bmatrix},\quad 0 \le m \le 2s -1.
\end{equation}
Thus we may rewrite \eqref{lem:existence:eq1} as  
\begin{equation}\label{lem:existence:eq2}
\begin{bmatrix}
cI_n & A_{2s-1} & \cdots & A_0
\end{bmatrix} C  M
= 0,
\end{equation}
where 
\begin{align*}
M &\coloneqq \begin{bmatrix}
P_0 & 0 & \cdots & 0  & 0 \\
P_1 & P_0 & \cdots & 0 & 0\\
\vdots &  \vdots & \ddots & \vdots & \vdots \\
P_{2s-2} & P_{2s-3} & \cdots & P_0 & 0\\
P_{2s-1} & P_{2s-2} & \cdots & P_1 & P_0
\end{bmatrix} \in \mathbb{C}^{2sn \times 2sn}, \\
C &\coloneqq \begin{bmatrix}
\frac{(2s)! \ci^{2s}}{(2s)!} I_n & \frac{(2s)! \ci^{2s-1}}{(2s-1)!} I_n &  \cdots & \frac{(2s)! \ci^{2}}{(2)!} I_n & \frac{(2s)! \ci^{1}}{(1)!} I_n  \\ 
\frac{(2s-1)! \ci^{2s-1} }{(2s - 1)!} I_n & \frac{(2s-1)! \ci^{2s-2} }{(2s - 2)!} I_n & \cdots &   \frac{(2s-1)! \ci}{(1)!} I_n & \frac{(2s-1)! \ci^{0}}{(0)!} I_n \\ 
\frac{(2s-2)! \ci^{2s-2} }{(2s - 2)!} I_n & \frac{(2s-2)! \ci^{2s-3} }{(2s - 3)!} I_n & \cdots &   \frac{(2s-2)! \ci^{0}}{(0)!} I_n & 0\\ 
\vdots & \vdots & \ddots & \vdots & \vdots \\
\frac{(1)! \ci^1}{1!} I_n & \frac{(1)! \ci^0}{0!} I_n & \cdots & 0 & 0  \\
\frac{(0)! \ci^0}{0!} I_n  & 0 & \cdots & 0 & 0  
\end{bmatrix} \in \mathbb{C}^{(2s+1)n \times 2sn}.
\end{align*}
Since $\gamma(t)$ is a  rational curve on $G_B(\mathbb{R})$, $P_0,\dots, P_{2s-1}$ satisfy relations in \eqref{lem:rank:eq1}. Lemma~\ref{lem:rank} implies that $\rank (C M) \le \rank(M) \le sn$. The homogeneous linear system \eqref{lem:existence:eq2} imposes at most $2 sn^2$ real constraints on $2sn^2 + 1$ real variables $(c,A_{2s-1},\dots, A_0)$. Therefore, \eqref{lem:existence:eq2} has a real solution. If all real solutions of \eqref{lem:existence:eq2} are contained in the hyperplane $c = 0$, then we must have 
\[
\rank \left( C M \right) = \rank \left( D \right),\quad D= \begin{bmatrix}
v_{(2s+1)n}^\tp & CM
\end{bmatrix},
\]
where $v_{(2s+1)n} = (1,0,\dots, 0)\in \mathbb{R}^{(2s+1)n}$. We observe that by row operations, $C$ can be transformed into 
\[
\begin{bmatrix}
0 & 0 &  \cdots & 0 & 0  \\ 
0 & 0& \cdots &   0 &  I_n \\ 
0 & 0 & \cdots &   I_n & 0\\ 
\vdots & \vdots & \ddots & \vdots & \vdots \\
0 & I_n & \cdots & 0 & 0  \\
I_n  & 0 & \cdots & 0 & 0  
\end{bmatrix} \in \mathbb{R}^{(2s+1)n \times 2sn},
\]
thus $CM$ and $D$ can be transformed by the same row operations into 
\[
\begin{bmatrix}
0 & 0 & \cdots & 0  & 0 \\
P_{2s-1} & P_{2s-2} & \cdots & P_1 & P_0 \\
P_{2s-2} & P_{2s-3} & \cdots & P_0 & 0\\
\vdots &  \vdots & \ddots & \vdots & \vdots \\
P_1 & P_0 & \cdots & 0 & 0\\
0 & 0 & \cdots & 0  & 0 
\end{bmatrix},\quad 
\begin{bmatrix}
v_n^\tp & 0 & 0 & \cdots & 0  & 0 \\
0 & P_{2s-1} & P_{2s-2} & \cdots & P_1 & P_0 \\
0 & P_{2s-2} & P_{2s-3} & \cdots & P_0 & 0\\
\vdots & \vdots &  \vdots & \ddots & \vdots & \vdots \\
0 & P_1 & P_0 & \cdots & 0 & 0\\
0 & 0 & 0 & \cdots & 0  & 0 
\end{bmatrix},
\]
where $v_{n} = (1,0,\dots, 0)\in \mathbb{R}^{n}$. This clearly contradicts the equality $\rank \left( C M \right) = \rank \left( D \right)$, so \eqref{lem:existence:eq2} must have a real solution $(c,A_{2s-1},\dots, A_0)$ such that $c \ne 0$.
\end{proof}
Next we consider the analogue of Lemma~\ref{lem:existenceR} for $G_B(\mathbb{C})$ and $G_B(\mathbb{H})$. 
\begin{lemma}[Degree reduction for $G_B(\mathbb{C})$ and $G_B(\mathbb{H})$]\label{lem:existenceC}
For any $\gamma(t) = P(t)/q(t) \in \Rat_d(G_B(\mathbb{C}), I_n)$ (resp.  $\gamma(t) = P(t)/q(t) \in \Rat_d(G_B(\mathbb{H}),  I_n)$) with a pole $\zeta \in \mathbb{C}\setminus \mathbb{R}$ of multiplicity $s$,  there exists an $\alpha(t) \in \Rat_{2s}(G_B(\mathbb{C}), I_n)$ (resp.  $\alpha(t) \in \Rat_{2s}(G_B(\mathbb{H}), I_n)$) with only poles at $\zeta$ and $\overline{\zeta}$ such that $\alpha(t) \gamma(t) \in \Rat_{d - 2s}(G_B(\mathbb{C}), I_n)$ (resp.  $\alpha(t) \in \Rat_{d-2s}(G_B(\mathbb{H}), I_n)$). 
\end{lemma}
\begin{proof}
We first deal with the case over $\mathbb{C}$. We recall that $\mathbb{C}^{n\times n}$ is embedded in $\mathbb{R}^{2n \times 2n}$ as an $\mathbb{R}$-subalgebra by 
\[
\psi: \mathbb{C}^{n\times n} \hookrightarrow \mathbb{R}^{2n\times 2n},\quad \psi(A + \ci B) = \begin{bmatrix}
A & B \\
-B & A
\end{bmatrix}.
\]


By a linear change of coordinate, we may assume that $\zeta = \ci$. We write $C(t) = c  I_n t^{2s} +\sum_{j=0}^{2s - 1} (A_j + \ci B_j) t^j$ where $c\in \mathbb{R}, A_{2s - 1},B_{2s-1}, \dots, A_0, B_0\in \mathbb{R}^{n\times n}$ are coefficients to be determined. We write $Z_j = \psi(A_j + \ci B_j), 0 \le j \le 2s-1$. Then we have $Z(t) = c  I_{2n} t^{2s} +\sum_{j=0}^{2s - 1} Z_j t^j$ and
\[
Z^{(m)}(\ci) =\frac{(2s)!}{(2s - m)!} c  I_{2n} \ci^{2s-m}  + \sum_{j=m}^{2s - 1} \frac{j!}{(j - m)!} Z_j \ci^{j-m}\in \mathbb{C}^{2n \times 2n},\quad 0 \le m \le 2s-1.
\]
We consider the homogeneous system of linear equations:
\begin{equation}\label{lem:existenceC:eq1}
(Z \psi(P))^{(l)}(\ci) = \sum_{j = 0}^l Z^{(l-j)}(\ci) P_j^\psi = 0,\quad l = 0,\dots, 2s-1
\end{equation}
where $P_j^\psi \coloneqq \psi(P)^{(j)}(\ci)\in \mathbb{C}^{2n \times 2n}, 0 \le j \le 2s-1$. 

If \eqref{lem:existenceC:eq1} has a solution of the form $(1,A_{2s-1},B_{2s-1}, \dots, A_0,B_0)\in \mathbb{R}\times (\mathbb{R}^{n\times n})^{4s}$, then $\alpha(t) \coloneqq C(t)/( t^2 + 1)^s$ is a desired  rational curve of degree $2s$. Indeed, by \eqref{lem:existenceC:eq1} we clearly have $(t - \ci)^{2s} | Z(t) \psi(P(t))$. Since both $Z(t)$ and $\psi(P(t))$ are real, we further have  $(t^2 + 1)^{2s} | Z(t) \psi(P(t))$. We notice that 
\[
(t^2 + 1)^{4s} | \left( Z \psi (P) \right) \psi(B) \left( Z \psi (P) \right)^\sigma
=
\psi ( (AP) B (AP)^\sigma)  = q^2 \psi(A B A^\sigma).
\]
Therefore, $(t^2 + 1)^{2s} | \psi(A B A^\sigma)$ as $\ci$ is a root of $q(t)$ of multiplicity $s$. By the definition of $\psi$, we derive $(t^2 + 1)^{2s} | A B A^\sigma$. The rest of the argument is the same as the one in the proof of Lemma~\ref{lem:existenceR}.
%Since $A(t) = I_n t^{2s} + \sum_{j=0}^{2s - 1} (A_j + \ci B_j) t^j$, we have $A(t) B A(t)^\sigma  = B t^{4s} + O(t^{4s-1}) \ne 0$. This implies $A(t) B A(t)^\sigma = (t^2 + 1)^{2s}B$ and $\alpha(t)$ is a  rational curve of degree $2s$ on $G_B(\mathbb{C})$.

Thus, it suffices to prove that \eqref{lem:existenceC:eq1} has a solution $(c,A_{2s-1},B_{2s-1},\dots,A_0,B_0)\in \mathbb{R}\times (\mathbb{R}^{n\times n})^{4s}$ such that $c \ne 0$. To this end, 
