%\begin{bmatrix}
%\frac{(2s)! \ci^{2s-m}}{(2s - m)!} I_{2n} \\ 
%\frac{(2s-1)! \ci^{2s-1-m} }{(2s - 1 - m)!} I_{2n} \\ 
%\vdots \\
%\frac{(m)! \ci^0}{0!} I_{2n} \\
%0 \\ 
