%\end{equation}
%Thus we may rewrite
we re-write \eqref{lem:existenceC:eq1} by   \eqref{lem:existence:eq11} as  
\begin{equation}\label{lem:existenceC:eq2}
\begin{bsmallmatrix}
cI_{2n} & Z_{2s-1} & \cdots & Z_0
\end{bsmallmatrix} C  M
= 0,
\end{equation}
