\begin{theorem}[Decomposition of rational curves on $G_B(\mathbb{F})$]\label{thm:KempeGBF}
If $\gamma(t) \in \Rat (G_B(\mathbb{F}),I_n)$ has poles of multiplicities $s_1,\dots, s_l$, then $\gamma (t) = \beta_1(t) \cdots \beta_l(t)$ for some $\beta_j(t) \in \Rat_{2s_j} (G_B(\mathbb{F}),I_n)$,  $1 \le j \le l$.  In particular, if all the poles of $\gamma(t)$ are simple, then $\gamma(t)$ can be decomposed into a product of $d$ quadratic  rational curves.
\end{theorem}
\begin{proof}
By Lemmas~\ref{lem:existenceR} and \ref{lem:existenceC}, there exist  rational curves $\alpha_1(t),\dots, \alpha_l(t)$ of degrees $2s_1,\dots, 2s_l$ respectively such that $\alpha_l(t) \cdots \alpha_1(t)  \gamma(t) = 1$. For each $1 \le j \le l$, we let $\beta_j(t) = \alpha_j(t)^{-1}$. Proposition~\ref{prop:inverse} indicates that $\beta_j(t)$ is a  rational curve on $G_B$ of degree $2s_j$ and this completes the proof.
\end{proof}
\begin{remark}
One can easily construct a rational curve on $G_B(\mathbb{F})$ with multiple poles,  which can be further decomposed into a product of low degree rational curves.  However, Example~\ref{ex:KempeGBF} indicates the existence of quartic rational curves with multiple poles,  which can not be decomposed into a product of two quadratic rational curves.
\end{remark}
\begin{example}\label{ex:KempeGBF}
We first consider
\[
\gamma(t) = I_3 +\frac{1}{t^2+1} W_1 +\frac{1}{2(t^2+1)^2} W_2,   \quad W_1 \coloneqq
\begin{bsmallmatrix}
 0 & 1  &   -1  \\
 -1 &  0  &   0 \\
 -1 &  0  &   0  
\end{bsmallmatrix}, 
\quad W_2\coloneqq 
\begin{bsmallmatrix}
 0 & 0  &   0  \\
 0 &  -1  &   1 \\
 0 &  -1  &  1  
\end{bsmallmatrix}.  
\]
It is straightforward to verify that $\gamma \in \Rat_4(\SO^+_{2,1}(\mathbb{R}), I_3)$.  We prove that $\gamma$ is not a product of two quadratic rational curves on $\SO^+_{2,1}(\mathbb{R},I_3)$.  Assume on the contrary that $\gamma(t) = \alpha(t) \beta(t)$ for some $\alpha,  \beta \in  \Rat_2(\SO^+_{2,1}(\mathbb{R}), I_3)$ which are parametrized as 
\[
 \alpha(t)=\frac{t^2 I_3 +t A_1+A_0}{t^2+1}, \quad  \beta(t)=\frac{t^2 I_3 + tB_1 + B_0}{t^2+1}.
\]
Since $\alpha(t)^\tp I_{2,1} \gamma(t) =I_{2,1} \beta(t)$,  the numerator $N(t)$ of $\alpha(t)^\tp I_{2,1} \gamma(t)$ must be divisible by $(t^2 + 1)^2$,  where 
\[
N(t) = \left(t^2 I_3 + tA_1^{\tp}+A_0^{\tp}\right)I_{2,1}\left(2(t^2+1)^2 I_3 + 2(t^2+1) W_1 + W_2\right).
\]
The remainder of $N(t)$ divided by $(t^2 + 1)^2$ is 
\[
\left(tA_1^{\tp}+A_0^{\tp}- I_3 \right)I_{2,1}(2(t^2+1) W_1+W_2)+(t^2+1) I_{2,1} W_2 = 0. 
\]
Since $\alpha \in \Rat_{2}(\SO_{2,1}(\mathbb{R}), I_2)$,  we obtain the equations for $A_1$:
\[
A_1 I_{2,1}+I_{2,1} A_1^{\tp}=A_1^{\tp} I_{2,1} W_1=A_1^{\tp} I_{2,1} W_2=0.
\]
This implies $A_1 = 0$ and we have $A_0= I_3$ by $\gamma_A(t)^{T} I_{2,1} \gamma_A(t)= I_{2,1}$.  This leads to a contradictory equality $0 = N(t) = (t^2 + 1)I_{2,1} W_2$.

Next we consider the rational curve on $\O_4(\mathbb{C})$ defined by 
\[
\gamma(t) =  
I_4 + \frac{t}{(t^2+1)^2}  U,\quad 
U \coloneqq \begin{bsmallmatrix}
 0 & -\ci  &   1  & 0 \\
 \ci &  0  &   0  & 1 \\
 -1 &  0  &   0  & \ci \\
 0 & -1  &  -\ci  & 0
\end{bsmallmatrix}.
\]
%\[\begin{bsmallmatrix}
%1              & \frac{-it}{(t^2+1)^2} & \frac{t}{(t^2+1)^2}  & 0 \\
%\frac{it}{(t^2+1)^2} & 1              &  0& \frac{t}{(t^2+1)^2}  \\
% \frac{t}{(t^2+1)^2} & 0             & 1  & \frac{it}{(t^2+1)^2} \\
% 0 & \frac{-t}{(t^2+1)^2}        & \frac{-it}{(t^2+1)^2},& 1
%\end{bsmallmatrix}\]
It is straightforward to verify $U +U^\tp=0$ and $U^2=0$.  We claim that $\gamma(t)\neq \alpha(t)\beta(t)$,  where $\alpha,\beta \in \Rat_2(\O_4(\mathbb{C}), I_4)$.  Otherwise, we write 
\[
\alpha(t)=\frac{t^2 I_4 + tA_1+A_0}{t^2+1}, \quad  \beta(t)= \frac{t^2 I_4 +tB_1+B_0}{t^2+1},          
\]
where $A_0,A_1,B_0,B_1$ are matrices such that $\alpha(t)^{\tp}\alpha(t)=\beta(t)^{\tp}\beta(t)= I_4 $. We obtain 
\[
\frac{t^2 I_4 +tB_1+B_0}{t^2+1} = \beta(t) = \alpha(t)^\tp \gamma(t) = \frac{t^2 I_4 + tA_1^\tp+A_0^\tp}{t^2+1}
\frac{(t^2+1)^2 I_4 + t U}{ (t^2+1)^2 },
\]
from which we conclude that $(t^2 + 1)^2$ divides $( t^2 I_4 + tA_1^\tp+A_0^\tp ) \left( 
(t^2+1)^2 I_4 + t U \right)$. However, this leads to a contradiction that $(t^2 + 1)^2$ must divide $t U (t^2 I_4 + t A_1^\tp + A_0^\tp)$.
\end{example}
