\subsection{Decomposition of rational curves on \texorpdfstring{$\ISO^+_{p,n-p}(\mathbb{R})$}{IGB}}\label{subsec:KempeEn}
We recall that
\[
\ISO^+_{p,n-p}(\mathbb{R}) \coloneqq \left\lbrace
\begin{bsmallmatrix}
Q & u \\
0 & 1
\end{bsmallmatrix} \in \GL_{n+1}(\mathbb{R}): Q\in \SO^+_{p,n-p}(\mathbb{R}),  u\in \mathbb{R}^n
\right\rbrace.
\]
A  rational curve $\gamma(t)$ on $\ISO^+_{p,n-p}(\mathbb{R})$ can be uniquely written as 
\begin{equation}\label{eq:curveSE}
\gamma(t) = 
\begin{bsmallmatrix}
\frac{Q(t)}{q_1(t)} & \frac{u(t)}{q_2(t)} \\
0 & 1
\end{bsmallmatrix},
\end{equation}
where $q_1(t)$ (resp. $q_2(t)$, $Q(t) = (Q_{ij}(t))_{i,j=1}^n$ and $u(t) = (u_i(t))_{i=1}^n$) is a real polynomial (resp. polynomial, $\mathbb{R}^{n\times n}$-valued polynomial and $\mathbb{R}^n$-valued polynomial) such that 
\begin{itemize}
\item $q_1(t), q_2(t)$ are monic with no real roots;
\item $\gcd(q_1(t),Q_{11}(t),\dots, Q_{nn}(t))  = \gcd(q_2(t), u_1(t),\dots, u_n(t)) = 1$;
%\item either $q_1(t) | q_2(t)$ or $q_2(t) | q_1(t)$;
\item $Q(t)^\tp I_{p,n-p} Q(t) = q_1(t)^2 I_{p,n-p}$;
\item $\lim_{t \to \infty} Q(t)/q_1(t) = I_n$;
\item $\lim_{t \to \infty} u(t)/q_2(t) = 0$.
\end{itemize}


\begin{lemma}\label{lem:existenceSE}
Let $\gamma(t) \in \Rat(\ISO_{p,n-p}^+(\mathbb{R}), I_n)$ be parametrized as in \eqref{eq:curveSE}.  Suppose that $q_1$ has $l$ roots of multiplicities $s_1,\dots, s_l$, respectively. Then there exist  rational curves $\alpha_1,\dots, \alpha_l$ on $\SO^+_{p,n-p}(\mathbb{R})$ of degrees $2s_1,\dots, 2s_l$ respectively such that 
\[
\gamma(t) = \begin{bsmallmatrix}
I_n & u(t)/q_2(t) \\
0 & 1 
\end{bsmallmatrix} 
\begin{bsmallmatrix}
\alpha_1(t) & 0 \\
0 & 1 
\end{bsmallmatrix} \cdots \begin{bsmallmatrix}
\alpha_l(t) & 0 \\
0 & 1 
\end{bsmallmatrix}.
\]
\end{lemma}
\begin{proof}
We denote $\eta(t) \coloneqq Q(t)/q_1(t)$ and $x(t) \coloneqq u(t)/q_2(t)$. 
It is straightforward to verify that $\eta$ is a  rational curve on $\SO^+_{p,n-p}(\mathbb{R})$ and $\gamma(t) =
\begin{bsmallmatrix}
I_n & x(t) \\
0 & 1 
\end{bsmallmatrix}
\begin{bsmallmatrix}
\eta(t) & 0 \\
0 & 1
\end{bsmallmatrix}$. The desired decomposition of $\gamma(t)$ follows immediately from the decomposition of $\eta$ whose existence is guaranteed by Theorem~\ref{thm:KempeGBF}.
\end{proof}
\begin{lemma}\label{lem:circular}
Assume that the image of $x(t) \in \Rat_{2d}(\mathbb{R}^n,0)$ lies in a two dimensional subspace $\mathbb{V} \subseteq \mathbb{R}^{n}$.  Then  there are 
 rotations %circular translations 
$\tau_1,\dots, \tau_{4d} \in \Rat_{2}(\SE_{2}(\mathbb{R}) ,I_2)$ and $Q \in \SO_n(\mathbb{R})$ such that
\begin{equation}\label{lem:circular:eq1}
\begin{bsmallmatrix}
I_n & x(t) \\
0 & 1
\end{bsmallmatrix} = \begin{bsmallmatrix}
Q^\tp & 0 \\
0 & 1
\end{bsmallmatrix} 
\iota_n(\tau_1) \cdots \iota_n(\tau_{4d})
\begin{bsmallmatrix}
Q & 0 \\
0 & 1
\end{bsmallmatrix}.
\end{equation}
Here $\iota_n: \SE_2(\mathbb{R}) \hookrightarrow \SE_n(\mathbb{R})$ is defined by 
\[
\begin{bsmallmatrix}
A & u \\
0 & 1
\end{bsmallmatrix} \mapsto 
\begin{bsmallmatrix}
A & 0 & u \\
0 & I_{n-2} & 0 \\
0 &  0 & 1
\end{bsmallmatrix}.
\]
\end{lemma}
\begin{proof}
We denote $\beta(t) \coloneqq \begin{bsmallmatrix}
I_n & x(t) \\
0 & 1
\end{bsmallmatrix}$.  Let $Q\in \SO_n(\mathbb{R})$ be such that $Q \mathbb{V} = \mathbb{R}^2 \times \{ 0\} \subseteq \mathbb{R}^n$. We have 
\[
\begin{bsmallmatrix}
Q & 0 \\
0 & 1
\end{bsmallmatrix} 
\beta(t)
\begin{bsmallmatrix}
Q^\tp & 0 \\
0 & 1
\end{bsmallmatrix} = 
\begin{bsmallmatrix}
I_n & Q x(t) \\
0 & 1
\end{bsmallmatrix}.
\]
Since $x(t)$ lies in $\mathbb{V}$,  $Q x(t) = (y(t),  0)^\tp$ lies in $\mathbb{R}^2 \times \{0\} \subseteq \mathbb{R}^n$ and by \cite{GKLRSV17}
%\textcolor{red}{\textbf[Is this a correct reference?]}
, there are rotations % circular translations 
$\tau_1,\dots, \tau_{4d} \in \Rat_{2}(\SE_2(\mathbb{R}),  I_2)$ such that 
\[
\begin{bsmallmatrix}
I_2 & y(t)^\tp \\
0 & 1
\end{bsmallmatrix} = \tau_1(t) \cdots \tau_{4d}(t).
\]
The proof is complete by applying $\iota_n$ to both sides.  
\end{proof}

\begin{lemma}\label{lem:circular SO21}
For each $x(t) \in \Rat_{2d}(\mathbb{R}^3,0)$,  there exist $P\in \ISO_{2,1}(\mathbb{R})$ and rotations %circular translations 
$\tau_1,\dots, \tau_{8d} \in \Rat(\SE_2(\mathbb{R})), I_3)$ such that 
\begin{equation}\label{lem:circular SO21:eq1}
\begin{bsmallmatrix}
I_3 & x(t) \\
0 & 1
\end{bsmallmatrix} = 
\iota_3(\tau_1) \cdots 
\iota_3(\tau_{4d})
P
\iota_3(\tau_{4d+1}) \cdots \iota_3(\tau_{8d})P^{-1},
\end{equation}
where $\iota_3: \SE_2(\mathbb{R}) \hookrightarrow \SE_3(\mathbb{R}) \cap \ISO_{2,1}(\mathbb{R})$ is the map defined in Lemma~\ref{lem:circular}.
\end{lemma}
\begin{proof}
We parametrize $x(t)$ as $x(t) = \begin{bsmallmatrix}
x_1(t) & x_2(t) & x_3(t)
\end{bsmallmatrix}^\tp$ and observe that 
\[
x(t) = \beta_1(t) + \beta_2(t),\quad 
\beta_1(t)  \coloneqq \begin{bsmallmatrix}
x_1(t) - x_3(t) \\
x_2(t) - x_3(t) \\ 
0
\end{bsmallmatrix},\quad
\beta_2(t) \coloneqq \begin{bsmallmatrix}
x_3(t) \\
x_3(t) \\ 
x_3(t)
\end{bsmallmatrix},
\]
which implies 
\begin{equation}\label{lem:circular SO21:eq2}
\begin{bsmallmatrix}
I_3 & x(t) \\
0 & 1
\end{bsmallmatrix}
= 
\begin{bsmallmatrix}
I_3 & \beta_1(t) \\
0 & 1
\end{bsmallmatrix}
\begin{bsmallmatrix}
I_3 & \beta_2(t) \\
0 & 1
\end{bsmallmatrix}.
\end{equation}
By Lemma~\ref{lem:circular},  the first factor of the right side of \eqref{lem:circular SO21:eq2} admits a decomposition of the form \eqref{lem:circular:eq1} with $Q = I_3$.  Therefore,  it suffices to decompose the second factor.  To this end,  we let 
\[
Q = \begin{bsmallmatrix}
-\sqrt{3} u, &  \sqrt{3}v & \sqrt{2}  \\
 v &  u &  0 \\
\sqrt{2}u &  -\sqrt{2}v  &  -\sqrt{3}
\end{bsmallmatrix},\quad u \coloneqq \frac{1 + \sqrt{3}}{2\sqrt{2}},\quad v \coloneqq \frac{1 - \sqrt{3}}{2\sqrt{2}}.
\]
It is straightforward to verify that $Q\in \SO_{2,1}^+(\mathbb{R})$ and 
\[
\begin{bsmallmatrix}
1 & 0 & 0  & x_3(t) \\
0 & 1 & 0 &  x_3(t) \\
0 & 0 & 1 & x_3(t) \\
0 & 0 & 0 & 1
\end{bsmallmatrix}
= 
P
\begin{bsmallmatrix}
1 & 0 & 0  & -\frac{\sqrt{2}}{2} x_3(t)  \\
0 & 1 & 0 &  \frac{\sqrt{2}}{2} x_3(t) \\
0 & 0 & 1 & 0 \\
0 & 0 & 0 & 1
\end{bsmallmatrix} P^{-1},\quad P \coloneqq \begin{bsmallmatrix}
I_{2,1}Q^\tp I_{2,1} & 0 \\
0 & 1
\end{bsmallmatrix}.
\]
By Lemma~\ref{lem:circular},  we obtain a decomposition of the second factor of the right side of \eqref{lem:circular SO21:eq2} and this completes the proof.
\end{proof}



\begin{theorem}[Decomposition of rational curves on $\ISO^+_{p,n-p}(\mathbb{R})$]\label{thm:KempeSE}
Let $p\le n$ be non-negative integers and let $\gamma(t) \in \Rat(\ISO_{p,n-p}^+(\mathbb{R}), I_n)$ be parametrized as in \eqref{eq:curveSE}.  Suppose that $\deg(q_2) = 2d_2$ and that $q_1$ has $l$ roots of multiplicities $s_1,\dots, s_l$, respectively.  Then there exist $N \coloneqq 4d_2 ( \lceil p/2 \rceil + \lceil (n-p)/2 \rceil)$ quadratic rational curves $\beta_1,\dots, \beta_N \in \Rat_2(\SO_2,I_2)$,  $N$ matrices $P_1,\dots, P_N \in \ISO_{p,n-p}^+(\mathbb{R})$ and $l$  rational curves $\alpha_1,\dots, \alpha_l$ on $\SO^+_{p,n-p}(\mathbb{R})$ of degrees $2s_1,\dots, 2s_l$ respectively such that  
\[
\gamma(t) = \left( P_1 
\begin{bsmallmatrix} 
\beta_1(t) & 0 \\
0 & I_{n-1}
\end{bsmallmatrix}
 P_1^{-1} \right) \cdots \left(P_N 
\begin{bsmallmatrix} 
\beta_N(t) & 0 \\
0 & I_{n-1}
\end{bsmallmatrix}
 P_N^{-1}\right) 
 \begin{bsmallmatrix}
\alpha_1(t) & 0 \\
0 & 1 
\end{bsmallmatrix} \cdots \begin{bsmallmatrix}
\alpha_l(t) & 0 \\
0 & 1 
\end{bsmallmatrix}.
\]
\end{theorem}
\begin{proof}
Denote $x(t) \coloneqq u(t)/q_2(t)$.  By Lemma~\ref{lem:existenceSE},  it is sufficient to decompose the curve 
\[
\beta (t) \coloneqq \begin{bsmallmatrix}
I_n & x(t) \\
0 & 1 
\end{bsmallmatrix},\quad x(t) \coloneqq \begin{bsmallmatrix}
x_1(t) \\
\vdots \\
x_n(t)
\end{bsmallmatrix}.
\] 

If $\min \{p, n - p\} \ne 1$,  we observe that
\[
\beta (t) =  \begin{bsmallmatrix}
I_n & y_1(t) \\
0 & 1 
\end{bsmallmatrix} \cdots \begin{bsmallmatrix}
I_n & y_{\lceil p/2 \rceil}(t) \\
0 & 1 
\end{bsmallmatrix}
\begin{bsmallmatrix}
I_n & z_1(t) \\
0 & 1 
\end{bsmallmatrix} \cdots \begin{bsmallmatrix}
I_n & z_{\lceil n-p/2 \rceil}(t) \\
0 & 1 
\end{bsmallmatrix},
\]
where 
\begin{align*}
y_i(t) &=\begin{cases}
 \begin{bsmallmatrix}
0_{2(i-1)} &\ x_{2i -1}(t) &\ x_{2i}(t) &\  0_{n - 2i} 
\end{bsmallmatrix}^\tp,&~\text{if}~2i \le p \\
 \begin{bsmallmatrix}
0_{p-2} &\ 0 &\  x_p (t) &\  0_{n-p}
\end{bsmallmatrix}^\tp,&~\text{if}~2i-1 = p 
\end{cases} \\ 
z_j(t) &=\begin{cases}
 \begin{bsmallmatrix}
0_{p + 2(j-1)} &\ x_{p + 2j -1}(t) &\ x_{p + 2j}(t) &\  0_{n - p - 2j} 
\end{bsmallmatrix}^\tp,&~\text{if}~2j \le n - p \\
 \begin{bsmallmatrix}
0_{n-2} &\ 0 &\  x_{n}(t)
\end{bsmallmatrix}^\tp,&~\text{if}~2j-1 = n-p
\end{cases}
\end{align*}
Here for each positive integer $k$, $0_k$ denotes the zero vector in $\mathbb{R}^k$.  By Lemma~\ref{lem:circular}, each $\begin{bsmallmatrix}
I_n & y_i(t) \\
0 & 1 
\end{bsmallmatrix}$ (resp.  $\begin{bsmallmatrix}
I_n & z_j(t) \\
0 & 1 
\end{bsmallmatrix}$) admits a decomposition of the form \eqref{lem:circular:eq1}.  %Moreover,  every circular translation $\tau \in \Rat_2(\SE_2(\mathbb{R}),  I_2)$ has a decomposition \textcolor{red}{\textbf[reference??]}
% \[
% \tau(t) = \left( Q_1 \begin{bsmallmatrix}
% \beta_1(t) & 0 \\
% 0 & 1
% \end{bsmallmatrix} Q_1^{-1} \right)
% \left(Q_2 \begin{bsmallmatrix}
% \beta_2(t) & 0 \\
% 0 & 1
% \end{bsmallmatrix}Q_2^{-1}\right),\quad Q_1,  Q_2 \in \SE_2(\mathbb{R}),\quad \beta_1,\beta_2 \in \Rat_2(\SO_2(\mathbb{R}),I_2).
% \]
Moreover,  every rotation $\tau \in \Rat_2(\SE_2(\mathbb{R}),  I_2)$ has a decomposition \cite{Selig2007geometric}
\[
\tau(t) = Q \begin{bsmallmatrix}
\beta(t) & 0 \\
0 & 1
\end{bsmallmatrix} Q^{-1},\quad Q\in \SE_2(\mathbb{R}),\quad \beta \in \Rat_2(\SO_2(\mathbb{R}),I_2).
\]
Since neither $p$ nor $n-p$ is equal to $1$,  constant matrices appeared in these decompositions are ensured to be contained in $\ISO_{p,n-p}(\mathbb{R})$ and the desired decomposition of $\gamma (t)$ follows immediately.

If $\min\{p,n-p\} = 1$,  we assume without loss of generality that $p = n-1$.  We notice that 
\[
\beta (t) =  \begin{bsmallmatrix}
I_n & y_1(t) \\
0 & 1 
\end{bsmallmatrix} \cdots \begin{bsmallmatrix}
I_n & y_{\lceil (n-3)/2 \rceil}(t) \\
0 & 1 
\end{bsmallmatrix}
\begin{bsmallmatrix}
I_n & z(t) \\
0 & 1 
\end{bsmallmatrix},
\]
where 
\begin{align*}
y_i(t) &=\begin{cases}
 \begin{bsmallmatrix}
0_{2(i-1)} &\ x_{2i -1}(t) &\ x_{2i}(t) &\  0_{n - 2i} 
\end{bsmallmatrix}^\tp,&~\text{if}~2i \le n-3 \\
 \begin{bsmallmatrix}
0_{n-5} &\ 0 &\  x_{n-3} (t) &\ 0_{3}
\end{bsmallmatrix}^\tp,&~\text{if}~2i -1 = n-3 
\end{cases}\\ 
z(t) &=
 \begin{bsmallmatrix}
0_{n-3} &\ x_{n-2}(t) &\ x_{n-1}(t) &\  x_{n}(t)
\end{bsmallmatrix}^\tp
\end{align*}
By Lemma~\ref{lem:circular},  each $\begin{bsmallmatrix}
I_n & y_i(t) \\
0 & 1 
\end{bsmallmatrix}$ has a decomposition of the form \eqref{lem:circular:eq1}.  According to Lemma~\ref{lem:circular SO21},  $\begin{bsmallmatrix}
I_n & z_j(t) \\
0 & 1 
\end{bsmallmatrix}$ admits a decomposition of the form \eqref{lem:circular SO21:eq1}.  %By further decomposing each circular translation,  we again obtain the desired decomposition of $\gamma(t)$.
Therefore, in summation, we obtain the desired decomposition of $\gamma(t)$.
\end{proof}
