\subsection{Generalized Kempe's Universality Theorem for loops}\label{subsec:top lift}
Since $\mathbb{P}^1_{\mathbb{R}}$ is homeomorphic to $\mathbb{S}^1$,  there is no harm to identify $\mathbb{P}^1_{\mathbb{R}}$ with $\mathbb{S}^1$ in this subsection.  Let $X$ be a topological space.   A continuous map $\gamma: \mathbb{S}^1 \to X$ is called a \emph{loop} on $X$.  First we establish a criterion for the existence of a lift of a loop,  which is similar to the well-known lifting criterion for covering spaces \cite[Proposition~1.33]{Hatcher02}.
\begin{lemma}[Topological lifting criterion]\label{lem:lifting criterion-1}
Let $H$ be a topological group and let $p : P \to X$ be a principal $H$-bundle.  A continuous loop $\gamma: \mathbb{S}^1 \to X$ admits a lift if and only if $[\gamma] \in p_\ast (\pi_1(P)) \subseteq \pi_1(X)$.  In particular,  any $\gamma$ admits a lift if either $X$ is simply connected or $H$ is connected.
\end{lemma}
\begin{proof}
Clearly,  $\gamma$ has a lift implies that $[\gamma] \in p_\ast (\pi_1(P)) \subseteq \pi_1(X)$.  For the converse,  we consider the following diagram 
\[\begin{tikzcd}
	{\gamma^\ast(P)} & {P \simeq f^\ast(EH)} & EH \\
	{\mathbb{S}^1} & X & BH
	\arrow["{\iota_\gamma}", from=1-1, to=1-2]
	\arrow["\theta"', from=1-1, to=2-1]
	\arrow["{\iota_f}", from=1-2, to=1-3]
	\arrow["p", from=1-2, to=2-2]
	\arrow["\eta", from=1-3, to=2-3]
	\arrow["s", curve={height=-12pt}, dashed, from=2-1, to=1-1]
	\arrow["\beta", dashed, from=2-1, to=1-2]
	\arrow["\gamma"', from=2-1, to=2-2]
	\arrow["f"', from=2-2, to=2-3]
\end{tikzcd}\]
where $BH$ is the classifying space of $H$,  $\eta: EH \to BH$ is the universal principal $H$-bundle,  $f$ is a continuous map such that $P \simeq f^\ast (EH)$,  $\theta: \gamma^\ast(P) \to \mathbb{S}^1$ is the pull-back of $p: P \to X$ by $\gamma$,  $\iota_\gamma$ and $\iota_f$ are maps induced by $\gamma$ and $f$ respectively.  The commutativity of this diagram implies
\begin{align*}
\text{$\gamma$ has a lift $\beta$} &\iff \text{the principal $H$-bundle $\theta: \gamma^\ast(P) \to \mathbb{S}^1$ has a section $s$} \\
&\iff \text{$\theta: \gamma^\ast(P) \to \mathbb{S}^1$ is a trivial principal $H$-bundle} \\
&\iff \text{$f\circ \gamma$  is null-homotopic} \\
&\iff f_{\ast} ([\gamma]) = 0 \in \pi_1 (BH) \xrightarrow{\delta}  \pi_0(H).
\end{align*}
Here the map $\delta$ in the last line is the first boundary map in the long exact sequence of homotopy groups for the fibration $\eta: EH \to BH$.  Since $EH$ is contractible,  $\pi_1(EH) = 0$ and $\delta$ is an isomorphism.  In particular,  $f_\ast([\gamma]) = 0$ is always satisfied if either $X$ is simply connected or $H$ is connected,  from which we conclude that $\gamma$ has a lift.

In general,  if $[\gamma] = p_\ast ([\alpha])$ for some $[\alpha]\in \pi_1(P)$,  then we have $f_\ast ([\gamma]) = f_\ast \circ p_\ast ([\alpha]) = \eta_\ast \circ (\iota_f)_\ast ([\alpha]) = 0$ as $\pi_1(EH)=0$.  Therefore,  $\gamma$ admits a lift.
\end{proof}

\begin{proposition}\label{prop:approx-lift}
Let $G$ be a real linear algebraic group and let $X$ be a homogeneous variety of $G$.  Assume $x_0\in X$ is a fixed point and $p:G \to X$ is the map defined by $p(g) = g x_0$.  If each class in $\pi_1(G)$ is represented by a rational curve on $G$,  then for any loop $\gamma: \mathbb{S}^1 \to X$ such that $[\gamma] \in p_\ast (\pi_1(G))$,  there exists a sequence of rational curves $\{\beta_n\}_{n=1}^\infty$ on $G$ such that $\{  \beta_n x_0  \}_{n=1}^\infty$ converges to $\gamma$ uniformly. 
\end{proposition}
\begin{proof}
Since $[\gamma] \in p_\ast (\pi_1(G))$,  Lemma~\ref{lem:lifting criterion-1} ensures that $\gamma$ has a lift $\beta: \mathbb{S}^1 \to G$.  By assumption,  $\beta$ is homotopic to a rational curve on $G$.  According to Theorem~\ref{thm:approx by regular maps},  $\beta$ is uniformly approximated by rational curves on $G$.
\end{proof}
\begin{remark}\label{ex:prop:approx-lift}
If $\gamma: \mathbb{S}^1 \to X$ can be uniformly approximated by $\{ \beta_n x_0 \}_{n=1}^\infty$ for a sequence $\{\beta_n\}_{n=1}^\infty$ of rational curves on $G$,  then Theorem~\ref{thm:approx by regular maps} implies that $\gamma$ is homotopic to a rational curve $\alpha$ on $X$.  In fact,  we must have $[\gamma] = [\alpha] \in p_\ast(\pi_1(G))$.  However,  it is not true that for any $\gamma: \mathbb{S}^1 \to X$ which is homotopic to a rational curve,  there exists a sequence of rational curves $\{\beta_n\}_{n=1}^\infty$ on $G$ such that $ \{\beta_n x_0\}_{n=1}^\infty$ uniformly converges to $\gamma$.  As an example,  we consider $(G,X) = (\mathbb{R}, \mathbb{S}^1)$ and $\gamma = \Id_{\mathbb{S}^1}$.  It is clear that $\gamma$ is a rational curve on $\mathbb{S}^1$,  but it has no lift since $[\gamma] = 1\in \mathbb{Z} \simeq \pi_1(\mathbb{S}^1)$.
\end{remark}

\begin{corollary}\label{cor:approx-lift}
If both $G$ and $X$ are simply connected,  then for every loop $\gamma: \mathbb{S}^1 \to X$,  there exists a sequence of rational curves $\{\beta_n\}_{n=1}^\infty$ on $G$ such that $\{ \beta_n x_0 \}_{n=1}^\infty$ uniformly converges to $\gamma$.  
\end{corollary}

Given non-negative integers $p < n$ and $0 < n_1 <  \cdots <  n_k < n$,  we denote 
\begin{align*}
\H_{p+1,n-p} &\coloneqq \{ x = (x_0,\dots, x_n) \in \mathbb{R}^{n+1}: x^\tp I_{p+1,n-p} x = 1,  x_0 \text{ for $p=0$}\},  \\
\V_{p,n}(\mathbb{R}) &\coloneqq \{ X \in \mathbb{R}^{n \times p}:  X^\tp X = I_p \},  \\
\Flag^o(n_1,\dots,  n_k; \mathbb{R}^n) &\coloneqq \lbrace
(\mathbb{V}_1,  \cdots,  \mathbb{V}_k): \mathbb{V}_j \subseteq \mathbb{V}_{j+1} \subseteq \mathbb{R}^n,  \dim \mathbb{V}_j  = n_j,\text{$\mathbb{V}_j$ is an oriented subspace}
\rbrace,  \\
\V_{p,n}(\mathbb{C}) &\coloneqq \{ X \in \mathbb{C}^{n \times p}:  X^\ast  X = I_p \},  \\
\Flag(n_1,\dots,  n_k; \mathbb{C}^n) &\coloneqq \lbrace
(\mathbb{V}_1,  \cdots,  \mathbb{V}_k): \mathbb{V}_j \subseteq \mathbb{V}_{j+1} \subseteq \mathbb{C}^n,  \dim \mathbb{V}_j  = n_j,\text{$\mathbb{V}_j$ is a subspace}
\rbrace,  \\
\V_{p,n}(\mathbb{H}) &\coloneqq \{ X \in \mathbb{H}^{n \times p}:  X^\ast X = I_p \}.
\end{align*}
We recall that all of these are homogeneous spaces:
\begin{align*}
\H_{p+1,n-p} &\simeq \SO_{p+1,n-p}^+/\SO_{p,n-p}^+,\quad  \V_{p,n}(\mathbb{H}) \simeq \Sp_n(\mathbb{H})/\Sp_{n-p}(\mathbb{H}),  \\
\V_{p,n}(\mathbb{R}) &\simeq \SO_n(\mathbb{R})/\SO_{n-p}(\mathbb{R}),\quad \Flag^o(n_1,\dots,  n_k; \mathbb{R}^n) \simeq \SO_{n}(\mathbb{R}) / \prod_{j=0}^k \SO_{n_{j+1} - n_{j}}(\mathbb{R}),\\ \V_{p,n}(\mathbb{C}) &\simeq \SU_n/\SU_{n-p},\quad \Flag(n_1,\dots,  n_k; \mathbb{C}^n) \simeq \SU_{n}/\prod_{j=0}^k \SU_{n_{j+1} - n_{j}}.
\end{align*} 
Moreover,   let $\mathbb{R}^{p,n-p-1}$ be $\mathbb{R}^{n-1}$ equipped with the standard pseudo Riemannian metric of signature $(p,n-p-1)$.  Then the conformal group $\Conf(\mathbb{R}^{p,n-p-1})$ is isomorphic to $\SO_{p+1,n-p}^+(\mathbb{R})$ \cite[Chapter 2]{Schottenloher97mathematical}.  In particular,  $\mathbb{R}^{p,n-p-1}$ is a homogeneous space of $\SO_{p+1,n-p}^+(\mathbb{R})$.
\begin{theorem}[Generalized Kempe's Universality Theorem I]\label{thm:approx-lift}
Let $(G,X)$ be one of the following pairs:
\begin{enumerate}[(i)]
\item\label{prop:ex-approx-lift:item1} $(G,X) = (\SO_{n}(\mathbb{R}),   \V_{p,n}(\mathbb{R})),  n\ge 3,  n - p \ge 2$.  
\item\label{prop:ex-approx-lift:item2} $(G,X) = (\SE_{n}(\mathbb{R}),  \mathbb{R}^n)$.
\item\label{prop:ex-approx-lift:item3} $(G,X) = (\SO_{n}(\mathbb{R}),  \Flag^o(n_1,\dots,  n_k; \mathbb{R}^n)),  n\ge 3$. 
\item\label{prop:ex-approx-lift:item4} $(G,X) = ( \SO^+_{p+1,  n-p}(\mathbb{R}),  \H_{p+1,  n-p})$.
\item\label{prop:ex-approx-lift:item4'} $(G,X) = ( \SO^+_{p+1,  n-p}(\mathbb{R}),  \mathbb{R}^{p,n-p-1})$.
\item\label{prop:ex-approx-lift:item5}  $(G,X) = (\ISO_{p+1,n-p}(\mathbb{R}),  \mathbb{R}^{n+1})$
\item\label{prop:ex-approx-lift:item6} $(G,X) = (\SU_n,  \V_{p,n}(\mathbb{C}))$ for $n \ge 2$.
\item\label{prop:ex-approx-lift:item7} $(G,X) = ( \SU_n,  \Flag(n_1,\dots,  n_k; \mathbb{C}^n))$.
\item\label{prop:ex-approx-lift:item8} $(G,X) = (\Sp_{n}(\mathbb{H}),  \V_{p,n}(\mathbb{H}))$.
\end{enumerate}
Then for every loop $\gamma: \mathbb{S}^1 \to X$,  there exists a sequence of rational curves $\{\beta_n\}_{n=1}^\infty$ on $G$ such that $\{ \beta_n x_0 \}_{n=1}^\infty$ uniformly converges to $\gamma$.  Moreover,  each $\beta_n$ can be decomposed as $\beta_n = \alpha_{n,1} \cdots \alpha_{n,s_n}$, where $\alpha_{n,j}\in \Rat(G)$ only has poles at $\{c_{n,j}, \overline{c}_{n,j} \}$ such that $\deg(\beta_n) = \sum_{j=1}^{s_n} \deg(\alpha_{n,j})$ and $\{c_{n,j}, \overline{c}_{n,j} \}$ $\ne$ $\{c_{n,k}, \overline{c}_{n,k} \}$ if $j\ne k$.
\end{theorem}
\begin{proof}
According to Theorems~\ref{thm:KempeGBF} and \ref{thm:KempeSE},  it suffices to prove the existence of $\{\beta_n\}_{n=1}^\infty$.  

In \eqref{prop:ex-approx-lift:item1}--\eqref{prop:ex-approx-lift:item3},  we have $\pi_1(G) = \mathbb{Z}_2$.  It is clear that the non-trivial class of $\pi_1(G)$ is represented by the non-trivial quadratic rational curve on $\SO_2(\mathbb{R})$ (cf. ~Example~\ref{ex:O_n}) via the natural embedding $\SO_2(\mathbb{R}) \hookrightarrow G$.  Since $X$ in \eqref{prop:ex-approx-lift:item1} and \eqref{prop:ex-approx-lift:item2} are simply connected,  the result immediately follows from Proposition~\ref{prop:approx-lift}.  For \eqref{prop:ex-approx-lift:item3},  we have $X = G/H$ where 
\[
H \coloneqq  \SO_{n_1}(\mathbb{R}) \times \SO_{n_2-n_1}(\mathbb{R}) \cdots \times \SO_{n_k - n_{k-1}}(\mathbb{R}) \times \SO_{n - n_k}(\mathbb{R}).
\]
Since $H$ is connected,  the result is obtained by Lemma~\ref{lem:lifting criterion-1} and Proposition~\ref{prop:approx-lift}.

For \eqref{prop:ex-approx-lift:item4} and \eqref{prop:ex-approx-lift:item4'}  we observe that $\SO^+_{p+1, n-p}(\mathbb{R})$ is homotopy equivalent to its subgroup $\SO_{p+1}(\mathbb{R}) \times \SO_{n-p}(\mathbb{R})$.  Thus,  $\pi_1(\SO^+_{p+1, n-p}(\mathbb{R})) = \pi_1(\SO_{p+1}(\mathbb{R})) \times \pi_1(\SO_{n-p}(\mathbb{R}))$ and each class can be represented by a quadratic rational curve on $\SO_{p+1}(\mathbb{R})$ or $\SO_{n-p}(\mathbb{R})$.  Since $\mathbb{R}^{n-1}$ and $H_{p+1, n-p}$ are simply connected,  the proof is complete by Proposition~\ref{prop:approx-lift}.  The proof for \eqref{prop:ex-approx-lift:item5} is similar,  as $\ISO^+_{p+1,n-p}(\mathbb{R})$ is homotopic equivalent to $\SO^+_{p+1,n-p}(\mathbb{R})$.

Lastly,  we notice that $G$ and $X$ in \eqref{prop:ex-approx-lift:item6}--\eqref{prop:ex-approx-lift:item8} are all simply connected.  Thus,  Corollary~\ref{cor:approx-lift} applies.  
\end{proof}
\begin{remark}
On the one hand,  homogeneous spaces considered in Theorem~\ref{thm:approx-lift} are of great importance in mathematics and physics.  For instance,  Stiefel manifolds $\V_{p,n}(\mathbb{R})$ and oriented flag manifolds $\Flag^o(n_1,\dots, n_k;\mathbb{R}^n)$ are important computational platforms in algebraic topology \cite{Milnor74,Steenrod62} and manifold optimization \cite{EAS99,YWL22}.  The hyperbolic space $H_{1,n} \simeq \SO_{1,n}^+/\SO_{n}$ is the model space for hyperbolic geometry \cite{Ratcliffe1994foundations}.  The pseudo-Euclidean space $\mathbb{R}^{p,q}$ plays a fundamental role in both Lorentzian geometry \cite{BEE96} and the study of general relativity \cite{HE23}.  The de Sitter spacetime (resp.  anti de Sitter spacetime) $H_{n,1} \simeq \SO^+_{n,1}/\SO^+_{n-1,1} $ (resp.  $H_{2,n-1} \simeq \SO^+_{2,n-1}/\SO^+_{1,n-1} $) is extensively studied in cosmology and quantum field theory \cite{AM84,Gazeau07}.  

On the other hand,  different choices of $G$ for the same $X$ allow us to study curves on $X$ with respect to different geometries.  Take $X = \mathbb{R}^n$ for example.  Theorem~\ref{thm:approx-lift} for $G = \SE_n(\mathbb{R})$ (cf.  item~\eqref{prop:ex-approx-lift:item2}) means any continuous loop in $\mathbb{R}^n$ can be approximately traced out by rational curves of rigid transformations,  while Theorem~\ref{thm:approx-lift} for $G = \SO^+_{p+1,n-p + 1}(\mathbb{R})$ (cf. item~\eqref{prop:ex-approx-lift:item4'}) (resp.  $G = \ISO_{n-1,1}(\mathbb{R})$ (cf. item~\eqref{prop:ex-approx-lift:item5}) implies continuous loops can be approximately traced out by rational curves of conformal (resp. spacetime preserving) transformations.
\end{remark}
