\subsection{Generalized Kempe's Universality Theorem} Let $G$ be a real linear algebraic group and let $X$ be a homogeneous $G$-variety.  Assume $x_0 \in X$ is a fixed point and $p: G \to X$ is the map $p(g) = g x_0$.  According to Lemma~\ref{lem:lifting criterion-1},  the existence of a continuous lift (in Euclidean topology) of a rational curve $\gamma: \mathbb{P}_{\mathbb{R}}^1 \to X$ passing through $x_0$ is determined by its class $[\gamma] \in \pi_1(X)$.  However,  Problem~\ref{prob:KempeProb} requires the lift to be rational.  This subsection is devoted to a discussion of the rationality of a lift,  from which we obtain a generalized Kempe's Universality Theorem.

Let $G$ be a real linear algebraic group and let $X$ be a homogeneous $G$-variety.  Assume that $x_0 \in X$ is a fixed point,  $p: G \to X$ is the map defined by $p(g) = g x_0$.  We denote  $H \coloneqq \Stab_{x_0}(G)$ and consider the following diagram
\[\begin{tikzcd}
	{\gamma^\ast G} & G \\
	{\mathbb{P}_{\mathbb{R}}^1} & X \simeq G/H
	\arrow["\theta"', from=1-1, to=2-1]
	\arrow["p", from=1-2, to=2-2]
	\arrow["s", curve={height=-12pt}, dashed, from=2-1, to=1-1]
	\arrow["\beta", dashed, from=2-1, to=1-2]
	\arrow["\gamma"', from=2-1, to=2-2]
\end{tikzcd}\]
where $\gamma$ is a rational curve on $X$ passing through $x_0$,  $\theta$ is the projection map of the principal $H$-bundle $\gamma^\ast G$ over $\mathbb{S}^1$.  Clearly,  we have 
\begin{align*}
\text{$\gamma$ has a rational lift $\beta$} &\iff \text{$\gamma^\ast G$ admits a rational section $s$} \\ 
&\iff \text{$\gamma^\ast G$ is a trivial algebraic principal $H$-bundle}.
\end{align*}
We notice that $\mathbb{P}_{\mathbb{R}}^1$ is a smooth affine curve over $\mathbb{R}$.  The lemma that follows is a direct consequence of Proposition~\ref{prop:rational triviality}. 
\begin{lemma}[Rational lifting criterion]\label{lem:lifting criterion-2}
Assume that $H$ is semisimple and simply connected.  If $\theta: \gamma^\ast G \to \mathbb{P}_{\mathbb{R}}^1$ is Zariski locally trivial,  then $\gamma$ admits a rational lift.  In particular,  if $p:G \to X$ is Zariski locally trivial,  then every rational curve on $X$ has a rational lift.
\end{lemma}
\begin{theorem}[Generalized Kempe's Universality Theorem II]\label{thm:Kempe G-space}
Let $(G,X)$ be one of the nine pairs listed in Theorem~\ref{thm:approx-lift}.  For every $\gamma\in \Rat(X,x_0)$,  there exist $\alpha_1,\dots,  \alpha_s \in \Rat(G,  I)$ such that 
\begin{enumerate}[(a)]
\item Each $ \alpha_j$only has poles at $\{c_j,\overline{c}_j\}$,  $1 \le j \le s$.  
\item If $j \ne k$ then $\{c_j,\overline{c}_j\} \ne \{c_k,\overline{c}_k\}$. 
\item $\prod_{j=1}^s \alpha(t) x_0  = \gamma(t)$.
\end{enumerate}
Here $I$ denotes the identity element in $G$.
\end{theorem}
\begin{proof}
By Theorems~\ref{thm:KempeGBF} and \ref{thm:KempeSE},  it is sufficient to prove the existence of a rational lift of $\gamma$. 

For \eqref{prop:ex-approx-lift:item4'},  we consider 
\[\begin{tikzcd}
	{\ISO^+_{p,n-p-1}(\mathbb{R})} & {\SO^+_{p+1,n-p}(\mathbb{R})} \\
	\\
	{\mathbb{P}_{\mathbb{R}}^1} & {\mathbb{R}^{n-1}}
	\arrow["j", hook, from=1-1, to=1-2]
	\arrow["{p \circ j}"', from=1-1, to=3-2]
	\arrow["p", from=1-2, to=3-2]
	\arrow["\beta", dashed, from=3-1, to=1-1]
	\arrow["\gamma", from=3-1, to=3-2]
\end{tikzcd}\]
where $j$ is the inclusion of $ \ISO^+_{p,n-p-1}(\mathbb{R})$ into $\SO^+_{p+1,n-p}(\mathbb{R})$  and $p$ is the projection map defined by the action of $\SO^+_{p+1,n-p}(\mathbb{R})$ on $\mathbb{R}^{n-1}$.  Hence it is reduced to prove \eqref{prop:ex-approx-lift:item5}.

For \eqref{prop:ex-approx-lift:item1}--\eqref{prop:ex-approx-lift:item4} and \eqref{prop:ex-approx-lift:item5},  we let $\widetilde{G}$ the universal covering of $G$.  Since $G$ in each of these cases is a semi-direct product of some $\SO^+_{p,q}$ and $\mathbb{R}^m$,  the corresponding $\widetilde{G}$ is also a semi-direct product of $\Spin_{p,q}(\mathbb{R})$  and $\mathbb{R}^m$.  In particular,  $\widetilde{G}$ is a real linear algebraic group.  Thus we may consider the following diagram.:
\[\begin{tikzcd}
	& {\widetilde{G}} \\
	& G \\
	{\mathbb{P}_{\mathbb{R}}^1} & {X \simeq G/H \simeq \widetilde{G}/\widetilde{H}}
	\arrow["\pi", from=1-2, to=2-2]
	\arrow["p", from=2-2, to=3-2]
	\arrow["{\widetilde{\beta}}", curve={height=-12pt}, dashed, from=3-1, to=1-2]
	\arrow["\beta", dashed, from=3-1, to=2-2]
	\arrow["\gamma"', from=3-1, to=3-2]
\end{tikzcd}\]
where $\pi: \widetilde{G} \to G$ is the covering map and $\widetilde{H} \coloneqq \Stab_{\widetilde{G}}(x_0)$.  Obviously,  if $\widetilde{\beta}$ is a rational lift of $\gamma$ to $\widetilde{G}$,  then $\beta \coloneqq \pi \circ \widetilde{\beta}$ is a rational lift of $\gamma$ to $G$.  Since $H$ is the product of $\SO^+_{p,q}$,  $\widetilde{H}$ is a product of $\Spin_{p,q}(\mathbb{R})$,  which is a semisimple and simply connected algebraic group.  It is straightforward to verify that $p: G \to X$ is Zariski locally trivial.  Thus,  $p \circ \pi: \widetilde{G} \to X$ is also Zariski locally trivial.  The existence of $\widetilde{\beta}$ and $\beta$ follows from Lemma~\ref{lem:lifting criterion-2}.

For \eqref{prop:ex-approx-lift:item6}--\eqref{prop:ex-approx-lift:item8},  we notice that $p: G \to X$ is Zariski locally trivial and $H$ is a semi-simple and simply connected algebraic group.  Hence Lemma~\ref{lem:lifting criterion-2} is applicable.
\end{proof}
