\section{Proof of Lemma~\ref{lem:lower triangular}}\label{append:proof of lem:lower triangular}
\begin{proof} 
We prove \eqref{lem:lower triangular:item1}--\eqref{lem:lower triangular:item6} case by case.
\begin{enumerate}[(a)]
\item We observe that $J_m(\lambda) Y + Y J_n(-\lambda) = 0$ is equivalent to $J_m(0) Y + Y J_n(0) = 0$. Thus we may assume $\lambda = 0$. Let $Y = (y_{ij})_{i,j=1}^{m,n}$. Then the equation can be written as
\[
y_{i,j+1} + y_{i-1,j} = 0.
\]
This implies that $Y$ is a lower triangular alternating Toeplitz matrix. 
\item The proof is the same as that of \eqref{lem:lower triangular:item1}.
\item If $\lambda \ne 0$ then the solution $Y = I_m + J_m(\lambda)^2/2$ is unique. If $\lambda = 0$ then we have 
\[
J_m(0) Y + Y J_m(0) = 2J_m(0)  + J_m(0)^3.
\]
We notice that a solution of this equation must have the form 
\[
Y = I_m + J_m(0)^2/2 + T,
\]
where $T$ satisfies $J_m(0) T + T J_m(0) = 0$, which is lower triangular alternating Toeplitz.
\item We write $Y = (Y_{ij})_{i,j=1}^{m\times n}$ where $Y_{ij}\in \mathbb{F}^{2\times 2}$. Then we have 
\[
\varphi(Y_{ij}) = - (Y_{i,j+1} + Y_{i-1,j}),\quad 1 \le i \le m, 1\le j \le n,
\]
where $\varphi:\mathbb{F}^{2\times 2} \to \mathbb{F}^{2\times 2}$ is the map defined by 
\[
\varphi_b(X) =b\left( \begin{bsmallmatrix}
0 & 1\\
-1 & 0
\end{bsmallmatrix} X + X \begin{bsmallmatrix}
0 & 1\\
-1 & 0
\end{bsmallmatrix} \right).
\]
Here we adopt the convention $Y_{ij} = 0$ if either $i < 1$ or $j>n$. We observe that if $b > 0$ then
\[
\varphi_b(\mathbb{F}^{2\times 2}) = \left\lbrace
\begin{bsmallmatrix}
x & y \\
-y & x
\end{bsmallmatrix}\in \mathbb{F}^{2\times 2}: x,y\in \mathbb{F}
\right\rbrace, \quad
\ker(\varphi_b) = \left\lbrace
\begin{bsmallmatrix}
x & y \\
y & -x
\end{bsmallmatrix}\in \mathbb{F}^{2\times 2}: x,y\in \mathbb{F}
\right\rbrace.
\]
If $b = 0$ then
\[
\varphi_b(\mathbb{F}^{2\times 2}) = \{0\}, \quad
\ker(\varphi_b) = \mathbb{F}^{2\times 2}.
\]
This implies $\varphi_b(\mathbb{F}^{n\times n}) \cap \ker(\varphi_b) = \{0\}$. Since $\varphi_b (Y_{1n}) = 0, \varphi_b(Y_{1,n-1}) = -Y_{1n}, \varphi_b(Y_{2n}) = - Y_{1n}$ we have $Y_{1n} = 0$ and $Y_{1,n-1}, Y_{2n}\in \ker(\varphi_b)$. By induction on $n$ and $m$, we may conclude that $Y$ is a block lower triangular alternating Toeplitz matrix.
\item The proof is similar to that of \eqref{lem:lower triangular:item2}.
\item We write $Y = (Y_{ij})_{i,j=1}^{m\times n}$ where $Y_{ij}\in \mathbb{C}^{2\times 2}$. Then we have 
\[
\varphi(Y_{ij}) = Y_{i-1,j} - Y_{i,j-1},\quad 1 \le i \le m, 1\le j \le n,
\]
where $\varphi:\mathbb{C}^{2\times 2} \to \mathbb{C}^{2\times 2}$ is the map defined by 
\[
\varphi(X) =\begin{bsmallmatrix}
a & b\\
-b & a
\end{bsmallmatrix} X + X \begin{bsmallmatrix}
a & b\\
-b & a
\end{bsmallmatrix}.
\]
Here we adopt the convention $Y_{ij} = 0$ if either $i < 1$ or $j>n$. We notice that $\varphi(\mathbb{C}^{2\times 2}) = \mathbb{C}^{2\times 2}, \ker(\varphi) = \{0\}$. This implies $\varphi(\mathbb{C}^{2\times 2}) \cap \ker(\varphi) = \{0\}$ and the rest of the proof is the same as that of \eqref{lem:lower triangular:item3}. 
\item We write $Y = (Y_{ij})_{i,j=1}^{m\times n}$ where $Y_{ij}\in \mathbb{H}^{2\times 2}$. Then we have 
\[
\varphi_{\lambda}(Y_{ij}) = Y_{i-1,j} - Y_{i,j-1},\quad 1 \le i \le m, 1\le j \le n,
\]
where $\varphi_{\lambda}:\mathbb{H}^{2\times 2} \to \mathbb{H}^{2\times 2}$ is the map defined by 
\[
\varphi_{\lambda}(X_1 + jX_2) = \left( \begin{bsmallmatrix}
\lambda & 0\\
0 & \lambda^\ast
\end{bsmallmatrix} X_1 - X_1\begin{bsmallmatrix}
\lambda^\ast & 0\\
0 & \lambda
\end{bsmallmatrix} \right) + \qj \left( \begin{bsmallmatrix}
\lambda^\ast & 0\\
0 & \lambda
\end{bsmallmatrix} X_2 - X_2\begin{bsmallmatrix}
\lambda^\ast & 0\\
0 & \lambda
\end{bsmallmatrix} \right). 
\]
Here $X_1,X_2\in \mathbb{C}^{2\times 2}$ and we adopt the convention $Y_{ij} = 0$ if either $i < 1$ or $j>n$. We notice that if $\operatorname{Im}(\lambda) > 0$
\begin{align*}
\varphi_{\lambda}(\mathbb{H}^{2\times 2}) &= \left\lbrace
\begin{bsmallmatrix}
x & 0 \\
0 & y
\end{bsmallmatrix} + \qj \begin{bsmallmatrix}
0 & z \\
w & 0
\end{bsmallmatrix}  \in \mathbb{H}^{2\times 2} : x,y,z,w \in \mathbb{C}
\right\rbrace, \\
\ker(\varphi_{\lambda}) &= \left\lbrace
\begin{bsmallmatrix}
0 & z \\
w & 0
\end{bsmallmatrix} + \qj \begin{bsmallmatrix}
x & 0 \\
0 & y
\end{bsmallmatrix}  \in \mathbb{H}^{2\times 2} : x,y,z,w \in \mathbb{C}
\right\rbrace.
\end{align*}
If $\operatorname{Im}(\lambda) = 0$ then $\varphi(\mathbb{H}^{2 \times 2}) = \{0\}$ and $\ker(\varphi) = \mathbb{H}^{2\times 2}$. This implies $\varphi(\mathbb{F}^{2 \times 2}) \cap \ker(\varphi) = \{0\}$ and the rest of the proof is the same as that of \eqref{lem:lower triangular:item3}. 
\end{enumerate}
\end{proof}

\section{Proof of Lemma~\ref{lem:Yij}}\label{append:proof lem:Yij}
\begin{proof}
We recall that \eqref{lem:block:eq1} is
\begin{align}
X_i Y_{ij} + Y_{ij} X_j &= 0, \quad i \ne j\label{lem:Yij:eq1} \\
X_i Y_{ii} + Y_{ii} X_i &= 2X_i + X_i^3. \label{lem:Yij:eq2}
\end{align}
We notice that a solution of \eqref{lem:Yij:eq2} is $Y_{ii} = I_{m_i} + X_i^2/2 + T_i$ where $T_i$ satisfies 
\begin{equation}\label{lem:Yij:eq3}
X_i T_i + T_i X_i = 0.
\end{equation}
It is straightforward to verify that $B_i^{-1} = \varepsilon B_i$ for each $1  \le i \le s$, thus \eqref{lem:block:eq2} implies 
\begin{align*}
i \ne j: Y_{ji}^\sigma &= -\varepsilon B_iY_{ij} B_j,\\
i = j: Y_{ii} &=\varepsilon ( B_i \left( (2 I_{m_i} + X_i^2) -  Y_{ii} \right) B_i)^\sigma.
\end{align*}
A direct calculation implies $\varepsilon (B_i X_i^2 B_i)^\sigma = X_i^2$. Thus, if $Y_{ii} = I_{m_i} + X_i^2/2 + T_i$ for some $T_i$ then 
\begin{equation}\label{lem:Yij:eq0} 
T_i =- \varepsilon (B_i T_i B_i)^\sigma.
\end{equation}
We also observe that $B_i^\sigma = \varepsilon B_i$.


Thus, to solve \eqref{lem:block:eq1} and \eqref{lem:block:eq2}, it is sufficient to consider the following system:
\begin{align}
X_1 Y_{12} + Y_{12} X_2 &= 0, \label{lem:Yij:eq4} \\
Y_{21} + \varepsilon (B_1 Y
_{12} B_2)^\sigma &=0. \label{lem:Yij:eq5}
\end{align}
where $(X_1,B_1), (X_2,B_2)$ are normal forms listed in Table~\ref{Tab:indecomposable} such that $0\in \rho(X_1) + \rho(X_2)$. We split the discussion with respect to the seven cases in Table~\ref{Tab:indecomposable}. 
\begin{enumerate}[No. 1:]
%% No.1 
