\ch{^{$\fp$} T}(u_1,\dots, u_{2m}) & 0 & 0 & 0
\end{bsmallmatrix}
\end{equation*}
and $Y_{21}$ is 
\begin{equation*}
-\begin{bsmallmatrix}
0 & 0 & 0 & T_{\fp} (w_1,\dots, w_{2n}) \\
\ch{^{$\fp$} T}(u_1,\dots, u_{2n}) & 0 & 0 & 0
\end{bsmallmatrix}
~\quad~\text{or}~\quad~
-\begin{bsmallmatrix}
0 & 0 \\
0 & T_{\fp} (w_1,\dots, w_{2m}) \\
\ch{^{$\fp$} T}(u_1,\dots, u_{2m}) & 0\\
0 & 0
\end{bsmallmatrix}.
\end{equation*}
In particular, if $Y_{12} = Y_{21}$ then $Y_{12} = Y_{21} = 0$.

If $\lambda = -\mu \ne 0$ then $W = U = 0$ and $Z, H_mV H_n$ are lower triangular alternating Toeplitz. Therefore $Y_{12}$ has one of the following two forms, depending on $m\ge n$ or $m < n$:
\begin{equation*}
\begin{bsmallmatrix}
0 & 0 \\
\ch{_{$\fp$} S}(z_1,\dots, z_{2n}) & 0 \\
0 & S^{\fp} (v_1,\dots, v_{2n})\\
0 & 0
\end{bsmallmatrix}
~\quad~\text{or}~\quad~
\begin{bsmallmatrix}
\ch{_{$\fp$} S}(z_1,\dots, z_{2m})  & 0 & 0 & 0\\
0& 0 & 0 & S^{\fp} (v_1,\dots, v_{2m}) 
\end{bsmallmatrix}
\]
and $Y_{21}$ is 
\begin{align*}
&-\begin{bsmallmatrix} 
\ch{_{$\fp$} S}(v_1, -v_2,\dots, v_{2n-1}, -v_{2n})  & 0 & 0 & 0\\
0& 0 & 0 & S^{\fp} (z_1, -z_2,\dots, z_{2n-1}, -z_{2n}) 
\end{bsmallmatrix}
~\quad~\text{or}~\quad~ \\
&-\begin{bsmallmatrix}
0 & 0 \\
\ch{_{$\fp$} S}(v_1, -v_2,\dots, v_{2m-1}, -v_{2m}) & 0 \\
0 & S^{\fp} (z_1, -z_2,\dots, z_{2m-1}, -z_{2m})\\
0 & 0
\end{bsmallmatrix}.
\end{align*}

If $\lambda = \mu = 0$ then $m, n$ are even, $Z, H_mV H_n$ are lower triangular alternating Toeplitz and $H_m U, WH_n$ are lower triangular Toeplitz. Thus, $Y$ has one of the following two forms, depending on $m\ge n$ or $m < n$:
\[
\begin{bsmallmatrix}
0& 0 \\
\ch{_{$\fp$} S}(z_1,\dots, z_{n})   & T_{\fp}(w_1,\dots, w_{n})\\
\ch{^{$\fp$} T}(u_1,\dots, u_{n}) & S^{\fp} (v_1,\dots, v_{n})  \\
0& 0
\end{bsmallmatrix}
~\quad~\text{or}~\quad~
\begin{bsmallmatrix}
\ch{_{$\fp$} S}(z_1,\dots, z_{m}) & 0 & 0   & T_{\fp}(w_1,\dots, w_{m})\\
\ch{^{$\fp$} T}(u_1,\dots, u_{m}) & 0 & 0 & S^{\fp} (v_1,\dots, v_{m})
\end{bsmallmatrix}.
\]
Thus $Y_{21}$ is 
\begin{align*}
&-\begin{bsmallmatrix}
\ch{_{$\fp$} S}(v_1,-v_2,\dots, v_{n-1},  -v_{n}) & 0 & 0   & T_{\fp}(w_1,\dots, w_{n})\\
\ch{^{$\fp$} T}(u_1,\dots, u_{n}) & 0 & 0 & S^{\fp} (z_1,-z_2,\dots, z_{n-1},  -z_{n})
\end{bsmallmatrix}~\quad~\text{or}~\quad~\\
&-\begin{bsmallmatrix}
0& 0 \\
\ch{_{$\fp$} S}(v_1, -v_2,\dots, v_{n-1},-v_{n})   & T_{\fp}(w_1,\dots, w_{n})\\
\ch{^{$\fp$} T}(u_1,\dots, u_{n}) & S^{\fp} (z_1, -z_2,\dots, z_{n-1}, -z_{n})  \\
0& 0
\end{bsmallmatrix}.
\end{align*}
In particular, $Y_{12} = Y_{21}$ implies 
\[
