If $Y_{12} = Y_{21}$ then $Y_{12} = Y_{21} = \ch{_{$\fp$}S}(Z_1,\dots, Z_{n})
$ where $(-1)^{m-1} (F_2^{m} Z_j F_2^{n})^\ast= Z_j$ for each $1 \le j \le n$.
%% 7.3
\item Let 
\begin{align*}
X_1  &=\left( 
\diag
\left(
J_m\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right),
-J_m\left(\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right)^\ast
\right)
\right), \\
X_2  &=\left( 
\diag
\left(
J_n \left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right),
-J_n\left(\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right)^\ast
\right)
\right),
\end{align*}
where $\lambda \in \mathbb{C}, \operatorname{Re}(\lambda) > 0, \operatorname{Im}(\lambda) \ge 0$. Then we have $(B_1,B_2) = ( I_{2m} \otimes F_2,I_{2n} \otimes F_2)$. We partition $Y\in \mathbb{H}^{4m \times 4n}$ as $Y = \begin{bsmallmatrix}
Z & W \\
U & V
\end{bsmallmatrix}$ where $Z, W, U, V\in \mathbb{H}^{2m\times 2n}$. Then \eqref{lem:Yij:eq1} becomes
\begin{align*}
J_m\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right) Z + Z J_n\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right) &= 0, \\ 
J_m\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right) W - W J_n\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right)^\ast &= 0,  \\
- J_m\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right)^\ast U + U J_n \left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right) &= 0,\\ 
J_m\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right)^\ast V + V J_n\left(
\begin{bsmallmatrix}
\lambda & 0 \\
0 & \overline{\lambda}
\end{bsmallmatrix}\right)^\ast &= 0.
\end{align*}
We conclude that $Z = V = 0$ by Lemma~\ref{lem:block} since $\lambda \ne 0$. Moreover, according to Lemma~\ref{lem:lower triangular} \eqref{lem:lower triangular:item6}, $W(I_2 \otimes H_n)$ and $(I_2 \otimes H_m)U$ are block lower triangular matrices where each block is $2\times 2$. This implies that $Y_{12}$ has one of the following two forms, depending on $m\ge n$ or $m < n$:
\[
\begin{bsmallmatrix}
0& 0 \\
0   & T_{\fp}(W_1,\dots, W_{n})\\
\ch{^{$\fp$} T}(U_1,\dots, U_{n}) & 0 \\
0& 0
\end{bsmallmatrix}
~\quad~\text{or}~\quad~
\begin{bsmallmatrix}
0& 0 & 0   & T_{\fp}(W_1,\dots, W_{m})\\
\ch{^{$\fp$} T}(U_1,\dots, U_{m}) & 0 & 0 & 0
\end{bsmallmatrix}.
\]
Thus $Y_{21}$ is 
\[
-\begin{bsmallmatrix}
0& 0 & 0   & T_{\fp}(W_1^\ast,\dots, W_{n}^\ast)\\
\ch{^{$\fp$} T}(U_1^\ast,\dots, U_{n}^\ast) & 0 & 0 & 0
\end{bsmallmatrix}
~\quad~\text{or}~\quad~
-\begin{bsmallmatrix}
0& 0 \\
0   & T_{\fp}(W_1^\ast,\dots, W_{m}^\ast)\\
\ch{^{$\fp$} T}(U_1^\ast,\dots, U_{m}^\ast) & 0 \\
0& 0
\end{bsmallmatrix}.
\]
If $Y_{12} = Y_{21}$ then $Y_{12} = Y_{21} = \begin{bsmallmatrix}
0   & T_{\fp}(W_1,\dots, W_{n})\\
\ch{^{$\fp$} T}(U_1,\dots, U_{n}) & 0 \\
\end{bsmallmatrix}$ where $U_j = -U_j^\ast$ and $W_j = -W_j^\ast$ for each $1\le j \le n$.
\end{enumerate}  
\end{enumerate}
\end{proof}
