In Appendix \ref{appendix:LinearTeo1} we discuss how to compute the order in linear time. 
Through the rest of the paper, we assume that $\skeleton$ is rooted at an internal vertex of degree at least three 
and that the procedure to sort the adjacency list of each vertex (as described in the previous proof) is applied.

\begin{definition}
\label{defi:adjnotation}
For a vertex $v \in \skeleton$ and $1 \leq i \leq \degreechildren(v)$, we denote by $\child{v}{i}$ the $i$-th children of $v$.  In addition, we denote its last children by $\child{v}{\infty}$.
\end{definition}

\begin{definition}
\label{defi:leafnotation}
For a vertex $v \in \skeleton$, we denote by $\leaf{v}{i}$ the $i$-th leaf visited in the subtree of $v$ when running a depth-first search restricted to its subtree. In addition, we denote its last leaf visited by $\leaf{v}{\infty}$.
\end{definition}

\begin{definition}
\label{defi:leaveslabel}
For each leaf $v \in \skeleton$, we define its $x$-value to be $x_v$ as in Proposition~\ref{TEO:ORDEN}.
\end{definition}

Note that considering only the leaves, the $x$-values are unique. Furthermore, the $x$-values are numbered in the direction of a traversal of $C$ so we can define the next and previous leaf of each.

\begin{definition}
\label{defi:leafNxtPrv}
For a leaf $v \in \skeleton$ with $x$-value $x_v$, we denote by $v^+$ the leaf with $x$-value $(x_v + 1) \mod |V_C|$ and with $v^-$ the leaf with $x$-value $(x_v - 1) \mod |V_C|$. 
\end{definition}

