\vspace{1em}
\noindent\textbf{\large\treeDecompAHCall{t}{v}{i}{j}}
\label{AlmostHalin1Algoritmo}

\begin{enumerate}[start=1,label={(\bfseries Step \arabic*)},leftmargin=3.5em]
    \item \label{AlmostHalin1:Step1} Create a tree $T$ with a single node $R$, whose bag is the set of representatives of $AH_t(v, i, j)$.
        \begin{itemize}
            \item If $i = j$
                \begin{itemize}[label={--}]
                    \item If $\height( \child{v}{i} ) = 0$ then go to \ref{AlmostHalin1:Step4}
                    \item Add one child $S$ to $R$ with bag $\{v, \leaf{ \child{v}{i} }{ 1}, \omega_t(v, j), \child{v}{i}\}$. Note that we include the $i$th child of $v$. 
                           \item Add one child $A$ to $S$ with bag $\{\leaf{ \child{v}{i} }{ 1}, \omega_t(v, j), \child{v}{i}\}$. 
                           \item Since $\height( \child{v}{i} ) > 0$, the graph $AH_t( \child{v}{i}, 1 ,\degreechildren(\child{v}{i}))$ is well-defined and the bag of $A$ is the set of its representatives. 
                           Append the construction of \treeDecompAHCall{t}{ \child{v}{i} }{1}{ \degreechildren(\child{v}{i}) } to $T$ identifying the node $A$ (of this call) with node $R$ (of the invoked call).
                           \item Go to \ref{AlmostHalin1:Step4}
                \end{itemize}
            \item Else ($i < j$)
                \begin{itemize}[label={--}]
                    \item Add one child $S$ to $R$ with bag $\{v, \leaf{ \child{v}{i} }{ 1}, \leaf{ \child{v}{i+1} }{ 1} , \omega_t(v, j) \}$. Note that we include the vertex $ \leaf{ \child{v}{i+1} }{ 1}$ in the bag, which is the first leaf in the subtree of the $(i+1){th}$ child of $v$; for simplicity, let us name it $x$. 
                    \item Add two children $A$ and $B$ to $S$ with bags $\{v, \leaf{ \child{v}{i} }{ 1}, x \}$ and $\{v, x, \omega_t(v, j)\}$, respectively. 
                    \item Go to \ref{AlmostHalin1:Step2}. 
                \end{itemize}
        \end{itemize}
    \item \label{AlmostHalin1:Step2}
        Since $AH_t(v, i, j)$ is well-defined, it follows that $AH_1( v, i , i)$ is also well-defined and the bag of $A$ is the set of representatives of $AH_1(v, i, i)$. Append the construction of \treeDecompAHCall{1}{v}{i}{i} to $T$, identifying the node $A$ (of this call) with node $R$ (of the invoked call). 
        Go to \ref{AlmostHalin1:Step3}.

    \item \label{AlmostHalin1:Step3}
        Since $AH_t(v, i, j)$ is well-defined and at this point $i < j$, it follows that $AH_t( v, i + 1 , j)$ is also well-defined and the bag of $B$ is the set of representatives of $AH_t(v, i + 1, j)$. Append the construction of \treeDecompAHCall{t}{v}{i+1}{j} to $T$, identifying the node $B$ (of this call) with node $R$ (of the invoked call). 
        Go to \ref{AlmostHalin1:Step4}.

    \item \label{AlmostHalin1:Step4} Return $T$
\end{enumerate}

\begin{proposition}
\label{AH-Linear}
\treeDecompAHCall{t}{v}{i}{j} finishes in linear time for any $t \in \{1, 2\}$
\end{proposition}
\begin{proof}
Since each recursive call considers at most two strictly smaller Almost Halin, the recursion will terminate. Furthermore, vertex $v$ will be considered the root of an Almost Halin in $2(j -i + 1) - 1$ calls, and each internal vertex $u$ different from $v$ will be considered the root of an Almost Halin in $2\degreechildren(u) - 1$ calls. Hence, there will be a linear amount of recursive calls and in each we make $O(1)$ operations across the three steps. Therefore, the algorithm finishes in linear time with respect to the number of vertices of $AH_t(v, i, j)$.
\end{proof}

\begin{corollary}
\label{Coro:NoCiclos}
\treeDecompAHCall{t}{v}{i}{j} does not cycle for any $t \in \{1, 2\}$
\end{corollary}

Let $\inducedGraphRecursiveCalls$ be the induced digraph of recursive calls of \treeDecompAH{}. Each vertex $\mathbcal{u}$ is a call of the algorithm and there is a directed edge $ \mathbcal{u} \to \mathbcal{v}$ when call $\mathbcal{u}$ invokes call $\mathbcal{v}$. By \hyperref[Coro:NoCiclos]{Corollary 1} $\inducedGraphRecursiveCalls$ is a directed acyclic graph.

\begin{notation}
We denote by $T(t, w, a, b)$ the set of nodes $R$, $S$, $A$, $B$ along with the edges joining them, whenever these nodes are created during the call \treeDecompAHCall{t}{w}{a}{b}.
\end{notation}

\begin{proposition}
\label{AH-TreeDecomposition}
\treeDecompAHCall{t}{v}{i}{j} computes a tree decomposition of $AH_t(v, i, j)$ of width three.
\end{proposition}
\begin{proof}
We will prove that each call to \treeDecompAH{} generates a tree decomposition of its associated Almost Halin. 
This way we will obtain that the first call computes a tree decomposition of $AH_t(v, i, j)$. 
Let us proceed by induction in a reversed topological order of $\inducedGraphRecursiveCalls$.

Note that the first vertex in the order, say $\mathbcal{u}$ associated with \treeDecompAHCall{t}{w}{a}{b}, has outdegree $0$; equivalently, 
it does not invoke any other call. Thus, the construction obtained is $T(t, w, a, b)$ and it can be explicitly 
shown that the proposition is satisfied (See Appendix \ref{appendix:BaseCase}).

Now, assume by induction that a certain prefix of vertices in the order generates a tree decomposition of its corresponding Almost Halin of width three. 
We will now show that the next vertex $\mathbcal{u}$ associated with $AH_s(w, a, b)$ (for some $s \in \{1,2\}$) also accomplishes that.
Denote by $T_{\mathbcal{u}}$ the construction obtained by $\mathbcal{u}$.
If $\mathbcal{u}$ has outdegree $0$, the result holds by the previous argument. 
If $\mathbcal{u}$ has only one dependency, the reasoning for the two dependency case can be applied with slight modifications. Thus, we assume that $\mathbcal{u}$ has outdegree $2$. 
In that case, $a < b$ and $\mathbcal{u}$ depends on the construction of $AH_1(w, a, a)$ and $AH_s(w, a + 1, b)$ (Figure \ref{fig:AlmostHalinTreeDecomposition}).
Let $\mathbcal{v}$ and $\mathbcal{w}$ be vertices of $\inducedGraphRecursiveCalls$, which represents the dependencies of $\mathbcal{u}$. 
Necessarily, both $\mathbcal{v}$ and $\mathbcal{w}$ appeared before $\mathbcal{u}$ in the order. 
By the inductive hypothesis, we assume that they generated a valid tree decomposition of its corresponding Almost Halin of width three, 
say $T_{\mathbcal{v}}$ and $T_{\mathbcal{w}}$ respectively. Since $T(s,w, a, b)$ is a tree to which we appended both $T_{\mathbcal{v}}$ and $T_{\mathbcal{w}}$ to the leaves $A$ and $B$, we find that $T_{\mathbcal{u}}$ is also a tree.

Given that the Almost Halin of both $T_{\mathbcal{v}}$ and $T_{\mathbcal{w}}$ are strictly smaller than $AH_s(w, a, b)$, all vertices included in their bags are also vertices of $AH_s(w, a, b)$. Additionally, by construction, each vertex of $AH_s(w, a, b)$ is included in at least one of $AH_1(w, a, a)$ or $AH_s(w, a + 1, b)$. Hence, $T_{\mathbcal{u}}$ satisfies \ref{condition:C1}.

Similarly, all the edges are present in one of the dependencies.
Therefore, $T_{\mathbcal{u}}$ satisfies \ref{condition:C2}.

For the last needed condition \ref{condition:C3}, consider a vertex $z$ of $AH_s(w, a, b)$. We have the following cases:
\begin{itemize}
    \item $z$ only appears in $T(s,w, a, b)$. 
        We can explicitly state that \ref{condition:C3} holds.
    \item $z$ appears in one of its dependencies and not in $T(s,w, a, b)$. 
        It will only appear in the corresponding dependency, so \ref{condition:C3} is satisfied by assumption.
    \item $z$ appears in one of its dependencies as well as in $T(s,w, a, b)$. Notice that by construction of $T(s,w, a, b)$, $z$ needs to be one of the representatives of the corresponding dependency. This means that $z$ will appear in the bag of either $A$ or $B$. Thus, the component that includes $z$ is connected.
    \item $z$ appears in both dependencies. Since $z$ is a common vertex between $AH_1(w, a, a)$ and $AH_s(w, a + 1, b)$, it follows that $z$ is either $v$ or $x$, which are representatives of the two subgraphs. By construction, both $v$ and $x$ appear in the bags of both $A$ and $B$. Thus, the component that includes $z$ is connected.
\end{itemize}
In any case, the component that includes $z$ is connected. Therefore, $T_{\mathbcal{u}}$ satisfies \ref{condition:C3}.

Thus, by the principle of mathematical induction, we conclude that each recursive call generates a tree decomposition of its associated Almost Halin. 
Therefore, at the end, we obtain a tree decomposition of $AH_t(v, i, j)$. Since each bag contains at most four vertices, the resulting tree decomposition has width three.
\end{proof}

