We identify MECs as in \cite[Alg.\ 3]{DBLP:journals/tcs/HaddadM18}
and eliminate them while preserving optimal reachability probabilities.
Our transformation is a variant of the ones in
\cite{DBLP:journals/tcs/HaddadM18}, the difference being that we give a single
transformation instead of two.
Each MEC $S_i$ is collapsed into a single state $s_i$ as sketched in \cref{fig:ecelim}.
To reflect the possibility to never exit the MEC, an additional transition to $\bad$ is added.

\begin{definition}[EC elimination]
    Let iMC \(\I= (S, s_I, \mathcal{P})\) and \(E_\I = \{S_1,
    \ldots, S_n\}\) the set of MECs with  \( S_i \cap (\good \cup \bad) = \emptyset\) for all $1 \le i \le n$.
For $s \in S$, define \( \elimstate{s} = S_i \) if $s \in S_i$ for some $S_i \in E_\I$ and \( \elimstate{s} = s \) otherwise.
The \emph{EC elimination} of \( \I \) is the iMC
    \(\mathrm{elim}(\I) = (\{ \elimstate{s} \mid s \in S \}, \elimstate{s_I}, \hat{\mathcal{P}})\),
where for $s,s' \in S$ \[
\hat{\mathcal{P}}\big(\elimstate{s}, \elimstate{s'}\big) =
\begin{cases}
[0,1] & \text{if } \elimstate{s} \in E_\I \text{, } \elimstate{s} \neq \elimstate{s'} \text{, and } \mathcal{P}\big(\elimstate{s}, \elimstate{s'}\big) \neq [0,0],\\
[0,1] & \text{if } \elimstate{s} \in E_\I \text{ and } \elimstate{s'} \cap \bad \neq \emptyset,\\
\mathcal{P}\big(s, \elimstate{s'}\big) & \text{if } \elimstate{s} \notin E_\I,\\
[0,0] & \text{otherwise.}
\end{cases}
\]
\end{definition}

%
%
%
%
%
%
%
%
%
%
%
%
%
%
%

\begin{theoremrep}
    \label{thm:imcunique}
    For any iMC \(\I\), (a)~\(elim(\I)\)'s system of equations has a unique
    solution and (b)~\(\llangle \I \rrangle = \llangle elim(\I) \rrangle\), i.e., the reachability intervals coincide.
\end{theoremrep}%
\begin{toappendix}
\begin{proofsketch}
    (a): The transformation eliminates all MECs except those in \(\good\)
    and \(\bad\), which, combined with \cref{thm:uniquefixedpoint}, leads to the
    statement.
    (b): We show that all replaced states have the same optimal probabilities and
    thus conclude the same for all other states. Suppose \(S_i\) is a MEC in
    \(\I\) and \(s_i\) its replacement in \(\I'\). We show
    \(\opt_{\M \in \MC(\I)}{\Pr}^{\M}(s' \leadsto
    \good) = \opt_{\M' \in \MC(\I')}{\Pr}^{\M'}(s_i \leadsto
    \good)\) for \(s' \in S_i\).
    For \(\opt = \min\), it is optimal to forever stay in \(S_i\) in \(\I\) and
    choose to go to \(\bad\) in \(\I'\), thus both probabilities are zero.
    For \(\opt = \max\), it is optimal to leave for the state with the largest
    probability to \(\good\) in \(\I\) and \(\I'\), thus both probabilities
    are equal to the probability for that successor state.
\end{proofsketch}
\end{toappendix}
Using EC elimination, we can thus compute optimal reachability probabilities for arbitrary iMCs.
Below, we apply this to analyze arbitrary pMCs.

\section{Generalized Parameter Lifting}
