\begin{definition}[Sub-pMC rooted in \(\hat{s}\) over \(p\)]
    \label{def:rootedpmc}
    A \emph{sub-pMC of \(\D\) rooted in \(\hat{s} \in S \) over \(p \in V\)} is a pMC \(\D_{\hat{s},p} = (\hat{S}, \hat{s},
    \hat{\mathcal{P}}, \{p\})\) such that  \(\hat{s} \in \hat{S} \subseteq S\) and
\begin{compactitem}
\item the underlying graph $\mathcal{G}_{\hat{s},p} = (\hat{S}, \{(s,t) \in \hat{S}\times\hat{S} \mid \hat{\mathcal{P}}(s,t) \neq 0\})$ is acyclic, i.e., all maximal paths end in $\hat{S}_\mathrm{exit} = \{ s \in \hat{S} \mid \hat{\mathcal{P}}(s,t) = 0 \text{ for all } t \in \hat{S}\}$,
\item every $s \in \hat{S}$ is reachable from $\hat{s}$ in $\mathcal{G}_{\hat{s},p}$, and
\item $s \notin \hat{S}_\mathrm{exit}$ implies $\hat{\mathcal{P}}(s,t) = \mathcal{P}(s,t) \in \mathbb{Q}[\{p\}]$  for all $t \in S$.
\end{compactitem}
\end{definition}
%
A sub-pMC of the pMC in \cref{fig:bigstep1} rooted in \(s_0\) over \(p\) is indicated in orange.
We have $\hat{S}_\mathrm{exit} = \{s_3,s_4,\bad\}$.
Our approach is to take \emph{shortcuts} from $s_0$ directly to $\hat{S}_\mathrm{exit}$---skipping over the intermediate states $s_1$ and $s_2$.
To this end, the outgoing transitions of $s_0$ are replaced in \cref{fig:bigstep2}.
We now fix $\D_{\hat{s},p}$ and $\hat{S}_\mathrm{exit}$ as in \cref{def:rootedpmc}.
%
\begin{definition}[Shortcut pMC]
    \label{def:shortcutpmc}
The \emph{shortcut pMC} of $\D$ and its sub-pMC \(\D_{\hat{s}, p}\) is the pMC $\ttra_\mathrm{shortcut}(\D, \D_{\hat{s},p}) = (S, s_I, \mathcal{P}_\mathrm{shortcut}, V)$,
with $\mathcal{P}_\mathrm{shortcut}(s,t) = \mathcal{P}(s,t)$ for $s,t \in S$, $s \neq \hat{s}$,
$\mathcal{P}_\mathrm{shortcut}(\hat{s},t) = 0$ for $t \notin \hat{S}_\mathrm{exit}$, and
\[
       \mathcal{P}_\mathrm{shortcut}(\hat{s},t) ~=~ {\Pr}^{\D_{\hat{s},p}}(\hat{s} \leadsto t) ~=~ { \textstyle \sum_{s_0 \dots s_n \in \mathit{Paths}(\hat{s}, t)}~ \prod_{i=1}^{n} \mathcal{P}(s_{i-1},s_i) }   \]
for $t \in \hat{S}_\mathrm{exit}$, where $\mathit{Paths}(\hat{s}, t)$ denotes the set of paths from $\hat{s}$ to $t$.
\end{definition}%
%
\noindent
The set $\mathit{Paths}(\hat{s}, t)$ for $t \in \hat{S}$ is finite as \cref{def:rootedpmc} requires $\D_{\hat{s},p}$ to be acyclic.
It follows that $\mathcal{P}_\mathrm{shortcut}(\hat{s},t) = {\Pr}^{\D_{\hat{s},p}}(\hat{s} \leadsto t)$ is a univariate polynomial over parameter $p$.
The polynomials ${\Pr}^{\D_{\hat{s},p}}(\hat{s} \leadsto t)$ for all $t \in \hat{S}$ can effectively be computed in a dynamic programming fashion by traversing the states of $\D_{\hat{s},p}$ in a topological order. 
Our implementation uses a factorized representation, cf. \cref{app:shortcutprobs}.

\begin{lemmarep}\label{lem:shortcuttightens}
$\isub_R(\ttra_\mathrm{shortcut}(\D, \D_{\hat{s},p}))$ tightens $\isub_R(\D)$ for any region $R$.
\end{lemmarep}
\begin{proof}
The two iMCs only differ at state $\hat{s}$.
For $t \in S_\mathrm{exit}$, we have $\mathcal{P}_\mathrm{shortcut}(\hat{s}, t) = \{ {\Pr}^{\D}(\hat{s} \leadsto t)[u] \mid u \in wd_\D(R)\}$.
 The claim follows as $\isub_R(\D)$ substitutes $\D$.%
\end{proof}

\subsection{Grouping Transitions}

Our approach is to iteratively apply transformations using shortcuts.
The following example suggests interleaving shortcuts with a grouping of transitions.

\begin{example}
After adding an intermediate state $s_1'$ as in \cref{fig:bigstep3}, we obtain a sub-pMC rooted in $s_1'$ over $q$.
This is a larger sub-pMC than the candidates in \cref{fig:bigstep2}.
\cref{fig:bigstep4} shows the corresponding shortcut pMC.
\end{example}

\begin{definition}[Grouped pMC]\label{def:grouping}
    Suppose we have \(\hat{s} \in S\), \(S' = \{s_1, \ldots, s_k\} \subseteq S\)
    s.t. $\mathcal{P}(\hat{s}, s_i) = g_i + c_i \cdot f$
    for some polynomials $f, g_i \in \mathbb{Q}[V]$ and factors $c_i \in \mathbb{Q}$
    with $c = \sum_{j=1}^k c_j$.
    Then for the \emph{grouped pMC}
    $\ttra_\mathrm{group}(\D,\hat{s},f) = (S \uplus \{s'\}, s_I,
    \mathcal{P}_\mathrm{group}, V)$ we have
    $\mathcal{P}_\mathrm{group}(\hat{s}, s') = c \cdot f$,
    $\mathcal{P}_\mathrm{group}(\hat{s}, s_i) = g_i$,
    $\mathcal{P}_\mathrm{group}(s', s_i) = \nicefrac{c_i}{c}$,
    $\mathcal{P}_\mathrm{group}(s', t') = 0$ for all \(t' \notin S'\), and
    $\mathcal{P}_\mathrm{group}(t, t') = \mathcal{P}(t, t')$ in all other cases.
\end{definition}

\begin{lemmarep}\label{lem:groupingtightens}
    $\isub_R(\ttra_\mathrm{group}(\D,\hat{s},f))$ tightens $\isub_R(\D)$ for any region $R$, \(f \in \mathbb{Q}[V]\).
\end{lemmarep}
\begin{proof}
Let \(\I_1 = \isub_R(\D)\) and
\(\I_2 = \isub_R(\ttra_\mathrm{group}(\D,\hat{s},f))\).
We have to prove that
$\llangle \I_2 \rrangle \subseteq \llangle \I_1 \rrangle$,
i.e.,
$\{\Pr^{\M}(s_I \leadsto \good) \mid \M \in \MC(\I_2)\}
\subseteq \{\Pr^{\M}(s_I \leadsto \good) \mid \M \in \MC(\I_1)\}$.
We consider an MC induced by \(\I_2\) and show that we can (re)construct another MC induced by \(\I_1\) with the same reachability probability.
Let \(c\), \(c_1, \ldots, c_k\) and \(y_1, \ldots, y_k\) be defined as in \cref{def:grouping}.
For \(\M \in \MC(\I_2)\),
let \(x = \mathcal{P}^\M(\hat{s}, s')\)
and \(y_i = \mathcal{P}^\M(\hat{s}, s_i)\),
then (re)construct \(\M' \in \MC(\I_1)\)
s.t. \(\mathcal{P}(\hat{s}, s_i) = y_i + c_i \cdot \nicefrac{x}{c}\).
Then, \(\Pr^{\M}(s_I \leadsto \good) = \Pr^{\M'}(s_I \leadsto \good)\).
\end{proof}
\begin{example}
    Creating shortcuts and grouping together \emph{reorders}
    parametric transitions to come before constant transitions. Consider the
    pMCs \(\D_a\) in \cref{fig:bigstep1} and \(\D_c\) in \cref{fig:bigstep3}.
    \(\D_c\) takes the \(p\)-transition before taking the constant transitions.
\end{example}
Our algorithm never changes the order in which parameters occur along a path,
because reordering parameters tends to lead to non-tightening transitions.
