\subsubsection{Angular velocity from optical flow}
The linear and angular velocity of the event camera in its local frame $\{\mathcal{E}\}$ is defined as  ${}^\mathcal{E}\vbf_e\in \mathbb{R}^3$ and  ${}^\mathcal{E}\boldsymbol{\omega}_e \mathbb{R}^3$ respectively. 
Given a static landmark point in the camera frame ${}^\mathcal{E}\pbf_l\in \mathbb{R}^3$, the following equation holds:
\begin{equation}
\label{motion_eq}
 {}^\mathcal{E}\dot{\pbf_l} = \left[{}^\mathcal{E}\boldsymbol{\omega}_e\right]_{\times}{}^\mathcal{E}{\pbf_l} + {}^\mathcal{E}\vbf_e,
\end{equation}
where $\left[{}^\mathcal{E}\pmb\omega_e\right]_\times$ is the skew-symmetric matrix associated with angular velocity vector ${}^\mathcal{E}\boldsymbol{\omega}_e\in \mathbb{R}^3$, and ${}^\mathcal{E}\vbf_e(t)\in\mathbb{R}^3$ denotes the translational velocity.
We further define ${}^\mathcal{E}\pbf_l = \lambda{\xbf}$, where $\
\pmb{x}= \begin{bmatrix}
    \pmb{u}^\top &1
\end{bmatrix}^\top$ is the homogeneous coordinate form of $\pmb{u}$, then ${}^\mathcal{E}\dot{\pbf}_l =  \dot{\lambda} {\xbf} +  \lambda\dot{ {\xbf}}$. Substitute it into (\ref{motion_eq}), we have
\begin{equation}
		\label{motion_lambda}
 \dot{\xbf} = \left[{}^\mathcal{E}\boldsymbol{\omega}_e\right]_\times \xbf +\frac{1}{\lambda} {}^\mathcal{E}\vbf_e-\frac{\dot{\lambda}}{\lambda} {\boldsymbol{x}} .
\end{equation}
multiplying  both sides of (\ref{motion_lambda}) by $\left(\left[\xbf\right]_\times {}^\mathcal{E}\boldsymbol{v}_e\right)^\top$, we have
\begin{equation}
\label{velocity_flow_constraint}
    \left(\left[\xbf\right]_\times {}^\mathcal{E}\boldsymbol{v}_e\right)^\top\dot{\xbf} + \left(\left[\xbf\right]_\times {}^\mathcal{E}\boldsymbol{v}_e\right)^\top\left[\xbf\right]_\times {}^\mathcal{E}\boldsymbol{\omega}_e=0.
\end{equation}



