\section{Proof of Lemma \ref{lemma::ET1Y2}}\label{app::appendix2}
%
%
\begin{lemma}\label{lemma::3}
	Let $X\sim\expo{\lambda}$ and $Y$ be a non-negative rv with a general distribution. Then
	\begin{equation*}
		\Pb{X>Y}=\tilde Y(\lambda),
	\end{equation*}
	where $\tilde Y(s)=\E{\ex^{-sY}}$ is the Laplace-Stieltjes Transform of $Y$.
\end{lemma}
%

%
\begin{myProof}
	\begin{align*}
		\Pb{X>Y} &= \int_0^\infty\Pb{X>y}f_Y(y)\dd y = \int_0^\infty\ex^{-\lambda y}f_Y(y)\dd y = \E{\ex^{-\lambda Y}}\qedsymbol
	\end{align*}
\end{myProof}
%

The following lemma follows from elementary properties of exponential random variables.

%
\begin{lemma}\label{lemma::5}
	Let $X_1,X_2$ be independent exponential random variables of rate $\lambda_i$, and $Z=X_2-X_1$.

	%
	\begin{enumerate}
		\item [a)] $\Pb{X_2>X_1}=\lambda_1/(\lambda_1+\lambda_2)$ (exponential version of Lemma \ref{lemma::3})
		\item [b)] Define the event $\Lambda=\{X_2>X_1\}$. Given $\Lambda$, $X_1$ and $Z$ are independent, and
		\begin{align*}
			X_1|\Lambda &\sim\expo{\lambda_1+\lambda_2}\\
			Z|\Lambda   &\sim\expo{\lambda_2}
		\end{align*}
		\item [c)] Given $\Lambda$, $X_1$ and $X_2$ are not independent, and $$X_2|\Lambda\sim\Hexp{\lambda_1,\lambda_1+\lambda_2}.$$
	\end{enumerate}
	%
\end{lemma}
%

The above results are somewhat extended in the following lemma.

%
\begin{lemma}\label{lemma::4}
	Let $X\sim\expo{\lambda}$ and $Y\sim\Hexp{\mu_1,\mu_2}$ independent random variables, $Z=Y-X$, and define the event $\Lambda=\left\{Y>X\right\}$. If $$w=\dfrac{\mu_2(\lambda+\mu_2)}{(\mu_2-\mu_1)(\lambda+\mu_1+\mu_2)},$$
	then

	%
	\begin{enumerate}
		\item[a)] $\Pb{Y>X}=\dfrac{\lambda(\lambda+\mu_1+\mu_2)}{(\lambda+\mu_1)(\lambda+\mu_2)}$
		\item[b)] the pdf of $Z|\Lambda$ is given by 
		%
		\begin{equation*}
			f_{Z|\Lambda}(z) = w\mu_1\ex^{-\mu_1 z} + (1-w)\mu_2\ex^{-\mu_2 z},
		\end{equation*}
		%

		\item[c)] the pdf of $X|\Lambda$ is

		%
		\begin{equation*}
			f_{X|\Lambda}(x)=w(\lambda+\mu_1)\ex^{-(\lambda+\mu_1)x}+(1-w)(\lambda+\mu_2)\ex^{-(\lambda+\mu_2)x},
		\end{equation*}
		%

		\item[d)] Given $\Lambda$, $Z$ and $X$ are not independent, and their joint pdf is given by

		%
		\begin{equation*}
			f_{Z,X|\Lambda}(z,x) = w\mu_1\ex^{-\mu_1 z}(\lambda+\mu_1)\ex^{-(\lambda+\mu_1)x} + (1-w)\mu_2\ex^{-\mu_2 z}(\lambda+\mu_2)\ex^{-(\lambda+\mu_2)x}.
		\end{equation*}
		%
	\end{enumerate}
	%

\end{lemma}
%

%
\begin{myProof}

	%
	\begin{enumerate}
		\item[a)] By Lemma \ref{lemma::3} as applied to hypoexponential distribution.
		\item[b)]

		%
		\begin{align*}
			\Pb{Y-X>z|\Lambda} &= \left(\Pb{Y>X}\right)^{-1}\Pb{Y>X+z}\\
			&= \dfrac{(\lambda+\mu_1)(\lambda+\mu_2)}{\lambda(\lambda+\mu_1+\mu_2)}\int_0^\infty\Pb{Y>x+z}\Pb{X=x}\dd x\\
			&= \dfrac{(\lambda+\mu_1)(\lambda+\mu_2)}{\lambda+\mu_1+\mu_2}\left(\dfrac{\mu_2}{\mu_2-\mu_1}\ex^{-\mu_1 z}\int_0^\infty\ex^{-(\lambda+\mu_1)x}\dd x - \dfrac{\mu_1}{\mu_2-\mu_1}\ex^{-\mu_2 z}\int_0^\infty\ex^{-(\lambda+\mu_2)x}\dd x \right)\\
			&=\dfrac{\mu_2(\lambda+\mu_2)}{(\mu_2-\mu_1)(\lambda+\mu_1+\mu_2)}\ex^{-\mu_1 z}-\dfrac{\mu_1(\lambda+\mu_1)}{(\mu_2-\mu_1)(\lambda+\mu_1+\mu_2)}\ex^{-\mu_2 z},\\
			\intertext{which, after differentiation, yields Lemma \ref{lemma::4}b).}
		\end{align*}
		%

		\item[c)]

		%
		\begin{align*}
			\Pb{X>x|\Lambda} &= \left(\Pb{Y>X}\right)^{-1}\Pb{X>x,Y>X}\\
			&= \dfrac{(\lambda+\mu_1)(\lambda+\mu_2)}{\lambda(\lambda+\mu_1+\mu_2)}\int_x^\infty\Pb{Y>x}\Pb{X=x}\dd x\\	
			&= \dfrac{(\lambda+\mu_1)(\lambda+\mu_2)}{\lambda+\mu_1+\mu_2}\left(\dfrac{\mu_2}{\mu_2-\mu_1}\int_x^\infty\ex^{-(\lambda+\mu_1)x}\dd x - \dfrac{\mu_1}{\mu_2-\mu_1}\int_x^\infty\ex^{-(\lambda+\mu_2)x}\dd x \right)\\
			&=\dfrac{\mu_2(\lambda+\mu_2)}{(\mu_2-\mu_1)(\lambda+\mu_1+\mu_2)}\ex^{-(\lambda+\mu_1) x}-\dfrac{\mu_1(\lambda+\mu_1)}{(\mu_2-\mu_1)(\lambda+\mu_1+\mu_2)}\ex^{-(\lambda+\mu_2) x},\\
			\intertext{which, after differentiation, yields Lemma \ref{lemma::4}c).}
		\end{align*}
		%

		\item[d)]

		%
		\begin{align*}
			\Pb{Y-X>z,X>x|\Lambda} &= \left(\Pb{Y>X}\right)^{-1}\Pb{Y>X+z,X>x}\\
			&= \dfrac{(\lambda+\mu_1)(\lambda+\mu_2)}{\lambda(\lambda+\mu_1+\mu_2)}\int_x^\infty\Pb{Y>t+z}\Pb{X=t}\dd t\\
			&= \dfrac{(\lambda+\mu_1)(\lambda+\mu_2)}{\lambda+\mu_1+\mu_2}\left(\dfrac{\mu_2}{\mu_2-\mu_1}\ex^{-\mu_1 z}\int_x^\infty\ex^{-(\lambda+\mu_1)t}\dd t - \dfrac{\mu_1}{\mu_2-\mu_1}\ex^{-\mu_2 z}\int_x^\infty\ex^{-(\lambda+\mu_2)t}\dd t \right),\\
			\intertext{which, after differentiation, yields Lemma \ref{lemma::4}d). The dependency follows from the inequality}
			& f_Z(z)f_{X|\Lambda}(x)\ne f_{Y-X,X|\Lambda}(z,x)
		\end{align*}
		%

		$\qedsymbol$
	\end{enumerate}
	%

\end{myProof}
%

%
\begin{myProof}[Lemma \ref{lemma::ET1Y2}]
	Using identity \eqref{eq::Yn_identity} with $Y_n^{(2)}$ and $Y_n^{(1)}$, the inter-departure times in the second queue can be decomposed as $$Y_n^{(2)}=S_n^{(2)}+\left(S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})^+-T_{n-1}^{(2)}\right)^+.$$ Recall that the system times in both queues are exponential, of rate $(\gamma-\lambda)$ in the first queue and rate $(\mu-\lambda)$ in the second one. Conditioning on the possible outcomes of the differences yields

	%
	\begin{align*}
		Y_n^{(2)}T_{n-1}^{(1)} &= S_n^{(2)}T_{n-1}^{(1)} + 
		\begin{cases}
			\left(S_n^{(1)}-T_{n-1}^{(2)}\right)^+T_{n-1}^{(1)}&\text{if }X_n^{(1)}<T_{n-1}^{(1)}\\
			\left(S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})-T_{n-1}^{(2)}\right)^+T_{n-1}^{(1)}&\text{if }X_n^{(1)}>T_{n-1}^{(1)}
		\end{cases}\\
		&=  S_n^{(2)}T_{n-1}^{(1)} + 
		\begin{cases}
			\left(S_n^{(1)}-T_{n-1}^{(2)}\right)T_{n-1}^{(1)}&\text{if }X_n^{(1)}<T_{n-1}^{(1)}\text{ and }S_n^{(1)}>T_{n-1}^{(2)}\\
			\left(S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})-T_{n-1}^{(2)}\right)T_{n-1}^{(1)}&\text{if }X_n^{(1)}>T_{n-1}^{(1)}\text{ and }S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})>T_{n-1}^{(2)}
		\end{cases}
	\end{align*} 
	%

	For the first case, by Lemma \ref{lemma::5}b),c)

	%
	\begin{align*}
		(S_n^{(1)}-T_{n-1}^{(2)})|S_n^{(1)}>T_{n-1}^{(2)}&\sim\expo{\gamma}\\
		T_{n-1}^{(1)}|T_{n-1}^{(1)}>X_n^{(1)} &\sim\Hexp{\gamma-\lambda,\gamma},
	\end{align*}
	%
	being also independent of each other. For the second case, 

	%
	\begin{align*}
		(X_n^{(1)}-T_{n-1}^{(1)})|X_n^{(1)}>T_{n-1}^{(1)} &\sim\expo{\lambda}\text{, by Lemma \ref{lemma::5}b)}\\
		S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})|X_n^{(1)}>T_{n-1}^{(1)} &\sim\Hexp{\gamma,\lambda}\text{, by definition}\\
		S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})-T_{n-1}^{(2)}|S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})>T_{n-1}^{(2)},X_n^{(1)}>T_{n-1}^{(1)}&\sim w\cdot\expo{\lambda}+(1-w)\cdot\expo{\gamma}\text{, by Lemma \ref{lemma::4}a)}\\
		T_{n-1}^{(1)}|X_n^{(1)}>T_{n-1}^{(1)}&\sim\expo{\gamma}\text{, by Lemma \ref{lemma::5}b)},
	\end{align*}
	%
	where $$w=\dfrac{\gamma(\gamma+\mu-\lambda)}{(\gamma-\lambda)(\gamma+\mu)}.$$ The independence between the last two also follows from Lemma \ref{lemma::5}b). All this results in

	%
	\begin{align*}
		\E{Y_n^{(2)}T_{n-1}^{(1)}} =& \ \E{S_n^{(2)}}\E{T_{n-1}^{(1)}}\\
		&+ \E{(S_n^{(1)}-T_{n-1}^{(2)})|S_n^{(1)}>T_{n-1}^{(2)}}\E{T_{n-1}^{(1)}|T_{n-1}^{(1)}>X_n^{(1)}}\Pb{S_n^{(1)}>T_{n-1}^{(2)}}\Pb{T_{n-1}^{(1)}>X_n^{(1)}}\\
		&+ \E{S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})-T_{n-1}^{(2)}|S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})>T_{n-1}^{(2)},X_n^{(1)}>T_{n-1}^{(1)}}\\
		&\quad \cdot\E{T_{n-1}^{(1)}|X_n^{(1)}>T_{n-1}^{(1)}}\Pb{S_n^{(1)}+(X_n^{(1)}-T_{n-1}^{(1)})>T_{n-1}^{(2)}|X_n^{(1)}>T_{n-1}^{(1)}}\Pb{X_n^{(1)}>T_{n-1}^{(1)}}\\
		=&\inv{\mu}\inv{\gamma-\lambda}+\inv{\gamma}\left(\inv{\gamma-\lambda}+\inv{\gamma}\right)\dfrac{\mu-\lambda}{\gamma+\mu-\lambda}\dfrac{\lambda}{\gamma}+\left(w\inv{\lambda}+(1-w)\inv{\gamma}\right)\inv{\gamma}\dfrac{(\mu-\lambda)(\gamma+\mu)}{\mu(\gamma+\mu-\lambda)}\dfrac{\gamma-\lambda}{\lambda}.
	\end{align*}
	%
	With a little algebra, this expression can be simplified to that of Lemma \ref{lemma::ET1Y2}$\qedsymbol$
\end{myProof}
%

