\section{Proof of Proposition \ref{prop::aaoi_hem1}}\label{app::appendix3}
%
%
\begin{myProof}[Proposition \ref{prop::aaoi_hem1}]
	This queue is a particular case of the G/M/1/$\infty$ queue, which has been extensively studied \cite{kleinrock:qst1,ross:ipm}. There are two main consequences of not having Poisson Process-type inputs. First, the PASTA (Poisson Arrivals See Times Averages) property is no longer available: the probability that an arrival sees the system in state $q$ is not the same as the stationary probability of the system being in state $q$. Second, since the inter-arrival times do not have the memoryless property, the residual inter-arrival times (which are also referred to here as idle times, since the server is idle during this period) and the real inter-arrival times do not have the same distribution. Finding the probability distribution of the residual inter-arrival times is another matter of interest.
	%

	Losing the PASTA property means that, to study this system, not only the number of packets is needed, but also the time elapsed since the last arrival. To overcome this problem, the system is observed at very specific instants. Let $L_k$ be the number of packets in the system \emph{just before the $k$th arrival}. Then the stationary number of jobs in the system before arrival is $L=\lim_{k\to\infty}L_k$ and, by \cite{kleinrock:qst1}, Equation (6.27),	

	%
	\begin{equation}\label{eq::hem1_Ldist}
		\Pb{L=n}=(1-\sigma)\sigma^n,\quad n=0,1,2,\ldots
	\end{equation}
	%
	where $\sigma$ is the unique root in $(0,1)$ of the following equation, that involves the Laplace-Stieltjes Transform of the inter-arrival times:

	%
	\begin{equation*}
		\sigma=\tilde X(\mu-\mu\sigma).
	\end{equation*}
	%

	For the case at hand, $\tilde X(s)=\dfrac{\lambda}{\lambda+s}\dfrac{\gamma}{\gamma+s}$ and

	%
	\begin{subequations}\label{def::sigma}
		\begin{equation}\label{def::sigma_eq1}
			\sigma=\dfrac{\lambda}{\lambda+\mu-\mu\sigma}\dfrac{\gamma}{\gamma+\mu-\mu\sigma},
		\end{equation}
		or
		\begin{equation}\label{def::sigma_eq2}
			\sigma=\dfrac{(\lambda+\gamma+\mu)-\sqrt{(\lambda+\gamma+\mu)^2-4\lambda\gamma}}{2\mu}.
		\end{equation}
	\end{subequations}
	%

	Arguing as in the M/M/1/$\infty$ queue,it can be concluded that the system times are exponentially distributed with rate ($\mu-\mu\sigma$), $T_n\sim\expo{\mu-\mu\sigma}$. Therefore, Lemma \ref{lemma::3} gives the probability

	%
	\begin{equation}\label{eq::X<T}
		\Pb{X_n<T_{n-1}} = \dfrac{\lambda}{\lambda+\mu-\mu\sigma}\dfrac{\gamma}{\gamma+\mu-\mu\sigma},
	\end{equation}
	%
	which, by Equation \eqref{def::sigma_eq1}, is equal to $\sigma$. This result can be better understood by realizing that the event $\left\{X_n>T_{n-1}\right\}$ is the same as the event $\left\{\text{the $n$th arrival finds an empty system}\right\}$, and that the probability of the latter is $1-\sigma$ by the geometrical distribution \eqref{eq::hem1_Ldist}.
	%

	Using Lemma \ref{lemma::4}a), the density of the residual inter-arrival times, defined as $$X^R_n\eqdef X_n-T_{n-1}|X_n>T_{n-1},$$ is given by

	%
	\begin{equation}\label{eq::pdf_XR_hem1}
		f_{X^R}(t) = w\lambda\ex^{-\lambda t} + (1-w)\gamma\ex^{-\gamma t},\quad w=\dfrac{\gamma(\gamma+\mu-\mu\sigma)}{(\gamma-\lambda)(\lambda+\gamma+\mu-\mu\sigma)}
	\end{equation}
	%

	By the Lindley-type identity \eqref{eq::Yn_identity} for the inter-departure times and Equation \eqref{eq::X<T}, it can be concluded that $Y_n$ is a service time with probability $\sigma$, or the sum of $S_n$ and $X^R_n$ with probability $(1-\sigma)$. With a little algebra, it can be proved that the convolution of $f_S(t)$ and $f_{X^R}(t)$ yields

	%
	\begin{equation*}
		f_{S+X^R}(t) = w\dfrac{\mu\lambda}{\mu-\lambda}\left(\ex^{-\lambda t}-\ex^{-\mu t}\right) + (1-w)\dfrac{\mu\gamma}{\mu-\gamma}\left(\ex^{-\gamma t}-\ex^{-\mu t}\right)
	\end{equation*}
	%
	which is a linear combination of $\Hexp{\lambda,\mu}$ and $\Hexp{\gamma,\mu}$ with the same weights of \eqref{eq::pdf_XR_hem1}. Hence, the density of $Y_n$ results in

	%
	\begin{subequations}
		\begin{align}
			f_Y(t) &= \sigma f_S(t) + (1-\sigma) f_{S+X^R}(t)\nonumber\\
			&= a_1\mu\ex^{-\mu t} + a_2\lambda\ex^{-\lambda t} + a_3\gamma\ex^{-\gamma t},\nonumber\\
			\intertext{with $a_2=(1-\sigma)\dfrac{w\mu}{\mu-\lambda},\ a_3=(1-\sigma)\dfrac{(1-w)\mu}{\mu-\gamma},\ a_1=1-a_2-a_3$. The first two moments are}
			\E{Y_n}  &= \dfrac{1}{\lambda} + \dfrac{1}{\gamma}\label{eq::EY_hem1}\\
			\E{Y_n^2} &= 2\left(\dfrac{1}{\gamma^2} + \dfrac{1}{\lambda^2} + \dfrac{1+\sigma}{\lambda\gamma}\right)=\E{X_n^2}+\dfrac{2\sigma}{\lambda\gamma}\label{eq::EY2_hem1}
		\end{align}
	\end{subequations}
	%

	From Lemma \ref{lemma::4}c), the joint probability of $X^R_n$ and $T^<_{n-1}\eqdef T_{n-1}|X_n>T_{n-1}$ and the expected value of their product are

	%
	\begin{align*}
		\Pb{X^R_n>x,T^<_{n-1}>t} &= w\ex^{-\lambda x-(\lambda+\mu)-\mu\sigma)t} + (1-w)\ex^{-\gamma x-(\gamma+\mu)-\mu\sigma)t}\\&\\
		\E{X^R_nT^<_{n-1}} &= \int_{x\geq0}\int_{t\geq0}\Pb{X^R_n>x,T^<_{n-1}>t} \\
		&= \dfrac{1}{\lambda(\lambda+\mu-\mu\sigma)} + \dfrac{1}{\gamma(\gamma+\mu-\mu\sigma)}
	\end{align*}
	%

	Thus, the expected value of the product $Y_nT_{n-1}$ is given by

	%
	\begin{align}\label{eq::EYT_hem1}
		\E{Y_nT_{n-1}} &= \E{S_n}\E{T_{n-1}} + (1-\sigma)\E{X^R_nT^<_{n-1}}\nonumber\\
		&= \dfrac{1}{\mu}\left(\dfrac{1}{\gamma}+\dfrac{1}{\lambda}-\dfrac{1}{\mu}\right) + \dfrac{\sigma}{\mu}\left(\dfrac{1}{\gamma}+\dfrac{1}{\lambda}-\dfrac{1}{\mu-\mu\sigma}\right).
	\end{align}
	%

	Plugging equations \eqref{eq::EY_hem1}, \eqref{eq::EY2_hem1} and \eqref{eq::EYT_hem1} into the definition of the AAoI

	%
	\begin{equation*}
		\Delta_{HE/M/1/\infty} = \dfrac{\E{Y_n^2}/2 + \E{Y_nT_{n-1}}}{\E{Y_n}}
	\end{equation*}
	%
	yields Proposition \ref{prop::aaoi_hem1}$\qedsymbol$
\end{myProof}
%

