\section{Proof of Theorem \ref{thm::rq_solution}}\label{app::appendix4}
%
%
The steady-state solutions for this system can be obtained following the same procedure as in \cite[Section 3.5.1]{gross:fqt}. Let $p_{i,n}$ be the probability that the system is in state $(i,n)$. From the flow diagram of Figure \ref{fig::retrial_diag}, we can derive the balance equations for this system:

%
\begin{subequations}
	\begin{align}
		\lambda p_{0,0} &= \mu p_{1,0}\label{eq::baleq00}\\
		(\lambda+\theta) p_{0,n} &= \mu p_{1,n},\qquad {n\geq1}\label{eq::baleq0n}\\
		(\lambda+\mu)p_{1,0} &= \phantom{\lambda p_{1,n-1} +}\lambda p_{0,0} + \theta p_{0,1}\label{eq::baleq10}\\
		(\lambda+\mu)p_{1,n} &= \lambda p_{1,n-1} + \lambda p_{0,n} + \theta p_{0,n+1}\label{eq::baleq1n},\quad n\geq1
	\end{align}
\end{subequations} 
%

Define the partial Probability Generating Functions (PGF) 
$$P_0(z)=\sum\limits_{n=0}^\infty p_{0,n}z^n,\qquad P_1(z)=\sum\limits_{n=0}^\infty p_{1,n}z^n,$$
and recall that $p_{i,n}$ is the coefficient of $z^n$ in $P_i(z)$ and  $P_0(1)+P_1(1)=1$. Multiply \ref{eq::baleq0n} by $z^n$, sum over $n\geq 1$, and add \ref{eq::baleq00}:

%
\begin{subequations}\label{eq::pgf_eq_system}
	\begin{equation}\label{eq::pgf_eq1}
		(\lambda+\theta)P_0(z) - \theta p_{0,0} = \mu P_1(z).
	\end{equation}
	Doing the same with equations \ref{eq::baleq1n} and \ref{eq::baleq10}:
	\begin{equation}\label{eq::pgf_eq2}
		(\lambda+\mu-\lambda z)P_1(z) = (\lambda+\theta/z)P_0(z) - \theta p_{0,0}/z.
	\end{equation}
	On the other hand, by induction it can be shown that $\lambda p_{1,n} = \theta p_{0,n+1},\ n\geq 0$, which gives another relationship between PGF's:
	\begin{equation}\label{eq::pgf_eq3}
		\lambda P_1(z) = \theta P_0(z)/z - \theta p_{0,0}/z.
	\end{equation}
\end{subequations}
%

Let $P_i(1)=\sum\limits_{n=0}^\infty p_{i,n}=p_i,\ i=0,1$. Evaluating \eqref{eq::pgf_eq1} (or \eqref{eq::pgf_eq2}) and \eqref{eq::pgf_eq3} in $z=1$ yields

%
\begin{subequations}
	\begin{align}
		(\lambda+\theta)p_0 - \theta p_{0,0} &= \mu p_1\label{eq::peq1}\\
		\theta p_0 - \theta p_{0,0} &= \lambda p_1\label{eq::peq2}.
	\end{align}
\end{subequations}
%

This system results in $\lambda p_0 = (\mu-\lambda)p_1$, which together with $p_0+p_1=1$ finally gives the solutions

%
\begin{equation}\label{eq::server_ss_probs}
	p_1=\lambda/\mu\eqdef\rho,\qquad p_0=1-\rho.
\end{equation}
%

Define the probability that an update comes from the orbit, provided that it is non-empty, as $\pi=\theta/(\lambda+\theta)$. Using \eqref{eq::peq2} and solving for $p_{0,0}$ gives,

%
\begin{equation*}
	p_{0,0} = p_0-\lambda p_1/\theta = 1 - \rho/\pi.
\end{equation*}
%
Note that $\pi>\rho$ must hold. This can be regarded as a stability condition for this system. Substituting \eqref{eq::pgf_eq3} in \eqref{eq::pgf_eq2}, and \eqref{eq::p00} in \eqref{eq::pgf_eq1} yields

%
\begin{align*}
	P_1(z) &= \dfrac{\rho}{1-\rho z}P_0(z)\\
	P_1(z) &= \dfrac{\rho}{1-\pi}P_0(z) + \dfrac{\rho(\pi-\rho)}{1-\pi}.
\end{align*}
%

Equating both expressions and solving for $P_0(z)$ yields

%
\begin{equation*}
	P_0(z) = (\pi-\rho)\dfrac{1-\rho z}{\pi-\rho z} = (\pi-\rho) + \dfrac{(\pi-\rho)(1-\pi)}{\pi-\rho z},
\end{equation*}
%
and solving for $P_1(z)$ gives 

%
\begin{equation*}
	P_1(z) = \dfrac{\rho(\pi-\rho)}{\pi-\rho z}.
\end{equation*}
%

Given that $\dfrac{1}{1-\rho z/\pi}=\sum\limits_{n=0}^\infty(\rho/\pi)^nz^n$ for $|z|<\pi/\rho$, the proof is complete $\qedsymbol$
\end{document}

