\subsection{Definition of the Graph Metrics}
\label{sec:graph_metrics}
\paragraph{Mean Degree:} 
The mean degree of a graph is the mean total degree of each node $i$:
\begin{equation}
k_i=\sum_{j\in N}a_{ij}.
\end{equation}

\paragraph{Efficiency:}
\begin{equation}E=\frac{1}{n}\sum_{i\in N}E_i=\frac{1}{n}\sum_{i\in N}\frac{\sum_{j\in N,j\neq i}d_{ij}^{-1}}{n-1},\end{equation}
where $E_i$ is the efficiency of node $i$. Directed global efficiency is defined as:
\begin{equation}E^{\rightarrow}=\frac{1}{n}\sum_{i\in N}\frac{\sum_{j\in N,j\neq i}\left(d_{ij}\right)^{-1}}{n-1}.\end{equation}

\paragraph{Clustering coefficient:}
\begin{equation}C=\frac{1}{n}\sum_{i\in N}C_i=\frac{1}{n}\sum_{i\in N}\frac{2t_i}{k_i(k_i-1)},\end{equation}
where $C_i$ is the clustering coefficient of node $i(C_i=0$ \text{for} $k_i<2)$. Directed clustering coefficient is defined as:
\begin{equation}C^\to=\frac{1}{n}\sum_{i\in N}\frac{t_i}{\left(k_i^\mathrm{out}+k_i^\mathrm{in}\right)\left(k_i^\mathrm{out}+k_i^\mathrm{in}-1\right)-2\sum_{j\in N}a_{ij}a_{ji}}.\end{equation}

\paragraph{Transitivity of the network}:
\begin{equation}T=\frac{\sum_{i\in N}2t_i}{\sum_{i\in N}k_i(k_i-1)},\end{equation}
Directed transitivity is defined as:
\begin{equation}T^{\to}=\frac{\sum_{i\in N}t_{i}^{\to}}{\sum_{i\in N}[(k_{i}^{\mathrm{out}}+k_{i}^{\mathrm{in}})(k_{i}^{\mathrm{out}}+k_{i}^{\mathrm{in}}-1)-2\sum_{j\in N}a_{ij}a_{ji}]}.\end{equation}

\paragraph{Modularity:}
\begin{equation}Q=\sum_{u\in M}\left[e_{uu}-\left(\sum_{v\in M}e_{uv}\right)^2\right], \end{equation}
where the network is fully subdivided into a set of non-overlapping modules $M$, and $e_{uv}$ is the proportion of all links that connect nodes in module $u$ with 
nodes in module $v$.

Directed modularity is defined as:
\begin{equation}Q^\to=\frac{1}{l}\sum_{i,j\in N}\left[a_{ij}-\frac{k_i^\mathrm{out}k_i^\mathrm{in}}{l}\right]\delta_{m_i,m_j}.\end{equation}


