\subsection{MCMC Sampling Details}
\label{sec:mcmc_details}
For features $\mathbf{z^*}=(z_1, ..., z_{32})$, we first normalize it to zero-mean and unit-variance $\mathbf{z}$. Then we fit a linear regression model from the 32-dimensional feature to the percentile of certain property, for example, mean degree. Denote the linear regression model as:
\begin{equation}
    y=f(\mathbf{z})=\mathbf{w}^T\mathbf{z}+b
\end{equation}
We rewrite the LTD function as:
\begin{equation}
    LTD(\mathbf{z}) = 
\begin{cases}
  w\text{log}p(\textbf{z}) & \text{if } \mathbf{z}\in \Omega_\mathcal{T}\\
  -\infty & \text{else }  \\
\end{cases}
\end{equation}

where $p(\textbf{z})$ is estimated by fitting a multivariate Gaussian distribution according to the correlations between dimensions of the normalized latent vectors:
\begin{equation}f(\mathbf{x};\boldsymbol{\mu},\boldsymbol{\Sigma})=\frac{1}{\sqrt{(2\pi)^{D}|\boldsymbol{\Sigma}|}}\exp\left(-\frac{1}{2}(\mathbf{x}-\boldsymbol{\mu})^{T}\boldsymbol{\Sigma}^{-1}(\mathbf{x}-\boldsymbol{\mu})\right)\end{equation}
and $w=\displaystyle\frac{1}{\tau}$ is the weight to control the degree how the sampled points concentrated around the high density area of the latent space. 
Let the target value to be $t$
We find the initial feasible point $\mathbf{z_0}$ by equation:
\begin{equation}
    k = \displaystyle \frac{t-\bar y}{|\mathbf{w}|^2},
\end{equation}
\begin{equation}
    \mathbf{z_0}=k\mathbf{w}.
\end{equation}
This point must satisfy the condition $|f(\mathbf{z})-t|<\epsilon$ because the linear regression plane pass the center point of the dataset, where $\mathbf{z}=\mathbf{0}$ and $y=\bar y$.

From this initial feasible solution, we run the Metropolis-Hastings Algorithm:

\begin{algorithm}
\caption{Metropolis-Hastings Algorithm}
\label{alg:1}
\begin{algorithmic}[1]
\State \textbf{Input:} 
\State \quad $t$: Target value;
\State \quad $\mathbf{z_0}$: Initial feasible point;
\State \quad $\text{Samples}$: The list of sampled points, initialized as an empty list;
\State \quad $\mathbf{\Sigma}, \mathbf{\mu}$: The covariance matrix and mean vector of the fitted multivariate Gaussian distribution;
\State \quad $f(\mathbf{z})$: Linear regression function;
\State \quad $w$: Prior probability weight;
\State \quad $\sigma$: Proposal standard deviation;
\State \quad $N$: Total sample number;
\State \quad $burn$: burn in round;
\State \quad $thin$: Sampling interval.

\State \textbf{Output:} A list of sampled latent vectors: $\mathbf{z}_0, ..., \mathbf{z}_N$.
\Statex
\State $c=\mathbf{x}_0$
\State $\text{Samples}.append(c)$
\State $\text{total iteration} = burn + N * thin$
\For{$i = 1$ \textbf{to} $\text{total iteration}$}
    \State Propose a new point $c'$ by disturbing $c$ a small step: $c'\sim \mathcal{N}(c, \sigma^2)$
    \State $\text{log acceptance ratio}=\text{LTD}(c')-\text{LTD}(c)$
    \State $r \sim \mathcal{N}(0, 1)$
    \If {$\text{log}r<\text{log acceptance ratio}$}
        $c=c'$
    \EndIf
    \If {$i \geq burn$ and $(i-burn) \text{ mod } thin==0$}
        \State $\text{Samples}.append(c)$
    \EndIf
\EndFor
\State \Return $\text{Samples}$
\end{algorithmic}
\end{algorithm}

