Observe that $G_1 = C_8^{\set{1,4}}$, and destroying any vertex yields a bipartite graph, and so $r_+(G_1)=1$. Next, $G_2$ (the $3$-cube) and $G_3$ ($K_{4,4}$) are both bipartite and thus have $\LS_+$-rank $0$. $G_4$ is  obtained from joining two disjoint copies of $K_4$ with a perfect matching, and thus is a perfect graph, which implies that $r_+(G_4) = 1$. This leaves us with $G_5$, which is the graph $G \ce G_{\ref{figVertexTransitive234},1}$ from Figure~\ref{figVertexTransitive234}. There are several ways to show that $r_+(G) \geq 2$:
\begin{itemize}
\item
An $\LS_+$ certificate package~\cite{AuT25data} shows that $\frac{4}{15} \bar{e} \in \LS_+(G)$, which implies that $\a_{\LS_+}(G) \geq \frac{32}{15} > \a(G) = 2$. Thus, $r_+(G) \geq 2$.
\item
Let $A(\overline{G})$ be the adjacency matrix of the complement graph of $G$, let $d \ce \frac{\sqrt{2}+4}{8(\sqrt{2}+1)}$, and let $Y \ce \begin{bmatrix} 1 & d \bar{e}^{\top} \\ d \bar{e} & d I_8 + \frac{d}{\sqrt{2}+1} A(\overline{G}) \end{bmatrix}$. Then one can check that $Y \in \widehat{\LS}_+(G)$ (see, for instance,~\cite[Proposition 4]{AuLT22} for a more detailed analysis for the $\LS_+$ certificates for regular graphs and some vertex-transitive graphs). This shows that $\a_{\LS_+}(G) \geq 8d \approx 2.24 > \a(G)$. 
\item
Observe that $G - \set{1,3}$ is isomorphic to $G_{\ref{figKnownEG},2}$. Since $G$ contains an induced subgraph with $\LS_+$-rank $2$, $r_+(G) \geq 2$.
\end{itemize}
Finally, since $|V(G)| = 8, r_+(G) \leq 2$ (by Theorem~\ref{thmLiptakT031}). It thus follows that $r_+(G) =2$.
\end{proof}

We remark that, for $n=9$, there is also exactly one vertex-transitive graph with $\LS_+$-rank $2$: $C_{9}^{\set{1,2}}$ (which contains $G_{\ref{figKnownEG},1}$ as an induced subgraph). The other two graphs which satisfy the criterion in Lemma~\ref{lemnkl} are $C_{9}^{\set{1,3}}$ and the Paley graph on $9$ vertices, both of which would result in a bipartite graph upon the destruction of any vertex.

Next, we remark that while $\a_{\LS_+^{\ell}}(G) > \a(G)$ implies $r_+(G) > \ell$, the converse is not true. Before we describe such an example, we first prove a more general result.

\begin{proposition}\label{prop11}
Suppose $G$ is a graph with $n$ vertices and $\deg(i) \geq k$ for every vertex $i \in V(G)$. Then
\begin{itemize}
\item[(i)]
\[
\alpha_{\LS_+}(G) \leq n-k.
\]
\item[(ii)]
Moreover, if $\max\set{ \bar{e}^{\top}x : x \in \FRAC(G \ominus i)} \leq \frac{1}{2} |V(G\ominus i)|$ for every vertex $i \in V(G)$, then
\[
\alpha_{\LS_+}(G) \leq \frac{n-k+1}{2}.
\]
\end{itemize}
\end{proposition}

\begin{proof}
Let $Y \ce \begin{bmatrix} 1& x^{\top} \\ x & \tn{Diag}(x) + M \end{bmatrix}$ be a certificate matrix in $\widehat{\LS}_+(G)$. Then $Y \succeq 0$, and thus the Schur complement $\Diag(x) + M - xx^{\top}$ is also positive semidefinite. Hence,
\[
\bar{e}^{\top} ( \tn{Diag}(x) + M - xx^{\top}) \bar{e} = \bar{e}^{\top}x - (\bar{e}^{\top}x)^2 + \bar{e}^{\top}M\bar{e} \geq 0.
\]
Next, notice that since $Ye_0 = \diag(Y)$, $M[i,i] = 0$ for every $i \in V(G)$. Also, $M[i,j] = 0$ for all edges $\set{i,j} \in E(G)$. Thus, for every $i \in V(G)$, $Me_i$ must contain at most $n-\deg(i)-1 \leq n-k-1$ positive entries, each being at most $x_i$. Applying this for every $i \in V(G)$ yields $\bar{e}^{\top}M\bar{e} \leq (n-k-1)\bar{e}^{\top}x$. This gives $\bar{e}^{\top}x \leq n-k$.

For (ii), the additional assumption assures that $Me_i \leq \frac{n-k-1}{2} x_i$, and so $\bar{e}^{\top}M\bar{e} \leq \frac{n-k-1}{2} \bar{e}^{\top}x$, leading to the tighter bound $\bar{e}^{\top}x \leq \frac{n-k+1}{2}$.
\end{proof}


