\subsection{Algebras}
%We continue with some general notions from universal algebra. 
A \emph{functional signature} is a signature $\tau$ which only contains function symbols and no relation symbols. In this case, 
a $\tau$-structure $\fA$ is also called a \emph{$\tau$-algebra}. 
In this case, substructures of $\fA$ 
are also called \emph{subalgebras} of $\fB$; we then write $A \leq \fB$ (and $\fA \leq \fB)$. The smallest subalgebra of $\fB$ which contains $A \subseteq B$ is called the \emph{subalgebra of $\fB$ generated by $A$}. 

We write 
$\Inv(\fA)$ for the set of all \emph{invariant} relations $R \subseteq A^k$, for some $k \in {\mathbb N}$, i.e., if $t_1,\dots,t_k \in R$ and $f \in \tau$ has arity $k$, then $f^{\fA}(t_1,\dots,t_k) \in R$.
Note that this is precisely the case when $R \leq \fA^k$. 
In this case we also say that $f^{\fA}$ \emph{preserves} $R$,
and that $R$ is \emph{compatible} with $f^{\fB}$. 


If $t := t(x_1,\dots,x_n)$ is a $\tau$-term (as in first-order logic (we refer to~\cite{Hodges}) over the variables $x_1,\dots,x_n$,
and $\bA$ is a $\tau$-structure, 
then the \emph{term operation} 
is defined to be the operation 
$t^{\fA} \colon A^k \to A$ 
where $(a_1,\dots,a_k) \in A^k$
is mapped to the element of $A$ obtained by evaluating $t$ at $(a_1,\dots,a_k)$ in the usual way. 
The set of all term operations of 
$\fA$ is a \emph{clone}, i.e., it is closed under composition 
and contains the projections, and it is denoted by $\Clo(\fA)$. 


If $t_1(x_1,\dots,x_k),\dots,t_k(x_1,\dots,x_k)$ are $\tau$-terms over the common variables $x_1,\dots,x_k$, then we write
$\fA \models t_1 \approx \cdots \approx t_k$ if 
$t_1^{\fA}(a_1,\dots,a_k) = \cdots = t_k^{\fA}(a_1,\dots,a_k)$ for all $a_1,\dots,a_k \in A$, and say that
$\fA$ \emph{satisfies} the identity $t_1 \approx \cdots \approx t_k$. 
For example, $({\mathbb Z_2};+) \models x+x+y \approx y+x+x$. 
The following identities are important for this article. 
\begin{align*}
    m(x,x,y) & \approx m(y,x,x) \approx y &&  \text{($m$ is a Maltsev operation)} \\
    f(x,x,y) & \approx f(x,y,x) \approx f(y,x,x) \approx y &&
    \text{($f$ is a minority operation)} \\
    g(x,x,y) & \approx g(x,y,x) \approx g(y,x,x) \approx y && \text{($g$ is a majority  operation).}
\end{align*}



A \emph{polymorphism} of a relational structure $\bA$ is an operation $f \colon A^k \to A$, for some $k \geq 1$, which preserves all relations of $\bA$. In other words, it is a homomorphism from $\bA^k$ to $\bA$. 
The set of all polymorphisms of $\bA$ is denoted by $\Pol(\bA)$; it is easy to see that $\Pol(\bA)$ is a clone as well. 
Previously, we have defined $\Inv(\bA)$ for an algebra $\bA$; we also use the same notation $\Inv({\mathcal F})$ 
if ${\mathcal F}$ is a set of operations on a set $A$, and we write
$\Inv({\mathcal F})$ 
for the set of all relations on $A$ that are preserved by all operations from ${\mathcal F}$. Note that
$\Inv(\bA) = \Inv(\Clo(\bA))$. 
%If
%${\mathcal F}$ is a set of operations on a set $A$, then we write
%$\Inv({\mathcal F})$ 
%for the set of all relations on $A$ that are preserved by all operations from ${\mathcal F}$. 
We need the following fundamental fact. 


\begin{theorem}[\cite{Geiger,BoKaKoRo}]\label{thm:inv-pol}
    Let $\bA$ be a finite relational structure.
    Then a relation is primitively positively definable in $\bA$ if and only if it is preserved by all polymorphisms of $\bA$. 
\end{theorem}


