\begin{lemma}\label{lem:brady1ishsimple}
    Let $n \geq 1$. The following statements about $\mathbf{P}_n$ hold.
    \begin{enumerate}
    \item The following relations belong to $\Inv(\mathbf{P}_n)$:
    \begin{enumerate}
        \item all unary relations $X \subseteq \{0, \dots, n-1\}$,
        \item all bijection graphs $G \subseteq n^2$, and 
        \item $L = \{ (x,y,z) \in \{0,1\}^3 : \text{$(x,y,z)$ is a solution to the $\mathbb{Z}_2$-linear equation $x+ y+ z = 1$}\}$.
    \end{enumerate}
    \item $\mathbf{P}_n$ is \emph{hereditarily simple}, i.e., each subalgebra of $\mathbf{P}_n$ has exactly two congruences: the equality relation and the full relation. 
    \end{enumerate}

\end{lemma}
\begin{proof}
    Item \emph{1.} can be easily checked by the reader. To see \emph{2.}, let $\mathbf{B} \leq \mathbf{P}_n$. 
