\begin{definition}\label{def:listofdifferentinstances(k=0also)}
Let $n \geq 2$ and $k \geq 0$.
\begin{enumerate}
    \item Given a collection of instances $\mathfrak{I}_1, \dots, \mathfrak{I}_l$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}_1 \cup \dots \cup \mathfrak{I}_l$ the instance of $\Csp(\mathfrak{P}^{n,k})$ with domain $I_1 \cup \dots \cup I_l$ and constraints the union of the constraints of the $\mathfrak{I}_1, \dots, \mathfrak{I}_l$. 

    \item Given an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ and a subset $M \subseteq I$, we denote by $\mathfrak{M}$ the \emph{induced subinstance} of $\mathfrak{I}$, which we define as the induced $\tau_{n,k}$-substructure of $\mathfrak{I}$ with domain $M$.

    \item We say an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ is \emph{concise} if for each $x \in I$, there is exactly one unary symbol $\rho \in \tau_{n,1}^{U,1}$ that constrains $x$ (i.e.,  $\Sup_1^\mathfrak{I} = I$ and $|\Cons^\mathfrak{I}(x)| = 1$ for each $x \in I$). Given an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}^C$ the instance with domain $I$ so that $\rho^{\mathfrak{I}^C} = \rho^{\mathfrak{I}}$ for every binary or ternary symbol $\rho \in \tau_{n,k}$, and $\Cons^{\mathfrak{I}^C}(x) = \{\lambda\}$, where $\lambda \in \tau_{n,k}$ is such that 
    \[
    \lambda^{\mathfrak{P}^{n,k}} = P^{n,k} \cap \left(\bigcap_{\rho \in \Cons^{\mathfrak{I}}(x)} \rho^{\mathfrak{P}^{n,k}}\right).
    \]

    \item We say an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ is a \emph{uniform instance} if it only contains constraints named by $\tau^U_{n,k}$ symbols. Given an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}^U$ the \emph{uniform reduct} of $\mathfrak{I}$, which has domain $I$ but only contains those constraints from $\mathfrak{I}$ that are named by $\tau_{n,k}^U$ symbols. 
\item We say an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ is a \emph{nonuinform instance} if it only contains constraints named by $\tau^N_{n,k}$ symbols. Given an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}^N$ the \emph{nonuniform reduct} of $\mathfrak{I}$, which has domain $I$ but only contains those constraints from $\mathfrak{I}$ that are named by $\tau_{n,k}^N$ symbols. 
\end{enumerate}
\end{definition}




 One of the main structural features of a $\Csp(\mathfrak{P}^{n,k+1})$-instance $\mathfrak{I}$ that is used to reduce it to an instance of $\Csp(\mathfrak{P}^{n,k})$ is the decomposition into connected components of $I$ with respect to the uniform relations. 


\begin{definition}\label{def:components}
Let $n \geq 2$ and $k \geq 0$. Let $\mathfrak{I}$ be an instance of $\Csp(\mathfrak{P}^{n,k})$. We define the \emph{connectivity graph} of $\mathfrak{I}$ to be the undirected graph with underlying set $I$ and edge set equal to the union the following sets:
\begin{itemize}
    \item $\{ (x,y) : \text{there exists binary $\rho \in \tau_{n,k}$ such that } (x,y) \in \rho^\mathfrak{I} \}$
    \item $\{(x,y) :\text{there exists ternary $\rho \in \tau_{n,k}$ and $z \in I$ such that } (x,y,z), (x,z,y), \text{or } (z,x,y) \in \rho^\mathfrak{I} \} $
\end{itemize}
 A \emph{connected component} of $\mathfrak{I}$ is a connected component of the connectivity graph of $\mathfrak{I}$. A \emph{uniform connected component} of $\mathfrak{I}$ is a connected component of $\mathfrak{I}^U$. Suppose that $(x,y) \in (T^{n,k}_{0,k-1})^\mathfrak{I}$. In this situation we call $x$ a \emph{transfer source variable} and $y$ a \emph{transfer target variable}. We call any uniform connected component containing a transfer source variable a \emph{transfer source} component. 
 \end{definition}

 We adopt the following convention for listing the uniform connected components of a $\Csp(\mathfrak{P}^{n,k})$ instance $\mathfrak{I}$.  The transfer source components and the other uniform connected components will be enumerated separately, with the transfer source components listed first. Specifically, if we say that $S_1, \dots, S_r, M_1, \dots, M_v$ are the uniform connected components of $\mathfrak{I}$, we mean that $S_1, \dots, S_r$ are exactly the transfer source components.
 %\todo{Problem: not monotone step}

\begin{definition}\label{def:innerouterinstances+targetcompatible}
Let $n \geq 2$ and $k \geq 1$.
\begin{enumerate}

\item Given a uniform instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}^{(0)}$ the \emph{inner restriction} of $\mathfrak{I}$, which is the following instance of $\Csp(\mathfrak{P}^{n,k-1})$:
\begin{itemize}
    \item The domain of $\mathfrak{I}^{(0)}$ is denoted $I^{(0)}$ and is equal to $I$.
    \item $\rho^{\mathfrak{I}^{(0)}} = \bigcup_{\lambda \in \tau_{O_n}} (\rho, \lambda)^\mathfrak{I} $, for each $\rho \in \tau_{n,k-1}$.

\end{itemize}


\item Given a uniform instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}^{ \lnot (0)}$ the \emph{outer restriction} of $\mathfrak{I}$, which is the following instance of $\Csp(\mathfrak{O}_n)$:
\begin{itemize}
    \item The domain of $\mathfrak{I}^{\lnot (0)}$  is denoted $I^{\lnot(0)}$ and is equal to $I$.
    \item $\lambda^{\mathfrak{I}^{(0)}} = \bigcup_{\rho \in \tau_{n,k-1}} (\rho, \lambda)^\mathfrak{I} $, for each $\lambda \in \tau_{O_n}$.
\end{itemize}

\item We say that an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ is \emph{transfer target compatible} if for every transfer target variable $y$, there is a unary symbol $\rho \in \tau_{n,k}$ with $\rho^{\mathfrak{P}^{n,k}} \subseteq P^{n,k}_{k-1}$ and $y \in \rho^\mathfrak{I}$. Given an instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$, we denote by $\mathfrak{I}^*$ the instance obtained from $\mathfrak{I}$ by asserting for all transfer target variables $y$ the extra unary constraint $y \in \lambda^\mathfrak{I}$, where 
\[
\lambda = ( (\dots ((R_{\{\epsilon\}}, R_\emptyset), R_{O_n}), \dots, R_{O_n}),R_{O_n}) \in \tau_{n,k}
\]
is the symbol naming $P^{n.k}_{k-1} \subseteq P^{n,k}$.
\end{enumerate}
\end{definition}

\begin{lemma}\label{lem:uniformsolutionssplit}
    Let $n \geq 2$ and $k \geq 1$. Let $\mathfrak{I}$ be a uniform instance of $\Csp(\mathfrak{P}^{n,k})$ with only one uniform connected component.  Then, every solution $s$ of $\mathfrak{I}$ satisfies exactly one of the following:
    \begin{enumerate}
    \item  $s(x) \in P^{n,k}_0$  for all $x \in I$, which is the case if and only if $(\psi^{n,k}_0)^{-1}\circ s$ is a solution of the inner restriction $\mathfrak{I}^{(0)}$.
    \item $s(x) \in  O_n$ for all $x \in I$, which is the case if and only if $s$ is a solution of the outer restriction $\mathfrak{I}^{\lnot (0) }$.

\end{enumerate}

\end{lemma}
\begin{proof}
    Let $\mathfrak{I}$ be such an instance and let $s \colon I \to P^{n,k}$ be a solution of $\mathfrak{I}$. We show that either $s(x) \in P^{n,k}_0$ for all $x \in I$, or $s(x) \notin P^{n,k}_0$ for all $x \in I$. Indeed, since $s$ is a solution, one of these cases must hold for some $y \in I$, suppose it holds that $s(y) \in P^{n,k}_0$. Now let $z \in I$ be connected to $y$ by a binary or ternary $\tau^U_{n,k}$ relation, for example, suppose $(y,z)\in (\rho_1, \rho_2)^\mathfrak{I}$. Since there are no edges that connect $P^{n,k}_0$ to $O_n$ in $(\rho_1, \rho_2)^{\mathfrak{P^{n,k}}}$, we conclude that $s(z)$ must also belong to $P^{n,k}_0$. Since $\mathfrak{I}$ is connected by uniform relations, an easy induction on path length proves that $s(x) \in P^{n,k}_0$ for all $x \in I$. Obviously, the argument works the same way for the case when $s(y) \in  O_n$. The remaining statements of the lemma are now immediate consequences of what we just proved and the definitions of $\mathfrak{I}^{(0)}$, $\mathfrak{I}^{\lnot(0)}$, $\mathfrak{P}^{n,k}$, and $\mathfrak{O}_n$.     
\end{proof}



Lemma \ref{lem:uniformsolutionssplit} establishes a close connection between uniform instances $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ with a single uniform connected component and the inner and outer restrictions $\mathfrak{I}^{(0)}$ and $\mathfrak{I}^{\lnot(0)}$. The main idea underlying our recursive reduction scheme is to replace the inner restriction $\mathfrak{I}^{(0)}$ of such instances with its reduced instance and then combine this data with the outer restriction $\mathfrak{I}^{\lnot (0)}$. Hence, our next task is to understand how an instance $\mathfrak{I}_1$ of $\Csp(\mathfrak{P}^{n,k-1})$ may be combined with an instance of $\mathfrak{I}_2$ of $\Csp(\mathfrak{O}_n)$ to obtain a uniform instance $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k})$ with the property that $\mathfrak{I}_1 = \mathfrak{I}^{(0)}$ and $\mathfrak{I}_2 = \mathfrak{I}^{\lnot (0)}$. A moment's reflection reveals that, for fixed $\mathfrak{I}_1$ and $\mathfrak{I}_2$, there are potentially many instances $\mathfrak{I}$ with the above property. This is illustrated in Example~\ref{ex:differentinstancesums}.

\begin{example}\label{ex:differentinstancesums}
Let $I = \{x,y\}$. Let $\mathfrak{I}_1$ be the instance of $\Csp(\mathfrak{P}^{n,1})$ with domain $I$ where $(x,y) \in (T^{n,1}_{0,0})^{\mathfrak{I}_1}$ and $(x,y) \in (\Eq_2, R_{((1)(2))})^{\mathfrak{I}_1}$, while all other relations are empty. Let $\mathfrak{I}_2$ be the instance of $\Csp(\mathfrak{O}_n)$ with domain $I$ where $(x,y) \in (R_{((1)(2))})^{\mathfrak{I}_2}$ and $(x,y) \in (R_{((2)(3))})^{\mathfrak{I}_2}$, while all other relations are empty. Consider the following instances $\mathfrak{I}$, $\mathfrak{I}'$, and $\mathfrak{I}''$ of $\Csp(\mathfrak{P}^{n,2})$, each with domain $I$. 
\begin{itemize}
    \item Let $\mathfrak{I}$ be the instance where $(x,y)$ belongs to 
    $(T^{n,1}_{0,0}, R_{((1)(2))})^\mathfrak{I} $ and $((\Eq_2, R_{((1)(2))}), R_{((2)(3))})^\mathfrak{I}$.
    \item Let $\mathfrak{I}'$ be the instance where $(x,y)$ belongs to 
    $((\Eq_2, R_{((1)(2))}) , R_{((1)(2))})^{\mathfrak{I}'} $ and $(T^{n,1}_{0,0}, R_{((2)(3))})^{\mathfrak{I}'}$.
    \item Let $\mathfrak{I}''$ be the instance where $(x,y)$ belongs to 
    $((\Eq_2, R_{((1)(2))}) , R_{((1)(2))})^{\mathfrak{I}''} $, $(T^{n,1}_{0,0}, R_{((1)(2))})^{\mathfrak{I}''}$, and $(T^{n,1}_{0,0}, R_{((2)(3))})^{\mathfrak{I}''}$.
\end{itemize}
Clearly, $\mathfrak{I}^{(0)} = (\mathfrak{I}')^{(0)} = (\mathfrak{I}'')^{(0)} = \mathfrak{I}_1$ and $\mathfrak{I}^{\lnot (0)} = (\mathfrak{I}')^{\lnot(0)} = (\mathfrak{I}'')^{\lnot(0)} = \mathfrak{I}_2$.
\end{example}
In view of Example~\ref{ex:differentinstancesums}, we make the following definitions.

\begin{definition}\label{def:sumofinstances}
    Let $n \geq 2$ and $k \geq 0$. Let $\mathfrak{I}_1$ and $\mathfrak{I}_2$ be instances of $\Csp(\mathfrak{P}^{n,k})$ and $\Csp(\mathfrak{O}_n)$, respectively. We define
    \[
    \mathfrak{I}_1 \oplus \mathfrak{I}_2  := \{ \text{ Instance  $\mathfrak{I}$ of $\Csp(\mathfrak{P}^{n,k+1})$ } : \mathfrak{I}^{(0)} = \mathfrak{I}_1 \text{ and } \mathfrak{I}^{\lnot(0)} = \mathfrak{I}_2 \}.
    \]
   Notice that $\mathfrak{I}_1 \oplus \mathfrak{I}_2$ may be empty.
\end{definition}

\begin{definition}\label{def:uniformproduct}
    Let $n \geq 0$, $k \geq 0$, and let $\mathfrak{I}_1$ and $\mathfrak{I}_2$ be instances of $\Csp(\mathfrak{P}^{n,k})$ and $\Csp(\mathfrak{O}_n)$, respectively, such that $I_1 = I_2$. We define an instance $\mathfrak{I}_1 \cdot \mathfrak{I}_2$ of $\Csp(\mathfrak{P}^{n,k+1})$ with domain $I = I_1 = I_2$ and constraints defined by $(x_1, \dots,  x_m) \in (\rho_1, \rho_2)^{\mathfrak{I}_1 \cdot \mathfrak{I}_2}$ if and only if $(x_1, \dots, x_m) \in \rho_1^{\mathfrak{I}_1}$ and $(x_1, \dots, x_m) \in \rho_2^{\mathfrak{I}_2}$, for each $1 \leq m \leq 3$. 
    %\begin{itemize}
        %\item $x \in (\rho_1, \rho_2)^{\mathfrak{I}_1 \times \mathfrak{I}_2}$ if and only if $x \in \rho_1^{\mathfrak{I}_1}$ and $x \in \rho_2^{\mathfrak{I}_2}$. 
        %\item $(x,y) \in (\rho_1, \rho_2)^{\mathfrak{I}_1 \times \mathfrak{I}_2}$ if and only if $(x,y) \in \rho_1^{\mathfrak{I}_1}$ and $(x,y) \in \rho_2^{\mathfrak{I}_2}$.
        %\item $(x,y,z) \in (\rho_1, \rho_2)^{\mathfrak{I}_1 \times \mathfrak{I}_2}$ if and only if $(x,y,z) \in \rho_1^{\mathfrak{I}_1}$ and $(x,y,z) \in \rho_2^{\mathfrak{I}_2}$.\todo{combine the three?}
    %\end{itemize}}
\end{definition}

\begin{lemma}\label{lem:nonemptyuniformsum}
    Let $n \geq 0$, $k \geq 0$, and let $\mathfrak{I}_1$ and $\mathfrak{I}_2$ be instances of $\Csp(\mathfrak{P}^{n,k})$ and $\Csp(\mathfrak{O}_n)$, respectively. Then, $\mathfrak{I}_1 \cdot \mathfrak{I}_2 \in \mathfrak{I}_1 \oplus \mathfrak{I}_2$ if and only if $I_1 = I_2$ and $\Sup_j(\mathfrak{I}_1) = \Sup_j(\mathfrak{I}_2)$ for each $1\leq j \leq 3$.  
\end{lemma}
\begin{proof}
    Suppose that $\mathfrak{I}_1 \cdot  \mathfrak{I}_2 \in \mathfrak{I}_1 \oplus \mathfrak{I}_2$. By Definition~\ref{def:sumofinstances}, we have that $(\mathfrak{I}_1 \cdot \mathfrak{I}_2)^{(0)} = \mathfrak{I}_1$ and $(\mathfrak{I}_1 \cdot \mathfrak{I}_2)^{\lnot (0) } = \mathfrak{I}_2$, hence $I_1 = I_2$. It is straightforward to apply \emph{1.}\ and \emph{2.}\ of Definition~\ref{def:innerouterinstances+targetcompatible} to conclude that $\Sup_j(\mathfrak{I}_1) = \Sup_j(\mathfrak{I}_2)$ for each $1\leq j \leq 3$. 

    For the other direction, take $\mathfrak{I}_1$ and $\mathfrak{I}_2$ so that $I_1 = I_2$ and $\Sup_j(\mathfrak{I}_1) = \Sup_j(\mathfrak{I}_2)$ for each $1\leq j \leq 3$.
    It is also similarly straightforward to verify that $\mathfrak{I}_1 \cdot \mathfrak{I}_2 \in \mathfrak{I}_1 \oplus \mathfrak{I}_2$.
\end{proof}

